INSERT INTO doc_pages VALUES('NCT05842941','master',7,replace('PROTOCOL APPROVAL SIGNATURE PAGE\nHEALEY ALS Platform Trial\nThe undersigned accept the content of this protocol in accordance with the appropriate\nregulations and agree to adhere to it throughout the execution of the study.\nMerit Cudkowicz, MD, MSe\nPrincipal Investigator\nDirector, Healey & AMG Center\nfor ALS at Mass General\nSabrina Paganoni, MD, PhD\nCo-Principal Investigator\nHealey Center & AMG for ALS at\nMass General\nMarianne Kearney Chase\nSr. Director of Research\nOperations, Healey Center &\nAMG for ALS at Mass General\nHEALEY ALS Platform Trial Protocol\nVersion 6.0 Page 6 of 82\nVersion date 10/14/2024\n','\n',char(10)));
INSERT INTO doc_pages VALUES('NCT05842941','master',8,replace('STATEMENT OF COMPLIANCE\nThis study will be conducted in compliance with the protocol, International Council for\nHarmonisation of Technical Requirements for Pharmaceuticals for Human Use (ICH), Guideline\nfor Good Clinical Practice (GP), and applicable regulatory requirements, including United\nStates Code of Federal Regulations (CFR) Title 45 CFR Part 46 and Title 21 CFR Parts 50, 56,\nand 312.\nHEALEY ALS Platform Trial Protocol\nPage 7 of 82 Version 6.0\nVersion date 10/14/2024\n','\n',char(10)));
INSERT INTO doc_pages VALUES('NCT05842941','master',9,replace('SIGNATURE PAGE\nI have read the attached ALS Platform Trial protocol entitled, "HEALEY ALS Platform Trial"\ndated 10/14/2024 (Version 6.0) and agree to abide by all described protocol procedures. I agree\nto comply with the ICH Guideline on GCP, applicable FDA regulations and guidelines,\nincluding those identified in Title 21 CFR Parts 11, 50, 54, and 312, single Institutional Review\nBoard (IRB) guidelines and policies, and the Health Insurance Portability and Accountability Act\n(HIPAA).\nBy signing the protocol, I agree to keep all information provided in strict confidence and to\nrequest the same from my staff. Study documents will be stored appropriately to ensure their\nconfidentiality. I will not disclose such information to others without authorization, except to the\nextent necessary to conduct the study.\nSite Name:\nSite Investigator:\nSigned:\nHEALEY ALS Platform Trial Protocol\nPage 8 of 82 Version 6.0\nVersion date 10/14/2024\n','\n',char(10)));
