INSERT INTO doc_pages VALUES('NCT05842941','regimen_g',3,replace(' \nHEALEY ALS Platform Trial CONFIDENTIAL \nRegimen-Specific Appendix G, DNL343 Page 2 of 69 \nVersion 2.0, 12/18/2023 \nTABLE OF CONTENTS \nPage \nSIGNATURE PAGE ...................................................................................................................... 5 \nLIST OF ABBREVIATIONS ......................................................................................................... 6 \nREGIMEN-SPECIFIC APPENDIX SUMMARY ......................................................................... 8 \nSCHEDULE OF ACTIVITIES – Placebo-controlled Treatment period ...................................... 10 \n1. INTRODUCTION ................................................................................................................ 17 \n1.1 DNL343 Background Information ................................................................................ 17 \n1.2 DNL343 Therapeutic Rationale .................................................................................... 20 \n2. OBJECTIVES ....................................................................................................................... 21 \n2.1 Study Objectives and Endpoints ................................................................................... 21 \n3. Regimen-specific Appendix DESIGN .................................................................................. 23 \n3.1 Scientific Rationale for Regimen-Specific Appendix Design ...................................... 23 \n3.2 End of Participation Definition ..................................................................................... 23 \nPlacebo-Controlled Period ........................................................................................................ 23 \nActive Treatment Extension Period .......................................................................................... 23 \n3.3 End of Regimen Definition ........................................................................................... 24 \n4. Regimen-Specific Appendix Enrollment .............................................................................. 25 \n4.1 Number of Study Participants ....................................................................................... 25 \n4.2 Inclusion and Exclusion Criteria ................................................................................... 25 \n4.2.1 Regimen-Specific Appendix Inclusion Criteria ................................................. 25 \n4.2.2 Regimen-Specific Appendix Exclusion Criteria ................................................ 25 \n4.3 Treatment Assignment Procedures ............................................................................... 25 \n5. INVESTIGATIONAL PRODUCT ....................................................................................... 26 \n5.1 Investigational Product Manufacturer ........................................................................... 26 \n5.2 Labeling, Packaging, and Resupply .............................................................................. 26 \n5.3 Acquisition, Storage, and Preparation .......................................................................... 26 \n5.4 Study Medication/Intervention, Administration, Escalation, and Duration ................. 27 \n5.5 Justification for Dosage ................................................................................................ 27 \n5.6 Dosage Changes ............................................................................................................ 29 \n5.6.1 Dose Modification for an Individual Participant ............................................... 29 \n5.7 Participant Compliance ................................................................................................. 30 \n5.8 Overdose or Medication Administration Error ............................................................. 30 \n5.9 Prohibited Medications ................................................................................................. 30 ','\n',char(10)));
INSERT INTO doc_pages VALUES('NCT05842941','regimen_g',4,replace('TABLE OF CONTENTS (CONT’D) \nPage \nHEALEY ALS Platform Trial CONFIDENTIAL \nRegimen-Specific Appendix G, DNL343 Page 3 of 69 \nVersion 2.0, 12/18/2023 \n5.10 DNL343 Known Potential Risks and Benefits ............................................................. 31 \n5.10.1 Known Potential Benefits and Risks.................................................................. 31 \n5.10.2 Contraceptive Requirements for Participants in Regimen G ............................. 31 \n6. Regimen Schedule ................................................................................................................ 34 \n6.1 Baseline Visit ................................................................................................................ 35 \n6.2 Week 2 Telephone Visit................................................................................................ 36 \n6.3 Week 4 and 8 Visits ...................................................................................................... 36 \n6.4 Week 12 Telephone Visit.............................................................................................. 37 \n6.5 Week 16 Visit ............................................................................................................... 37 \n6.6 Week 20 Telephone Visit.............................................................................................. 37 \n6.7 Week 24 Visit or Early Termination Visit .................................................................... 37 \n6.8 Follow-Up Safety Call .................................................................................................. 38 \n6.9 Process for Early Terminations ..................................................................................... 39 \n6.10 Active Treatment Extension ......................................................................................... 39 \n6.10.1 Week 2 ATE Telephone 