INSERT INTO doc_pages VALUES('NCT05842941','regimen_g',63,replace(' \nHEALEY ALS Platform Trial CONFIDENTIAL \nRegimen-Specific Appendix G, DNL343 Page 62 of 69 \nVersion 2.0, 12/18/2023 \n \n','\n',char(10)));
INSERT INTO doc_pages VALUES('NCT05842941','regimen_g',64,replace(' \nHEALEY ALS Platform Trial CONFIDENTIAL \nRegimen-Specific Appendix G, DNL343 Page 63 of 69 \nVersion 2.0, 12/18/2023 \nAPPENDIX III: CONTRACEPTIVE GUIDANCE FOR FEMALE PARTICIPANTS \nOF CHILDBEARING POTENTIAL \nHighly Effective Methods a to be used in combination with a male barrier method (e.g. condom)  \n• Intrauterine device (IUD) \n• Intrauterine hormone-releasing system (IUS) b \n• Bilateral tubal ligation c \n• Azoospermic male partner of woman of childbearing potential participant d \nAlternative Highly Effective Method \n• Abstinence defined as refraining from heterosexual intercourse during the entire duration of the \nstudy and for 90 days after last dose of study drug. ‘Periodic abstinence’ is considered not reliable \nand would not be acceptablee \nNotes: Male condom and female condom should not be used together (due to risk of failure with friction).  \na Contraceptive use by participants should be consistent with local regulations regarding the use of \ncontraceptive methods for those participating in clinical studies.  \nb Failure rate of < 1% per year when used consistently and correctly. Typical use failure rates differ  from \nthose when used consistently and correctly. \nc Essure fallopian tube coil placement is not accepted, as the permanent contraception failure rate is likely \ngreater than 1%.  \nd Azoospermia is a highly effective contraceptive method provided that the partner is the sole sexual \npartner of the woman of childbearing potential and the absence of sperm has been confirmed . If \nnot, an additional highly effective method of contraception should be used. Spermatogenesis cycle is \napproximately 90 days. \nNote: documentation of azoospermia for a male participant can come from the site personnel’s review of \nthe participant’s medical records, medical examination, or medical history interview.  \ne Periodic abstinence (calendar, symptothermal, post ovulation methods), withdrawal (coitus interruptus), \nspermicides only, and lactational amenorrhea method are NOT acceptable methods of contraception. \n \n \n \n \n \n \n \n \n \n \n \n \n ','\n',char(10)));
INSERT INTO doc_pages VALUES('NCT05842941','regimen_g',65,replace(' \nHEALEY ALS Platform Trial CONFIDENTIAL \nRegimen-Specific Appendix G, DNL343 Page 64 of 69 \nVersion 2.0, 12/18/2023 \nAPPENDIX III: CONTRACEPTIVE GUIDANCE FOR MALE PARTICIPANTS WITH \nFEMALE PARTNERS OF CHILDBEARING POTENTIAL \nHighly Effective Methods a to be used in combination with a male barrier method (e.g. \ncondom)  \n• Intrauterine device (IUD) \n• Intrauterine hormone-releasing system (IUS) b \n• Bilateral tubal ligation c \n• Implantable progestogen-only hormone contraception associated with inhibition of ovulation  \n• Combined (estrogen- and progestogen-containing) hormonal contraception associated with \ninhibition of ovulation \n− oral \n− intravaginal \n− transdermal \n− injectable \n• Progestogen-only hormone contraception associated with inhibition of ovulation ) \n− Oral \n− injectable \n• Azoospermic male participantd \nAlternative Highly Effective Method \n• Abstinence defined as refraining from heterosexual intercourse during the entire duration of \nthe study and for 90 days after last dose of study drug. ‘Periodic abstinence’ is considered not \nreliable and would not be acceptablee. \nNotes: Male condom and female condom should not be used together (due to risk of failure with \nfriction). \na Contraceptive use by participants should be consistent with local regulations regarding the use of \ncontraceptive methods for those participating in clinical studies.  \nb Failure rate of < 1% per year when used consistently and correctly. Typical use failure rates \ndiffer from those when used consistently and correctly. \nc   Essure fallopian tube coil placement is not accepted, as the permanent contraception failure rate \nis likely greater than 1%.  \nd Azoospermia is a highly effective contraceptive method provided that the partner is the sole \nsexual partner of the woman of childbearing potential and the absence of sperm has been \nconfirmed. If not, an additional highly effective method of contraception should be used. \nSpermatogenesis cycle is approximately 90 days. \nNote: documentation of azoospermia for a male participant can come from the site personnel’s \nreview of the participant’s medical records, medical examination, or medical history interview.  \ne  Periodic abstinence (calendar, symptothermal, post ovulation methods), withdrawal (coitus \ninterruptus), spermicides only, and lactational amenorrhea method are NOT acceptable methods \nof contraception.  ','\n',char(10)));
INSERT INTO doc_pages VALUES('NCT05842941','regimen_g',66,replace(' \nHEALEY ALS Platform Trial CONFIDENTIAL \nRegimen-Specific Appendix G, DNL343 Page 65 of 69 \nVersion 2.0, 12/18/2023 \nAPPENDIX IV: CONCOMITANT MEDICATION RESTRICTIONS \nExcluded Medications \nThe medications indicated below are excluded during the study (unless otherwise specified) (See \nSection 5.9 for prohibited medications). The lists below are not exhaustive; the use of any \nconcomitant medication is at the discretion of the investigator who knows the participant’s \nmedical history.  \nStrong CYP3A4/5 Inducers \nDNL343 is a CYP3A4/5 substrate based on in vitro data; use of strong CYP3A4/5 inducers may \ndecrease DNL343 plasma concentrations.  \nThe medications in Table 4 are examples of strong CYP3A4/5 inducers and are excluded during \nthe study. If needed, it is recommended that a tertiary source, such as the Drug Interactions \nFlockhart Table (found at https://drug-interactions.medicine.iu.edu/MainTable.aspx), be used for \nmore information regarding other medications. \nTable 4: Strong CYP3A4/5 Inducers with the Drug Half-Life and Washout Periods \nGeneric Drug Name Drug Half-life Recommended Washout \napalutamide 4.2 d 2 weeks \ncarbamazepine 15 h 2 weeks \nphenytoin 24 h 2 weeks \nrifampin 3.5 h 2 weeks \nSt. John’s wort 36 h 2 weeks \nbosentan 5 h 2 weeks \nAbbreviations: CYP, cytochrome P450. \nSource: US Food and Drug Administration (FDA). Drug Development and Drug Interactions: \nTable of Substrates, Inhibitors and Inducers. FDA website. Published 2020. \nhttps://www.fda.gov/drugs/drug-interactions-labeling/drug-development-and-drug-interactions-\ntable-substrates-inhibitors-and-inducers. \n \nSensitive CYP3A4/5 Substrates \nThe clinical DDI study was conducted in healthy participants with midazolam, a sensitive \nsubstrate of CYP3A (DNLI-F-0007). The preliminary data showed DNL343 is a moderate \ninducer of CYP3A4 metabolism, indicating that sensitive CYP3A substrates may have \nreductions in exposure when coadministered with DNL343 which may lead to reduction in \nefficacy if the therapeutic index is narrow.  \n \nThe medications in Table 5 are examples of sensitive CYP3A4/5 substrates. The list below is \nnot exhaustive and if any of these medications are considered to have a narrow therapeutic \nindex, they should be excluded during the study. Medications that are sensitive CYP3A4/5 \nsubstrates with a wide therapeutic index are permitted; participants taking them are to be ','\n',char(10)));
INSERT INTO doc_pages VALUES('NCT05842941','regimen_g',67,replace(' \nHEALEY ALS Platform Trial CONFIDENTIAL \nRegimen-Specific Appendix G, DNL343 Page 66 of 69 \nVersion 2.0, 12/18/2023 \nmonitored for signs of loss of efficacy and/or may require dose increases based on the respective \nmedication’s prescribing information. \nThe medical monitor may be consulted to assess whether any of the medications listed in Table 5 \nwould be considered to have narrow therapeutic index for the individual participant taking the \nmedication. \nTable 5: Sensitive CYP3A4/5 Substrates \nGeneric  \nDrug Name Drug Half-Life Recommended Washout \nbuspirone 5.0 h 7 days \ndarunavir 3–5 h 7 days \ndronedarone 1.6 ± 0.2 h 7 days \neplerenone 3–6 h 7 days \nfelodipine 4.8 min, 1.5 h, and 9.1 h (IV); \n11–16 h (IR tablet) \n7 days \nindinavir 1.8 ± 0.4 h 7 days \nlurasidone 18 h 7 days \nmaraviroc 13.2 (10.3–8.3) h 7 days \nnisoldipine 3.2 h (young), 6.5 h (elderly) 7 days \nquetiapine 6 h 7 days \nQuinine 11 ± 2 h 7 days \nsaquinavir 7–12 h 7 days \nsildenafil (when used for PAH) 2.4 ± 1.0 h 7 days \nsirolimus 62.3 ± 16.2 h 13 days \ntacrolimus 31.9 ± 10.5 h (based on radioactivity);  \n48.4 ± 12.3 h (based on tacrolimus \nconcentrations) \n10 days \nticagrelor 6.8 h (IV); 8.1 h (oral) 7 days \ntipranavir 4.8 h (healthy volunteers); 5.5 h (female \npatients); 6.0 h (male patients) \n7 days \nAbbreviations: CYP, cytochrome P450; IM, intramuscular; IR, immediate release; IV, intravenous; PAH, \npulmonary arterial hypertension. \nNote: Sensitive substrates are drugs that demonstrate an increase in area under the concentration -time \ncurve of ≥ 5-fold with strong inhibitors of a given metabolic pathway in clinical drug-drug interaction \nstudies.  \nSource: US Food and Drug Administration (FDA). Drug Development and Drug Interactions: Table of \nSubstrates, Inhibitors and Inducers. FDA website. Published 2020. https://www.fda.gov/drugs/drug-\ninteractions-labeling/drug-development-and-drug-interactions-table-substrates-inhibitors-and-inducers.  \n \nSubstrates of Major Transporters  \nDNL343 has a risk of inhibition of BCRP and OAT3 transporters at clinically relevant \nconcentrations based on preliminary in vitro transporter inhibition studies. Medications that are \nsubstrates for these transporters may have increased exposure when taken with DNL343. ','\n',char(10)));
INSERT INTO doc_pages VALUES('NCT05842941','regimen_g',68,replace(' \nHEALEY ALS Platform Trial CONFIDENTIAL \nRegimen-Specific Appendix G, DNL343 Page 67 of 69 \nVersion 2.0, 12/18/2023 \nThe medications in Table 6 are examples of substrates of BCRP or OAT3. The list below is not \nexhaustive and if any of these medications are considered to have a narrow therapeutic index, \nthey should be excluded during the study. Medications that are considered to have a wide \ntherapeutic index are permitted, and participants taking them are to be monitored for signs of \nAEs noted in the respective medication’s prescribing information. \nThe medical monitor may be consulted to assess whether any of the medications listed in Table 6 \nwould be considered to have narrow therapeutic index for the individual participant taking the \nmedication. \nTable 6: Substrates of BCRP or OAT3 Transporters \nSubstrate Generic Drug Name Drug Half-Life \nRecommended \nWashout \nBCRP Substrates rosuvastatin 7.48 ± 1.65 h 7 days \nsulfasalazine 22.45 ± 6.366 h 7 days \nOAT3 Substrates adefovir 7.48 ± 1.65 h 7 days \ncefaclor 11 h 7 days \nceftizoxime 1.8 ± 0.8 h 7 days \nfamotidine 0.8 ± 0.2 h 7 days \nfurosemide 20 ± 6 h 7 days \nmethotrexate 15 h 7 days \noseltamivir carboxylate 6 to 10 h 7 days \npenicillin G 7.6 ± 3.4 h 7 days \nAbbreviations: BCRP, breast cancer resistance protein; OAT3, organic anion transporter 3Source: US Food \nand Drug Administration (FDA). Drug development and drug interactions: table of substrates, inhibitors \nand inducers. FDA website. Published 2020. https://www.fda.gov/drugs/drug-interactions-\nlabeling/drug-development-and-drug-interactions-table-substrates-inhibitors-and-inducers. ','\n',char(10)));
INSERT INTO doc_pages VALUES('NCT05842941','regimen_g',69,replace(' \nHEALEY ALS Platform Trial CONFIDENTIAL \nRegimen-Specific Appendix G, DNL343 Page 68 of 69 \nVersion 2.0, 12/18/2023 \nREFERENCES \nBusnar J and Targum S. The Clinical Global Impression Scale. Psychiatry (Edgmont). 2007 Jul; \n4(7): 28–37 \nCheng W, Wang S, Mestre AA, et al. C9ORF72 GGGGCC repeat-associated non-AUG \ntranslation is upregulated by stress through eIF2α phosphorylation. Nat Commun. 2018;9(1):51. \nFournier CN, Bedlack R, Quinn C, et al. Development and validation of the Rasch-built overall \namyotrophic lateral sclerosis disability scale (ROADS). JAMA Neurol. 2020;77:480-488. \nHetz C, Saxena S. ER stress and the unfolded protein response in neurodegeneration. NatRev \nNeurol. 2017;13(8):477–91. \nHetz C, Thielen P, Matus S, et al. XBP-1 deficiency in the nervous system protects against \namyotrophic lateral sclerosis by increasing autophagy. Genes Dev. 2009;23(19):2294–306. \nHurst H, Bolton J. Assessing the clinical significance of change scores recorded on subjective \noutcome measures. J Manipulative Physiol Ther. 2004;27:26-35 \nIlieva EV, Ayala V, Jové M, et al.Oxidative and endoplasmic reticulum stress interplay in \nsporadic amyotrophic lateral sclerosis. Brain. 2007;130(Pt 12):3111–23. \nKim HJ, Raphael AR, LaDow ES, et al. Therapeutic modulation of eIF2α phosphorylation \nrescues TDP-43 toxicity in amyotrophic lateral sclerosis disease models. Nat Genet. \n2013;46(2):152–60. \nLarhammar M, Huntwork-Rodriguez S, Jiang Z, et al. Dual leucine zipper kinase-dependent \nPERK activation contributes to neuronal degeneration following insult. Elife. 2017;6: e20725. \nMoreno JA, Halliday M, Molloy C, et al. Oral treatment targeting the unfolded protein response \nprevents neurodegeneration and clinical disease in prion-infected mice. Sci Transl Med. \n2013;5(206):206ra138. \nNagata T, Ilieva H, Murakami T, et al.Increased ER stress during motor neuron degeneration in a \ntransgenic mouse model of amyotrophic lateral sclerosis. NeurolRes. 2007;29(8):767–71. \nPakos-Zebrucka K, Koryga I, Mnich K, et al. The integrated stress response. EMBO Rep. \n2016;17(10):1374–95. \nSonobe Y, Ghadge G, MasakiK, et al. Translation of dipeptide repeat proteins from the \nC9ORF72 expanded repeat is associated with cellular stress. Neurobiol Dis. 2018;116:155–65. \nVanhoutte EK, Hermans MC, Faber CG, et al. Rasch-ionale for neurologists. J Peripher Nerv \nSyst. 2015;20(3):260-268. \nViktrup L, et al., Construct validation of patient global impression of severity (PGI-S) and \nimprovement (PGI-I) questionnaires in the treatment of men with lower urinary tract symptoms \nsecondary to benign prostatic hypertrophy. BMC Urol. 2012;12:30.  \nWestergard T, McAvoy K, Russell K, et al. Repeat-associated non-AUG translation in C9orf72-\nALS/FTD is driven by neuronal excitation and stress. EMBO Mol Med. 2019;11(2): e9423. ','\n',char(10)));
INSERT INTO doc_pages VALUES('NCT05842941','regimen_g',70,replace(' \nHEALEY ALS Platform Trial CONFIDENTIAL \nRegimen-Specific Appendix G, DNL343 Page 69 of 69 \nVersion 2.0, 12/18/2023 \nWong YL, LeBon L, Basso AM, et al. eIF2B activator prevents neurological defects caused by a \nchronic integrated stress response. Elife. 2019;8:e42940. ','\n',char(10)));
INSERT INTO rules VALUES('MAP-protocol-consent-001','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','The consent form will be reviewed and if appropriate, signed by the participant and coordinator. A copy of the consent form will be provided to the participant for his or her records. The consent form will specifically request consent for the future use of data and stored serum and plasma for ancillary studies.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent", "screening", "enrollment", "randomization", "dosing", "sample_collection", "imaging"]','the consent form will be reviewed and if appropriate, signed by the participant and coordinator. A copy of the consent form will be provided to the participant for his or her records. The consent form will specifically request consent for the future use of data and stored serum and plasma for ancillary studies.',22,'2.3.1 Risk/Benefit Assessment - Adequacy of protection against risks - Informed Consent',1,0,1,'2026-10-10T14:43:31+00:00',NULL,NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-002','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','Informed consent is a process that is initiated prior to the individual’s agreeing to participate in the study and continues throughout the individual’s study participation. ... The informed consent process must be conducted, and the form signed, before the participant undergoes any study-specific procedures.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent", "screening", "enrollment", "randomization", "dosing", "sample_collection", "imaging"]','Informed consent is a process that is initiated prior to the individual’s agreeing to participate in the study and continues throughout the individual’s study participation. ... The informed consent process must be conducted, and the form signed, before the participant undergoes any study-specific procedures.',NULL,'10.1.1.2 Consent Procedures and Documentation',0,1,0,'2026-10-10T14:43:31+00:00','quote not found in the document',NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-003','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','No study-related procedures may occur until the consent designee is in possession of the signed ICF.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization", "dosing", "sample_collection", "imaging"]','No study-related procedures may occur until the consent designee is in possession of the signed ICF.',56,'10.1.1.2 Consent Procedures and Documentation',1,2,1,'2026-10-10T14:43:31+00:00',NULL,NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-004','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','The participant must return the original signed document on their first in-person visit. Once the participant’s original copy is received, the consent designee will append this to their own signed copy and create a single document.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent", "screening", "enrollment", "randomization", "dosing", "sample_collection", "imaging"]','The participant must return the original signed document on their first in-person visit. Once the participant’s original copy is received, the consent designee will append this to their own signed copy and create a single document.',56,'10.1.1.2 Consent Procedures and Documentation',1,3,1,'2026-10-10T14:43:31+00:00',NULL,NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-005','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','There will be three informed consent forms, one for the main study, one for the PET imaging sub-study, and one for volunteers (non-participants) undergoing MRI for calibration.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent", "screening", "enrollment", "randomization", "dosing", "sample_collection", "imaging"]','There will be three informed consent forms, one for the main study, one for the PET imaging sub- study, and one for volunteers (non-participants) undergoing MRI for calibration.',56,'10.1.1.2 Consent Procedures and Documentation',1,4,0,'2026-10-10T14:43:31+00:00','dropped by review (not_checkable): The existence of three consent forms (main, PET, MRI volunteer) is not a site duty to obtain or document consent, but a description of study materials. There is no checkable site action or omission here.',NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-006','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','MAP requires the participation of a study partner who should be available by telephone or in person to answer questionnaires about the participant’s cognition, mental health, and function. The study partner must provide verbal consent to participation. The consent designee will read a consent script and document that the study partner verbally consented to participation in the MAP trial. The waiver of written documentation of consent is available only to study partners, not to study participants.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent", "screening", "enrollment", "randomization", "dosing", "sample_collection", "imaging"]','MAP requires the participation of a study partner who should be available by telephone or in person to answer questionnaires about the participant’s cognition, mental health, and function. The study partner must provide verbal consent to participation . The consent designee will read a consent script and document that the study partner verbally consented to participation in the MAP trial. The waiver of written documentation of consent is available only to study partners, not to study participants.',55,'10.1.1.2 Consent Procedures and Documentation',1,5,1,'2026-10-10T14:43:31+00:00',NULL,NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-007','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','Participants will be given three trials to respond to the UBACC. If after three trials they do not have a perfect score, they will be determined to lack capacity to consent. The determination of lacking capacity to consent will lead to exclusion at baseline, and to the need for a legally authorized representative to provide consent during follow-up.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent", "screening", "enrollment"]','Participants will be given three trials to respond to the UBACC. If after three trials they do not have a perfect score, they will be determined to lack capacity to consent. The determination of lacking capacity to consent will lead to exclusion at baseline, and to the need for a legally authorized representative to provide consent during follow -up.',39,'8.1 Efficacy Assessments - Capacity to consent',1,6,1,'2026-10-10T14:43:31+00:00',NULL,NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-008','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','At baseline, lack of capacity to understand the study will constitute a reason for exclusion. During follow-up assessments, determination of lack of capacity to consent will lead to the need for a legal authorized representative to consent after the participant provides assent to participate.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent", "screening", "enrollment"]','At baseline, lack of capacity to understand the study will constitute a reason for exclusion. During follow-up assessments, determination of lack of capacity to consent will lead to the need for a legal authorized representative to consent after the participant provides assent to participate.',39,'8.1 Efficacy Assessments - Capacity to consent',1,7,1,'2026-10-10T14:43:31+00:00',NULL,NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-009','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','If the participant demonstrates capacity, he/she may consent; if the participant lacks capacity but wants to continue participation, a legally authorized representative will need to provide consent after the participant’s assent.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent", "screening", "enrollment"]','If the participant demonstrates capacity, he/she may consent; if the participant lacks capacity but wants to continue participation, a legally authorized representative will need to provide consent after the participant’s assent.',39,'8.1 Efficacy Assessments - Capacity to consent',1,8,1,'2026-10-10T14:43:31+00:00',NULL,NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-010','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','The consent form must be reviewed by the participant and, if appropriate, signed by both the participant and the coordinator.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','the consent form will be reviewed and if appropriate, signed by the participant and coordinator.',22,'2.3.1 Known Potential Risks and their mitigation',1,9,1,'2026-10-10T14:43:31+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-011','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','A copy of the signed consent form must be provided to the participant for their records.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','A copy of the consent form will be provided to the participant for his or her records.',22,'2.3.1 Known Potential Risks and their mitigation',1,10,1,'2026-10-10T14:43:31+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-012','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','The consent form must specifically request consent for the future use of data and stored serum and plasma for ancillary studies.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','The consent form will specifically request consent for the future use of data and stored serum and plasma for ancillary studies.',22,'2.3.1 Known Potential Risks and their mitigation',1,11,1,'2026-10-10T14:43:31+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-013','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','MAP requires the participation of a study partner who should be available by telephone or in person to answer questionnaires about the participant’s cognition, mental health, and function.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','MAP requires the participation of a study partner who should be available by telephone or in person to answer questionnaires about the participant’s cognition, mental health, and function.',55,'10.1.1 Informed Consent Process',1,12,1,'2026-10-10T14:43:31+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-014','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','The study partner must provide verbal consent to participation, which must be documented by the consent designee reading a consent script and documenting the verbal consent.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','The study partner must provide verbal consent to participation . The consent designee will read a consent script and document that the study partner verbally consented to participation in the MAP trial.',55,'10.1.1 Informed Consent Process',1,13,1,'2026-10-10T14:43:31+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('MAP-protocol-consent-015','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','prohibition','Waiver of written documentation of consent is available only to study partners, not to study participants.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','The waiver of written documentation of consent is available only to study partners, not to study participants.',55,'10.1.1 Informed Consent Process',1,14,1,'2026-10-10T14:43:31+00:00','added_by_review',NULL);
