INSERT INTO rules VALUES('MAP-protocol-consent-018','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','In-person screening includes written informed consent, demographics, anthropometric measurements (height, weight, waist and hip circumference), vital signs (blood pressure and heart rate), EKG, laboratory tests ( thyroid stimulating hormone [TSH], rapid plasma reagin [RPR], vitamin B12, complete blood count [CBC], basic metabolic panel [BMP], hepatic panel, lipid','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment"]','In-person screening includes written informed consent, demographics, anthropometric measurements (height, weight, waist and hip circumference), vital signs (blood pressure and heart rate), EKG, laboratory tests ( thyroid stimulating hormone [TSH], rapid plasma reagin [RPR], vitamin B12, complete blood count [CBC], basic metabolic panel [BMP], hepatic panel, lipid',38,'8 STUDY ASSESSMENTS AND PROCEDURES',1,17,1,'2026-10-10T14:43:31+00:00','added_by_coverage_check',NULL);
