INSERT INTO rules VALUES('MAP-protocol-consent-037','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','consent','requirement','Participants will be given three trials to respond to the UBACC. If after three trials they do not have a perfect score, they will be determined to lack capacity to consent. The determination of lacking capacity to consent will lead to exclusion at baseline, and to the need for a legally authorized representative to provide consent during follow-up.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "consent"]','Participants will be given three trials to respond to the UBACC. If after three trials they do not have a perfect score, they will be determined to lack capacity to consent. The determination of lacking capacity to consent will lead to exclusion at baseline, and to the need for a legally authorized representative to provide consent during follow -up.',39,'8.1 Efficacy Assessments',1,36,0,'2026-10-10T14:43:31+00:00','dropped: duplicate of rule 6',NULL);
