INSERT INTO rules VALUES('MAP-consent-consent-009','NCT04098666','consent','3bcc42459e49602f387bdd4d0302aee1c9f254f07c2240a116b0daf3933e487e','consent','requirement','If the participant loses capacity during the course of the research, consent must be documented by the signature of a Legally Authorized Representative (LAR), with printed name, date, and relationship to the participant, including why the LAR is authorized to act as a surrogate health care decision-maker under state or applicable local law.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','(Indicate why the LAR is authorized to act as a surrogate health care decision-maker under state or applicable local law)',17,'Documentation of Consent/Signatures',1,8,0,'2026-10-10T14:43:32+00:00','dropped: not a checkable requirement (form or signature text)',NULL);
INSERT INTO rules VALUES('MAP-protocol-eligibility-001','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','eligibility','inclusion','A mini -mental state exam ≥ 2 2 for participant s with more than 8 years of education. For participants with less than 8 years of education, a MMSE ≥ 20 will be allowed.','numeric','mmse_score','lt',22.0,NULL,NULL,'{"parameter": "education_years", "operator": "gt", "value": 8, "value2": null}','["screening", "enrollment", "randomization"]','A mini -mental state exam ≥ 2 2 for participant s with more than 8 years of education. For participants with less than 8 years of education, a MMSE ≥ 20 will be allowed.',29,'5.1 Inclusion Criteria',1,0,1,'2026-10-10T14:43:20+00:00',NULL,NULL);
INSERT INTO rules VALUES('MAP-protocol-eligibility-002','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','eligibility','inclusion','A mini -mental state exam ≥ 2 2 for participant s with more than 8 years of education. For participants with less than 8 years of education, a MMSE ≥ 20 will be allowed.','numeric','mmse_score','lt',20.0,NULL,NULL,'{"parameter": "education_years", "operator": "le", "value": 8, "value2": null}','["screening", "enrollment", "randomization"]','A mini -mental state exam ≥ 2 2 for participant s with more than 8 years of education. For participants with less than 8 years of education, a MMSE ≥ 20 will be allowed.',29,'5.1 Inclusion Criteria',1,1,1,'2026-10-10T14:43:20+00:00',NULL,NULL);
INSERT INTO rules VALUES('MAP-protocol-eligibility-003','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','eligibility','inclusion','Clinical Dementia Rating (CDR) = 0.5. The memory box score must be at least 0.5.  Information from the formal University of Washington CDR instrument , report by the participant of subjective cognitive complaints, and findings from the screening neuropsychological battery, can be used for this determination  by the investigative team.  For example, the University of Washington CDR can be 0, but the CDR memory box score can be deemed to be 0.5 based on cognitive complaints at screening and meeting the MCI neuropsychological criteria.','numeric','cdr_score','ne',0.5,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Clinical Dementia Rating (CDR) = 0.5. The memory box score must be at least 0.5. Information from the formal University of Washington CDR instrument , report by the participant of subjective cognitive complaints, and findings from the screening neuropsychological battery, can be used for this determination by the investigative team. For example, the University of Washington CDR can be 0, but the CDR memory box score can be deemed to be 0.5 based on cognitive complaints at screening and meeting the MCI neuropsychological criteria.',29,'5.1 Inclusion Criteria',1,2,1,'2026-10-10T14:43:20+00:00','kept: splitting it would lose 0 (This rule bundles two conditions: (1) CDR = 0.5, and (2) memory box score must be at least 0.5. These should be split into separate atomic rules.)','[{"parameter": "cdr_score", "operator": "eq", "value": 0, "value2": null}, {"parameter": "cdr_memory_box_score", "operator": "ge", "value": 0.5, "value2": null}]');
INSERT INTO rules VALUES('MAP-protocol-eligibility-004','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','eligibility','inclusion',replace('Abnormal memory function documented by scoring within the education adjusted ranges on the Logical Memory II subscale (Delayed Paragraph Recall, Paragraph A only) from the Wechsler Memory Scale-Revised.  \n    For early MCI: \n    9-11 for 16 or more years of education \n    5-9 for 8-15 years of education \n    3-6 for 0-7 years of education \n    For late MCI  \n    ≤ 8 for 16 or more years of education \n    ≤ 4 for 8-15 years of education \n    ≤ 2 for 0-7 years of education','\n',char(10)),'numeric','logical_memory_ii_score','gt',11.0,NULL,NULL,'{"parameter": "education_years", "operator": "ge", "value": 16, "value2": null}','["screening", "enrollment", "randomization"]','Abnormal memory function documented by scoring within the education adjusted ranges on the Logical Memory II subscale (Delayed Paragraph Recall, Paragraph A only) from the Wechsler Memory Scale-Revised.  For early MCI: 9-11 for 16 or more years of education 5-9 for 8-15 years of education 3-6 for 0-7 years of education  For late MCI ≤ 8 for 16 or more years of education ≤ 4 for 8-15 years of education ≤ 2 for 0-7 years of educati',30,'5.1 Inclusion Criteria',1,3,1,'2026-10-10T14:43:20+00:00','kept the wider of two allowed limits from the same passage (Abnormal memory function documented by scoring within the ed)',NULL);
