INSERT INTO rules VALUES('MAP-protocol-eligibility-033','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','eligibility','exclusion','• Participants with a known history of diabetes. The rationale for this exclusion is persons with diabetes may already be on metformin or on other medications that increase insulin levels and could confound the trial.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Participants with a known history of diabetes. The rationale for this exclusion is persons with diabetes may already be on metformin or on other medications that increase insulin levels and could confound the trial.',31,'5.2 EXCLUSION CRITERIA',1,32,1,'2026-10-10T14:43:20+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('MAP-protocol-eligibility-034','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','eligibility','exclusion','• Participants with diabetes discovered on screening based on American Diabetes Association criteria using HbA1c (HbA1c of 6.5% or greater). Although metformin could be a first treatment of diabetes for these participants, addition of treatments for diabetes by physicians could confound the study.','numeric','hba1c_percent','ge',6.5,NULL,'percent',NULL,'["screening", "enrollment", "randomization"]','Participants with diabetes discovered on screening based on American Diabetes Association criteria using HbA1c (HbA1c of 6.5% or greater). Although metformin could be a first treatment of diabetes for these participants, addition of treatments for diabetes by physicians could confound the study.',31,'5.2 EXCLUSION CRITERIA',1,33,0,'2026-10-10T14:43:20+00:00','dropped by review (duplicate): repeats a kept rule (Rule 34 (HbA1c ≥ 6.5% exclusion) is already covered by rule 11, which states the same threshold for exclusion.)',NULL);
INSERT INTO rules VALUES('MAP-protocol-eligibility-035','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','eligibility','exclusion','• Use of any amyloid modifying treatment for AD such as lecanemab, either experimental or approved by the Food and Drug Administration, is exclusionary. Previous use of amyloid targeting therapy that was shown to be non-efficacious (e.g. solunazemab) is not exclusionary.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Use of any amyloid modifying treatment for AD such as lecanemab, either experimental or approved by the Food and Drug Administration, is exclusionary. Previous use of amyloid targeting therapy that was shown to be non-efficacious (e.g. solunazemab) is not exclusionary.',31,'5.2 EXCLUSION CRITERIA',1,34,1,'2026-10-10T14:43:20+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('MAP-protocol-eligibility-036','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','eligibility','exclusion','• Not able to undergo phlebotomy as reported by the participant or determined by the study coordinator or physician.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Not able to undergo phlebotomy as reported by the participant or determined by the study coordinator or physician.',31,'5.2 EXCLUSION CRITERIA',1,35,1,'2026-10-10T14:43:20+00:00','added_by_coverage_check',NULL);
