INSERT INTO rules VALUES('MAP-protocol-eligibility-038','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','eligibility','exclusion','• The presence of a medical condition, and/or use of a medication and/or any substance, individually or in aggregate, that in the judgement of the study team, is the primary cause of cognitive impairment. For example, if hypothyroidism, cobalamin deficiency, or tertiary syphilis are reported or found during screening, they could be deemed as being likely contributors to cognitive impairment, and thus be exclusionary. Combinations of multiple medications with anti -cholinergic','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','The presence of a medical condition, and/or use of a medication and/or any substance, individually or in aggregate, that in the judgement of the study team, is the primary cause of cognitive impairment. For example, if hypothyroidism, cobalamin deficiency, or tertiary syphilis are reported or found during screening, they could be deemed as being likely contributors to cognitive impairment, and thus be exclusionary. Combinations of multiple medications with anti -cholinergic',31,'5.2 EXCLUSION CRITERIA',1,37,1,'2026-10-10T14:43:20+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('MAP-protocol-eligibility-039','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','eligibility','inclusion','Clinical Dementia Rating (CDR) = 0.5.','numeric','cdr_score','ne',0.5,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Clinical Dementia Rating (CDR) = 0.5. The memory box score must be at least 0.5.',29,'5.1 Inclusion Criteria',1,38,0,'2026-10-10T14:43:20+00:00','dropped: duplicate of rule 17',NULL);
