INSERT INTO rules VALUES('MAP-protocol-procedure_sequence-001','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','procedure_sequence','sequence','All brain imaging procedures should be conducted prior to starting study drug. Participants who completed the 18 months visit before the implementation of protocol 1.9 will be informed of the change in study duration and that they have completed the study. Participants in this situation who are awaiting follow-up brain imaging (originally after the 24-month visit) will be invited to undergo the brain imaging procedures as soon as protocol 1.9 is approved and implemented.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["dosing", "imaging"]','All brain imaging procedures should be conducted prior to starting study drug. Participants who completed the 18 months visit before the implementation of protocol 1.9 will be informed of the change in study duration and that they have completed the study. Participants in this situation who are awaiting follow-up brain imaging (originally after the 24-month visit) will be invited to undergo the brain imaging procedures as soon as protocol 1.9 is approved and implemented.',NULL,'8 STUDY ASSESSMENTS AND PROCEDURES',0,0,0,'2026-10-10T14:43:25+00:00','kept: splitting it would lose 1.9, 18, 24 (The rule bundles several conditions: (a) all brain imaging procedures should be conducted prior to starting study drug, (b) participants who completed the 18 months visit before protocol 1.9 will be informed of the change in study duration and that they have completed the study, (c) participants in this situation awaiting follow-up brain imaging will be invited to undergo the brain imaging procedures as soon as protocol 1.9 is approved and implemented. Only (a) is a procedure sequence rule; (b) and (c) are not procedure sequence requirements for site conduct.); quote not found in the document',NULL);
INSERT INTO rules VALUES('MAP-protocol-procedure_sequence-002','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','procedure_sequence','requirement','All brain imaging procedures should be conducted prior to starting study drug.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["imaging", "dosing"]','All brain imaging procedures should be conducted prior to starting study drug.',36,'8. STUDY ASSESSMENTS AND PROCEDURES',1,1,1,'2026-10-10T14:43:25+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('MAP-protocol-procedure_sequence-003','NCT04098666','protocol','8bc7d898644cddb6dd4a0c4c224da3178a3999f01067b1f9a62070a7eb877791','procedure_sequence','sequence','All brain imaging must be completed before study intervention is initiated. To this end, a window of 2 months is allowed between enrollment and commencing titration of study drug to complete brain imaging procedures.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["dosing", "imaging", "enrollment"]','All brain imaging must be completed before study intervention is initiated. To this end, a window of 2 months is allowed between enrollment and commencing titration of study drug to complete brain imaging procedures.',42,'8.2.2 Brain imaging',1,2,1,'2026-10-10T14:43:25+00:00','added_by_coverage_check',NULL);
