INSERT INTO rules VALUES('MAP-lab_manual-sample_handling-004','NCT04098666','lab_manual','5d1571c6f2ae2171a2bd52388d0e5851710056f641cc79bbb22401939b8bd9e5','sample_handling','requirement','Participants must fast for at least 8 hours before the blood draw (water is allowed). If the participant has not fasted, record the time of their last meal on the requisition form; do not cancel the draw. Exception: If the participant has not fasted, record the time of their last meal on the requisition form; do not cancel the draw.','numeric','fasting_hours','lt',8.0,NULL,'hours',NULL,'["sample_collection", "visit"]','Participants must fast for at least 8 hours before the blood draw (water is allowed). If the participant has not fasted, record the time of their last meal on the requisition form; do not cancel the draw.',4,'3. Participant preparation',1,3,1,'2026-10-10T14:43:32+00:00','exception: "If the participant has not fasted, record the time of their last meal on the requisition form; do not cancel the draw." (not testable on numbers: a number hit goes to the judgment step)','[{"parameter": "exception_applies", "operator": "eq", "value": 1, "value2": null}]');
