INSERT INTO rules VALUES('MAP-lab_manual-sample_handling-007','NCT04098666','lab_manual','5d1571c6f2ae2171a2bd52388d0e5851710056f641cc79bbb22401939b8bd9e5','sample_handling','requirement','Record the exact time of the draw on the requisition form.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection"]','Record the exact time of the draw on the requisition form.',5,'4. Collection',1,6,1,'2026-10-10T14:43:32+00:00',NULL,NULL);
