INSERT INTO rules VALUES('MAP-lab_manual-sample_handling-009','NCT04098666','lab_manual','5d1571c6f2ae2171a2bd52388d0e5851710056f641cc79bbb22401939b8bd9e5','sample_handling','window','The K2EDTA tube must be centrifuged within 60 minutes of the blood draw.','numeric','minutes_draw_to_centrifuge','gt',60.0,NULL,'minutes',NULL,'["sample_collection"]','The K2EDTA tube must be centrifuged within 60 minutes of the blood draw.',6,'5. Processing of plasma',1,8,1,'2026-10-10T14:43:32+00:00',NULL,NULL);
