INSERT INTO rules VALUES('MAP-lab_manual-sample_handling-012','NCT04098666','lab_manual','5d1571c6f2ae2171a2bd52388d0e5851710056f641cc79bbb22401939b8bd9e5','sample_handling','window','Aliquots must be placed in a freezer at -80 degrees C within 2 hours of the blood draw. Samples that were not frozen within 2 hours of the blood draw must still be shipped but must be marked as a processing deviation on the requisition form, and the central laboratory must be told in the shipment notification. Exception: Samples that were not frozen within 2 hours of the blood draw must still be shipped but must be marked as a processing deviation on the requisition form, and the central laboratory must be told in the shipment notification.','numeric','hours_draw_to_freeze','gt',2.0,NULL,'hours',NULL,'["sample_collection"]','Aliquots must be placed in a freezer at -80 degrees C within 2 hours of the blood draw. Samples that were not frozen within 2 hours of the blood draw must still be shipped but must be marked as a processing deviation on the requisition form, and the central laboratory must be told in the shipment notification.',6,'5. Processing of plasma',1,11,1,'2026-10-10T14:43:32+00:00','exception: "Samples that were not frozen within 2 hours of the blood draw must still be shipped but must be marked as a processing d" (not testable on numbers: a number hit goes to the judgment step)','[{"parameter": "exception_applies", "operator": "eq", "value": 1, "value2": null}]');
INSERT INTO rules VALUES('MAP-lab_manual-sample_handling-013','NCT04098666','lab_manual','5d1571c6f2ae2171a2bd52388d0e5851710056f641cc79bbb22401939b8bd9e5','sample_handling','requirement','Every tube and cryovial must carry a printed kit label showing the participant ID, visit, collection date and collection time. Handwritten labels are not acceptable. Unlabeled or mislabeled samples will be rejected by the central laboratory.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "sample_shipment"]','Every tube and cryovial must carry a printed kit label showing the participant ID, visit, collection date and collection time. Handwritten labels are not acceptable. Unlabeled or mislabeled samples will be rejected by the central laboratory.',7,'6. Labeling',1,12,0,'2026-10-10T14:43:32+00:00','dropped by review (not_atomic): Rule 13 bundles several requirements: (a) every tube and cryovial must carry a printed kit label, (b) label must show participant ID, visit, collection date, and collection time, (c) handwritten labels are not acceptable, (d) unlabeled or mislabeled samples will be rejected. Each should be a separate rule.',NULL);
INSERT INTO rules VALUES('MAP-lab_manual-sample_handling-014','NCT04098666','lab_manual','5d1571c6f2ae2171a2bd52388d0e5851710056f641cc79bbb22401939b8bd9e5','sample_handling','requirement','Frozen aliquots must be stored at -80 degrees C until shipment.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "sample_shipment"]','Frozen aliquots must be stored at -80 degrees C until shipment.',8,'7. Storage',1,13,1,'2026-10-10T14:43:32+00:00',NULL,NULL);
