INSERT INTO rules VALUES('MAP-lab_manual-sample_handling-016','NCT04098666','lab_manual','5d1571c6f2ae2171a2bd52388d0e5851710056f641cc79bbb22401939b8bd9e5','sample_handling','prohibition','Samples must not be thawed and refrozen.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "sample_shipment"]','Samples must not be thawed and refrozen.',8,'7. Storage',1,15,1,'2026-10-10T14:43:32+00:00',NULL,NULL);
