INSERT INTO rules VALUES('DNL343-master-consent-008','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','consent','requirement','Site study staff must continuously provide information as the clinical investigation progresses or as the participant or situation requires.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','Site study staff must continuously provide information as the clinical investigation progresses or as the participant or situation requires.',32,'6.2 Consenting Participants',1,7,1,'2026-10-12T22:01:03+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-consent-009','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','consent','requirement','Consent for non-English speakers may be obtained using an sIRB approved consent form that has been translated into the participant''s spoken language. Sites should follow study MOPs and local policy on the use of translators.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','Consent for non-English speakers may be obtained using an sIRB approved consent form that has been translated into the participant''s spoken language. Sites should follow study MOPs and local policy on the use of translators.',33,'6.2 Consenting Participants',1,8,1,'2026-10-12T22:01:03+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-consent-010','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','consent','requirement','Participants may be required to reconsent to the Master Protocol or a regimen if new procedures or information is added in the future. Should a participant need to reconsent, this should occur during the participant''s next visit.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','Participants may be required to reconsent to the Master Protocol or a regimen if new procedures or information is added in the future. Should a participant need to reconsent, this should occur during the participant''s next visit.',33,'6.2 Consenting Participants',1,9,0,'2026-10-12T22:01:03+00:00','dropped: replaced by DNL343-regimen_g-consent-002 (regimen_g takes precedence): S2 requires reconsent at the next in-person visit, while G10 allows reconsent at the next visit regardless of type (in-person or remote).',NULL);
INSERT INTO rules VALUES('DNL343-master-consent-011','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','consent','requirement','If the participant''s next visit is conducted remotely, reconsent may also be completed remotely using the following procedures: 1. The site staff provides a copy of the informed consent form to the participant. 2. The participant reads through the consent form but does not sign. 3. The Site Investigator, or other study staff member approved and delegated to obtain informed consent, contacts the participant and reviews the informed consent form with the participant over the phone or via telemedicine. 4. The participant signs the informed consent form and provides the original signed consent form back to the site. Once received at the site, the individual who consented the participant via phone or telemedicine signs the informed consent form.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','If the participant''s next visit is conducted remotely, reconsent may also be completed remotely using the following procedures: 1. The site staff provides a copy of the informed consent form to the participant. 2. The participant reads through the consent form but does not sign. 3. The Site Investigator, or other study staff member approved and delegated to obtain informed consent, contacts the participant and reviews the informed consent form with the participant over the phone or via telemedicine. 4. The participant signs the informed consent form and provides the original signed consent form back to the site. Once received at the site, the individual who consented the participant via phone or telemedicine signs the informed consent form.',33,'6.2 Consenting Participants',1,10,0,'2026-10-12T22:01:03+00:00','dropped by review (not_atomic): Rule 11 bundles several steps of the remote reconsent process into one rule. Each step should be a separate atomic rule.',NULL);
INSERT INTO rules VALUES('DNL343-master-consent-012','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','consent','requirement','No study procedures are performed prior to the signing of the Master Protocol ICF. All participants will sign the Master Protocol ICF prior to undergoing any study tests or procedures.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization", "dosing", "sample_collection"]','No study procedures are performed prior to the signing of the Master Protocol ICF. All participants will sign the Master Protocol ICF prior to undergoing any study tests or procedures.',40,'8 STUDY SCHEDULE',1,11,1,'2026-10-12T22:01:03+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-consent-013','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','consent','requirement','Obtain written regimen-specific informed consent from participant at the Regimen Specific Screening Visit before performing regimen-specific procedures.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization", "dosing", "sample_collection"]','Obtain written regimen-specific informed consent from participant Assess regimen-specific inclusion and exclusion criteria Concomitant medication review Assess and document AEs',43,'8.2 Regimen Specific Screening Visit',1,12,1,'2026-10-12T22:01:03+00:00',NULL,NULL);
