INSERT INTO rules VALUES('DNL343-regimen_g-consent-006','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','consent','requirement','For remote reconsent, the Site Investigator, or other study staff member approved and delegated to obtain informed consent, contacts the participant and reviews the informed consent form with the participant.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','The Site Investigator, or other study staff member approved and delegated to obtain informed consent, contacts the participant and reviews the informed consent form with the participant.',35,'6. REGIMEN SCHEDULE',1,5,1,'2026-10-12T22:03:55+00:00','added_by_review',NULL);
