INSERT INTO rules VALUES('DNL343-regimen_g-consent-008','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','consent','requirement','For remote reconsent, once received at the site, the individual who consented the participant signs the informed consent form.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent"]','Once received at the site, the individual who consented the participant signs the informed consent form.',35,'6. REGIMEN SCHEDULE',1,7,1,'2026-10-12T22:03:55+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-001','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','inclusion','Sporadic or familial ALS diagnosed as clinically possible, probable, lab-supported probable, or definite ALS defined by revised El Escorial criteria (Appendix I).','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Sporadic or familial ALS diagnosed as clinically possible, probable, lab-supported probable, or definite ALS defined by revised El Escorial criteria (Appendix I).',29,'5.2.1 Master Protocol Inclusion Criteria',1,0,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-002','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','inclusion','Include only if age is 18 years or older at screening.','numeric','age_years','lt',18.0,NULL,'years',NULL,'["screening", "enrollment", "randomization"]','2. Age 18 years or older.',29,'5.2.1 Master Protocol Inclusion Criteria',1,1,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-003','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','inclusion','Include only if, in the SI''s opinion, the participant is capable of providing informed consent and complying with study procedures.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','3. Capable of providing informed consent and complying with study procedures, in the SI''s opinion.',29,'5.2.1 Master Protocol Inclusion Criteria',1,2,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-004','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','inclusion','Include only if time since onset of weakness due to ALS is 24 months or less at the time of the Master Protocol Screening Visit.','numeric','months_since_als_weakness_onset','gt',24.0,NULL,'months',NULL,'["screening", "enrollment", "randomization"]','4. Time since onset of weakness due to ALS ≤ 24 months at the time of the Master Protocol Screening Visit.',29,'5.2.1 Master Protocol Inclusion Criteria',1,3,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-005','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','inclusion','Include only if vital capacity is at least 50% of predicted capacity at the time of Master Protocol Screening measured by Slow Vital Capacity (SVC), or, if required due to pandemic-related restrictions, Forced Vital Capacity (FVC) measured in person.','numeric','vital_capacity_percent_predicted','lt',50.0,NULL,'percent',NULL,'["screening", "enrollment", "randomization"]','5. Vital Capacity ≥ 50% of predicted capacity at the time of Master Protocol Screening measured by Slow Vital Capacity (SVC), or, if required due to pandemic-related restrictions, Forced Vital Capacity (FVC) measured in person.',29,'5.2.1 Master Protocol Inclusion Criteria',1,4,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-006','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','inclusion','Include only if participant either does not take riluzole or has been on a stable dose of riluzole for at least 30 days prior to the Master Protocol Screening Visit.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','6. Participants must either not take riluzole or be on a stable dose of riluzole for ≥ 30 days prior to the Master Protocol Screening Visit.',29,'5.2.1 Master Protocol Inclusion Criteria',1,5,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-007','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','inclusion','Include only if participant either does not take edaravone or has completed at least one cycle (typically 14 days) of edaravone prior to the Master Protocol Screening Visit.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','7. Participants must either not take edaravone or have completed at least one cycle (typically 14 days) of edaravone prior to the Master Protocol Screening Visit.',29,'5.2.1 Master Protocol Inclusion Criteria',1,6,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-008','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','inclusion','Include only if participant has the ability to swallow pills and liquids at the time of the Master Protocol Screening Visit and, in the SI''s opinion, has the ability to swallow for the duration of the study.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','8. Participants must have the ability to swallow pills and liquids at the time of the Master Protocol Screening Visit and, in the SI''s opinion, have the ability to swallow for the duration of the study.',29,'5.2.1 Master Protocol Inclusion Criteria',1,7,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-009','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','inclusion','Include only if participant is geographically accessible to the site.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','9. Geographically accessible to the site.',29,'5.2.1 Master Protocol Inclusion Criteria',1,8,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-010','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if participant has a clinically significant unstable medical condition (other than ALS) that would pose a risk to the participant, according to SI''s judgment (e.g., cardiovascular instability, systemic infection), or clinically significant laboratory abnormality or EKG changes.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','1. Clinically significant unstable medical condition (other than ALS) that would pose a risk to the participant, according to SI''s judgment (e.g., cardiovascular instability, systemic infection,), or clinically significant laboratory abnormality or EKG changes.',30,'5.2.2 Master Protocol Exclusion Criteria',1,9,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-011','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if ALT or AST is greater than 3 times the upper limit of normal (ULN) at screening.','numeric','alt_or_ast_multiple_uln','gt',3.0,NULL,'x ULN',NULL,'["screening", "enrollment", "randomization"]','alanine aminotransferase (ALT) or aspartate aminotransferase (AST) > 3 times the upper limit of normal (ULN)',30,'5.2.2 Master Protocol Exclusion Criteria',1,10,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-012','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if estimated Glomerular Filtration Rate (eGFR) is less than 30 mL/min/1.73m² at screening.','numeric','egfr_ml_min_1_73m2','lt',30.0,NULL,'mL/min/1.73m2',NULL,'["screening", "enrollment", "randomization"]','The following values [alanine aminotransferase (ALT) or aspartate aminotransferase (AST) > 3 times the upper limit of normal (ULN) or estimated Glomerular Filtration Rate (eGFR) < 30 mL/min/1.73m°] are exclusionary regardless of clinical symptoms.',30,'5.2.2 Master Protocol Exclusion Criteria',1,11,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-013','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if participant has presence of unstable psychiatric disease, cognitive impairment, dementia or substance abuse that would impair ability to provide informed consent, in the SI''s opinion.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','2. Presence of unstable psychiatric disease, cognitive impairment, dementia or substance abuse that would impair ability of the participant to provide informed consent, in the SI''s opinion.',30,'5.2.2 Master Protocol Exclusion Criteria',1,12,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-014','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if participant has active cancer or history of cancer, except for basal cell carcinoma or successfully treated squamous cell carcinoma of the skin, cervical carcinoma in situ, prostatic carcinoma in situ, or other malignancies curatively treated and with no evidence of disease recurrence for at least 3 years.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','3. Active cancer or history of cancer, except for the following: basal cell carcinoma or successfully treated squamous cell carcinoma of the skin, cervical carcinoma in situ, prostatic carcinoma in situ, or other malignancies curatively treated and with no evidence of disease recurrence for at least 3 years.',30,'5.2.2 Master Protocol Exclusion Criteria',1,13,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-015','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if participant has used investigational treatments for ALS (off-label use or active participation in a clinical trial) within 5 half-lives (if known) or 30 days (whichever is longer) prior to the Master Protocol Screening Visit.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','4. Use of investigational treatments for ALS (off-label use or active participation in a clinical trial within 5 half-lives (if known) or 30 days (whichever is longer) prior to the Master Protocol Screening Visit.',30,'5.2.2 Master Protocol Exclusion Criteria',1,14,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-016','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if participant has had exposure at any time to any gene therapies under investigation for the treatment of ALS (off-label use or investigational).','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','5. Exposure at any time to any gene therapies under investigation for the treatment of ALS (off-label use or investigational).',30,'5.2.2 Master Protocol Exclusion Criteria',1,15,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-017','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if female and breastfeeding, known to be pregnant, planning to become pregnant during the study, or of child-bearing potential and unwilling to use effective contraception for the duration of the trial and for 3 months, or as specified in each RSA, after discontinuing study treatment.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','6. If female, breastfeeding, known to be pregnant, planning to become pregnant during the study, or of child-bearing potential and unwilling to use effective contraception, for the duration of the trial and for 3 months, or as specified in each RSA, after discontinuing study treatment.',30,'5.2.2 Master Protocol Exclusion Criteria',1,16,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-018','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if male of reproductive capacity and unwilling to use effective contraception for the duration of the trial and for 3 months, or as specified in each RSA, after discontinuing study treatment.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','7. If male of reproductive capacity, unwilling to use effective contraception for the duration of the trial and for 3 months, or as specified in each RSA, after discontinuing study treatment.',30,'5.2.2 Master Protocol Exclusion Criteria',1,17,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-019','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if, in the SI''s opinion, anything would place the participant at increased risk or preclude the participant''s full compliance with or completion of the study.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','8. Anything that would place the participant at increased risk or preclude the participant''s full compliance with or completion of the study, in the SI''s opinion.',30,'5.2.2 Master Protocol Exclusion Criteria',1,18,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-020','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if a participant is being re-screened and the disqualifying condition has not been resolved, or the mandatory wash-out duration has not occurred.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','9. If a participant is being re-screened, the disqualifying condition has not been resolved, or the mandatory wash-out duration has not occurred.',30,'5.2.2 Master Protocol Exclusion Criteria',1,19,1,'2026-10-12T21:58:57+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-021','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','inclusion','To be eligible for this study, the date of symptom onset must be no greater than 24 months prior to the Master Protocol Screening Visit date.','numeric','months_symptom_onset_to_screening','gt',24.0,NULL,'months',NULL,'["screening", "enrollment", "randomization"]','To be eligible for this study, the date of symptom onset must be no greater than 24 months prior to the Master Protocol Screening Visit date.',31,'5.2.1 Master Protocol Inclusion Criteria',1,20,0,'2026-10-12T21:58:57+00:00','dropped by review (duplicate): repeats a kept rule (Rule 21 duplicates rule 4: both require symptom onset to be no more than 24 months prior to screening. Rule 4 is more general and covers the requirement.)',NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-022','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','requirement','Each SI will be responsible for enrolling into the Master Protocol only those study participants who have met all Master Protocol eligibility criteria, and for enrolling into a Regimen only those study participants who have met the additional eligibility criteria (if any) of the corresponding RSA.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["enrollment", "randomization"]','Each SI will be responsible for enrolling into the Master Protocol only those study participants who have met all Master Protocol eligibility criteria, and for enrolling into a Regimen only those study participants who have met the additional eligibility criteria (if any) of the corresponding RSA.',22,'1.5 Protocol Adherence',1,21,1,'2026-10-12T21:58:57+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-023','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','requirement','Those participants who are not found eligible for the Master Protocol will not be consented for any regimen.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["enrollment", "randomization"]','Those participants who are not found eligible for the Master Protocol will not be consented for any regimen.',33,'5.2.1 Master Protocol Inclusion Criteria',1,22,1,'2026-10-12T21:58:57+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-024','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','requirement','Reasons for ineligibility for the regimen must be documented.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Reasons for ineligibility for the regimen must be documented',33,'6.4 Randomization 6.4.1 Randomization Procedures',1,23,1,'2026-10-12T21:58:57+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-025','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','requirement','If it is known at the time of regimen assignment that the participant is not eligible for the regimen, a participant may be administratively screen-failed for a regimen prior to regimen consent and screening.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','If it is known at the time of regimen assignment that the participant is not eligible for the regimen, a participant may be administratively screen-failed for a regimen prior to regimen consent and screening.',42,'6.4 Randomization 6.4.1 Randomization Procedures',1,24,1,'2026-10-12T21:58:57+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-026','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','requirement','If a research participant fails to meet a time-dependent Master Protocol eligibility criterion (e.g., duration of stable medication prior to enrollment, interval following last use of an investigational treatment, or other criteria as applicable), then that participant may become eligible immediately after resolution of the disqualifying condition if resolution occurs within the screening period and re-screening is not required.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','If a research participant fails to meet a time-dependent Master Protocol eligibility criterion (e.g., duration of stable medication prior to enrollment, interval following last use of an investigational treatment, or other criteria as applicable), then that participant may become eligible immediately after resolution of the disqualifying condition if resolution occurs within the screening period and re-screening is not required.',42,'6.4 Randomization 6.4.1 Randomization Procedures',1,25,1,'2026-10-12T21:58:57+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-027','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','requirement','Safety labs required for the site investigator to determine eligibility, can be repeated during the Master Protocol screening period, if necessary.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Safety labs required for the site investigator to determine eligibility, can be repeated during the Master Protocol screening period, if necessary.',42,'6.4 Randomization 6.4.1 Randomization Procedures',1,26,1,'2026-10-12T21:58:57+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-eligibility-028','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','eligibility','exclusion','Exclude if clinically significant abnormal liver or kidney function is present at screening, as determined by the SI, regardless of clinical symptoms.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Clinically significant abnormal liver or kidney function is exclusionary.',30,'5.2.2 Master Protocol Exclusion Criteria',1,27,1,'2026-10-12T21:58:57+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-001','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Diagnosis of epilepsy currently requiring antiepileptic therapy, or seizure of any cause within 6 months of randomization','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Participants who meet any of the following criteria will be excluded from study entry: 1. Diagnosis of epilepsy currently requiring antiepileptic therapy, or seizure of any cause within 6 months of randomization',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,0,1,'2026-10-12T22:02:19+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-002','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Exclude if participant has hypersensitivity to DNL343 or any of the excipients contained within the DNL343 drug product.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','2. Hypersensitivity to DNL343 or any of the excipients contained within the DNL343 drug product',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,1,0,'2026-10-12T22:02:19+00:00','dropped by review (not_atomic): The rule bundles two conditions: hypersensitivity to DNL343 and hypersensitivity to any excipient. These should be split into two atomic rules.',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-003','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Exclude if participant used prescription or OTC medications (including herbal medicines such as St. John’s wort) that are strong CYP3A4/5 inducers within 2 weeks or 5 half-lives (whichever is longer) of the first dose administration or anticipates use during the study treatment period.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','3. Use of prescription or over-the-counter (OTC) medications (including herbal medicines such as St. John’s wort) that are strong CYP3A4/5 inducers within 2 weeks or 5 half-lives (whichever is longer) of the first dose administration or anticipated use during the study treatment period (see Section 5.9)',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,2,1,'2026-10-12T22:02:19+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-004','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Exclude if participant used prescription or OTC medications that are sensitive CYP3A4/5 substrates with a narrow therapeutic index within 7 days or 5 half-lives (whichever is longer) of the first dose administration or anticipates use during the study treatment period.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','4. Use of prescription or OTC medications that are sensitive CYP3A4/5 substrates with a narrow therapeutic index within 7 days or 5 half-lives (whichever is longer) of the first dose administration or anticipated use during the study treatment period (see Section 5.9)',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,3,1,'2026-10-12T22:02:19+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-005','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Exclude if participant used prescription or OTC medications that are substrates for BCRP or OAT3 transporters and have a narrow therapeutic index within 7 days or 5 half-lives (whichever is longer) of the first dose administration or anticipates use during the study treatment period.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','5. Use of prescription or OTC medications that are substrates for breast cancer resistance protein (BCRP) or organic anion transporter (OAT)3 transporters and have a narrow therapeutic index within 7 days or 5 half-lives (whichever is longer) of the first dose administration or anticipated use during the study treatment period (see Section 5.9)',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,4,1,'2026-10-12T22:02:19+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-006','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Exclude if participant has hypersensitivity to DNL343.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','2. Hypersensitivity to DNL343 or any of the excipients contained within the DNL343 drug product',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,5,1,'2026-10-12T22:02:19+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-007','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Exclude if participant has hypersensitivity to any of the excipients contained within the DNL343 drug product.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','2. Hypersensitivity to DNL343 or any of the excipients contained within the DNL343 drug product',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,6,1,'2026-10-12T22:02:19+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-008','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','inclusion','In order to be randomized to Regimen G, participants must meet the Master Protocol eligibility criteria. In addition, participants meeting all of the following inclusion and exclusion criteria will be allowed to enroll in Regimen G.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','In order to be randomized to Regimen G, participants must meet the Master Protocol eligibility criteria. In addition, participants meeting all of the following inclusion and exclusion criteria will be allowed to enroll in Regimen G.',26,'4.2 Inclusion and Exclusion Criteria',1,7,0,'2026-10-12T22:02:19+00:00','dropped by review (not_stated): This is not an eligibility criterion but a statement of process: it says participants must meet Master Protocol eligibility and the Regimen G criteria, but does not itself specify a checkable criterion. The actual eligibility criteria are in the Master Protocol and the Regimen G list.',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-009','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','inclusion','For female participants, one of the following must apply: a. Postmenopausal (defined as no menses for ≥ 12 consecutive months before screening without an alternative medical cause, with a follicle-stimulating hormone level of > 40 IU/L or mIU/mL at screening) b. Surgically sterilized (eg, hysterectomy, bilateral salpingectomy, bilateral oophorectomy) at least 6 months before dosing OR c. For participants of childbearing potential: both the participant and the male partner must use highly effective contraception at the start of dosing, throughout the study period, and for 90 days after the final administration of study drug.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','pendix G, DNL343 Page 32 of 69 Version 2.0, 12/18/2023 a. Postmenopausal (defined as no menses for ≥ 12 consecutive months before screening without an alternative medical cause, with a follicle-stimulating hormone level of > 40 IU/L or mIU/mL at screening) b. Surgically sterilized (eg, hysterectomy, bilateral salpingectomy, bilateral oophorectomy) at least 6 months before dosing OR c. For participants of childbearing potential: both the participant and the male partner must use highly effective contraception at the start of dosing, throughout the study period, and for 90 days after the final administration of study drug. High',33,'4.2.1 Regimen-Specific Appendix Inclusion Criteria',1,8,0,'2026-10-12T22:02:19+00:00','dropped by review (not_atomic): This rule bundles several alternative conditions (postmenopausal, surgically sterilized, or contraception requirements for women of childbearing potential). Each should be a separate rule.',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-010','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','requirement','Highly effective contraception consists of two forms of birth control, one of which must be a male barrier method such as a latex or polyurethane condom. The other must be a highly effective method (as defined in Appendix III).','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','. Highly effective contraception consists of two forms of birth control, one of which must be a male barrier method such as a latex or polyurethane condom. The other must be a highly effective method (as defined in Appendix III)',33,'4.2.1 Regimen-Specific Appendix Inclusion Criteria',1,9,1,'2026-10-12T22:02:19+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-011','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','requirement','For male participants: When engaging in sex with a female partner of childbearing potential, both the male participant and his female partner must use highly effective contraception consisting of two forms of birth control, one of which must be a male barrier method such as a latex or polyurethane condom, and the other of which must be a highly effective form of birth control (as defined in Appendix III) used by the female partner. This is required from the start of dosing, throughout the study period, and for 90 days after the final administration of study drug.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','For male participants: a. When engaging in sex with a female partner of childbearing potential, both the male participant and his female partner must use highly effective contraception consisting of two forms of birth control, one of which must be a male barrier method such as a latex or polyurethane condom, and the other of which must be a highly effective form of birth control (as defined in Appendix III) used by the female partner. This is required from the start of dosing, throughout the study period, and for 90 days after the final administration of study dru',33,'4.2.1 Regimen-Specific Appendix Inclusion Criteria',1,10,1,'2026-10-12T22:02:19+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-012','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Diagnosis of epilepsy currently requiring antiepileptic therapy, or seizure of any cause within 6 months of randomization.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Diagnosis of epilepsy currently requiring antiepileptic therapy, or seizure of any cause within 6 months of randomization',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,11,0,'2026-10-12T22:02:19+00:00','dropped: duplicate of rule 1',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-013','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Hypersensitivity to DNL343.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Hypersensitivity to DNL343 or any of the excipients contained within the DNL343 drug product',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,12,1,'2026-10-12T22:02:19+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-014','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Hypersensitivity to any of the excipients contained within the DNL343 drug product.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Hypersensitivity to DNL343 or any of the excipients contained within the DNL343 drug product',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,13,1,'2026-10-12T22:02:19+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-015','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Use of prescription or over-the-counter (OTC) medications (including herbal medicines such as St. John’s wort) that are strong CYP3A4/5 inducers within 2 weeks or 5 half-lives (whichever is longer) of the first dose administration or anticipated use during the study treatment period.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Use of prescription or over-the-counter (OTC) medications (including herbal medicines such as St. John’s wort) that are strong CYP3A4/5 inducers within 2 weeks or 5 half-lives (whichever is longer) of the first dose administration or anticipated use during the study treatment period',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,14,1,'2026-10-12T22:02:19+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-016','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Use of prescription or OTC medications that are sensitive CYP3A4/5 substrates with a narrow therapeutic index within 7 days or 5 half-lives (whichever is longer) of the first dose administration or anticipated use during the study treatment period.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Use of prescription or OTC medications that are sensitive CYP3A4/5 substrates with a narrow therapeutic index within 7 days or 5 half-lives (whichever is longer) of the first dose administration or anticipated use during the study treatment period',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,15,0,'2026-10-12T22:02:19+00:00','dropped: duplicate of rule 3',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-017','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','exclusion','Use of prescription or OTC medications that are substrates for breast cancer resistance protein (BCRP) or organic anion transporter (OAT)3 transporters and have a narrow therapeutic index within 7 days or 5 half-lives (whichever is longer) of the first dose administration or anticipated use during the study treatment period.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Use of prescription or OTC medications that are substrates for breast cancer resistance protein (BCRP) or organic anion transporter (OAT)3 transporters and have a narrow therapeutic index within 7 days or 5 half-lives (whichever is longer) of the first dose administration or anticipated use during the study treatment period',26,'4.2.2 Regimen-Specific Appendix Exclusion Criteria',1,16,1,'2026-10-12T22:02:19+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-018','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','inclusion','For female participants, one of the following must apply: (a) Postmenopausal (defined as no menses for ≥ 12 consecutive months before screening without an alternative medical cause, with a follicle-stimulating hormone level of > 40 IU/L or mIU/mL at screening); (b) Surgically sterilized (eg, hysterectomy, bilateral salpingectomy, bilateral oophorectomy) at least 6 months before dosing; (c) For participants of childbearing potential: both the participant and the male partner must use highly effective contraception at the start of dosing, throughout the study period, and for 90 days after the final administration of study drug; (d) For participants of childbearing potential with an azoospermic male partner, the male partner must use a male barrier method such as a latex or polyurethane condom.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','a. Postmenopausal (defined as no menses for ≥ 12 consecutive months before screening without an alternative medical cause, with a follicle-stimulating hormone level of > 40 IU/L or mIU/mL at screening) b. Surgically sterilized (eg, hysterectomy, bilateral salpingectomy, bilateral oophorectomy) at least 6 months before dosing OR c. For participants of childbearing potential',33,'5.10.2 Contraceptive Requirements for Participants in Regimen G',1,17,1,'2026-10-12T22:02:19+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-019','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','inclusion','For female participants: Postmenopausal, defined as no menses for ≥ 12 consecutive months before screening without an alternative medical cause, with a follicle-stimulating hormone level of > 40 IU/L or mIU/mL at screening.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Postmenopausal (defined as no menses for ≥ 12 consecutive months before screening without an alternative medical cause, with a follicle-stimulating hormone level of > 40 IU/L or mIU/mL at screening)',33,'5.10.2 Contraceptive Requirements for Participants in Regimen G',1,18,1,'2026-10-12T22:02:19+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-020','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','inclusion','For female participants: Surgically sterilized (eg, hysterectomy, bilateral salpingectomy, bilateral oophorectomy) at least 6 months before dosing.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','Surgically sterilized (eg, hysterectomy, bilateral salpingectomy, bilateral oophorectomy) at least 6 months before dosing',33,'5.10.2 Contraceptive Requirements for Participants in Regimen G',1,19,1,'2026-10-12T22:02:19+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-021','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','requirement','For female participants of childbearing potential: both the participant and the male partner must use highly effective contraception at the start of dosing, throughout the study period, and for 90 days after the final administration of study drug.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','For participants of childbearing potential: both the participant and the male partner must use highly effective contraception at the start of dosing, throughout the study period, and for 90 days after the final administration of study drug.',33,'5.10.2 Contraceptive Requirements for Participants in Regimen G',1,20,1,'2026-10-12T22:02:19+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-eligibility-022','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','eligibility','requirement','For female participants of childbearing potential with an azoospermic male partner, the male partner must use a male barrier method such as a latex or polyurethane condom.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization"]','For participants of childbearing potential with an azoospermic male partner, the male partner must use a male barrier method such as a latex or polyurethane condom.',33,'5.10.2 Contraceptive Requirements for Participants in Regimen G',1,21,1,'2026-10-12T22:02:19+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-001','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','Administer first dose of study drug only after Baseline Visit procedures are completed','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["dosing", "visit"]','Administer first dose of study drug only after Baseline Visit procedures are completed',16,'Schedule of Activities (page 15)',1,0,1,'2026-10-12T21:59:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-002','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','Assessment of vital capacity should be performed at the start of a visit so as not to fatigue the participant with other testing.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit"]','Assessment of vital capacity should be performed at the start of a visit so as not to fatigue the participant with other testing.',40,'8 STUDY SCHEDULE (page 40)',1,1,1,'2026-10-12T21:59:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-003','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','The remaining clinical assessments should be administered in the same sequence as listed in the sections below and at approximately the same time of the day.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit"]','The remaining clinical assessments should be administered in the same sequence as listed in the sections below and at approximately the same time of the day.',40,'8 STUDY SCHEDULE (page 40)',1,2,1,'2026-10-12T21:59:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-004','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','Any additional assessments that are included in an RSA for a given visit should be completed once the Master Protocol SOA for that visit is complete, unless otherwise specified in the RSA.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit"]','Any additional assessments that are included in an RSA for a given visit should be completed once the Master Protocol SOA for that visit is complete, unless otherwise specified in the RSA.',40,'8 STUDY SCHEDULE (page 40)',1,3,1,'2026-10-12T21:59:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-005','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','Randomize within the regimen before administering the first dose of investigational product for the regimen.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["randomization", "dosing"]','Administer first dose of investigational product for the regimen, per the instructions in the RSA',43,'8.3 Baseline Visit (page 42)',1,4,1,'2026-10-12T21:59:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-006','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','Obtain written regimen-specific informed consent before assessing regimen-specific inclusion and exclusion criteria at the Regimen Specific Screening Visit.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["consent", "enrollment"]','Obtain written regimen-specific informed consent from participant Assess regimen-specific inclusion and exclusion criteria',43,'8.2 Regimen Specific Screening Visit (page 43)',1,5,0,'2026-10-12T21:59:58+00:00','dropped by review (not_atomic): This rule bundles two conditions: obtaining consent and assessing eligibility. Each should be a separate atomic rule.',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-007','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','At the Master Protocol Screening Visit, perform procedures in the preferred order: assess Master Protocol inclusion and exclusion criteria, obtain ALS and medical history, obtain demographics, perform Vital Capacity, perform physical examination, perform neurological examination, measure vital signs including height and weight, administer ALSFRS-R questionnaire, perform 12-lead ECG, collect blood samples for clinical screening assessments (including coagulation parameters) and, for women of child bearing potential, for pregnancy test, collect urine for urinalysis, collect blood biomarker sample, review and document concomitant medications, assess and document AEs, schedule the Regimen Specific Screening Visit if the participant passes screening for the Master Protocol.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "visit", "sample_collection"]','The following procedures will be performed in-person, after Master Protocol informed consent is obtained, to determine the participant''s eligibility for the Master Protocol and are listed in preferred order to be completed: Assess Master Protocol inclusion and exclusion criteria: Obtain ALS and medical history Obtain demographics Perform Vital Capacity Perform physical examination Perform neurological examination Measure vital signs including height and weight Administer ALSFRS-R questionnaire Perform 12-lead electrocardiogram (ECG) Collect blood samples for clinical screening assessments (including coagulation parameters) and, for women of child bearing potential (WOCBP), for pregnancy test Collect urine for urinalysis Collect blood biomarker sample Review and document concomitant medications Assess and document AEs Schedule the Regimen Specific Screening Visit if the participant passes screening for the Master Protocol',41,'8.1 Master Protocol Screening Visit (page 41)',1,6,1,'2026-10-12T21:59:58+00:00','kept: review said it bundles conditions but did not split it (This rule bundles a long sequence of procedures as a single rule. Each step should be a separate atomic rule for procedure order.)',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-008','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','At the Regimen Specific Screening Visit, perform procedures in the preferred order: obtain written regimen-specific informed consent, assess regimen-specific inclusion and exclusion criteria, review concomitant medications, assess and document AEs.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["enrollment", "visit"]','The following procedures will be performed and are listed in preferred order to be completed: Obtain written regimen-specific informed consent from participant Assess regimen-specific inclusion and exclusion criteria Concomitant medication review Assess and document AEs',43,'8.2 Regimen Specific Screening Visit (page 43)',1,7,0,'2026-10-12T21:59:58+00:00','dropped by review (not_atomic): This rule bundles multiple procedures into one rule. Each procedure should be a separate atomic rule for sequence checking.',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-009','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','At the Baseline Visit, perform procedures in the preferred order: randomize within the regimen, collect vital signs, perform SVC, administer ALSFRS-R questionnaire, ask participant to complete Patient Reported Outcomes, collect blood samples for Clinical Safety Labs, biomarkers, and optional DNA sequencing, collect urine for urinalysis, collect blood biomarker sample, perform LP for CSF collection (as described in the RSA), review and document concomitant medications, assess and document AEs, administer the C-SSRS Baseline questionnaire, administer first dose of investigational product for the regimen, dispense investigational product to participant, instruct participant to bring in investigational product to the Week 4 visit.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "dosing", "sample_collection"]','The following procedures will be performed and are listed in preferred order to be completed: Randomize within the regimen Collect vital signs Perform SVC Administer ALSFRS-R questionnaire Ask participant to complete Patient Reported Outcomes Collect blood samples for Clinical Safety Labs, biomarkers, and optional DNA sequencing Collect urine for urinalysis Collect blood biomarker sample Perform LP for CSF collection (as described in the RSA) Review and document concomitant medications Assess and document AEs Administer the C-SSRS Baseline questionnaire Administer first dose of investigational product for the regimen, per the instructions in the RSA. Dispense investigational product to participant, per instructions in the RSA Instruct participant to bring in investigational product to the Week 4 visit',43,'8.3 Baseline Visit (page 42)',1,8,1,'2026-10-12T21:59:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-010','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','At the Week 4 Visit, perform procedures in the preferred order: collect vital signs, administer ALSFRS-R questionnaire, collect blood samples for Clinical Safety Labs and, for WOCBP, for pregnancy test if applicable, collect urine for urinalysis, review and document concomitant medications, assess and document AEs, administer the C-SSRS Since Last Visit questionnaire, collect blood for optional DNA sequencing (if not done at Baseline), perform investigational product accountability and compliance, dispense investigational product to participant, schedule next Study Visit, remind participant to bring in investigational product to the Week 8 Visit.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "sample_collection"]','The following procedures will be performed and are listed in the preferred order to be completed',43,'8.5 Week 4 Visit (page 44)',1,9,1,'2026-10-12T21:59:58+00:00','kept: review said it bundles conditions but did not split it (This rule bundles multiple procedures into one rule. Each procedure should be a separate atomic rule for sequence checking.)',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-011','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','At the Week 8 Visit, perform procedures in the preferred order: collect vital signs including weight, perform SVC, administer ALSFRS-R questionnaire, collect blood samples for Clinical Safety Labs and, for WOCBP, for pregnancy test if applicable, collect urine for urinalysis, collect blood sample for biomarker analyses, collect blood for optional DNA sequencing (if not done previously), review and document concomitant medications, assess and document AEs, administer the C-SSRS Since Last Visit questionnaire, perform investigational product accountability and compliance, dispense investigational product to participant.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "sample_collection"]','The following procedures will be performed and are listed in the preferred order to be completed: Collect vital signs including weight Perform SVC Administer ALSFRS-R questionnaire Collect blood samples for Clinical Safety Labs and, for WOCBP, for pregnancy test if applicable Collect urine for urinalysis Collect blood sample for biomarker analyses Collect blood for optional DNA sequencing (if not done previously) Review and document concomitant medications Assess and document AEs Administer the C-SSRS Since Last Visit questionnaire Perform investigational product accountability and compliance Dispense investigational product to participant, per instructions in the RSA',44,'8.6 Week 8 Visit (page 44)',1,10,1,'2026-10-12T21:59:58+00:00','kept: review said it bundles conditions but did not split it (This rule bundles multiple procedures into one rule. Each procedure should be a separate atomic rule for sequence checking.)',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-012','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','At the Week 16 Visit, perform procedures in the preferred order: collect vital signs including weight, perform SVC, administer ALSFRS-R questionnaire, collect blood samples for Clinical Safety Labs (including coagulation parameters) and, for WOCBP, for pregnancy test if applicable, collect urine for urinalysis, collect blood sample for biomarker analyses, collect blood for optional DNA sequencing (if not done previously), review and document concomitant medications, assess and document AEs, administer the C-SSRS Since Last Visit questionnaire, perform LP for CSF collection (or as described in the RSA), perform investigational product accountability and compliance, dispense investigational product to participant.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "sample_collection"]','The following procedures will be performed and are listed in the preferred order to be completed: Collect vital signs including weight Perform SVC Administer ALSFRS-R questionnaire Collect blood samples for Clinical Safety Labs (including coagulation parameters) and, for WOCBP, for pregnancy test if applicable Collect urine for urinalysis Collect blood sample for biomarker analyses Collect blood for optional DNA sequencing (if not done previously) Review and document concomitant medications Assess and document AEs Administer the C-SSRS Since Last Visit questionnaire Perform LP for CSF collection (or as described in the RSA) Perform investigational product accountability and compliance Dispense investigational product to participant, per instructions in the RSA',45,'8.8 Week 16 Visit (page 45)',1,11,1,'2026-10-12T21:59:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-013','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','At the Week 24 Visit, perform procedures in the preferred order: collect vital signs including weight, perform SVC, administer ALSFRS-R questionnaire, ask participant to complete Patient Reported Outcomes, collect blood samples for Clinical Safety Labs and, for WOCBP, for pregnancy test if applicable, collect urine for urinalysis, collect blood sample for biomarker analyses, collect blood for optional DNA sequencing (if not done previously), review and document concomitant medications, assess and document AEs, administer the C-SSRS Since Last Visit questionnaire, perform investigational product accountability and compliance, dispense investigational product to participant.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "sample_collection"]','The following procedures will be performed and are listed in the preferred order to be completed',45,'8.10 Week 24 Visit (page 44)',1,12,1,'2026-10-12T21:59:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-014','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','At the Week 36 Visit, perform procedures in the preferred order: collect vital signs including weight, perform SVC, administer ALSFRS-R questionnaire, ask participant to complete Patient Reported Outcomes, perform 12-lead ECG, collect blood samples for Clinical Safety Labs and, for WOCBP, for pregnancy test if applicable, collect urine for urinalysis, collect blood sample for biomarker analyses, collect blood for optional DNA sequencing (if not done previously), review and document concomitant medications, assess and document AEs, administer the C-SSRS Since Last Visit questionnaire, perform investigational product accountability and compliance, ask participant to complete the Exit Questionnaire.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "sample_collection"]','The following procedures will be performed and are listed in the preferred order to be completed',45,'8.10 Week 36 Visit (page 45)',1,13,1,'2026-10-12T21:59:58+00:00','kept: review said it bundles conditions but did not split it (This rule bundles multiple procedures into one rule. Each procedure should be a separate atomic rule for sequence checking.)',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-015','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','The DNA sample can be collected after the Baseline Visit if a baseline sample is not obtained or the sample is not usable.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection"]','The DNA sample can be collected after the Baseline Visit if a baseline sample is not obtained or the sample is not usable.',16,'Schedule of Activities (page 15); 9.3.1 DNA Collection (page 53)',1,14,1,'2026-10-12T21:59:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-016','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','requirement','Obtain written regimen-specific informed consent before assessing regimen-specific inclusion and exclusion criteria at the Regimen Specific Screening Visit.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["enrollment", "screening"]','Obtain written regimen-specific informed consent from participant Assess regimen-specific inclusion and exclusion criteria',43,'8.2 Regimen Specific Screening Visit',1,15,1,'2026-10-12T21:59:58+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-017','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','requirement','Assess regimen-specific inclusion and exclusion criteria after obtaining written regimen-specific informed consent at the Regimen Specific Screening Visit.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["enrollment", "screening"]','Obtain written regimen-specific informed consent from participant Assess regimen-specific inclusion and exclusion criteria',43,'8.2 Regimen Specific Screening Visit',1,16,1,'2026-10-12T21:59:58+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-018','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','Randomization to a regimen must occur only after the participant is determined eligible according to the Master Protocol inclusion and exclusion criteria.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["randomization"]','In the first stage, after a participant is determined eligible according to the Master Protocol inclusion and exclusion criteria, a research participant will be randomly assigned equally among all available regimens to which the participant has not previously been assigned.',34,'6.4.1 Regimen Assignment and Randomization',1,17,1,'2026-10-12T21:59:58+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-019','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','Randomization to active treatment or placebo within a regimen must occur only after the participant is determined eligible by meeting all inclusion and no exclusion criteria specific to their assigned regimen.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["randomization"]','In the second stage, if a participant has been determined eligible by meeting all inclusion and no exclusion criteria specific to their assigned regimen, the research participant will be randomized 3:1 to the active intervention or the placebo for the regimen.',34,'6.4.1 Regimen Assignment and Randomization',1,18,1,'2026-10-12T21:59:58+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-020','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','Randomization into treatment group within a regimen must be facilitated via the IRT system after a participant has been determined eligible for any inclusion and exclusion criteria specific to their assigned regimen.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["randomization"]','Randomization into treatment group within a regimen will be facilitated via the IRT system after a participant has been determined eligible for any inclusion and exclusion criteria specific to their assigned regimen.',34,'6.4.2 Treatment Allocation',1,19,1,'2026-10-12T21:59:58+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-021','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','The Regimen Specific Screening Visit must take place in-person after random assignment to a regimen.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit"]','8.2 Regimen Specific Screening Visit This visit will take place in-person after random assignment to a regimen.',43,'8.2 Regimen Specific Screening Visit',1,20,1,'2026-10-12T21:59:58+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-022','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','The following procedures should be completed in the suggested order and as per the Schedule of Activities: ALSFRS-R, AE Review, Columbia-Suicide Severity Rating Scale, Concomitant Medications, IP Accountability/Compliance, and shipment of IP as applicable; each RA may describe additional activities.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit"]','The following procedures should be completed in the suggested order and as per the Schedule of Activities: ALSFRS-R, AE Review, Columbia-Suicide Severity Rating Scale, Concomitant Medications, IP Accountability/Compliance, and shipment of IP as applicable; each RA may describe additional activities.',40,'8.11 Visit Procedures Order',1,21,1,'2026-10-12T21:59:58+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-procedure_sequence-023','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','procedure_sequence','sequence','No study procedures are performed prior to the signing of the Master Protocol ICF.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening", "enrollment", "randomization", "visit", "contact", "dosing", "imaging", "sample_collection"]','No study procedures are performed prior to the signing of the Master Protocol ICF. All participants will sign the Master Protocol ICF prior to undergoing any study tests or procedures.',40,'8 STUDY SCHEDULE',1,22,1,'2026-10-12T21:59:58+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-001','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','sequence','Administer the first dose of study drug only after the Baseline Visit procedures are completed.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["dosing"]','Administer the first dose of study drug only after the Baseline Visit procedures are completed.',13,'Schedule of Activities – Placebo-controlled Treatment period (Table footnote 8), page 12',1,0,1,'2026-10-12T22:02:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-002','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','sequence','For the Baseline visit, CSF may be collected at any time within one week prior to administration of the first dose of study medication after Regimen G eligibility is confirmed.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "dosing"]','For the Baseline visit, CSF may be collected at any time within one week prior to administration of the first dose of study medication after Regimen G eligibility is confirmed.',36,'Schedule of Activities – Placebo-controlled Treatment period (Table footnote 16), page 12',1,1,1,'2026-10-12T22:02:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-003','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','sequence','For participants continuing into ATE, CSF collection must occur prior to taking the first dose of study medication from the ATE period.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "dosing"]','For participants continuing into ATE, CSF collection must occur prior to taking the first dose of study medication from the ATE period.',13,'Schedule of Activities – Placebo-controlled Treatment period (Table footnote 16), page 12',1,2,1,'2026-10-12T22:02:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-004','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','sequence','At the Week 4 visit, study drug should not be taken until after study visit procedures are complete.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["dosing", "visit"]','On the day of the Week 4 visit the participant should take their daily dose in-clinic. Study drug should not be taken until after study visit procedures are complete.',37,'6.3 Week 4 and 8 Visits, page 36',1,3,1,'2026-10-12T22:02:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-005','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','sequence','At the Week 24 Visit, the participant should not take any dose from the placebo-controlled period and take their ATE dose in-clinic. Study drug should not be taken until after study visit procedures are complete.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["dosing", "visit"]','On the day of the Week 24 Visit, the participant should not take any dose from the placebo-controlled period and take their ATE dose in-clinic. Study drug should not be taken until after study visit procedures are complete.',NULL,'6.7 Week 24 Visit or Early Termination Visit, page 38',0,4,0,'2026-10-12T22:02:58+00:00','quote not found in the document',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-006','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','sequence','For the Week 24 Visit, optional CSF collection must occur prior to taking the first dose from the ATE period.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "dosing"]','For participants continuing into ATE, optional CSF collection must occur prior to taking the first dose from the ATE period.',39,'6.7 Week 24 Visit or Early Termination Visit, page 38',1,5,0,'2026-10-12T22:02:58+00:00','dropped by review (duplicate): Rule 6 is a duplicate of rule 3. Both state that for participants continuing into ATE, CSF collection must occur prior to taking the first dose of study medication from the ATE period.',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-007','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','sequence','For the Week 4 and Week 24 visits with a predose PK sample, the predose sample should be collected prior to dosing (ie, any time 0 to 2 hours before the dose) and approximately 24 hours after the most recent dose.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "dosing"]','For visits with a predose PK sample (Week 4 and Week 24), these visits should be scheduled for the morning and participants should take their dose in the clinic at approximately the same time in the morning as usual. The predose sample should be collected prior to dosing (ie, any time 0 to 2 hours before the dose) and approximately 24 hours after the most recent dose.',13,'Schedule of Activities – Placebo-controlled Treatment period (Table footnote 15), page 12',1,6,1,'2026-10-12T22:02:58+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-008','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','sequence','For the Week 24 Visit, CSF collection may occur on a separate date from the other assessments scheduled at the Week 24 Visit, provided CSF collection occurs within the allowed window for the Week 24 Visit as defined in the protocol. For participants continuing into ATE, optional CSF collection must occur prior to taking the first dose from the ATE period. The date of the other assessments (ie, not the date of CSF collection) will be considered the date of the Week 24 Visit.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "dosing", "visit"]','CSF collection may occur on a separate date from the other assessments scheduled at the Week 24 Visit, provided CSF collection occurs within the allowed window for the Week 24 Visit as defined in the protocol. For participants continuing into ATE, optional CSF collection must occur prior to taking the first dose from the ATE period. The date of the other assessments (ie, not the date of CSF collection) will be considered the date of the Week 24 Visit.',39,'6.7 Week 24 Visit or Early Termination Visit, page 38',1,7,0,'2026-10-12T22:02:58+00:00','dropped by review (not_atomic): Rule 8 bundles several conditions: (1) CSF collection may occur on a separate date from other assessments at Week 24, (2) CSF collection must occur within the allowed window for the Week 24 Visit, (3) for participants continuing into ATE, CSF collection must occur prior to taking the first ATE dose, (4) the date of the other assessments is considered the date of the Week 24 Visit. These should be split into atomic rules.',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-009','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','sequence','At the Week 16 ATE Visit, participants should be instructed to hold study drug on the day of the study visit. Study drug should not be taken until after study visit procedures are complete.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["dosing", "visit"]','Participants should be instructed to hold study drug on the day of the study visit. Study drug should not be taken until after study visit procedures are complete.',43,'6.10.5 Week 16 ATE Visit, page 42',1,8,1,'2026-10-12T22:02:58+00:00',NULL,NULL);
