INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-012','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','requirement','For the Week 24 Visit, CSF collection may occur on a separate date from the other assessments scheduled at the Week 24 Visit, provided CSF collection occurs within the allowed window for the Week 24 Visit as defined in the protocol.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection"]','CSF collection may occur on a separate date from the other assessments scheduled at the Week 24 Visit, provided CSF collection occurs within the allowed window for the Week 24 Visit as defined in the protocol.',39,'6.7 Week 24 Visit or Early Termination Visit',1,11,1,'2026-10-12T22:02:58+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-013','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','requirement','For the Week 24 Visit, the date of the other assessments (ie, not the date of CSF collection) will be considered the date of the Week 24 Visit.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "sample_collection"]','The date of the other assessments (ie, not the date of CSF collection) will be considered the date of the Week 24 Visit.',39,'6.7 Week 24 Visit or Early Termination Visit',1,12,1,'2026-10-12T22:02:58+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-014','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','sequence','Participants must first be screened under the Master Protocol and before they are randomly assigned to a regimen.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["randomization"]','Participants must first be screened under the Master Protocol and before they are randomly assigned to a regimen.',9,'102. Allocation to Treatment Regimens',1,13,1,'2026-10-12T22:02:58+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-015','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','sequence','The first dose of study drug must be administered in clinic after all Baseline procedures have been completed.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["dosing"]','Administer first dose of study drug in clinic after all Baseline procedures have been completed',36,'6.1 Baseline Visit',1,14,0,'2026-10-12T22:02:58+00:00','dropped by review (duplicate): repeats a kept rule (Rule 13 is a duplicate of rule 1. Both require the first dose to be administered in clinic after all Baseline procedures are completed.)',NULL);
INSERT INTO rules VALUES('DNL343-regimen_g-procedure_sequence-016','NCT05842941','regimen_g','23949dcec99dffcfa0f1a49eee2b519708f7e3cad02562f446df379930f651a1','procedure_sequence','window','For the Baseline visit, CSF may be collected at any time within one week prior to administration of the first dose of study medication after Regimen G eligibility is confirmed.','numeric','days_between_baseline_csf_and_first_dose','gt',7.0,NULL,'days',NULL,'["sample_collection"]','For the Baseline visit, CSF may be collected at any time within one week prior to administration of the first dose of study medication after Regimen G eligibility is confirmed.',36,'Schedule of Activities – Placebo-controlled Treatment period, footnote 16',1,15,0,'2026-10-12T22:02:58+00:00','dropped: duplicate of DNL343-regimen_g-sample_handling-025 (the same requirement, which belongs to sample_handling)',NULL);
INSERT INTO rules VALUES('DNL343-master-sample_handling-001','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','sample_handling','requirement','All samples will be labeled with a code. The code will not include any identifiable information but will be linked to a specific participant, visit, and sample by data entry of the code into the EDC. There is no scheduled date on which the samples will be destroyed. Samples may be stored for research until they are used, damaged, decayed or otherwise unfit for analysis. Participants have the option of declining participation in this portion of the study at any time by withdrawing their consent to have their sample used. However, it will not be possible to destroy samples that may have already been used. Specific instructions regarding the collection, processing, storage, and shipment of these samples will be provided in the study Laboratory Manual.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "sample_shipment", "visit"]','All samples will be labeled with a code. The code will not include any identifiable information but will be linked to a specific participant, visit, and sample by data entry of the code into the EDC. There is no scheduled date on which the samples will be destroyed. Samples may be stored for research until they are used, damaged, decayed or otherwise unfit for analysis. Participants have the option of declining participation in this portion of the study at any time by withdrawing their consent to have their sample used. However, it will not be possible to destroy samples that may have already been used. Specific instructions regarding the collection, processing, storage, and shipment of these samples will be provided in the study Laboratory Manual.',53,'9.4 Biofluid Collection',1,0,0,'2026-10-12T22:00:44+00:00','dropped by review (not_atomic): Rule 1 bundles several conditions: labeling, coding, linkage, destruction, storage, participant withdrawal, and reference to the Laboratory Manual. Each should be a separate atomic rule.',NULL);
INSERT INTO rules VALUES('DNL343-master-sample_handling-002','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','sample_handling','requirement','The DNA sample can be collected after the Baseline Visit if a baseline sample is not obtained or the sample is not usable.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "visit"]','The DNA sample can be collected after the Baseline Visit if a baseline sample is not obtained or the sample is not usable.',16,'9.3.1 DNA Collection',1,1,1,'2026-10-12T22:00:44+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-sample_handling-003','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','sample_handling','requirement','All samples must be labeled with a code that does not include any identifiable information.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "sample_shipment"]','All samples will be labeled with a code. The code will not include any identifiable information but will be linked to a specific participant, visit, and sample by data entry of the code into the EDC.',53,'9.4 Biofluid Collection',1,2,1,'2026-10-12T22:00:44+00:00','added_by_review',NULL);
