INSERT INTO rules VALUES('DNL343-master-sample_handling-008','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','sample_handling','requirement','The DNA sample can be collected at any time after the Baseline Visit if a baseline sample is not obtained for any reason or the sample is not usable.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection"]','The DNA sample can be collected at any time after the Baseline Visit if a baseline sample is not obtained for any reason or the sample is not usable.',54,'9.3.1 DNA Sample Collection',1,7,0,'2026-10-12T22:00:44+00:00','dropped: duplicate of rule 1',NULL);
INSERT INTO rules VALUES('DNL343-master-sample_handling-009','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','sample_handling','requirement','All participants will provide blood samples for biomarker assessments.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection"]','All participants will provide blood samples for biomarker assessments.',54,'9.3.2 Blood Biomarker Sample Collection',1,8,1,'2026-10-12T22:00:44+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-sample_handling-010','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','sample_handling','requirement','The lumbar puncture (LP) procedure will be performed to collect CSF, as described in each RSA.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection"]','The lumbar puncture (LP) procedure will be performed to collect CSF, as described in each RSA.',54,'9.3.4 Lumbar Puncture',1,9,0,'2026-10-12T22:00:44+00:00','dropped by review (not_checkable): This is a statement that the procedure will be performed as described in the RSA, but the protocol does not specify a requirement for sample handling in the Master Protocol; the actual requirements are in the RSA.',NULL);
INSERT INTO rules VALUES('DNL343-master-sample_handling-011','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','sample_handling','requirement','All samples must be labeled with a code that does not include any identifiable information but is linked to a specific participant, visit, and sample by data entry of the code into the EDC.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["sample_collection", "sample_shipment"]','All samples will be labeled with a code. The code will not include any identifiable information but will be linked to a specific participant, visit, and sample by data entry of the code into the EDC.',53,'9.4 Biofluid Collection',1,10,1,'2026-10-12T22:00:44+00:00','added_by_review',NULL);
