INSERT INTO rules VALUES('DNL343-master-study_drug-008','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','study_drug','requirement','Participants taking concomitant riluzole at study entry must be on a stable dose for 30 days prior to the Master Protocol Screening Visit and must intend to continue taking the same stable dosage throughout the study.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["dosing", "visit", "other"]','Participants taking concomitant riluzole at study entry must be on a stable dose for 30 days prior to the Master Protocol Screening Visit and must intend to continue taking the same stable dosage throughout the study.',30,'5.2.1 Master Protocol Inclusion Criteria',1,7,1,'2026-10-12T22:00:24+00:00','added_by_coverage_check',NULL);
