INSERT INTO rules VALUES('DNL343-master-visit_schedule-010','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','The following procedures will be performed in-person, after Master Protocol informed consent is obtained, to determine the participant''s eligibility for the Master Protocol and are listed in preferred order to be completed: Assess Master Protocol inclusion and exclusion criteria: Obtain ALS and medical history Obtain demographics Perform Vital Capacity Perform physical examination Perform neurological examination Measure vital signs including height and weight Administer ALSFRS-R questionnaire Perform 12-lead electrocardiogram (ECG) Collect blood samples for clinical screening assessments (including coagulation parameters) and, for women of child bearing potential (WOCBP), for pregnancy test Collect urine for urinalysis Collect blood biomarker sample Review and document concomitant medications Assess and document AEs Schedule the Regimen Specific Screening Visit if the participant passes screening for the Master Protocol','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening"]','The following procedures will be performed in-person, after Master Protocol informed consent is obtained, to determine the participant''s eligibility for the Master Protocol and are listed in preferred order to be completed: Assess Master Protocol inclusion and exclusion criteria: Obtain ALS and medical history Obtain demographics Perform Vital Capacity Perform physical examination Perform neurological examination Measure vital signs including height and weight Administer ALSFRS-R questionnaire Perform 12-lead electrocardiogram (ECG) Collect blood samples for clinical screening assessments (including coagulation parameters) and, for women of child bearing potential (WOCBP), for pregnancy test Collect urine for urinalysis Collect blood biomarker sample Review and document concomitant medications Assess and document AEs Schedule the Regimen Specific Screening Visit if the participant passes screening for the Master Protocol',41,'8.1 Master Protocol Screening Visit',1,9,1,'2026-10-12T21:59:35+00:00',NULL,NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-011','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','The following procedures will be performed and are listed in preferred order to be completed: Obtain written regimen-specific informed consent from participant Assess regimen-specific inclusion and exclusion criteria Concomitant medication review Assess and document AEs','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["screening"]','The following procedures will be performed and are listed in preferred order to be completed: Obtain written regimen-specific informed consent from participant Assess regimen-specific inclusion and exclusion criteria Concomitant medication review Assess and document AEs',43,'8.2 Regimen Specific Screening Visit',1,10,1,'2026-10-12T21:59:35+00:00',NULL,NULL);
