INSERT INTO rules VALUES('DNL343-master-visit_schedule-026','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','The following procedure will be performed at a minimum: • Assess and document AEs (at the Follow-Up Safety Call).','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["contact"]','The following procedure will be performed at a minimum: • Assess and document AEs',47,'8.11 Follow-Up Safety Call',1,25,1,'2026-10-12T21:59:35+00:00','added_by_review',NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-027','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','window','Visit windows are consecutive calendar days and the target visit dates are calculated from the Baseline Visit - Day 0 (first day of investigational product administration).','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "contact"]','Visit windows are consecutive calendar days and the target visit dates are calculated from the Baseline Visit - Day 0 (first day of investigational product administration).',40,'18. Visit windows and target visit dates',1,26,0,'2026-10-12T21:59:35+00:00','dropped by review (not_checkable): This is a statement about how visit windows are calculated, not a site duty or checkable requirement.',NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-028','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','Outcomes for individual participants should be measured by the same evaluator throughout their participation in a regimen.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit"]','Outcomes for individual participants should be measured by the same evaluator throughout their participation in a regimen.',40,'19. Evaluator consistency',1,27,0,'2026-10-12T21:59:35+00:00','dropped by review (not_checkable): This is a recommendation/preference, not a requirement; the protocol does not require the same evaluator, only prefers it.',NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-029','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','Evaluators must be qualified, trained, certified, and delegated. Training documentation must be filed in the Investigator Site File (ISF).','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit"]','Evaluators must be qualified, trained, certified, and delegated. Training documentation must be filed in the Investigator Site File (ISF).',40,'19. Evaluator consistency',1,28,0,'2026-10-12T21:59:35+00:00','dropped by review (not_checkable): This is a qualification/training documentation requirement, not a visit schedule requirement (belongs to a different problem class).',NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-030','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','If needed to protect the safety of the participant, an in-clinic visit may be conducted via telemedicine (or phone if telemedicine is not available) with remote services instead of in-person.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "contact"]','If needed to protect the safety of the participant, an in-clinic visit may be conducted via telemedicine (or phone if telemedicine is not available) with remote services instead of in-',40,'19. Evaluator consistency',1,29,0,'2026-10-12T21:59:35+00:00','dropped by review (not_checkable): This is a contingency for participant safety, not a visit schedule requirement; it does not set a checkable rule for visit timing or content.',NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-031','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','At a minimum, collection of the ALSFRS-R, AEs, Concomitant Medications, C-SSRS, and other outcome measures should be encouraged. Loss to follow-up should be prevented whenever possible.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "contact"]','At a minimum, collection of the ALSFRS-R, AEs, Concomitant Medications, C-SSRS, and other outcome measures should be encouraged Loss to follow-up should be prevented whenever possible.',35,'124. Minimum required assessments',1,30,0,'2026-10-12T21:59:35+00:00','dropped by review (not_checkable): This is a recommendation to encourage collection, not a requirement; it is not checkable as a visit schedule deviation.',NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-032','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','For participants followed under the ITT principle, an in-person Early Termination Visit will be completed after they discontinue follow-up under the ITT principle.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit"]','For participants followed under the ITT principle, an in-person Early Termination Visit will be completed after they discontinue follow-up under the ITT principle.',35,'125. Early Termination Visit',1,31,0,'2026-10-12T21:59:35+00:00','dropped by review (not_checkable): This is a statement about what is done for ITT participants, not a visit schedule requirement for all.',NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-033','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','A Follow-Up Safety Call at the time study drug is discontinued is not be required, as long as the participant is followed under the ITT principle for a minimum of 28 days.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["contact"]','A Follow-Up Safety Call at the time study drug is discontinued is not be required, as long as the participant is followed under the ITT principle for a minimum of 28 days.',35,'126. Follow-Up Safety Call',1,32,0,'2026-10-12T21:59:35+00:00','dropped by review (not_checkable): This is a statement about when a safety call is not required, not a visit schedule requirement.',NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-034','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','If a planned in-clinic visit is conducted via telemedicine (or phone if telemedicine is not available) with remote services, only selected procedures will be performed.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "contact"]','If a planned in-clinic visit is conducted via telemedicine (or phone if telemedicine is not available) with remote services, only selected procedures will be performed.',40,'135. Telemedicine visits',1,33,0,'2026-10-12T21:59:35+00:00','dropped by review (not_checkable): This is a statement about what happens if a visit is remote, not a visit schedule requirement.',NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-035','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','The following procedures should be completed in the suggested order and as per the Schedule of Activities: ALSFRS-R, AE Review, Columbia-Suicide Severity Rating Scale, Concomitant Medications, IP Accountability/Compliance, and shipment of IP as applicable; each RA may describe additional activities.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit"]','The following procedures should be completed in the suggested order and as per the Schedule of Activities: ALSFRS-R, AE Review, Columbia-Suicide Severity Rating Scale, Concomitant Medications, IP Accountability/Compliance, and shipment of IP as applicable; each RA may describe additional activities.',40,'136. Required procedures per visit',1,34,0,'2026-10-12T21:59:35+00:00','dropped by review (not_checkable): This is a statement about the order of procedures, not a visit schedule requirement.',NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-036','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','Missed assessments due to pandemic-related restrictions must be documented as such in the source documentation and in the EDC.','judgment',NULL,NULL,NULL,NULL,NULL,NULL,'["visit", "contact"]','Missed assessments due to pandemic-related restrictions must be documented as such in the source documentation and in the EDC.',48,'147. Missed assessments due to pandemic',1,35,1,'2026-10-12T21:59:35+00:00','added_by_coverage_check',NULL);
INSERT INTO rules VALUES('DNL343-master-visit_schedule-037','NCT05842941','master','1fb881ace3f4c76b872af96f541141ecc75e3ae75d86d8153b22b805d51d89be','visit_schedule','requirement','At least 3 measurable VC trials must be completed to score VC for all visits after screening.','numeric','vc_trials_count','lt',3.0,NULL,NULL,NULL,'["visit"]','At least 3 measurable VC trials must be completed to score VC for all visits after screening.',53,'163. VC trials per visit',1,36,1,'2026-10-12T21:59:35+00:00','added_by_coverage_check',NULL);
