INSERT INTO guide VALUES('NCT05842941','checks','chk:0010','check','','not_checkable','','{"kind": "not_checkable", "text": "DNL343 rationale, mechanism, development background, study objectives, and design summary.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The principal aim of Regimen G is to investigate the efficacy of DNL343 in slowing clinical progression of disease as compared to placebo; and the secondary aim is to investigate the safety and tolerability of DNL343.", "section_id": "regimen_g:s004", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0010"}','','[]',6010,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
