INSERT INTO guide VALUES('NCT05842941','checks','chk:0022','check','','follow_up','','{"kind": "follow_up", "text": "Continue participants in ATE receiving DNL343 after placebo-controlled treatment.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "completion of placebo-controlled treatment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "At the conclusion of the 24-week placebo-controlled treatment period, all participants will continue in the ATE period and receive DNL343.", "section_id": "regimen_g:s008", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "blinded_treatment_end", "value_name_id": "", "code": false, "id": "chk:0022"}','','[]',6022,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0023','check','','follow_up','','{"kind": "follow_up", "text": "Schedule a 28-day follow-up safety phone call after final ATE visit and study drug discontinuation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ATE completion and study drug discontinuation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Once a participant completes the final visit in the ATE and discontinues study drug, a 28-day follow-up safety phone call will be scheduled.", "section_id": "regimen_g:s008", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ate_end_drug_stop", "value_name_id": "", "code": false, "id": "chk:0023"}','','[]',6023,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
