INSERT INTO guide VALUES('NCT05842941','checks','chk:0093','check','','follow_up','','{"kind": "follow_up", "text": "Determine death date, PAV status, or last known alive date for each randomized participant at the end of placebo-controlled follow-up.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "end of placebo-controlled follow-up", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for each randomized participant", "exception": "", "quote": "Vital status, defined as a determination of date of death or PAV status or date last known alive, will be determined for each randomized participant at the end of the placebocontrolled portion of their follow-up (generally the Week 24 Visit, as indicated).", "section_id": "regimen_g:s010", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "placebo_followup_end", "value_name_id": "", "code": false, "id": "chk:0093"}','','[]',6093,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0094','check','','follow_up','','{"kind": "follow_up", "text": "Determine vital status again at regimen last participant, last visit for participants alive at the end of placebo-controlled follow-up.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "regimen last participant, last visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants alive at the end of placebo-controlled follow-up", "exception": "", "quote": "If at that time the participant is alive, his or her vital status should be determined again at the time of the last participant, last visit (LPLV) of the Regimen.", "section_id": "regimen_g:s010", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "regimen_lplv", "value_name_id": "", "code": false, "id": "chk:0094"}','','[]',6094,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0095','check','','judgment','','{"kind": "judgment", "text": "Replace weeks 4, 8, or 16 in-person visits with phone or telemedicine plus remote services only when needed to protect safety due to pandemic, disability, or medical necessity.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when replacing a visit marked footnote 12 with a remote visit", "exception": "", "quote": "Visit may be conducted via phone or telemedicine with remote services instead of in-person if this is needed to protect the safety of the participant due to a pandemic, disability, or a medically necessary reason.", "section_id": "regimen_g:s010", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0095"}','','[]',6095,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0096','check','','judgment','','{"kind": "judgment", "text": "Base additional endocrinology safety laboratory testing on clinical indication from signs and symptoms.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when considering additional endocrinology testing", "exception": "", "quote": "Endocrinology safety laboratory tests (blood ACTH, cortisol, fT4) may be performed additionally during the study as clinically indicated based on signs and symptoms.", "section_id": "regimen_g:s010", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0096"}','','[]',6096,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0097','check','','judgment','','{"kind": "judgment", "text": "Collect ACTH/cortisol samples at approximately the same morning time when possible.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for each endocrinology laboratory assessment", "exception": "Not collecting at the same morning time as earlier assessments is explicitly not a protocol deviation.", "quote": "Collect blood sample for measurement of ACTH/cortisol at approximately the same time in the morning for each endocrinology laboratory assessment, if possible.", "section_id": "regimen_g:s010", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0097"}','','[]',6097,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0098','check','','judgment','','{"kind": "judgment", "text": "Schedule week 4 and week 24 predose PK visits in the morning.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for visits with a predose PK sample at week 4 and week 24", "exception": "", "quote": "For visits with a predose PK sample (Week 4 and Week 24), these visits should be scheduled for the morning and participants should take their dose in the clinic at approximately the same time in the morning as usual.", "section_id": "regimen_g:s010", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0098"}','','[]',6098,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0099','check','','judgment','','{"kind": "judgment", "text": "Have participants dose in clinic at approximately their usual morning time at predose PK visits.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for visits with a predose PK sample at week 4 and week 24", "exception": "", "quote": "For visits with a predose PK sample (Week 4 and Week 24), these visits should be scheduled for the morning and participants should take their dose in the clinic at approximately the same time in the morning as usual.", "section_id": "regimen_g:s010", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0099"}','','[]',6099,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0100','check','','interval','','{"kind": "interval", "text": "Collect predose PK sample 0\u20132 hours before dosing.", "from_event": "predose PK sample", "to_event": "study drug dose", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "hours", "min": 0, "max": 2, "applies_when": "for predose PK sampling", "exception": "At week 4, two postdose samples at least one hour apart may replace an impossible predose collection.", "quote": "The predose sample should be collected prior to dosing (ie, any time 0 to 2 hours before the dose) and approximately 24 hours after the most recent dose.", "section_id": "regimen_g:s010", "from_event_id": "predose_pk", "to_event_id": "study_drug_dose", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0100", "implied": true, "stated": [0, 2]}','','[]',6100,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
