INSERT INTO guide VALUES('NCT05842941','checks','chk:0168','check','','follow_up','','{"kind": "follow_up", "text": "Ask participants withdrawing consent or terminating early during the ATE to complete an early termination visit.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "consent withdrawal or early termination", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the ATE", "exception": "", "quote": "Participants who withdraw consent or early terminate during the ATE will be asked to complete an Early Termination Visit and Follow-Up Safety Call as described in the body of this RSA.", "section_id": "regimen_g:s011", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "withdrawal_or_et", "value_name_id": "", "code": false, "id": "chk:0168"}','','[]',6168,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0169','check','','follow_up','','{"kind": "follow_up", "text": "Ask participants withdrawing consent or terminating early during the ATE to complete a follow-up safety call.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "consent withdrawal or early termination", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the ATE", "exception": "", "quote": "Participants who withdraw consent or early terminate during the ATE will be asked to complete an Early Termination Visit and Follow-Up Safety Call as described in the body of this RSA.", "section_id": "regimen_g:s011", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "withdrawal_or_et", "value_name_id": "", "code": false, "id": "chk:0169"}','','[]',6169,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0170','check','','judgment','','{"kind": "judgment", "text": "Use phone or telemedicine with remote services instead of in-person visits only when needed to protect participant safety because of a pandemic, disability, or a medically necessary reason.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "using the footnote [7] remote-visit option", "exception": "", "quote": "Visit may be conducted via phone or telemedicine with remote services instead of in-person if this is needed to protect the safety of the participant due to a pandemic, disability, or a medically necessary reason.", "section_id": "regimen_g:s011", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0170"}','','[]',6170,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0171','check','','interval','','{"kind": "interval", "text": "Schedule post-week-52 ATE visits at 96 \u00b1 14 days according to footnote 8; the table instead specifies 84 \u00b1 14 days, requiring clarification.", "from_event": "previous ATE visit", "to_event": "next ATE visit after week 52", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 82, "max": 110, "applies_when": "visits after ATE week 52", "exception": "", "quote": "All visits after the 52-week Visit in the ATE will be in-clinic visits that occur at 13-week (96 days \u00b114 days) intervals.", "section_id": "regimen_g:s011", "from_event_id": "previous_ate_visit", "to_event_id": "next_ate_post_w52", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0171", "stated": [82, 110], "superseded": "chk:0134"}','','[]',6171,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0172','check','','judgment','','{"kind": "judgment", "text": "Keep participants in the ATE until all active participants have completed at least 52 weeks, without allowing any participant to exceed 78 weeks.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "ongoing ATE participation", "exception": "Consent withdrawal or early termination.", "quote": "Participants will continue in the ATE until all active participants have completed a minimum of 52 weeks of the ATE; no participant will exceed 78 weeks in the ATE.", "section_id": "regimen_g:s011", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0172"}','','[]',6172,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0173','check','','follow_up','','{"kind": "follow_up", "text": "Determine each participant''s vital status at the end of ATE follow-up, recording date of death, PAV status, or date last known alive.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "end of participant ATE follow-up", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Vital status, defined as a determination of date of death or PAV status or date last known alive, will be determined for each participant at the end of the ATE portion of their follow-up.", "section_id": "regimen_g:s011", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ate_followup_end", "value_name_id": "", "code": false, "id": "chk:0173"}','','[]',6173,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0174','check','','follow_up','','{"kind": "follow_up", "text": "Determine vital status again at the Regimen ATE last participant, last visit if the participant was alive at the end of their ATE follow-up.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "Regimen ATE last participant last visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "participant alive at end of their ATE follow-up", "exception": "", "quote": "If at that time the participant is alive, his or her vital status should be determined again at the time of the last participant, last visit (LPLV) of the Regimen ATE.", "section_id": "regimen_g:s011", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "regimen_ate_lplv", "value_name_id": "", "code": false, "id": "chk:0174"}','','[]',6174,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0175','check','','judgment','','{"kind": "judgment", "text": "Do not perform drug accountability at phone visits.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "phone visits", "exception": "", "quote": "Drug accountability will not be done at phone visits.", "section_id": "regimen_g:s011", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0175"}','','[]',6175,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0176','check','','follow_up','','{"kind": "follow_up", "text": "At phone visits conduct a drug compliance check-in to confirm adherence to the dose regimen and note reported missed doses.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "phone visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "A drug compliance check in should be held during phone visits to ensure participant is taking drug per dose regimen and to note any report of missed doses.", "section_id": "regimen_g:s011", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "phone_visit", "value_name_id": "", "code": false, "id": "chk:0176"}','','[]',6176,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0177','check','','follow_up','','{"kind": "follow_up", "text": "Review and document current contraceptive methods.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "contraception review", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "female participants of childbearing potential and men with a female partner of childbearing potential", "exception": "", "quote": "[13]For female participants of childbearing potential and for men with a female partner of childbearing potential, review and document current contraceptive method(s) and ensure they meet study requirements.", "section_id": "regimen_g:s011", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "contraception_review", "value_name_id": "", "code": false, "id": "chk:0177"}','','[]',6177,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0178','check','','judgment','','{"kind": "judgment", "text": "Ensure current contraceptive methods meet study requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "female participants of childbearing potential and men with a female partner of childbearing potential", "exception": "", "quote": "[13]For female participants of childbearing potential and for men with a female partner of childbearing potential, review and document current contraceptive method(s) and ensure they meet study requirements.", "section_id": "regimen_g:s011", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0178"}','','[]',6178,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0179','check','','not_checkable','','{"kind": "not_checkable", "text": "Section title, schedule labels, abbreviations, cross-references to Section 6.9, and optional later vital-status ascertainment using public sources are administrative or explanatory material, not additional mandatory site rules. Table entries are fragments rather than sentences; their exact source text is quoted above.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "We may also ascertain vital status (death or date last known alive only) at later time points by using publicly available data sources as described in Section 8.15 of the Master Protocol.", "section_id": "regimen_g:s011", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0179"}','','[]',6179,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0180','check','','not_checkable','','{"kind": "not_checkable", "text": "Background description of DNL343, its mechanism, developer, and intended indication.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "DNL343 is a central nervous system (CNS)\u2013penetrant eukaryotic translation initiation factor 2B (eIF2B) small molecule activator that is being developed by Denali Therapeutics Inc. (Denali) as a potential treatment for amyotrophic lateral sclerosis (ALS).", "section_id": "regimen_g:s013", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0180"}','','[]',6180,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0181','check','','not_checkable','','{"kind": "not_checkable", "text": "Drug mechanism, nonclinical toxicology, target organs, recovery findings, clinical-development history, historical exposure and tolerability, and Investigator\u2019s Brochure references are background rather than current site requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Collectively, DNL343 doses up to 260 mg once daily (QD) for up to 14 days in healthy participants and up to 200 mg for up to 10 months in participants with ALS have been generally well tolerated and support continued evaluation of DNL343 in participants with ALS.", "section_id": "regimen_g:s015", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0181"}','','[]',6181,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0182','check','','not_checkable','','{"kind": "not_checkable", "text": "Phase 1b design, interim population and cutoff, historical adverse events and dose changes, safety findings, PK narrative and table, statistics, exclusions from analysis, abbreviations, and biomarker results are historical research information, not requirements for this site''s conduct.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "DNL343 achieved robust inhibition of ATF4 protein levels (73%\u201379%) and CHAC1 gene expression (56%\u201389%) at both the 100 mg and 200 mg QD doses studied in ALS participants.", "section_id": "regimen_g:s016", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0182"}','','[]',6182,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0183','check','','not_checkable','','{"kind": "not_checkable", "text": "Historical itraconazole interaction study design, completion, enrollment, dosing, safety and PK results are background; permission to coadminister CYP3A4 inhibitors and moderate inducers is not a mandatory action or prohibition a site can break.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The results indicate that DNL343 is not a sensitive substrate of CYP3A4 and that DNL343 can be coadministered with strong, moderate, or weak inhibitors of CYP3A4.", "section_id": "regimen_g:s017", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0183"}','','[]',6183,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0184','check','','not_checkable','','{"kind": "not_checkable", "text": "Historical midazolam interaction study design, status, population, safety events including AST meeting AESI criteria, dosing, statistics, PK results, and CYP3A-induction interpretation are background, not current site thresholds or instructions.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The preliminary results indicate that DNL343 is moderate CYP3A inducer; medications that are CYP3A substrates may have increased hepatic clearance and decreased exposure when taken with DNL343.", "section_id": "regimen_g:s018", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0184"}','','[]',6184,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0185','check','','not_checkable','','{"kind": "not_checkable", "text": "Therapeutic rationale, cited nonclinical and patient findings, proposed mechanism and potential benefit, and Investigator\u2019s Brochure reference are scientific background.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The nonclinical neuroprotective findings of ISR pathway inhibition, combined with the observation of increased ISR activity in patients with ALS, indicate that inhibition of the ISR pathway by DNL343 activation of eIF2B could be beneficial in the treatment of ALS.", "section_id": "regimen_g:1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0185"}','','[]',6185,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0186','check','','not_checkable','','{"kind": "not_checkable", "text": "Study objectives and efficacy, safety, and exploratory endpoint definitions; these do not independently prescribe site procedures.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "3. To evaluate the safety of DNL343 in participants with ALS", "section_id": "regimen_g:2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0186"}','','[]',6186,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
