INSERT INTO guide VALUES('NCT05842941','checks','chk:0190','check','','interval','','{"kind": "interval", "text": "Begin the ATE following 24 weeks of double-blinded treatment.", "from_event": "start of double-blinded treatment", "to_event": "ATE entry", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "weeks", "min": 24, "max": 24, "applies_when": "", "exception": "Protocol-permitted early termination.", "quote": "Following 24 weeks of double-blinded treatment, all participants will enter the active treatment extension (ATE) period to receive DNL343 200 mg QD for a minimum of additional 52 weeks to a maximum of additional 78 weeks.", "section_id": "regimen_g:3", "from_event_id": "double_blind_start", "to_event_id": "ate_entry", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0190", "stated": [24, 24]}','','[]',6190,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
