INSERT INTO guide VALUES('NCT05842941','checks','chk:0192','check','','interval','','{"kind": "interval", "text": "The planned ATE treatment duration is 52 to 78 additional weeks.", "from_event": "ATE entry", "to_event": "end of ATE treatment", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "weeks", "min": 52, "max": 78, "applies_when": "", "exception": "Protocol-permitted early termination or treatment discontinuation.", "quote": "Following 24 weeks of double-blinded treatment, all participants will enter the active treatment extension (ATE) period to receive DNL343 200 mg QD for a minimum of additional 52 weeks to a maximum of additional 78 weeks.", "section_id": "regimen_g:3", "from_event_id": "ate_entry", "to_event_id": "ate_treatment_end", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0192", "stated": [52, 78], "superseded": "chk:0453"}','','[]',6192,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0193','check','','not_checkable','','{"kind": "not_checkable", "text": "Scientific rationale and description of additional objectives and measures.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "This Regimen-Specific Appendix (RSA) is designed to correspond with the design of the Master Protocol and the goals of the Platform Trial.", "section_id": "regimen_g:3.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0193"}','','[]',6193,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0194','check','','judgment','','{"kind": "judgment", "text": "Do not classify placebo-controlled participation as completed unless the participant completed Week 24 or the early termination visit.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "determining placebo-controlled completion status", "exception": "", "quote": "A participant is considered to have completed the placebo-controlled period of the Regimen when they have completed Week 24 or the Early Termination (ET) Visit.", "section_id": "regimen_g:s025", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0194"}','','[]',6194,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0195','check','','judgment','','{"kind": "judgment", "text": "Determine ATE completion using completion of planned ATE visits, including the last visit, early termination visit, or last scheduled SOA procedure.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "determining ATE completion status", "exception": "", "quote": "Participants are considered to have completed their participation in the ATE period of\nRegimen G if planned ATE period visits, including the last visit, ET Visit, or the last scheduled procedure shown in the Schedule of Activities (SOA), have been completed.", "section_id": "regimen_g:s026", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0195"}','','[]',6195,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0196','check','','not_checkable','','{"kind": "not_checkable", "text": "Regimen-level end definitions depend on completion by all randomized participants or all ATE participants who initiated study drug, respectively.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The end of the placebo-controlled period in Regimen G occurs when all randomized participants have completed their participation in the placebo-controlled period as defined in Section 3.2.", "section_id": "regimen_g:3.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0196"}','','[]',6196,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0197','check','','not_checkable','','{"kind": "not_checkable", "text": "Approximate regimen-wide enrollment target is 240 participants, not a site enrollment limit.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Approximately two hundred-forty (n=240) participants will be randomized in Regimen G.", "section_id": "regimen_g:4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0197"}','','[]',6197,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0198','check','','judgment','','{"kind": "judgment", "text": "Randomize only participants who meet Master Protocol eligibility criteria.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "before randomization", "exception": "", "quote": "In order to be randomized to Regimen G, participants must meet the Master Protocol eligibility criteria.", "section_id": "regimen_g:4.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0198"}','','[]',6198,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
