INSERT INTO guide VALUES('NCT05842941','checks','chk:0215','check','','follow_up','','{"kind": "follow_up", "text": "Randomize eligible participants to DNL343 200 mg or placebo for approximately 24 weeks and continue them into the ATE for up to 78 additional weeks.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "confirmation of regimen eligibility", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Protocol-permitted early termination or dose modification.", "quote": "Each participant who meets all eligibility criteria for the Regimen will be randomized to receive either DNL343 200 mg or placebo for approximately 24 weeks of placebo-controlled treatment and will continue on to the ATE period for up to an additional 78 weeks.", "section_id": "regimen_g:4.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "regimen_eligibility", "value_name_id": "", "code": false, "id": "chk:0215"}','','[]',6215,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
