INSERT INTO guide VALUES('NCT05842941','checks','chk:0221','check','','judgment','','{"kind": "judgment", "text": "Transport, receive, store, and handle study drug according to its label, supplied site and pharmacy instructions, site SOPs, and applicable country regulations.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "site study drug transport, receipt, storage, and handling", "exception": "", "quote": "All study drug will be transported, received, stored, and handled in accordance with the container or product label, the instructions supplied to the research site and its designated pharmacy, the site\u2019s standard operating procedures, and the applicable country regulations.", "section_id": "regimen_g:5.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0221"}','','[]',6221,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0222','check','','not_checkable','','{"kind": "not_checkable", "text": "Upstream supply-chain requirement to maintain appropriate storage and transportation conditions from manufacture to site delivery.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Appropriate storage temperature and transportation conditions will be maintained for the study drug from the point of manufacture up to delivery of the study drug to each participating clinical site.", "section_id": "regimen_g:5.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0222"}','','[]',6222,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0223','check','','follow_up','','{"kind": "follow_up", "text": "Research pharmacy staff must transfer received shipments to appropriate environmentally controlled storage.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug shipment receipt", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Upon receipt by the study site, the research pharmacy staff will transfer the shipment to the appropriate environmentally controlled storage area.", "section_id": "regimen_g:5.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_shipment_receipt", "value_name_id": "", "code": false, "id": "chk:0223"}','','[]',6223,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0224','check','','follow_up','','{"kind": "follow_up", "text": "Examine the shipment and any applicable temperature monitoring devices to verify acceptable receipt condition.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug shipment receipt", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Temperature monitoring device examination applies only if devices are provided.", "quote": "The shipment and temperature monitoring devices (if applicable) will then be examined to verify that the study drug was received in acceptable condition.", "section_id": "regimen_g:5.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_shipment_receipt", "value_name_id": "", "code": false, "id": "chk:0224"}','','[]',6224,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0225','check','','judgment','','{"kind": "judgment", "text": "After inspection and acceptance, store study drug securely with access restricted to authorized research staff and physical conditions meeting product requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "after shipment inspection and acceptance", "exception": "", "quote": "Once inspected and deemed acceptable, the study drug will then be stored in a restricted access, secured area with access limited to authorized research site staff, under physical conditions consistent with the study drug\u2019s specific requirements.", "section_id": "regimen_g:5.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0225"}','','[]',6225,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0226','check','','follow_up','','{"kind": "follow_up", "text": "The investigator or designee must confirm appropriate transit temperature conditions for all received study drug.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug shipment receipt", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The investigator or designee must confirm that appropriate temperature conditions have been maintained during transit for all study drug received and that any discrepancies are reported and resolved before use of the study drug.", "section_id": "regimen_g:5.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_shipment_receipt", "value_name_id": "", "code": false, "id": "chk:0226"}','','[]',6226,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
