INSERT INTO guide VALUES('NCT05842941','checks','chk:0228','check','','order','','{"kind": "order", "text": "Report and resolve transit temperature discrepancies before using affected study drug.", "from_event": "", "to_event": "", "first_event": "reporting and resolution of study drug transit temperature discrepancy", "then_event": "use of affected study drug", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "study drug received with transit temperature discrepancies", "exception": "", "quote": "The investigator or designee must confirm that appropriate temperature conditions have been maintained during transit for all study drug received and that any discrepancies are reported and resolved before use of the study drug.", "section_id": "regimen_g:5.3", "from_event_id": "", "to_event_id": "", "first_event_id": "transit_temp_resolution", "then_event_id": "affected_drug_use", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0228", "implied": true}','','[]',6228,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0229','check','','judgment','','{"kind": "judgment", "text": "Follow additional study drug handling and storage instructions in the MOP.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "study drug handling and storage", "exception": "", "quote": "Refer to the Manual of Procedures (MOP) for additional instructions on handling and storage of study drug.", "section_id": "regimen_g:5.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0229"}','','[]',6229,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0230','check','','judgment','','{"kind": "judgment", "text": "Administer study drug reconstituted in water orally or via feeding tube, or coadministered with soft food.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "study drug administration", "exception": "", "quote": "DNL343 drug product and placebo will be administered reconstituted in water for oral or feeding tube administration (eg, gastrostomy tube [G-tube], jejunostomy tube [J-tube], or nasogastric tube) or coadministered with soft food (eg, applesauce or yogurt).", "section_id": "regimen_g:5.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0230"}','','[]',6230,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0231','check','','not_checkable','','{"kind": "not_checkable", "text": "Optional fluid thickener use, table descriptors of formulation and comparator roles, and abbreviations; food does not restrict dosing.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants can take the drug with fluid thickener as needed.", "section_id": "regimen_g:5.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0231"}','','[]',6231,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0232','check','','judgment','','{"kind": "judgment", "text": "Use the assigned regimen in Table 2: DNL343 200 mg once daily or placebo once daily in the placebo-controlled period, and DNL343 200 mg once daily in the ATE, using oral or feeding tube administration.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "study drug administration", "exception": "Protocol-permitted dose modifications.", "quote": "Study drug administered are described in Table 2.", "section_id": "regimen_g:5.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0232"}','','[]',6232,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0233','check','','judgment','','{"kind": "judgment", "text": "Take study drug at approximately the same time each day in the morning.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "routine daily dosing", "exception": "Missed doses may be taken when remembered on the same day.", "quote": "Participants should take the study drug at approximately the same time each day in the morning without regard to food.", "section_id": "regimen_g:5.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0233"}','','[]',6233,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0234','check','','interval','','{"kind": "interval", "text": "Complete each dose within 15 minutes.", "from_event": "start of study drug dose administration", "to_event": "completion of study drug dose administration", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "minutes", "min": 0, "max": 15, "applies_when": "", "exception": "", "quote": "All dosing should be completed within 15 minutes.", "section_id": "regimen_g:5.4", "from_event_id": "first_study_dose", "to_event_id": "dose_administration_complete", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0234", "stated": [0, 15]}','','[]',6234,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0235','check','','judgment','','{"kind": "judgment", "text": "Administer the study drug dose in the clinic on visit days with predose PK assessments.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "clinic visit days with predose PK assessments", "exception": "", "quote": "On clinic visit days with predose PK assessments, participants will be administered their dose of study drug in the clinic.", "section_id": "regimen_g:5.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0235"}','','[]',6235,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0236','check','','judgment','','{"kind": "judgment", "text": "A missed dose may be taken when remembered only on the same day.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "a missed study drug dose is remembered on the same day", "exception": "", "quote": "Participants may take their missed dose as soon as they remember to take it in the same day.", "section_id": "regimen_g:5.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0236"}','','[]',6236,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0237','check','','judgment','','{"kind": "judgment", "text": "If a missed dose is remembered the next day, take only the next scheduled dose, not the missed dose.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "a missed study drug dose is remembered the next day", "exception": "", "quote": "If the participant remembers the day after the dose was missed, only the next dose should be taken.", "section_id": "regimen_g:5.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0237"}','','[]',6237,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0238','check','','count','','{"kind": "count", "text": "Do not take more than one study drug dose per day.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug dose", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": null, "max": 1, "applies_when": "", "exception": "", "quote": "Only one dose is to be taken per day.", "section_id": "regimen_g:5.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "study_drug_dose", "value_name_id": "", "code": true, "id": "chk:0238"}','','[]',6238,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0239','check','','not_checkable','','{"kind": "not_checkable", "text": "Dosage rationale, prior clinical and animal findings, PK/PD modeling, predicted efficacy and safety margins, Table 3 exposure data, abbreviations, and calculation footnotes.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The DNL343 dose selected for this study (200 mg QD) is based on safety, PK, and PD data from the Phase 1 study in healthy participants (Study DNLI-F-0001) and interim data from the Phase 1b study in ALS participants (Study DNLI-F-0003) and is further supported by neuroprotection data from DNL343-treated mouse models of neurodegeneration.", "section_id": "regimen_g:5.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0239"}','','[]',6239,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0240','check','','not_checkable','','{"kind": "not_checkable", "text": "Rationale for selection of the 200 mg once-daily dose based on preclinical, biomarker, and safety evidence.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The DNL343 dose (200 mg QD) was selected given that it is considered to have the highest potential to demonstrate efficacy based on data from preclinical studies, clinical\nbiomarker engagement, and clinical safety (see Section 5.5).", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0240"}','','[]',6240,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0241','check','','judgment','','{"kind": "judgment", "text": "Maintain participants on randomized treatment.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the placebo-controlled period", "exception": "Protocol-permitted modification for substantial intolerability.", "quote": "To adequately evaluate the efficacy of DNL343 participants should be maintained on the randomized treatment.", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0241"}','','[]',6241,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0242','check','','judgment','','{"kind": "judgment", "text": "Interrupt, temporarily reduce, or discontinue study drug only for substantial intolerability judged by the investigator or medical monitor, including moderate or severe AEs or clinically significant laboratory or other safety abnormalities.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "individual dose modification during the placebo-controlled period", "exception": "", "quote": "For situations of substantial intolerability (moderate or severe adverse events [AEs], clinically significant abnormal laboratory test results, or other safety parameter, as judged by the investigator or medical monitor), the site investigator, in consultation with the medical monitor, may withhold study drug (dose interruption), temporarily reduce the dose (administer one stick pack rather than two stick packs), or discontinue study drug for an individual participant.", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0242"}','','[]',6242,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0243','check','','follow_up','','{"kind": "follow_up", "text": "The site investigator must consult the medical monitor regarding individual interruption, reduction, or discontinuation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "individual dose modification decision", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the placebo-controlled period", "exception": "", "quote": "For situations of substantial intolerability (moderate or severe adverse events [AEs], clinically significant abnormal laboratory test results, or other safety parameter, as judged by the investigator or medical monitor), the site investigator, in consultation with the medical monitor, may withhold study drug (dose interruption), temporarily reduce the dose (administer one stick pack rather than two stick packs), or discontinue study drug for an individual participant.", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "dose_modification_decision", "value_name_id": "", "code": false, "id": "chk:0243"}','','[]',6243,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0244','check','','judgment','','{"kind": "judgment", "text": "A temporary reduced dose consists of one stick pack rather than two.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "temporary dose reduction during the placebo-controlled period", "exception": "", "quote": "For situations of substantial intolerability (moderate or severe adverse events [AEs], clinically significant abnormal laboratory test results, or other safety parameter, as judged by the investigator or medical monitor), the site investigator, in consultation with the medical monitor, may withhold study drug (dose interruption), temporarily reduce the dose (administer one stick pack rather than two stick packs), or discontinue study drug for an individual participant.", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0244"}','','[]',6244,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0245','check','','follow_up','','{"kind": "follow_up", "text": "Consider resuming the randomized dose within 28 days after reduction or interruption; actual resumption is not mandatory.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug dose reduction or interruption", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the placebo-controlled period", "exception": "", "quote": "Investigators should consider resuming treatment at the randomized dose within 28 days from the dose reduction or dose interruption.", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "dose_reduce_or_interrupt", "value_name_id": "", "code": false, "id": "chk:0245"}','','[]',6245,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0246','check','','judgment','','{"kind": "judgment", "text": "Maintain the blind throughout dose modification.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "throughout dose modification", "exception": "", "quote": "The blind will be maintained throughout the dose modification procedure.", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0246"}','','[]',6246,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0247','check','','judgment','','{"kind": "judgment", "text": "Dose all ATE participants with DNL343 200 mg once daily regardless of prior placebo-controlled dose reduction.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the ATE", "exception": "Reduced-dose initiation discussed with the medical monitor or protocol-permitted ATE dose modification.", "quote": "All participants in the ATE will be dosed with DNL343 200 mg QD regardless of whether they had a dose reduction during the placebo-controlled period.", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0247"}','','[]',6247,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0248','check','','order','','{"kind": "order", "text": "Discuss proposed ATE initiation at 100 mg with the medical monitor before ATE entry.", "from_event": "", "to_event": "", "first_event": "medical monitor discussion of reduced-dose ATE initiation", "then_event": "ATE entry", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "situations potentially necessitating ATE initiation at 100 mg", "exception": "", "quote": "In situations that may necessitate initiation of DNL343 at the reduced dose (100 mg) in the ATE, the investigator should discuss with the medical monitor before entry into the ATE.", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "reduced_ate_monitor_discussion", "then_event_id": "ate_entry", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0248", "implied": false}','','[]',6248,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0249','check','','follow_up','','{"kind": "follow_up", "text": "The site investigator must consult the medical monitor regarding ATE interruption, temporary reduction, or discontinuation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "individual dose modification decision", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the ATE", "exception": "", "quote": "As in the placebo-controlled period, the site investigator, in consultation with the medical monitor, may withhold study drug (dose interruption), temporarily reduce the dose (administer one stick pack rather than two stick packs), or discontinue study drug for an individual participant.", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "dose_modification_decision", "value_name_id": "", "code": false, "id": "chk:0249"}','','[]',6249,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0250','check','','judgment','','{"kind": "judgment", "text": "ATE dose modifications follow the placebo-controlled approach, including temporary reduction to one stick pack rather than two.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "individual dose modification during the ATE", "exception": "", "quote": "As in the placebo-controlled period, the site investigator, in consultation with the medical monitor, may withhold study drug (dose interruption), temporarily reduce the dose (administer one stick pack rather than two stick packs), or discontinue study drug for an individual participant.", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0250"}','','[]',6250,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0251','check','','follow_up','','{"kind": "follow_up", "text": "Consider resuming treatment at 200 mg if possible after an ATE dose modification.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug dose reduction or interruption", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the ATE", "exception": "", "quote": "Investigators should consider resuming treatment at the 200 mg dose level if possible.", "section_id": "regimen_g:5.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "dose_reduce_or_interrupt", "value_name_id": "", "code": false, "id": "chk:0251"}','','[]',6251,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0252','check','','judgment','','{"kind": "judgment", "text": "Site doses must be provided directly by the investigator or designee under medical supervision.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when participants are dosed at the site", "exception": "", "quote": "When participants are dosed at the site, they will receive study drug directly from the investigator or designee, under medical supervision.", "section_id": "regimen_g:5.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0252"}','','[]',6252,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0253','check','','follow_up','','{"kind": "follow_up", "text": "Record the date and time of every clinic dose in both source documents and eCRF.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug dose in clinic", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The date and time of each dose administered in the clinic will be recorded in the source documents and electronic case report form (eCRF).", "section_id": "regimen_g:5.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "clinic_drug_dose", "value_name_id": "", "code": false, "id": "chk:0253"}','','[]',6253,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0254','check','','follow_up','','{"kind": "follow_up", "text": "At dosing, a staff member other than the administrator must confirm both dose and participant identification.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug dose in clinic", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The dose of study drug and study participant identification will be confirmed at the time of dosing by a member of the study site staff other than the person administering the study drug.", "section_id": "regimen_g:5.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "clinic_drug_dose", "value_name_id": "", "code": false, "id": "chk:0254"}','','[]',6254,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0255','check','','follow_up','','{"kind": "follow_up", "text": "Assess home-dose compliance at each study visit.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "participants self-administer study drug at home", "exception": "", "quote": "When participants self-administer study drug at home, compliance with study drug will be assessed at each study visit.", "section_id": "regimen_g:5.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "study_visit", "value_name_id": "", "code": false, "id": "chk:0255"}','','[]',6255,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0256','check','','follow_up','','{"kind": "follow_up", "text": "Instruct participants to bring all unused study drug packets to every clinic visit.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "home administration of study drug", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants will be instructed to bring all their unused packets of study drug with them to all clinic visits.", "section_id": "regimen_g:5.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "home_drug_administration", "value_name_id": "", "code": false, "id": "chk:0256"}','','[]',6256,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0257','check','','follow_up','','{"kind": "follow_up", "text": "Study staff must count unused packets to assess home compliance and record the assessment.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "home-dose compliance assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Compliance with home administration of study drug will be performed by the study staff by counting the number of unused packets and will be recorded.", "section_id": "regimen_g:5.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "home_dose_compliance", "value_name_id": "", "code": false, "id": "chk:0257"}','','[]',6257,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
