INSERT INTO guide VALUES('NCT05842941','checks','chk:0259','check','','not_checkable','','{"kind": "not_checkable", "text": "Background defines overdose and states that overdose safety data are unavailable; the safety-event list is non-exhaustive.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "No safety data related to overdosing of DNL343 are available.", "section_id": "regimen_g:5.8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0259"}','','[]',6259,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0260','check','','follow_up','','{"kind": "follow_up", "text": "Report DNL343 overdose, suspected abuse/misuse, inadvertent or accidental exposure, medication errors with or without exposure, and other qualifying safety events to the Coordination Center even without AE/SAE.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "DNL343 safety event", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "These safety events should be reported to the Coordination Center whether they result in an AE/SAE or not.", "section_id": "regimen_g:5.8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "dnl343_safety_event", "value_name_id": "", "code": false, "id": "chk:0260"}','','[]',6260,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0261','check','','follow_up','','{"kind": "follow_up", "text": "Also report safety events associated with an AE/SAE in electronic data capture.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "DNL343 safety event associated with AE/SAE", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Safety events associated with an AE/SAE should also be reported in the electronic data capture.", "section_id": "regimen_g:5.8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "dnl343_safety_ae", "value_name_id": "", "code": false, "id": "chk:0261"}','','[]',6261,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0262','check','','follow_up','','{"kind": "follow_up", "text": "Monitor the participant following overdose.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "DNL343 overdose", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "In the event of overdose, study staff should monitor the participant and provide supportive care as needed.", "section_id": "regimen_g:5.8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "dnl343_overdose", "value_name_id": "", "code": false, "id": "chk:0262"}','','[]',6262,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0263','check','','judgment','','{"kind": "judgment", "text": "Provide supportive care as needed following overdose.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "DNL343 overdose", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "In the event of overdose, study staff should monitor the participant and provide supportive care as needed.", "section_id": "regimen_g:5.8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "dnl343_overdose", "value_name_id": "", "code": false, "id": "chk:0263"}','','[]',6263,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0264','check','','interval','','{"kind": "interval", "text": "The Site Investigator must contact the Medical Monitor within 24 hours of awareness of overdose.", "from_event": "Site Investigator aware of overdose", "to_event": "Site Investigator contacts Medical Monitor", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "hours", "min": 0, "max": 24, "applies_when": "overdose", "exception": "", "quote": "The Site Investigator should also contact the Medical Monitor within 24 hours of the Site Investigator\u2019s awareness.", "section_id": "regimen_g:5.8", "from_event_id": "si_overdose_awareness", "to_event_id": "si_monitor_contact", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0264", "implied": true, "stated": [0, 24]}','','[]',6264,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0265','check','','interval','','{"kind": "interval", "text": "Allow at least 14 days after the last strong CYP3A4/5 inducer before first study drug dose.", "from_event": "last dose of strong CYP3A4/5 inducer", "to_event": "first dose of study drug", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 14, "max": null, "applies_when": "", "exception": "A longer five-half-life washout also applies.", "quote": "Participants may not take any prescription or OTC medications (including herbal medicines such as St. John\u2019s wort) that are strong CYP3A4/5 inducers within 2 weeks or 5 half-lives (whichever is longer) of the first dose of study drug and must not anticipate needing to take any of these medications during the study treatment period (see Appendix IV Table 4).", "section_id": "regimen_g:5.9", "from_event_id": "last_strong_cyp3a_inducer", "to_event_id": "first_study_dose", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0265", "stated": [14, null]}','','[]',6265,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0266','check','','judgment','','{"kind": "judgment", "text": "Ensure the strong CYP3A4/5 inducer washout also spans at least five medication half-lives; use the longer washout.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "prior strong CYP3A4/5 inducer use", "exception": "", "quote": "Participants may not take any prescription or OTC medications (including herbal medicines such as St. John\u2019s wort) that are strong CYP3A4/5 inducers within 2 weeks or 5 half-lives (whichever is longer) of the first dose of study drug and must not anticipate needing to take any of these medications during the study treatment period (see Appendix IV Table 4).", "section_id": "regimen_g:5.9", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0266"}','','[]',6266,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0267','check','','judgment','','{"kind": "judgment", "text": "Participants must not anticipate needing strong CYP3A4/5 inducers during treatment.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants may not take any prescription or OTC medications (including herbal medicines such as St. John\u2019s wort) that are strong CYP3A4/5 inducers within 2 weeks or 5 half-lives (whichever is longer) of the first dose of study drug and must not anticipate needing to take any of these medications during the study treatment period (see Appendix IV Table 4).", "section_id": "regimen_g:5.9", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0267"}','','[]',6267,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0268','check','','interval','','{"kind": "interval", "text": "Allow at least seven days after the last narrow-therapeutic-index sensitive CYP3A4/5 substrate before first study drug dose.", "from_event": "last dose of narrow-therapeutic-index sensitive CYP3A4/5 substrate", "to_event": "first dose of study drug", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 7, "max": null, "applies_when": "", "exception": "A longer five-half-life washout also applies.", "quote": "Participants may not take any prescription or OTC medications that are sensitive CYP3A4/5 substrates with a narrow therapeutic index within 7 days or 5 half-lives (whichever is longer) of the first dose of study drug and must not anticipate needing to take any of these medications during the study treatment period (see Appendix IV, Table 5 for common examples of sensitive substrates).", "section_id": "regimen_g:5.9", "from_event_id": "last_nti_cyp3a", "to_event_id": "first_study_dose", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0268", "stated": [7, null]}','','[]',6268,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0269','check','','judgment','','{"kind": "judgment", "text": "Ensure narrow-therapeutic-index sensitive CYP3A4/5 substrate washout spans five half-lives when longer than seven days.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "prior use of these substrates", "exception": "", "quote": "Participants may not take any prescription or OTC medications that are sensitive CYP3A4/5 substrates with a narrow therapeutic index within 7 days or 5 half-lives (whichever is longer) of the first dose of study drug and must not anticipate needing to take any of these medications during the study treatment period (see Appendix IV, Table 5 for common examples of sensitive substrates).", "section_id": "regimen_g:5.9", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0269"}','','[]',6269,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0270','check','','judgment','','{"kind": "judgment", "text": "Participants must not anticipate needing narrow-therapeutic-index sensitive CYP3A4/5 substrates during treatment.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants may not take any prescription or OTC medications that are sensitive CYP3A4/5 substrates with a narrow therapeutic index within 7 days or 5 half-lives (whichever is longer) of the first dose of study drug and must not anticipate needing to take any of these medications during the study treatment period (see Appendix IV, Table 5 for common examples of sensitive substrates).", "section_id": "regimen_g:5.9", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0270"}','','[]',6270,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0271','check','','follow_up','','{"kind": "follow_up", "text": "Monitor participants taking wide-therapeutic-index sensitive CYP3A4/5 substrates for loss of efficacy.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "use of wide-therapeutic-index sensitive CYP3A4/5 substrate", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Medications that are sensitive CYP3A4/5 substrates with a wide therapeutic index are permitted; participants taking them are to be monitored for signs of loss of efficacy and/or may require dose increase based on the respective medication\u2019s prescribing information and discretion of the investigator and/or medical monitor.", "section_id": "regimen_g:5.9", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "cyp3a_substrate_use", "value_name_id": "", "code": false, "id": "chk:0271"}','','[]',6271,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0272','check','','judgment','','{"kind": "judgment", "text": "Consider any needed substrate dose increase using prescribing information and investigator/medical monitor discretion.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "use of wide-therapeutic-index sensitive CYP3A4/5 substrate", "exception": "", "quote": "Medications that are sensitive CYP3A4/5 substrates with a wide therapeutic index are permitted; participants taking them are to be monitored for signs of loss of efficacy and/or may require dose increase based on the respective medication\u2019s prescribing information and discretion of the investigator and/or medical monitor.", "section_id": "regimen_g:5.9", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0272"}','','[]',6272,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
