INSERT INTO guide VALUES('NCT05842941','checks','chk:0281','check','','judgment','','{"kind": "judgment", "text": "Female participants must meet a permitted postmenopausal, surgical sterilization, or childbearing-potential contraception pathway throughout the trial.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "female participants", "exception": "", "quote": "For female participants, one of the following must apply:", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0281"}','','[]',6281,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0282','check','','interval','','{"kind": "interval", "text": "Postmenopausal qualification requires at least 12 consecutive months without menses before screening.", "from_event": "start of uninterrupted absence of menses", "to_event": "screening", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "months", "min": 12, "max": null, "applies_when": "postmenopausal qualification", "exception": "", "quote": "Postmenopausal (defined as no menses for \u2265 12 consecutive months before screening without an alternative medical cause, with a follicle-stimulating hormone level of > 40\nIU/L or mIU/mL at screening)", "section_id": "regimen_g:5.10.2", "from_event_id": "amenorrhea_start", "to_event_id": "screening", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0282", "implied": false, "stated": [12, null]}','','[]',6282,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
