INSERT INTO guide VALUES('NCT05842941','checks','chk:0285','check','','interval','','{"kind": "interval", "text": "Qualifying surgical sterilization must precede dosing by at least six months.", "from_event": "surgical sterilization", "to_event": "first dose of study drug", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "months", "min": 6, "max": null, "applies_when": "surgical sterilization qualification", "exception": "", "quote": "Surgically sterilized (eg, hysterectomy, bilateral salpingectomy, bilateral oophorectomy) at least 6 months before dosing", "section_id": "regimen_g:5.10.2", "from_event_id": "surgical_sterilization", "to_event_id": "first_study_dose", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0285", "implied": false, "stated": [6, null]}','','[]',6285,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0286','check','','judgment','','{"kind": "judgment", "text": "Female participants of childbearing potential and their male partners must use highly effective contraception from start of dosing through study participation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "female participants of childbearing potential using standard contraception pathway", "exception": "azoospermic partner pathway", "quote": "For participants of childbearing potential: both the participant and the male partner must use highly effective contraception at the start of dosing, throughout the study period, and for 90 days after the final administration of study drug.", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0286"}','','[]',6286,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0287','check','','interval','','{"kind": "interval", "text": "Continue required contraception at least 90 days after final study drug dose.", "from_event": "last dose of study drug", "to_event": "end of required contraception", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 90, "max": null, "applies_when": "female participants of childbearing potential using standard contraception pathway", "exception": "", "quote": "For participants of childbearing potential: both the participant and the male partner must use highly effective contraception at the start of dosing, throughout the study period, and for 90 days after the final administration of study drug.", "section_id": "regimen_g:5.10.2", "from_event_id": "last_study_dose", "to_event_id": "contraception_end", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0287", "implied": false, "stated": [90, null]}','','[]',6287,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0288','check','','judgment','','{"kind": "judgment", "text": "Use two birth-control forms including a male barrier such as latex or polyurethane condom.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "female participants using standard contraception pathway", "exception": "", "quote": "Highly effective contraception consists of two forms of birth control, one of which must be a male barrier method such as a latex or polyurethane condom.", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0288"}','','[]',6288,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0289','check','','judgment','','{"kind": "judgment", "text": "The other method must qualify under Appendix III: IUD, intrauterine hormone-releasing system, bilateral tubal ligation, or defined abstinence.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "female participants using standard contraception pathway", "exception": "", "quote": "The other must be a highly effective method (as defined in Appendix III), which includes one of the following:", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0289"}','','[]',6289,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0290','check','','judgment','','{"kind": "judgment", "text": "Abstinence means no heterosexual intercourse throughout the entire study.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "abstinence chosen as contraception", "exception": "", "quote": "Abstinence, defined as refraining from heterosexual intercourse during the entire study and for 90 days after last dose of study drug.", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0290"}','','[]',6290,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0291','check','','interval','','{"kind": "interval", "text": "Maintain chosen abstinence for at least 90 days after last study drug dose.", "from_event": "last dose of study drug", "to_event": "end of abstinence", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 90, "max": null, "applies_when": "abstinence chosen as contraception", "exception": "", "quote": "Abstinence, defined as refraining from heterosexual intercourse during the entire study and for 90 days after last dose of study drug.", "section_id": "regimen_g:5.10.2", "from_event_id": "last_study_dose", "to_event_id": "abstinence_end", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0291", "implied": false, "stated": [90, null]}','','[]',6291,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0292','check','','judgment','','{"kind": "judgment", "text": "Do not accept periodic abstinence, including calendar, symptothermal or postovulation methods.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "\u2018Periodic abstinence\u2019 (calendar, symptothermal, postovulation methods) is considered not reliable and would not be acceptable.", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0292"}','','[]',6292,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0293','check','','judgment','','{"kind": "judgment", "text": "An azoospermic male partner must still use a male barrier method.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "female participant of childbearing potential with azoospermic male partner", "exception": "", "quote": "For participants of childbearing potential with an azoospermic male partner, the male partner must use a male barrier method such as a latex or polyurethane condom.", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0293"}','','[]',6293,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0294','check','','judgment','','{"kind": "judgment", "text": "Accept azoospermia as highly effective contraception only if that partner is the woman''s sole sexual partner.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "azoospermic partner contraception pathway", "exception": "", "quote": "Azoospermia is a highly effective contraceptive method provided that the partner is the sole sexual partner of the woman of childbearing potential.", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0294"}','','[]',6294,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0295','check','','not_checkable','','{"kind": "not_checkable", "text": "Azoospermia documentation may derive from site review of medical records, medical examination, or medical history interview.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Note: documentation of azoospermia for a male participant can come from the site personnel\u2019s review of the participant\u2019s medical records, medical examination, or medical history interview.", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0295"}','','[]',6295,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0296','check','','judgment','','{"kind": "judgment", "text": "Male participants having sex with a woman of childbearing potential must use two methods: male barrier plus highly effective female-partner contraception under Appendix III.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "male participant engaging in sex with female partner of childbearing potential", "exception": "azoospermic male participant pathway", "quote": "When engaging in sex with a female partner of childbearing potential, both the male participant and his female partner must use highly effective contraception consisting of two forms of birth control, one of which must be a male barrier method such as a latex or polyurethane condom, and the other of which must be a highly effective form of birth control (as defined in Appendix III) used by the female partner.", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0296"}','','[]',6296,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0297','check','','judgment','','{"kind": "judgment", "text": "Male-participant contraception is required from start of dosing throughout study participation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "male participant standard contraception pathway", "exception": "", "quote": "This is required from the start of dosing, throughout the study period, and for 90 days after the final administration of study drug.", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0297"}','','[]',6297,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0298','check','','interval','','{"kind": "interval", "text": "Continue male-participant contraception at least 90 days after final study drug dose.", "from_event": "last dose of study drug", "to_event": "end of required contraception", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 90, "max": null, "applies_when": "male participant standard contraception pathway", "exception": "", "quote": "This is required from the start of dosing, throughout the study period, and for 90 days after the final administration of study drug.", "section_id": "regimen_g:5.10.2", "from_event_id": "last_study_dose", "to_event_id": "contraception_end", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0298", "implied": false, "stated": [90, null]}','','[]',6298,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0299','check','','judgment','','{"kind": "judgment", "text": "Azoospermic male participants with a female partner of childbearing potential must use a male barrier.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "azoospermic male participant with female partner of childbearing potential", "exception": "", "quote": "For azoospermic male participants with a woman partner of childbearing potential the male partner must use a male barrier method such as a latex or polyurethane condom.", "section_id": "regimen_g:5.10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0299"}','','[]',6299,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
