INSERT INTO guide VALUES('NCT05842941','checks','chk:0317','check','','order','','{"kind": "order", "text": "Participant must read the form before signing, with signature deferred until consent review.", "from_event": "", "to_event": "", "first_event": "participant reads informed consent form", "then_event": "participant signs informed consent form", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "remote reconsent", "exception": "", "quote": "b) The participant reads through the consent form but does not sign.", "section_id": "regimen_g:6", "from_event_id": "", "to_event_id": "", "first_event_id": "icf_reading", "then_event_id": "participant_icf_signature", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0317", "implied": false}','','[]',6317,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0318','check','','follow_up','','{"kind": "follow_up", "text": "Investigator or approved, delegated consent staff must contact the participant and review the form.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "remote reconsent", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "c) The Site Investigator, or other study staff member approved and delegated to obtain informed consent, contacts the participant and reviews the informed consent form with the participant.", "section_id": "regimen_g:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "remote_reconsent", "value_name_id": "", "code": false, "id": "chk:0318"}','','[]',6318,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
