INSERT INTO guide VALUES('NCT05842941','checks','chk:0321','check','','order','','{"kind": "order", "text": "The staff member who consented the participant must sign after the site receives the participant-signed form.", "from_event": "", "to_event": "", "first_event": "site receives original participant-signed informed consent form", "then_event": "consenting staff member signs informed consent form", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "remote reconsent", "exception": "", "quote": "e) Once received at the site, the individual who consented the participant signs the informed consent form.", "section_id": "regimen_g:6", "from_event_id": "", "to_event_id": "", "first_event_id": "original_icf_received", "then_event_id": "staff_icf_signature", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0321", "implied": false}','','[]',6321,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0322','check','','judgment','','{"kind": "judgment", "text": "Use remote substitution for designated week 4, 8 and 16 visits only for participant safety due to pandemic, disability or another medically necessary reason.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "substituting remote services for designated in-person visit", "exception": "", "quote": "Designated visits in the SOA (i.e., Week 4, Week 8, and Week 16) may be conducted via telemedicine (or phone if telemedicine is not available) with remote services instead of in-person if needed to protect the safety of the participant due to a pandemic, disability, or other medically necessary reason.", "section_id": "regimen_g:s049", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0322"}','','[]',6322,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0323','check','','judgment','','{"kind": "judgment", "text": "Use phone instead of telemedicine only if telemedicine is unavailable.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "remote substitution for designated visits", "exception": "", "quote": "Designated visits in the SOA (i.e., Week 4, Week 8, and Week 16) may be conducted via telemedicine (or phone if telemedicine is not available) with remote services instead of in-person if needed to protect the safety of the participant due to a pandemic, disability, or other medically necessary reason.", "section_id": "regimen_g:s049", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0323"}','','[]',6323,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
