INSERT INTO guide VALUES('NCT05842941','checks','chk:0359','check','','interval','','{"kind": "interval", "text": "Separate the two alternative week 4 postdose PK collections by at least one hour.", "from_event": "first alternative week 4 postdose PK sample", "to_event": "second alternative week 4 postdose PK sample", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "hours", "min": 1, "max": null, "applies_when": "week 4 home-dose alternative", "exception": "", "quote": "The two PK collections should occur at least one hour apart without a dose administered in between and a minor protocol deviation recorded.", "section_id": "regimen_g:6.3", "from_event_id": "first_alt_w4_postdose_pk", "to_event_id": "w4_alt_pk_2", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0359", "implied": false, "stated": [1, null]}','','[]',6359,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
