INSERT INTO guide VALUES('NCT05842941','checks','chk:0442','check','','judgment','','{"kind": "judgment", "text": "Schedule in-person ET visit as soon as possible after early termination.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "early termination", "exception": "", "quote": "The in-person ET Visit should be scheduled as soon as possible after a participant early terminates.", "section_id": "regimen_g:6.9", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0442"}','','[]',6442,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0443','check','','follow_up','','{"kind": "follow_up", "text": "Conduct all applicable week 24 in-clinic assessments at ET after placebo-controlled-period termination or consent withdrawal.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "early termination visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "termination or consent withdrawal during placebo-controlled portion", "exception": "Assessment-specific conditions, including optional CSF eligibility, still apply.", "quote": "If the participant early terminates or withdraws consent during the placebo-controlled portion of the Regimen, all assessments that are collected at the Week 24 in-clinic visit should be conducted.", "section_id": "regimen_g:6.9", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "et_visit", "value_name_id": "", "code": false, "id": "chk:0443"}','','[]',6443,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0444','check','','judgment','','{"kind": "judgment", "text": "Complete early-termination follow-up safety call approximately 28 days after last dose.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": null, "max": null, "applies_when": "early termination", "exception": "May collect information at ET within 25\u201331 days after last dose.", "quote": "The Follow-Up Safety Call should be completed approximately 28 days after the last dose of study drug.", "section_id": "regimen_g:6.9", "from_event_id": "last_study_dose", "to_event_id": "safety_followup_call", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0444", "about": 28, "implied": false}','','[]',6444,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0445','check','','interval','','{"kind": "interval", "text": "Combine follow-up safety information with ET visit only when ET occurs 25\u201331 days after last dose.", "from_event": "last dose of study drug", "to_event": "early termination visit", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 25, "max": 31, "applies_when": "using ET visit instead of separate follow-up safety call", "exception": "", "quote": "If the ET Visit occurs approximately 28\u00b13 days after the last dose of study drug, the information for the Follow-Up Safety Call can be collected during the ET visit, and a separate Follow-Up Safety Call does not need to be completed.", "section_id": "regimen_g:6.9", "from_event_id": "last_study_dose", "to_event_id": "et_visit", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0445", "implied": false, "stated": [25, 31]}','','[]',6445,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0446','check','','order','','{"kind": "order", "text": "If ET is not within 25\u201331 days after last dose, complete follow-up safety call before ET visit.", "from_event": "", "to_event": "", "first_event": "follow-up safety call", "then_event": "early termination visit", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "ET visit does not occur within 28\u00b13 days of last dose", "exception": "", "quote": "If the in-person ET Visit does not occur within\n28\u00b13 days of the last dose of study drug, the Follow-Up Safety Call should occur approximately 28 days after the last dose of study drug and the ET Visit will be completed after the Follow-Up Safety Call.", "section_id": "regimen_g:6.9", "from_event_id": "", "to_event_id": "", "first_event_id": "safety_followup_call", "then_event_id": "et_visit", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0446", "implied": false}','','[]',6446,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0447','check','','not_checkable','','{"kind": "not_checkable", "text": "Separate ET visit and follow-up call are unnecessary when study drug is discontinued but participant completes protocol; a qualifying ET visit can replace a separate safety call.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "If a participant has to discontinue study drug, but will complete the protocol, an in-person ET Visit and Follow-Up Safety Call is not necessary.", "section_id": "regimen_g:6.9", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0447"}','','[]',6447,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0448','check','','judgment','','{"kind": "judgment", "text": "Make every effort to retain participants, including in ATE, regardless of drug discontinuation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Every effort should be made to retain participants in the study, including the ATE period, regardless of whether they have discontinued study drug.", "section_id": "regimen_g:6.9", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0448"}','','[]',6448,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0449','check','','judgment','','{"kind": "judgment", "text": "Optional ET CSF collection requires baseline CSF collection.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "early termination CSF collection", "exception": "", "quote": "For the ET Visit, optional CSF collection will be completed in participants with a Baseline CSF collection and only if the ET visit occurs at or after the Week 12 visit.", "section_id": "regimen_g:6.9", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0449"}','','[]',6449,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0450','check','','order','','{"kind": "order", "text": "Perform optional ET CSF only when ET occurs at or after week 12 visit.", "from_event": "", "to_event": "", "first_event": "week 12 visit", "then_event": "early termination visit", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "early termination CSF collection", "exception": "ET visit may coincide with week 12 visit.", "quote": "For the ET Visit, optional CSF collection will be completed in participants with a Baseline CSF collection and only if the ET visit occurs at or after the Week 12 visit.", "section_id": "regimen_g:6.9", "from_event_id": "", "to_event_id": "", "first_event_id": "w12_visit", "then_event_id": "et_visit", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0450", "implied": false}','','[]',6450,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0451','check','','follow_up','','{"kind": "follow_up", "text": "Continue participants into the ATE according to the SOA.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "completion of placebo-controlled period", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Following the placebo-controlled period, participants will continue in the ATE as outlined in the SOA.", "section_id": "regimen_g:6.10", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "blinded_treatment_end", "value_name_id": "", "code": false, "id": "chk:0451"}','','[]',6451,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0452','check','','judgment','','{"kind": "judgment", "text": "Continue the ATE until all active participants have completed at least 52 weeks.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Industry Partner extension or discontinuation based on primary analysis results.", "quote": "The ATE will continue until all active participants have completed a minimum of 52 weeks in the ATE; no participant will exceed 78 weeks in the ATE (ie, 102 weeks total from the Baseline visit).", "section_id": "regimen_g:6.10", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0452"}','','[]',6452,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0453','check','','interval','','{"kind": "interval", "text": "Do not exceed 78 weeks in the ATE.", "from_event": "ATE entry", "to_event": "ATE completion", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "weeks", "min": null, "max": 78, "applies_when": "", "exception": "Industry Partner extension of the ATE.", "quote": "The ATE will continue until all active participants have completed a minimum of 52 weeks in the ATE; no participant will exceed 78 weeks in the ATE (ie, 102 weeks total from the Baseline visit).", "section_id": "regimen_g:6.10", "from_event_id": "ate_entry", "to_event_id": "ate_treatment_end", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0453", "stated": [null, 78]}','','[]',6453,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
