INSERT INTO guide VALUES('NCT05842941','checks','chk:0455','check','','not_checkable','','{"kind": "not_checkable", "text": "The Industry Partner may change the ATE duration based on primary analysis results.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The Industry Partner may consider extending or discontinuing the ATE period depending on the results from the primary analysis.", "section_id": "regimen_g:6.10", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0455"}','','[]',6455,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0456','check','','judgment','','{"kind": "judgment", "text": "Unscheduled safety visits may occur at any time when the Investigator deems them medically appropriate and necessary.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "unscheduled safety assessment visit", "exception": "", "quote": "Unscheduled visits for safety assessments that are deemed medically appropriate and necessary by the Investigator may be performed at any time, independent of scheduled in-clinic visits.", "section_id": "regimen_g:6.10", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0456"}','','[]',6456,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0457','check','','follow_up','','{"kind": "follow_up", "text": "Collect additional unscheduled PK samples as needed to assess TEAEs causing dose reduction or interruption, or severe TEAEs requiring an unscheduled assessment visit.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "TEAE causing dose reduction or interruption or severe TEAE requiring an unscheduled assessment visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "PK samples needed for TEAE assessment", "exception": "", "quote": "Additional unscheduled PK samples should be collected as needed as part of assessment for TEAEs leading to dose reduction or dose interruption or any severe TEAE that requires an unscheduled visit for assessment.", "section_id": "regimen_g:6.10", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "teae_dose_or_visit", "value_name_id": "", "code": false, "id": "chk:0457"}','','[]',6457,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0458','check','','judgment','','{"kind": "judgment", "text": "Use remote services instead of in-person visits only at designated SOA visits (Week 4, 8, 16, 28, 40 in ATE) when necessary for participant safety due to a pandemic, disability, or another medically necessary reason.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "replacement of a designated in-person visit with remote services", "exception": "", "quote": "Designated visits in the SOA (i.e., Week 4, Week 8, Week 16, Week 28, Week 40 in ATE) may be conducted via telemedicine (or phone if telemedicine is not available) with remote services instead of in-person if needed to protect the safety of the participant due to a pandemic, disability, or other medically necessary reason.", "section_id": "regimen_g:s060", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0458"}','','[]',6458,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
