INSERT INTO guide VALUES('NCT05842941','checks','chk:0658','check','','not_checkable','','{"kind": "not_checkable", "text": "ALSAQ-40, ROADS, PGI-C, PGI-S, and CGI-C are explicitly not required for early discontinuations after week 52; this permission is not itself a site violation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "For early discontinuations after Week 52 in ATE, assessments for ALSAQ-40, ROADS, PGI-C, PGI-S, and CGI-C are not required.", "section_id": "regimen_g:6.10.13", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0658"}','','[]',6658,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0659','check','','judgment','','{"kind": "judgment", "text": "Complete the follow-up safety call approximately 28 days after the last dose.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": null, "max": null, "applies_when": "early termination", "exception": "Safety-call information collected at an ET visit 25\u201331 days after the last dose.", "quote": "The Follow-Up Safety Call should be completed approximately 28 days after the last dose of study drug.", "section_id": "regimen_g:6.10.13", "from_event_id": "last_study_dose", "to_event_id": "safety_followup_call", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0659", "about": 28, "implied": false}','','[]',6659,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0660','check','','interval','','{"kind": "interval", "text": "An ET visit replacing the separate safety call must occur 25\u201331 days after the last dose.", "from_event": "last dose of study drug", "to_event": "ET visit", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 25, "max": 31, "applies_when": "ET visit used instead of a separate follow-up safety call", "exception": "", "quote": "If the ET Visit occurs approximately 28\u00b13 days after the last dose of study drug, the information for the Follow-Up Safety Call can be collected during the ET visit, and a separate Follow-Up Safety Call does not need to be completed.", "section_id": "regimen_g:6.10.13", "from_event_id": "last_study_dose", "to_event_id": "et_visit", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0660", "implied": false, "stated": [25, 31]}','','[]',6660,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0661','check','','follow_up','','{"kind": "follow_up", "text": "Collect the safety-call information at ET when omitting the separate safety call.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ET visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "ET visit 25\u201331 days after the last dose replaces the separate safety call", "exception": "", "quote": "If the ET Visit occurs approximately 28\u00b13 days after the last dose of study drug, the information for the Follow-Up Safety Call can be collected during the ET visit, and a separate Follow-Up Safety Call does not need to be completed.", "section_id": "regimen_g:6.10.13", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "et_visit", "value_name_id": "", "code": false, "id": "chk:0661"}','','[]',6661,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0662','check','','judgment','','{"kind": "judgment", "text": "Conduct a separate safety call approximately 28 days after the last dose when ET is outside the 25\u201331-day window.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": null, "max": null, "applies_when": "in-person ET visit does not occur 25\u201331 days after last dose", "exception": "", "quote": "If the in-person ET Visit does not occur within 28\u00b13 days of the last dose of study drug, the Follow-Up Safety Call should occur approximately 28 days after the last dose of study drug and the ET Visit will be completed after the Follow-Up Safety Call.", "section_id": "regimen_g:6.10.13", "from_event_id": "last_study_dose", "to_event_id": "safety_followup_call", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0662", "about": 28, "implied": false}','','[]',6662,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0663','check','','order','','{"kind": "order", "text": "Complete the safety call before the ET visit when ET is outside the 25\u201331-day window.", "from_event": "", "to_event": "", "first_event": "follow-up safety call", "then_event": "ET visit", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "in-person ET visit does not occur 25\u201331 days after last dose", "exception": "", "quote": "If the in-person ET Visit does not occur within 28\u00b13 days of the last dose of study drug, the Follow-Up Safety Call should occur approximately 28 days after the last dose of study drug and the ET Visit will be completed after the Follow-Up Safety Call.", "section_id": "regimen_g:6.10.13", "from_event_id": "", "to_event_id": "", "first_event_id": "safety_followup_call", "then_event_id": "et_visit", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0663", "implied": false}','','[]',6663,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0664','check','','not_checkable','','{"kind": "not_checkable", "text": "Background: ALSAQ-40 is a 40-question self-report outcome measuring subjective well-being in ALS and motor neuron disease.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The ALSAQ-40 consists of forty questions that are specifically used to measure the subjective well-being of patients with ALS and motor neuron disease.", "section_id": "regimen_g:7.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0664"}','','[]',6664,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0665','check','','follow_up','','{"kind": "follow_up", "text": "Hand participants ALSAQ-40 and ask them to write their own answers.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALSAQ-40 administration", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Needed assistance transferring participant responses to the form.", "quote": "Participants will be handed the questionnaire and asked to write their answers themselves.", "section_id": "regimen_g:7.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "alsaq40", "value_name_id": "", "code": false, "id": "chk:0665"}','','[]',6665,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0666','check','','judgment','','{"kind": "judgment", "text": "Caregiver or staff assistance with ALSAQ-40 must be needed and limited to transferring participant responses; do not help determine answers.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "assistance with ALSAQ-40", "exception": "", "quote": "Caregivers or study staff can also help, if needed but should only assist in transferring the participant\u2019s responses to the form, and should not provide any assistance with determining answers.", "section_id": "regimen_g:7.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0666"}','','[]',6666,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0667','check','','not_checkable','','{"kind": "not_checkable", "text": "Background: CNS-BFS is a 21-question self-report scale covering swallowing, speech, and salivation, used in trials and clinical evaluation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The CNS-BFS consists of three domains (swallowing, speech, and salivation), which are assessed with a 21-question, self-report questionnaire.", "section_id": "regimen_g:7.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0667"}','','[]',6667,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
