INSERT INTO guide VALUES('NCT05842941','checks','chk:0669','check','','judgment','','{"kind": "judgment", "text": "Caregiver or staff assistance with CNS-BFS must be needed and limited to transferring participant responses; do not help determine answers.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "assistance with CNS-BFS", "exception": "", "quote": "Caregivers or study staff can also help, if needed, but should only assist in transferring the participant\u2019s responses to the form, and should not provide any assistance with determining answers.", "section_id": "regimen_g:7.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0669"}','','[]',6669,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0670','check','','not_checkable','','{"kind": "not_checkable", "text": "Background/statistics: ROADS is a validated 28-question linear self-report functional outcome created with Rasch modeling; raw scores are converted to normed whole numbers before analysis, and the scale and conversion table are publicly available.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Prior to analysis, ROADS raw scores are converted to normed whole numbers.", "section_id": "regimen_g:7.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0670"}','','[]',6670,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0671','check','','follow_up','','{"kind": "follow_up", "text": "Hand participants ROADS and ask them to write their own answers.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ROADS administration", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Needed assistance transferring participant responses to the form.", "quote": "Participants will be handed the questionnaire and asked to write their answers themselves.", "section_id": "regimen_g:7.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "roads_administration", "value_name_id": "", "code": false, "id": "chk:0671"}','','[]',6671,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0672','check','','judgment','','{"kind": "judgment", "text": "Caregiver or staff assistance with ROADS must be needed and limited to transferring participant responses; do not help determine answers.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "assistance with ROADS", "exception": "", "quote": "Caregivers or study staff can also help, if needed but should only assist in transferring the participant\u2019s responses to the form and should not provide any assistance with determining answers.", "section_id": "regimen_g:7.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0672"}','','[]',6672,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0673','check','','not_checkable','','{"kind": "not_checkable", "text": "Background/patient-facing scale description: PGI-C assesses perceived treatment efficacy and change relative to baseline on seven categories from very much improved to very much worse.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Respondents rate their change relative to baseline as \u201cvery much improved,\u201d \u201cmuch improved,\u201d \u201cminimally improved,\u201d \u201cno change,\u201d \u201cminimally worse,\u201d \u201cmuch worse,\u201d or \u201cvery much worse\u201d (Hurst and Bolton 2004).", "section_id": "regimen_g:7.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0673"}','','[]',6673,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0674','check','','not_checkable','','{"kind": "not_checkable", "text": "Background/patient-facing scale description: PGI-S is a single-item current-severity outcome scored normal=1, mild=2, moderate=3, severe=4.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The PGI-S item asks the respondent to best describe the level of severity of their symptoms now on a 4-point scale scored as: \u201cnormal\u201d (1), \u201cmild\u201d (2), \u201cmoderate\u201d (3), or \u201csevere\u201d (4) (Viktrup et al 2012).", "section_id": "regimen_g:7.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0674"}','','[]',6674,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0675','check','','not_checkable','','{"kind": "not_checkable", "text": "Background: CGI-C describes the clinician''s global-function assessment before and after medication initiation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The CGI-C is a stand-alone assessment of the clinician''s view of the patient''s global functioning prior to and after initiating a study medication (Busnar et al 2007).", "section_id": "regimen_g:7.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0675"}','','[]',6675,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0676','check','','judgment','','{"kind": "judgment", "text": "Have the clinician rate CGI-C relative to the pre-study-drug condition using the seven-point scale: 1 very much improved through 7 very much worse.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "CGI-C administration", "exception": "", "quote": "CGI-C asks the clinician one question, which is rated on a seven-point scale: \u201cCompared to the patient\u2019s condition at admission the project (prior to study drug initiation), this patient\u2019s condition is 1=very much improved; 2=much improved; 3=minimally improved; 4=no change from baseline; 5=minimally worse; 6=much worse; 7=very much worse since the initiation of study drug treatment\u201d.", "section_id": "regimen_g:7.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0676"}','','[]',6676,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0677','check','','follow_up','','{"kind": "follow_up", "text": "Record vital status for every randomized participant throughout placebo-controlled follow-up, including dates of death and PAV initiation or last-known-alive and last-known-PAV-free dates.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "placebo-controlled follow-up", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "each randomized participant", "exception": "", "quote": "Vital status, including determination of dates of death and initiation of PAV or dates last known alive and last known PAV-free, will be recorded by site study staff for each randomized participant throughout the placebo-controlled portion of their follow-up (generally the Week 24 Visit, as indicated in the SOA) and at the conclusion of the ATE participation.", "section_id": "regimen_g:7.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "placebo_followup", "value_name_id": "", "code": false, "id": "chk:0677"}','','[]',6677,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0678','check','','follow_up','','{"kind": "follow_up", "text": "Record vital status at conclusion of ATE participation, including death/PAV dates or last-known-alive/PAV-free dates.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ATE completion", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "each randomized participant participating in ATE", "exception": "", "quote": "Vital status, including determination of dates of death and initiation of PAV or dates last known alive and last known PAV-free, will be recorded by site study staff for each randomized participant throughout the placebo-controlled portion of their follow-up (generally the Week 24 Visit, as indicated in the SOA) and at the conclusion of the ATE participation.", "section_id": "regimen_g:7.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ate_treatment_end", "value_name_id": "", "code": false, "id": "chk:0678"}','','[]',6678,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0679','check','','judgment','','{"kind": "judgment", "text": "Complete a second vital-status check for every randomized participant approximately at placebo-controlled LPLV.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "approximately placebo-controlled regimen LPLV", "exception": "", "quote": "At approximately the time of the last participant, last visit (LPLV) of the placebo-controlled portion of the regimen, a second vital status check will be completed by site study staff for each randomized participant.", "section_id": "regimen_g:7.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0679"}','','[]',6679,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0680','check','','follow_up','','{"kind": "follow_up", "text": "Contact all randomized participants or caregivers to assess vital status when prompted.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "Coordination Center prompt for vital-status assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "When prompted by the Coordination Center, sites will contact all randomized participants or their caregivers to assess vital status.", "section_id": "regimen_g:7.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "vital_status_prompt", "value_name_id": "", "code": false, "id": "chk:0680"}','','[]',6680,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0681','check','','not_checkable','','{"kind": "not_checkable", "text": "Later vital-status ascertainment may occur; an outside vendor will use public data to determine death or last-known-alive dates for randomized participants.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "An outside vendor will be used to ascertain death or date of last known alive for all randomized participants by using publicly available data sources.", "section_id": "regimen_g:7.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0681"}','','[]',6681,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0682','check','','follow_up','','{"kind": "follow_up", "text": "Provide participant demographic information to the vendor using a secure method when prompted.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "Coordination Center prompt for vendor demographic information", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "When prompted by the Coordination Center, sites will provide demographic information (e.g., participant name, date of birth, last known address) to the vendor using a secure method.", "section_id": "regimen_g:7.7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "vendor_demographics_prompt", "value_name_id": "", "code": false, "id": "chk:0682"}','','[]',6682,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0683','check','','not_checkable','','{"kind": "not_checkable", "text": "Master Protocol contains the biomarker biofluid collection requirements; CSF collection is optional.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Biofluid samples (blood, urine, and CSF) that will be used for biomarker assessments for Regimen G are captured in the Master Protocol.", "section_id": "regimen_g:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0683"}','','[]',6683,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0684','check','','judgment','','{"kind": "judgment", "text": "For optional Regimen G CSF collection, use baseline and week 24 rather than baseline and week 16.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "participant undergoes optional Regimen G CSF collection", "exception": "CSF collection may be declined.", "quote": "It should be noted that the CSF biofluid collection is optional and collection for Regimen G occurs at Baseline and Week 24 (rather than Baseline and Week 16 as noted in the Master Protocol).", "section_id": "regimen_g:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0684"}','','[]',6684,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0685','check','','follow_up','','{"kind": "follow_up", "text": "Collect additional blood samples for plasma PK at SOA-scheduled timepoints.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "SOA-scheduled plasma PK collection timepoint", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "Regimen G", "exception": "", "quote": "Additional biofluid samples (blood) will be collected for Regimen G for evaluation of plasma PK at scheduled timepoints described in the SOA.", "section_id": "regimen_g:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "soa_plasma_pk_time", "value_name_id": "", "code": false, "id": "chk:0685"}','','[]',6685,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0686','check','','not_checkable','','{"kind": "not_checkable", "text": "Statistical design follows Appendix I of the Master SAP unless otherwise noted.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The statistical design for Regimen G will be in accordance with the statistical design described in Appendix I of the Master SAP, unless otherwise noted.", "section_id": "regimen_g:9.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0686"}','','[]',6686,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0687','check','','not_checkable','','{"kind": "not_checkable", "text": "Clinical trial simulations quantified operating characteristics; details are in the Regimen G SAP.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Clinical trial simulation was used to quantify operating characteristics for Regimen G (refer to the Regimen G statistical analysis plan for further details).", "section_id": "regimen_g:9.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0687"}','','[]',6687,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0688','check','','not_checkable','','{"kind": "not_checkable", "text": "Analyses share controls across regimens, justified by minor eligibility differences and no expected systematic endpoint or safety differences.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The primary or supportive analyses of Regimen G will include sharing of controls from other regimens.", "section_id": "regimen_g:9.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0688"}','','[]',6688,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0689','check','','judgment','','{"kind": "judgment", "text": "Use an accepted highly effective method (IUD, IUS, bilateral tubal ligation, or qualifying azoospermic partner) together with a male barrier method.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "female participants of childbearing potential", "exception": "Qualifying abstinence is an alternative highly effective method.", "quote": "Table: Highly Effective Methods a to be used in combination with a male barrier method (e.g. condom)", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0689"}','','[]',6689,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0690','check','','judgment','','{"kind": "judgment", "text": "Abstinence must mean refraining from heterosexual intercourse throughout the study.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "abstinence used as contraception by a female participant of childbearing potential", "exception": "", "quote": "- \u2022 Abstinence defined as refraining from heterosexual intercourse during the entire duration of the study and for 90 days after last dose of study drug.", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0690"}','','[]',6690,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0691','check','','interval','','{"kind": "interval", "text": "Maintain abstinence for at least 90 days after the last dose.", "from_event": "last dose of study drug", "to_event": "resumption of heterosexual intercourse", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 90, "max": null, "applies_when": "abstinence used as contraception by a female participant of childbearing potential", "exception": "", "quote": "- \u2022 Abstinence defined as refraining from heterosexual intercourse during the entire duration of the study and for 90 days after last dose of study drug.", "section_id": "regimen_g:s089", "from_event_id": "last_study_dose", "to_event_id": "intercourse_resumed", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0691", "implied": false, "stated": [90, null]}','','[]',6691,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0692','check','','judgment','','{"kind": "judgment", "text": "Do not accept periodic abstinence as contraception.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "female participants of childbearing potential", "exception": "", "quote": "\u2018Periodic abstinence\u2019 is considered not reliable and would not be acceptablee", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0692"}','','[]',6692,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0693','check','','judgment','','{"kind": "judgment", "text": "Do not use male and female condoms together.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "contraceptive use", "exception": "", "quote": "Notes: Male condom and female condom should not be used together (due to risk of failure with friction).", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0693"}','','[]',6693,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0694','check','','judgment','','{"kind": "judgment", "text": "Ensure contraceptive use is consistent with local clinical-study contraception regulations.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "contraceptive use by participants", "exception": "", "quote": "1. Contraceptive use by participants should be consistent with local regulations regarding the use of contraceptive methods for those participating in clinical studies.", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0694"}','','[]',6694,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0695','check','','not_checkable','','{"kind": "not_checkable", "text": "Background: highly effective methods have less than 1% annual failure with consistent correct use; typical-use rates differ, and spermatogenesis takes approximately 90 days.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "2. Failure rate of < 1% per year when used consistently and correctly.", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0695"}','','[]',6695,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0696','check','','judgment','','{"kind": "judgment", "text": "Do not accept Essure fallopian tube coil placement as contraception.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "female participants of childbearing potential", "exception": "", "quote": "c Essure fallopian tube coil placement is not accepted, as the permanent contraception failure rate is likely greater than 1%.", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0696"}','','[]',6696,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0697','check','','judgment','','{"kind": "judgment", "text": "Rely on partner azoospermia only if that partner is the woman''s sole sexual partner.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "azoospermic partner used as highly effective contraception", "exception": "Use an additional highly effective contraceptive method if this condition is not met.", "quote": "1. Azoospermia is a highly effective contraceptive method provided that the partner is the sole sexual partner of the woman of childbearing potential and the absence of sperm has been confirmed.", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0697"}','','[]',6697,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0698','check','','judgment','','{"kind": "judgment", "text": "Rely on partner azoospermia only when absence of sperm has been confirmed.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "azoospermic partner used as highly effective contraception", "exception": "Use an additional highly effective contraceptive method if this condition is not met.", "quote": "1. Azoospermia is a highly effective contraceptive method provided that the partner is the sole sexual partner of the woman of childbearing potential and the absence of sperm has been confirmed.", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0698"}','','[]',6698,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0699','check','','follow_up','','{"kind": "follow_up", "text": "Use an additional highly effective method if the azoospermic partner is not the sole partner or absence of sperm is unconfirmed.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "azoospermic partner contraception conditions not met", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "female participant of childbearing potential relying on partner azoospermia", "exception": "", "quote": "If not, an additional highly effective method of contraception should be used.", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "azoospermia_conditions_unmet", "value_name_id": "", "code": false, "id": "chk:0699"}','','[]',6699,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0700','check','','judgment','','{"kind": "judgment", "text": "Azoospermia documentation for a male participant may be based on site review of medical records, medical examination, or medical-history interview.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "documenting azoospermia for a male participant", "exception": "", "quote": "Note: documentation of azoospermia for a male participant can come from the site personnel\u2019s review of the participant\u2019s medical records, medical examination, or medical history interview.", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0700"}','','[]',6700,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0701','check','','judgment','','{"kind": "judgment", "text": "Do not accept periodic abstinence, including calendar, symptothermal, or post-ovulation methods.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "contraception for female participants of childbearing potential", "exception": "", "quote": "2. Periodic abstinence (calendar, symptothermal, post ovulation methods), withdrawal (coitus interruptus),\nspermicides only, and lactational amenorrhea method are NOT acceptable methods of contraception.", "section_id": "regimen_g:s089", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0701"}','','[]',6701,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
