INSERT INTO guide VALUES('NCT05842941','checks','chk:0709','check','','judgment','','{"kind": "judgment", "text": "Do not use male and female condoms together.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Notes: Male condom and female condom should not be used together (due to risk of failure with friction).", "section_id": "regimen_g:s090", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0709"}','','[]',6709,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0710','check','','judgment','','{"kind": "judgment", "text": "Ensure contraceptive use complies with local clinical-study contraception regulations.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Contraceptive use by participants should be consistent with local regulations regarding the use of contraceptive methods for those participating in clinical studies.", "section_id": "regimen_g:s090", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0710"}','','[]',6710,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0711','check','','not_checkable','','{"kind": "not_checkable", "text": "Appendix heading, method descriptions, contraceptive failure-rate background, approximately 90-day spermatogenesis cycle, and permitted sources of azoospermia documentation are informational.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Typical use failure rates differ from those when used consistently and correctly.", "section_id": "regimen_g:s090", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0711"}','','[]',6711,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0712','check','','judgment','','{"kind": "judgment", "text": "Do not accept Essure fallopian tube coil placement as contraception.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Essure fallopian tube coil placement is not accepted, as the permanent contraception failure rate is likely greater than 1%.", "section_id": "regimen_g:s090", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0712"}','','[]',6712,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0713','check','','judgment','','{"kind": "judgment", "text": "Accept azoospermia as highly effective contraception only when the male participant is the woman''s sole sexual partner.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when relying on azoospermia", "exception": "", "quote": "Azoospermia is a highly effective contraceptive method provided that the partner is the sole sexual partner of the woman of childbearing potential and the absence of sperm has been confirmed.", "section_id": "regimen_g:s090", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0713"}','','[]',6713,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0714','check','','follow_up','','{"kind": "follow_up", "text": "Confirm absence of sperm before accepting azoospermia as highly effective contraception; documentation may come from site review of medical records, medical examination, or medical history interview.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "reliance on azoospermia for contraception", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when relying on azoospermia", "exception": "", "quote": "Azoospermia is a highly effective contraceptive method provided that the partner is the sole sexual partner of the woman of childbearing potential and the absence of sperm has been confirmed.", "section_id": "regimen_g:s090", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "azoospermia_contraception", "value_name_id": "", "code": false, "id": "chk:0714"}','','[]',6714,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0715','check','','follow_up','','{"kind": "follow_up", "text": "Require an additional highly effective contraceptive method if the azoospermia conditions are not met.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "azoospermia contraception conditions not met", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "absence of sperm is not confirmed or the male participant is not the woman''s sole sexual partner", "exception": "", "quote": "If not, an additional highly effective method of contraception should be used.", "section_id": "regimen_g:s090", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "azoospermia_conditions_unmet", "value_name_id": "", "code": false, "id": "chk:0715"}','','[]',6715,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0716','check','','judgment','','{"kind": "judgment", "text": "Do not accept periodic abstinence (calendar, symptothermal, or post ovulation methods), withdrawal, spermicides alone, or lactational amenorrhea as contraception.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Periodic abstinence (calendar, symptothermal, post ovulation methods), withdrawal (coitus interruptus), spermicides only, and lactational amenorrhea method are NOT acceptable methods of contraception.", "section_id": "regimen_g:s090", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0716"}','','[]',6716,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0717','check','','judgment','','{"kind": "judgment", "text": "Exclude the indicated medications during the study.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the study", "exception": "unless otherwise specified", "quote": "The medications indicated below are excluded during the study (unless otherwise specified) (See Section 5.9 for prohibited medications).", "section_id": "regimen_g:s092", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0717"}','','[]',6717,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0718','check','','judgment','','{"kind": "judgment", "text": "Have the investigator who knows the participant''s medical history exercise discretion over any concomitant medication; do not treat the lists as exhaustive.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when considering concomitant medication", "exception": "", "quote": "The lists below are not exhaustive; the use of any concomitant medication is at the discretion of the investigator who knows the participant\u2019s medical history.", "section_id": "regimen_g:s092", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0718"}','','[]',6718,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0719','check','','not_checkable','','{"kind": "not_checkable", "text": "Strong CYP3A4/5 inducer background, drug half-lives, table heading, abbreviation, and source citation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "DNL343 is a CYP3A4/5 substrate based on in vitro data; use of strong CYP3A4/5 inducers may decrease DNL343 plasma concentrations.", "section_id": "regimen_g:s093", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0719"}','','[]',6719,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0720','check','','judgment','','{"kind": "judgment", "text": "Exclude strong CYP3A4/5 inducers during the study, including apalutamide, carbamazepine, phenytoin, rifampin, St. John\u2019s wort, and bosentan.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the study", "exception": "", "quote": "The medications in Table 4 are examples of strong CYP3A4/5 inducers and are excluded during the study.", "section_id": "regimen_g:s093", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0720"}','','[]',6720,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0721','check','','follow_up','','{"kind": "follow_up", "text": "Use a tertiary source such as the Drug Interactions Flockhart Table for information on other medications when needed (recommended).", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "need for information on other strong CYP3A4/5 inducers", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if needed", "exception": "", "quote": "If needed, it is recommended that a tertiary source, such as the Drug Interactions Flockhart Table (found at https://drug-interactions.medicine.iu.edu/MainTable.aspx), be used for more information regarding other medications.", "section_id": "regimen_g:s093", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "other_inducer_information_need", "value_name_id": "", "code": false, "id": "chk:0721"}','','[]',6721,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0722','check','','interval','','{"kind": "interval", "text": "Recommended apalutamide washout is at least 2 weeks before first study-drug dose. Limit: 21 days, the longest of the table''s 14 days, 14 days and 5 half-lives (5 x 4.2 days), as regimen_g:5.9 requires.", "from_event": "last dose of apalutamide", "to_event": "first dose of study drug", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 21.0, "max": null, "applies_when": "prior apalutamide use", "exception": "", "quote": "- Generic Drug Name: apalutamide | Drug Half-life: 4.2 d | Recommended Washout: 2 weeks", "section_id": "regimen_g:s093", "from_event_id": "last_apalutamide", "to_event_id": "first_study_dose", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0722", "implied": true, "stated": [21.0, null]}','','[]',6722,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
