INSERT INTO guide VALUES('NCT05842941','checks','chk:0762','check','','not_checkable','','{"kind": "not_checkable", "text": "Protocol approval signature page, acceptance statement, named approvers, and titles.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The undersigned accept the content of this protocol in accordance with the appropriate regulations and agree to adhere to it throughout the execution of the study.", "section_id": "master:protocol-approval-signature-page", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0762"}','','[]',6762,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0763','check','','judgment','','{"kind": "judgment", "text": "Conduct the study in compliance with the protocol, ICH Good Clinical Practice guideline, and applicable regulatory requirements, including 45 CFR Part 46 and 21 CFR Parts 50, 56, and 312.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "This study will be conducted in compliance with the protocol, International Council for Harmonisation of Technical Requirements for Pharmaceuticals for Human Use (ICH), Guideline for Good Clinical Practice (GP), and applicable regulatory requirements, including United States Code of Federal Regulations (CFR) Title 45 CFR Part 46 and Title 21 CFR Parts 50, 56, and 312.", "section_id": "master:statement-of-compliance", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0763"}','','[]',6763,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
