INSERT INTO guide VALUES('NCT05842941','checks','chk:0770','check','','not_checkable','','{"kind": "not_checkable", "text": "Study identity, indication, phase, platform rationale and design, RSA contents, allocation probabilities, sample-size methodology, planned centers, objectives, endpoints, treatment-extension and follow-up durations deferred to RSAs, and illustrative schemas are background, statistical, or central administrative information rather than independently checkable site requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The HEALEY ALS Platform Trial is a perpetual multi-center, multi-regimen clinical trial evaluating the safety and efficacy of investigational products for the treatment of ALS.", "section_id": "master:protocol-summary", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0770"}','','[]',6770,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0771','check','','follow_up','','{"kind": "follow_up", "text": "Screen participants who consent to the Master Protocol against Master Protocol inclusion and exclusion criteria.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "master protocol consent", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants that provide consent to the Master Protocol will be screened for Master Protocol-level inclusion and exclusion criteria.", "section_id": "master:protocol-summary", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "master_consent", "value_name_id": "", "code": false, "id": "chk:0771"}','','[]',6771,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0772','check','','judgment','','{"kind": "judgment", "text": "Assign eligible participants randomly among active regimens; do not assign ineligible participants or assign to inactive regimens.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning a participant to a regimen", "exception": "", "quote": "Those determined eligible will be randomly assigned with equal probability among all active regimens.", "section_id": "master:protocol-summary", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0772"}','','[]',6772,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0773','check','','judgment','','{"kind": "judgment", "text": "Stop enrollment in a regimen once predefined futility or applicable success criteria are met, or the target randomized enrollment has been reached.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when a regimen reaches a stopping criterion or target randomized enrollment", "exception": "", "quote": "As soon as pre-defined criteria for futility or success (if applicable) are met, or the target number of randomized participants in a regimen has been reached, enrollment will stop in that regimen.", "section_id": "master:protocol-summary", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0773"}','','[]',6773,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0774','check','','judgment','','{"kind": "judgment", "text": "Assign participants to a regimen only if they meet Master Protocol inclusion and exclusion criteria.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning a participant to a regimen", "exception": "", "quote": "Those participants that meet the Master Protocol inclusion and exclusion criteria will be randomly assigned to a regimen.", "section_id": "master:protocol-summary", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0774"}','','[]',6774,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0775','check','','order','','{"kind": "order", "text": "Perform regimen assignment before treatment-arm randomization within that regimen, using the specified randomization procedure rather than site-selected treatment.", "from_event": "", "to_event": "", "first_event": "regimen assignment", "then_event": "treatment-arm randomization", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Within cach regimen, participants will then be randomized a second time in a 3:1 ratio to active treatment or matching placebo.", "section_id": "master:protocol-summary", "from_event_id": "", "to_event_id": "", "first_event_id": "regimen_assignment", "then_event_id": "treatment_randomization", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0775"}','','[]',6775,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
