INSERT INTO guide VALUES('NCT05842941','checks','chk:0812','check','','order','','{"kind": "order", "text": "At the first visit, explain the Master Protocol nature and purpose, participation and termination conditions, and risks and benefits before study-related procedures.", "from_event": "", "to_event": "", "first_event": "master protocol participant information discussion", "then_event": "first study-related procedure", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at the first visit", "exception": "Procedures performed as clinic-visit standard of care, such as vital signs or weight.", "quote": "At the first visit, prior to initiation of any study related procedures not performed as clinic visit standard of care (e.g., vital signs, weight), participants will be informed about the nature and purpose of the Master Protocol, participation/termination conditions, and risks and benefits.", "section_id": "master:1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "master_information_discussion", "then_event_id": "first_study_procedure", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0812", "implied": false}','','[]',6812,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0813','check','','judgment','','{"kind": "judgment", "text": "Give participants adequate time to ask questions and become familiar with the Master Protocol before consent.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "before master protocol consent", "exception": "", "quote": "Participants will be given adequate time to ask questions and become familiar with the Master Protocol prior to providing consent to participate.", "section_id": "master:1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0813"}','','[]',6813,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0814','check','','follow_up','','{"kind": "follow_up", "text": "Obtain and document informed consent to participate in the Master Protocol.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "master protocol enrollment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants will give their documented informed consent to participate in the Master Protocol and will be provided with a copy of the fully executed Master Protocol consent form for their records.", "section_id": "master:1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "master_enrollment", "value_name_id": "", "code": false, "id": "chk:0814"}','','[]',6814,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0815','check','','follow_up','','{"kind": "follow_up", "text": "Give participants a copy of their fully executed Master Protocol consent form.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "master protocol consent", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants will give their documented informed consent to participate in the Master Protocol and will be provided with a copy of the fully executed Master Protocol consent form for their records.", "section_id": "master:1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "master_consent", "value_name_id": "", "code": false, "id": "chk:0815"}','','[]',6815,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0816','check','','judgment','','{"kind": "judgment", "text": "Randomly assign participants to a regimen only after they meet Master Protocol eligibility criteria.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning a participant to a regimen", "exception": "", "quote": "Participants meeting Master Protocol eligibility criteria will be randomly assigned to a regimen.", "section_id": "master:1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0816"}','','[]',6816,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0817','check','','follow_up','','{"kind": "follow_up", "text": "After regimen assignment, explain the assigned intervention and regimen-specific participation and termination conditions, risks, and benefits.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "regimen assignment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants will then be informed about the intervention specific to their assigned regimen and any participation/termination conditions or risks and benefits specific to that regimen.", "section_id": "master:1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "regimen_assignment", "value_name_id": "", "code": false, "id": "chk:0817"}','','[]',6817,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0818','check','','follow_up','','{"kind": "follow_up", "text": "Obtain written consent to participate in the assigned regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "regimen enrollment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants will give their written consent to participate in their assigned regimen and will be provided with a copy of the fully executed regimen-specific consent form for their records.", "section_id": "master:1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "regimen_enrollment", "value_name_id": "", "code": false, "id": "chk:0818"}','','[]',6818,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0819','check','','follow_up','','{"kind": "follow_up", "text": "Give participants a copy of their fully executed regimen-specific consent form.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "regimen-specific consent", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants will give their written consent to participate in their assigned regimen and will be provided with a copy of the fully executed regimen-specific consent form for their records.", "section_id": "master:1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "regimen_consent", "value_name_id": "", "code": false, "id": "chk:0819"}','','[]',6819,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0820','check','','judgment','','{"kind": "judgment", "text": "Randomize participants within their regimen only if they meet any additional regimen eligibility criteria, using the specified active-treatment versus matching-placebo randomization.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at treatment-arm randomization", "exception": "", "quote": "Participants meeting additional eligibility criteria required by their assigned regimen, if any, will be randomized in a 3:1 ratio to receive either active treatment or matching placebo in that regimen.", "section_id": "master:1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0820"}','','[]',6820,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0821','check','','judgment','','{"kind": "judgment", "text": "Reassign a participant to other regimens only if eligible.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when reassigning a participant", "exception": "", "quote": "In some situations, an individual may be re-assigned to multiple different regimens, if eligible.", "section_id": "master:1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0821"}','','[]',6821,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0822','check','','not_checkable','','{"kind": "not_checkable", "text": "The reassignment-process cross-reference supplies no additional procedural details in this section; the 3:1 allocation ratio is a statistical design requirement, not a requirement for each site''s realized enrollment ratio.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The procedures detailing the re-assignment process can be found in Section 8.1.2 Screen Failures and Re-Assignment.", "section_id": "master:1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0822"}','','[]',6822,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0823','check','','not_checkable','','{"kind": "not_checkable", "text": "Sponsor-issued amendments, central submission and addition of regimen appendices, and the statements that adding regimens does not require reconsent and stopping regimens does not require a Master Protocol amendment are central administrative provisions.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Any change to the Master Protocol will be documented in a protocol amendment, issued by the Sponsor.", "section_id": "master:1.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0823"}','','[]',6823,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0824','check','','order','','{"kind": "order", "text": "Do not implement a Master Protocol amendment before submission for sIRB approval; approval before implementation is additionally required by Section 1.5.", "from_event": "", "to_event": "", "first_event": "submission of protocol amendment for sIRB approval", "then_event": "implementation of protocol amendment", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when implementing an amendment", "exception": "", "quote": "Master Protocol amendments will be submitted for approval to the sIRB prior to implementation.", "section_id": "master:1.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "sirb_amendment_submission", "then_event_id": "protocol_amendment_implementation", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0824", "implied": true}','','[]',6824,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0825','check','','follow_up','','{"kind": "follow_up", "text": "Obtain written informed reconsent from enrolled participants for continued participation when required.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "protocol amendment requiring reconsent", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when reconsent is required", "exception": "", "quote": "Written informed re-consent for continued participation in the study may be required by participants already enrolled in the Master Protocol.", "section_id": "master:1.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "reconsent_amendment", "value_name_id": "", "code": false, "id": "chk:0825"}','','[]',6825,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0826','check','','order','','{"kind": "order", "text": "Do not implement a newly added regimen before it has been submitted for sIRB approval.", "from_event": "", "to_event": "", "first_event": "submission of new regimen for sIRB approval", "then_event": "implementation of new regimen", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when adding a regimen", "exception": "", "quote": "As regimens are added to the Platform Trial, they will be submitted for approval to the sIRB prior to implementation.", "section_id": "master:1.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "sirb_regimen_submission", "then_event_id": "new_regimen_implementation", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0826", "implied": true}','','[]',6826,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0827','check','','order','','{"kind": "order", "text": "Do not assign participants to a regimen until it has been added as an appendix to the Master Protocol.", "from_event": "", "to_event": "", "first_event": "addition of regimen appendix to master protocol", "then_event": "regimen assignment", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning participants to a new regimen", "exception": "", "quote": "Each regimen will be added as an appendix to the Master Protocol prior to any participant being assigned to that regimen.", "section_id": "master:1.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "regimen_appendix_addition", "then_event_id": "regimen_assignment", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0827", "implied": false}','','[]',6827,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0828','check','','not_checkable','','{"kind": "not_checkable", "text": "The Sponsor''s right to terminate sites and examples of circumstances warranting termination are administrative provisions; no numerical acceptable enrollment rate is supplied.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Conditions that may warrant termination include, but are not limited to, insufficient adherence to protocol requirements and failure to enter participants at an acceptable rate.", "section_id": "master:1.4.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0828"}','','[]',6828,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0829','check','','judgment','','{"kind": "judgment", "text": "Each Site Investigator must adhere to the Master Protocol.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Each Site Investigator (SI) must adhere to the Master Protocol detailed in this document and agree that any changes to the protocol must be approved by the sIRB.", "section_id": "master:1.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0829"}','','[]',6829,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0830','check','','order','','{"kind": "order", "text": "Obtain sIRB approval before implementing protocol changes.", "from_event": "", "to_event": "", "first_event": "sIRB approval of protocol change", "then_event": "implementation of protocol change", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when changing the protocol", "exception": "", "quote": "Each Site Investigator (SI) must adhere to the Master Protocol detailed in this document and agree that any changes to the protocol must be approved by the sIRB.", "section_id": "master:1.5", "from_event_id": "", "to_event_id": "", "first_event_id": "sirb_change_approval", "then_event_id": "protocol_change_implementation", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0830", "implied": true}','','[]',6830,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0831','check','','judgment','','{"kind": "judgment", "text": "Enroll only participants meeting all Master Protocol eligibility criteria into the Master Protocol.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at master protocol enrollment", "exception": "", "quote": "Each SI will be responsible for enrolling into the Master Protocol only those study participants who have met all Master Protocol eligibility criteria, and for enrolling into a Regimen only those study participants who have met the additional eligibility criteria (if any) of the corresponding RSA.", "section_id": "master:1.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0831"}','','[]',6831,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0832','check','','judgment','','{"kind": "judgment", "text": "Enroll only participants meeting any additional eligibility criteria in the corresponding RSA into a regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at regimen enrollment", "exception": "", "quote": "Each SI will be responsible for enrolling into the Master Protocol only those study participants who have met all Master Protocol eligibility criteria, and for enrolling into a Regimen only those study participants who have met the additional eligibility criteria (if any) of the corresponding RSA.", "section_id": "master:1.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0832"}','','[]',6832,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0833','check','','not_checkable','','{"kind": "not_checkable", "text": "ALS natural history, epidemiology, available treatments, research advances, unmet need, operational and scientific challenges, network infrastructure, biomarkers, outcome measures, and the rationale for coordinated collaboration are background and rationale, not site conduct requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Scientific challenges to ALS therapy development include disease rarity, patient heterogeneity, lack of validated surrogate endpoints, and a relatively rapid disease course.", "section_id": "master:2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0833"}','','[]',6833,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0834','check','','not_checkable','','{"kind": "not_checkable", "text": "Background explains conventional and platform trials, shared infrastructure and placebo groups, the Master Protocol framework, and scientific rationale.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "In contrast, platform trials are designed to investigate multiple investigational products in parallel and sequentially with the capability to adapt over time.", "section_id": "master:2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0834"}','','[]',6834,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0835','check','','not_checkable','','{"kind": "not_checkable", "text": "Product provision, platform governance, regimen addition and discontinuation, TEC intervention selection, and required RSA contents are background or central administrative requirements rather than site-checkable rules.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The additional details that govern the testing of each investigational product will be summarized in separate RSAs.", "section_id": "master:2.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0835"}','','[]',6835,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0836','check','','not_checkable','','{"kind": "not_checkable", "text": "Trial design, regimen structure and start times, and interim-analysis timing and specifications are background and statistical requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "This is a perpetual, multicenter, multi-regimen, randomized, placebo-controlled, adaptive platform clinical trial evaluating the safety and efficacy of multiple investigational products simultaneously or sequentially in ALS.", "section_id": "master:4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0836"}','','[]',6836,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0837','check','','judgment','','{"kind": "judgment", "text": "Maintain participant, investigator, and site staff blinding to active product versus matching placebo throughout the ATE period; regimen assignment is not blinded.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "throughout the ATE period", "exception": "", "quote": "Research participants, investigators and site staff will not be blinded to the regimen assignment, but they will be blinded to active product or matching placebo assignment and this blind will be maintained throughout the ATE period of the study.", "section_id": "master:4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0837"}','','[]',6837,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0838','check','','interval','','{"kind": "interval", "text": "Assess the primary endpoint every 4 weeks for all interventions, on-site or by phone.", "from_event": "primary endpoint assessment", "to_event": "next primary endpoint assessment", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "weeks", "min": 4, "max": 4, "applies_when": "for all interventions", "exception": "", "quote": "The primary endpoint will be assessed for all interventions every 4 weeks, either on-site or via phone.", "section_id": "master:4.1", "from_event_id": "primary_endpoint", "to_event_id": "next_primary_endpoint", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0838", "implied": true, "stated": [4, 4]}','','[]',6838,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0839','check','','order','','{"kind": "order", "text": "Establish Master Protocol eligibility before further screening and regimen assignment.", "from_event": "", "to_event": "", "first_event": "Master Protocol eligibility confirmation", "then_event": "further screening and regimen assignment", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Research participants that meet the Master Protocol inclusion and exclusion criteria listed below will be further screened and randomly assigned to a regimen.", "section_id": "master:5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "master_eligibility", "then_event_id": "further_screening_assignment", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0839"}','','[]',6839,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0840','check','','not_checkable','','{"kind": "not_checkable", "text": "Each RSA specifies its regimen sample size.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The sample size enrolled in each regimen will be specified in each RSA.", "section_id": "master:5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0840"}','','[]',6840,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0841','check','','not_checkable','','{"kind": "not_checkable", "text": "Section heading only: Master Protocol inclusion and exclusion criteria.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "the Master Protocol inclusion and exclusion criteria", "section_id": "master:5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0841"}','','[]',6841,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0842','check','','not_checkable','','{"kind": "not_checkable", "text": "The inclusion criteria apply to Master Protocol entry and all regimens.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "These are the inclusion criteria that research participants must meet to be eligible to enter the Master Protocol and are common for all regimens:", "section_id": "master:5.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0842"}','','[]',6842,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0843','check','','judgment','','{"kind": "judgment", "text": "Require sporadic or familial ALS classified as clinically possible, probable, lab-supported probable, or definite under revised El Escorial criteria.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "1. Sporadic or familial ALS diagnosed as clinically possible, probable, lab-supported probable, or definite ALS defined by revised El Escorial criteria (Appendix I).", "section_id": "master:5.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0843"}','','[]',6843,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0844','check','','value','','{"kind": "value", "text": "Participants younger than 18 years are ineligible.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "age", "operator": "lt", "limit": 18, "limit2": null, "value_unit": "years", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "2. Age 18 years or older.", "section_id": "master:5.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "age", "code": true, "id": "chk:0844", "implied": false}','','[]',6844,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
