INSERT INTO guide VALUES('NCT05842941','checks','chk:0846','check','','judgment','','{"kind": "judgment", "text": "Require ability to comply with study procedures in the SI''s opinion.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "3. Capable of providing informed consent and complying with study procedures, in the SI''s opinion.", "section_id": "master:5.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0846"}','','[]',6846,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0847','check','','interval','','{"kind": "interval", "text": "ALS weakness onset must be no more than 24 months before screening.", "from_event": "ALS weakness onset", "to_event": "master protocol screening visit", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "months", "min": 0, "max": 24, "applies_when": "", "exception": "", "quote": "4. Time since onset of weakness due to ALS \u2264 24 months at the time of the Master Protocol Screening Visit.", "section_id": "master:5.2.1", "from_event_id": "als_weakness_onset", "to_event_id": "master_screening_visit", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0847", "stated": [0, 24]}','','[]',6847,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0848','check','','value','','{"kind": "value", "text": "Screening vital capacity below 50% of predicted is ineligible.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "screening vital capacity", "operator": "lt", "limit": 50, "limit2": null, "value_unit": "% of predicted capacity", "unit": "", "min": null, "max": null, "applies_when": "at master protocol screening visit", "exception": "", "quote": "5. Vital Capacity \u2265 50% of predicted capacity at the time of Master Protocol Screening measured by Slow Vital Capacity (SVC), or, if required due to pandemic-related restrictions, Forced Vital Capacity (FVC) measured in person.", "section_id": "master:5.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "screening_vc", "code": true, "id": "chk:0848", "implied": true}','','[]',6848,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0849','check','','judgment','','{"kind": "judgment", "text": "Measure screening vital capacity using SVC; FVC must be measured in person and is permitted only if required by pandemic-related restrictions.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at master protocol screening visit", "exception": "FVC measured in person if required due to pandemic-related restrictions", "quote": "5. Vital Capacity \u2265 50% of predicted capacity at the time of Master Protocol Screening measured by Slow Vital Capacity (SVC), or, if required due to pandemic-related restrictions, Forced Vital Capacity (FVC) measured in person.", "section_id": "master:5.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0849"}','','[]',6849,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0850','check','','interval','','{"kind": "interval", "text": "Participants taking riluzole must have a stable dose for at least 30 days before screening.", "from_event": "start of stable riluzole dose", "to_event": "master protocol screening visit", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 30, "max": null, "applies_when": "for participants taking riluzole", "exception": "participants not taking riluzole", "quote": "6. Participants must either not take riluzole or be on a stable dose of riluzole for \u2265 30 days prior to the Master Protocol Screening Visit.", "section_id": "master:5.2.1", "from_event_id": "stable_riluzole_start", "to_event_id": "master_screening_visit", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0850", "implied": true, "stated": [30, null]}','','[]',6850,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0851','check','','order','','{"kind": "order", "text": "Participants taking edaravone must complete at least one treatment cycle before screening; 14 days is typical, not a fixed minimum.", "from_event": "", "to_event": "", "first_event": "completion of first edaravone cycle", "then_event": "master protocol screening visit", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants taking edaravone", "exception": "participants not taking edaravone", "quote": "7. Participants must either not take edaravone or have completed at least one cycle (typically 14 days) of edaravone prior to the Master Protocol Screening Visit.", "section_id": "master:5.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "first_edaravone_cycle_end", "then_event_id": "master_screening_visit", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0851", "implied": true}','','[]',6851,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0852','check','','judgment','','{"kind": "judgment", "text": "Require ability to swallow pills and liquids at screening.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at master protocol screening visit", "exception": "", "quote": "8. Participants must have the ability to swallow pills and liquids at the time of the Master Protocol Screening Visit and, in the SI''s opinion, have the ability to swallow for the duration of the study.", "section_id": "master:5.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0852"}','','[]',6852,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0853','check','','judgment','','{"kind": "judgment", "text": "The SI must expect the participant to be able to swallow throughout the study.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "8. Participants must have the ability to swallow pills and liquids at the time of the Master Protocol Screening Visit and, in the SI''s opinion, have the ability to swallow for the duration of the study.", "section_id": "master:5.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0853"}','','[]',6853,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0854','check','','judgment','','{"kind": "judgment", "text": "Require geographic accessibility to the site.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "9. Geographically accessible to the site.", "section_id": "master:5.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0854"}','','[]',6854,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0855','check','','not_checkable','','{"kind": "not_checkable", "text": "Exclusion criteria are common across regimens; justified additional criteria are specified centrally in RSAs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "If justified based on regimen''s specific investigational product, additional inclusion or exclusion criteria (c.g., contraindications, laboratory parameters) will be listed in the RSA.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0855"}','','[]',6855,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0856','check','','judgment','','{"kind": "judgment", "text": "Exclude clinically significant unstable non-ALS medical conditions posing risk in the SI''s judgment.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "1. Clinically significant unstable medical condition (other than ALS) that would pose a risk to the participant, according to SI''s judgment (e.g., cardiovascular instability, systemic infection,), or clinically significant laboratory abnormality or EKG changes.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0856"}','','[]',6856,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
