INSERT INTO guide VALUES('NCT05842941','checks','chk:0859','check','','judgment','','{"kind": "judgment", "text": "Exclude clinically significant abnormal liver function.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "Clinically significant abnormal liver or kidney function is exclusionary.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0859"}','','[]',6859,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0860','check','','judgment','','{"kind": "judgment", "text": "Exclude clinically significant abnormal kidney function.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "Clinically significant abnormal liver or kidney function is exclusionary.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0860"}','','[]',6860,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0861','check','','value','','{"kind": "value", "text": "ALT greater than 3 times ULN is exclusionary regardless of symptoms.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "ALT", "operator": "gt", "limit": 3, "limit2": null, "value_unit": "times ULN", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "The following values [alanine aminotransferase (ALT) or aspartate aminotransferase (AST) > 3 times the upper limit of normal (ULN) or estimated Glomerular Filtration Rate (eGFR) < 30 mL/min/1.73m\u00b0] are exclusionary regardless of clinical symptoms.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "alt", "code": true, "id": "chk:0861", "implied": false}','','[]',6861,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0862','check','','value','','{"kind": "value", "text": "AST greater than 3 times ULN is exclusionary regardless of symptoms.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "AST", "operator": "gt", "limit": 3, "limit2": null, "value_unit": "times ULN", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "The following values [alanine aminotransferase (ALT) or aspartate aminotransferase (AST) > 3 times the upper limit of normal (ULN) or estimated Glomerular Filtration Rate (eGFR) < 30 mL/min/1.73m\u00b0] are exclusionary regardless of clinical symptoms.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "ast", "code": true, "id": "chk:0862", "implied": false}','','[]',6862,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0863','check','','value','','{"kind": "value", "text": "eGFR below 30 is exclusionary regardless of symptoms.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "eGFR", "operator": "lt", "limit": 30, "limit2": null, "value_unit": "mL/min/1.73m\u00b2", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "The following values [alanine aminotransferase (ALT) or aspartate aminotransferase (AST) > 3 times the upper limit of normal (ULN) or estimated Glomerular Filtration Rate (eGFR) < 30 mL/min/1.73m\u00b0] are exclusionary regardless of clinical symptoms.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "egfr", "code": true, "id": "chk:0863", "implied": false}','','[]',6863,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0864','check','','judgment','','{"kind": "judgment", "text": "Exclude unstable psychiatric disease, cognitive impairment, dementia, or substance abuse that impairs informed-consent capacity in the SI''s opinion.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "2. Presence of unstable psychiatric disease, cognitive impairment, dementia or substance abuse that would impair ability of the participant to provide informed consent, in the SI''s opinion.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0864"}','','[]',6864,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0865','check','','judgment','','{"kind": "judgment", "text": "Exclude active cancer or cancer history except the specified permitted cancers or curatively treated malignancies with at least 3 years without recurrence.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "basal cell carcinoma; successfully treated squamous cell carcinoma of the skin; cervical carcinoma in situ; prostatic carcinoma in situ; other malignancies curatively treated with no recurrence for at least 3 years", "quote": "3. Active cancer or history of cancer, except for the following: basal cell carcinoma or successfully treated squamous cell carcinoma of the skin, cervical carcinoma in situ, prostatic carcinoma in situ, or other malignancies curatively treated and with no evidence of disease recurrence for at least 3 years.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0865"}','','[]',6865,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0866','check','','interval','','{"kind": "interval", "text": "Require at least 30 days since investigational ALS treatment use or active trial participation before screening, and longer if 5 known half-lives exceed 30 days.", "from_event": "last investigational ALS treatment use or active trial participation", "to_event": "master protocol screening visit", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 30, "max": null, "applies_when": "for prior investigational ALS treatment, including off-label use or active trial participation", "exception": "", "quote": "4. Use of investigational treatments for ALS (off-label use or active participation in a clinical trial within 5 half-lives (if known) or 30 days (whichever is longer) prior to the Master Protocol Screening Visit.", "section_id": "master:5.2.2", "from_event_id": "last_investigational_als_use", "to_event_id": "master_screening_visit", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0866", "implied": true, "stated": [30, null]}','','[]',6866,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0867','check','','judgment','','{"kind": "judgment", "text": "When known, require washout of at least 5 half-lives of investigational ALS treatment if longer than 30 days; consult the MOP experimental-therapy list.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for prior investigational ALS treatment with known half-life", "exception": "", "quote": "4. Use of investigational treatments for ALS (off-label use or active participation in a clinical trial within 5 half-lives (if known) or 30 days (whichever is longer) prior to the Master Protocol Screening Visit.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0867"}','','[]',6867,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0868','check','','judgment','','{"kind": "judgment", "text": "Exclude any prior exposure to gene therapies under investigation for ALS, including off-label exposure.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "5. Exposure at any time to any gene therapies under investigation for the treatment of ALS (off-label use or investigational).", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0868"}','','[]',6868,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0869','check','','judgment','','{"kind": "judgment", "text": "Exclude female participants who are breastfeeding.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for female participants at eligibility determination", "exception": "", "quote": "6. If female, breastfeeding, known to be pregnant, planning to become pregnant during the study, or of child-bearing potential and unwilling to use effective contraception, for the duration of the trial and for 3 months, or as specified in each RSA, after discontinuing study treatment.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0869"}','','[]',6869,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0870','check','','judgment','','{"kind": "judgment", "text": "Exclude female participants known to be pregnant.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for female participants at eligibility determination", "exception": "", "quote": "6. If female, breastfeeding, known to be pregnant, planning to become pregnant during the study, or of child-bearing potential and unwilling to use effective contraception, for the duration of the trial and for 3 months, or as specified in each RSA, after discontinuing study treatment.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0870"}','','[]',6870,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0871','check','','judgment','','{"kind": "judgment", "text": "Exclude female participants planning pregnancy during the study.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for female participants at eligibility determination", "exception": "", "quote": "6. If female, breastfeeding, known to be pregnant, planning to become pregnant during the study, or of child-bearing potential and unwilling to use effective contraception, for the duration of the trial and for 3 months, or as specified in each RSA, after discontinuing study treatment.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0871"}','','[]',6871,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0872','check','','judgment','','{"kind": "judgment", "text": "Require willingness to use effective contraception throughout the trial and for 3 months after treatment discontinuation, or the RSA-specified duration.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for female participants of child-bearing potential", "exception": "post-treatment duration may differ as specified in the RSA", "quote": "6. If female, breastfeeding, known to be pregnant, planning to become pregnant during the study, or of child-bearing potential and unwilling to use effective contraception, for the duration of the trial and for 3 months, or as specified in each RSA, after discontinuing study treatment.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0872"}','','[]',6872,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0873','check','','judgment','','{"kind": "judgment", "text": "Require willingness to use effective contraception throughout the trial and for 3 months after treatment discontinuation, or the RSA-specified duration.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for male participants of reproductive capacity", "exception": "post-treatment duration may differ as specified in the RSA", "quote": "7. If male of reproductive capacity, unwilling to use effective contraception for the duration of the trial and for 3 months, or as specified in each RSA, after discontinuing study treatment.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0873"}','','[]',6873,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0874','check','','judgment','','{"kind": "judgment", "text": "Exclude anything that increases risk or precludes full compliance or study completion in the SI''s opinion.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at Master Protocol eligibility determination", "exception": "", "quote": "8. Anything that would place the participant at increased risk or preclude the participant''s full compliance with or completion of the study, in the SI''s opinion.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0874"}','','[]',6874,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0875','check','','judgment','','{"kind": "judgment", "text": "Do not qualify a re-screened participant unless the previous disqualifying condition has resolved.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants being re-screened", "exception": "", "quote": "9. If a participant is being re-screened, the disqualifying condition has not been resolved, or the mandatory wash-out duration has not occurred.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0875"}','','[]',6875,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0876','check','','judgment','','{"kind": "judgment", "text": "Do not qualify a re-screened participant before the mandatory washout is complete.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants being re-screened", "exception": "", "quote": "9. If a participant is being re-screened, the disqualifying condition has not been resolved, or the mandatory wash-out duration has not occurred.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0876"}','','[]',6876,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0877','check','','interval','','{"kind": "interval", "text": "At entry, concomitant riluzole users must have maintained a stable dose for at least 30 days before screening.", "from_event": "start of stable riluzole dose", "to_event": "master protocol screening visit", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 30, "max": null, "applies_when": "for participants taking concomitant riluzole at study entry", "exception": "", "quote": "Participants taking concomitant riluzole at study entry must be on a stable dose for 30 days prior to the Master Protocol Screening Visit and must intend to continue taking the same stable dosage throughout the study.", "section_id": "master:5.2.2", "from_event_id": "stable_riluzole_start", "to_event_id": "master_screening_visit", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0877", "implied": false, "stated": [30, null]}','','[]',6877,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0878','check','','judgment','','{"kind": "judgment", "text": "Concomitant riluzole users must intend to continue the same stable dosage throughout the study.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants taking concomitant riluzole at study entry", "exception": "", "quote": "Participants taking concomitant riluzole at study entry must be on a stable dose for 30 days prior to the Master Protocol Screening Visit and must intend to continue taking the same stable dosage throughout the study.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0878"}','','[]',6878,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0879','check','','order','','{"kind": "order", "text": "At entry, concomitant edaravone users must have completed at least one treatment cycle before screening.", "from_event": "", "to_event": "", "first_event": "completion of first edaravone cycle", "then_event": "master protocol screening visit", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants taking concomitant edaravone at study entry", "exception": "", "quote": "Participants taking concomitant edaravone at study entry must have completed at least one cycle of treatment (typically 14 days) prior to the Master Protocol Screening Visit and must intend to continue taking the same stable dosage throughout the study.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "first_edaravone_cycle_end", "then_event_id": "master_screening_visit", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0879", "implied": false}','','[]',6879,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0880','check','','judgment','','{"kind": "judgment", "text": "Concomitant edaravone users must intend to continue the same stable dosage throughout the study.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants taking concomitant edaravone at study entry", "exception": "", "quote": "Participants taking concomitant edaravone at study entry must have completed at least one cycle of treatment (typically 14 days) prior to the Master Protocol Screening Visit and must intend to continue taking the same stable dosage throughout the study.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0880"}','','[]',6880,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0881','check','','judgment','','{"kind": "judgment", "text": "Do not classify SI-directed medical discontinuation or dose adjustment of riluzole or edaravone as a protocol deviation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when the SI determines a medical need to discontinue or adjust riluzole or edaravone", "exception": "", "quote": "If the SI determines that riluzole or edaravone should be discontinued or dose-adjusted for medical reasons, this will not be considered a protocol deviation.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0881"}','','[]',6881,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0882','check','','judgment','','{"kind": "judgment", "text": "Do not classify unintended missed riluzole or edaravone doses caused by extenuating circumstances as deviations.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when extenuating circumstances cause unintended missed doses", "exception": "", "quote": "If extenuating circumstances cause doses to be missed for reasons not intended or medically indicated (scheduling, drug availability, etc.), this will not be considered a protocol deviation.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0882"}','','[]',6882,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0883','check','','follow_up','','{"kind": "follow_up", "text": "Record non-medical discontinuation of riluzole or edaravone as a minor protocol deviation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "non-medical discontinuation of riluzole or edaravone", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "If riluzole or edaravone is stopped for any non-medical reason (participant preference), this will be recorded as a minor protocol deviation.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "nonmedical_riluzole_edaravone_stop", "value_name_id": "", "code": false, "id": "chk:0883"}','','[]',6883,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0884','check','','follow_up','','{"kind": "follow_up", "text": "Record initiation of riluzole or edaravone during participation as a minor protocol deviation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "initiation of riluzole or edaravone during participation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "If initiation of riluzole or edaravone therapy begins at any point during participation, this will be recorded as a minor protocol deviation.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "riluzole_edaravone_start", "value_name_id": "", "code": false, "id": "chk:0884"}','','[]',6884,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0885','check','','judgment','','{"kind": "judgment", "text": "Use the first date of muscle weakness symptoms as ALS symptom onset.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when determining ALS symptom onset", "exception": "", "quote": "For the purposes of this study, the date of symptom onset will be defined as the date the participant first had symptoms of muscle weakness.", "section_id": "master:5.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0885"}','','[]',6885,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0886','check','','interval','','{"kind": "interval", "text": "ALS weakness onset must be no more than 24 months before screening.", "from_event": "ALS weakness onset", "to_event": "master protocol screening visit", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "months", "min": 0, "max": 24, "applies_when": "", "exception": "", "quote": "To be eligible for this study, the date of symptom onset must be no greater than 24 months prior to the Master Protocol Screening Visit date.", "section_id": "master:5.2.2", "from_event_id": "als_weakness_onset", "to_event_id": "master_screening_visit", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0886", "stated": [0, 24]}','','[]',6886,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0887','check','','not_checkable','','{"kind": "not_checkable", "text": "Selected US ALS centers are the study setting; NEALS organizational description is background.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "This study will be conducted at selected ALS centers in the US.", "section_id": "master:6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0887"}','','[]',6887,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0888','check','','judgment','','{"kind": "judgment", "text": "Participating sites must be NEALS members.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for sites participating in the Master Protocol", "exception": "", "quote": "Sites participating in this Master Protocol must be members of the Northeast ALS Consortium (NEALS).", "section_id": "master:6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0888"}','','[]',6888,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
