INSERT INTO guide VALUES('NCT05842941','checks','chk:0890','check','','follow_up','','{"kind": "follow_up", "text": "Record information for every enrolled participant in EDC.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "participant enrollment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Information about all research participants enrolled into the trial will be recorded in the Electronic Data Capture (EDC) system.", "section_id": "master:6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "participant_enrollment", "value_name_id": "", "code": false, "id": "chk:0890"}','','[]',6890,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0891','check','','follow_up','','{"kind": "follow_up", "text": "Record screen-failure reasons in EDC for participants not assigned to a regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "screen failure without regimen assignment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "This information will include reasons for screen failure for participants not assigned to a regimen, as well as a log of all participants randomized within a regimen, irrespective of whether they have been treated with the intervention or not.", "section_id": "master:6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "screen_fail_unassigned", "value_name_id": "", "code": false, "id": "chk:0891"}','','[]',6891,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
