INSERT INTO guide VALUES('NCT05842941','checks','chk:0893','check','','order','','{"kind": "order", "text": "Obtain written informed consent before study procedures or assessments.", "from_event": "", "to_event": "", "first_event": "written informed consent", "then_event": "study procedure or assessment", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "procedures or assessments performed as clinic-visit standard of care, such as vital signs or weight", "quote": "Written informed consent will be obtained from participants before any study procedures or assessments, not performed as clinic visit standard of care (e.g., vital signs, weight), are done and after the study objectives and endpoints, methods, anticipated benefits, and potential hazards are explained.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "written_consent", "then_event_id": "study_procedure", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0893"}','','[]',6893,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0894','check','','order','','{"kind": "order", "text": "Explain objectives, endpoints, methods, anticipated benefits, and potential hazards before obtaining written consent.", "from_event": "", "to_event": "", "first_event": "explanation of study objectives, endpoints, methods, benefits, and hazards", "then_event": "written informed consent", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Written informed consent will be obtained from participants before any study procedures or assessments, not performed as clinic visit standard of care (e.g., vital signs, weight), are done and after the study objectives and endpoints, methods, anticipated benefits, and potential hazards are explained.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "study_explanation", "then_event_id": "written_consent", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0894"}','','[]',6894,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0895','check','','follow_up','','{"kind": "follow_up", "text": "Document willingness to participate on an sIRB-approved consent form signed and dated by the participant.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "participant consent", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The willingness of the participant to participate in the study will be documented in writing on a consent form approved by the sIRB, which will be signed and dated by the participant.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "participant_consent", "value_name_id": "", "code": false, "id": "chk:0895"}','','[]',6895,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0896','check','','follow_up','','{"kind": "follow_up", "text": "The SI must retain original consent forms.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "participant consent", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The SI will keep the original consent forms and a copy will be given to the participant.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "participant_consent", "value_name_id": "", "code": false, "id": "chk:0896"}','','[]',6896,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
