INSERT INTO guide VALUES('NCT05842941','checks','chk:0898','check','','follow_up','','{"kind": "follow_up", "text": "Inform participants of their right to refuse entry or withdraw at any time without prejudice to future treatment.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "consent process", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The participant will also be informed that they may refuse entry into the trial and are free to withdraw from the trial at any time without prejudice to future treatment.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "consent_process", "value_name_id": "", "code": false, "id": "chk:0898"}','','[]',6898,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0899','check','','judgment','','{"kind": "judgment", "text": "Consent must be obtained by the site investigator or licensed staff trained on the study and delegated to obtain consent.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when obtaining informed consent", "exception": "", "quote": "Informed consent will be obtained by the site investigator or other licensed staff who are trained on the study and delegated to obtain consent.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0899"}','','[]',6899,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0900','check','','follow_up','','{"kind": "follow_up", "text": "The SI or licensed staff must help explain the study, answer questions with the coordinator, and ensure correct consent conduct.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "consent process", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The SI, or other licensed staff, will be involved in explaining the study and will play a role during the consent process, answering any questions in conjunction with the coordinator and ensuring that the process is carried out correctly.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "consent_process", "value_name_id": "", "code": false, "id": "chk:0900"}','','[]',6900,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0901','check','','follow_up','','{"kind": "follow_up", "text": "Offer every participant discussion of participation with a licensed physician Investigator.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "consent process", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All participants will be offered the opportunity to discuss participation with a licensed physician Investigator and the participant''s decision to accept or decline this opportunity will be documented in the research file.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "consent_process", "value_name_id": "", "code": false, "id": "chk:0901"}','','[]',6901,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0902','check','','follow_up','','{"kind": "follow_up", "text": "Document in the research file whether the participant accepts or declines physician discussion.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "participant decision about physician discussion", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All participants will be offered the opportunity to discuss participation with a licensed physician Investigator and the participant''s decision to accept or decline this opportunity will be documented in the research file.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "physician_discussion_decision", "value_name_id": "", "code": false, "id": "chk:0902"}','','[]',6902,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0903','check','','judgment','','{"kind": "judgment", "text": "Provide adequate information for an informed participation decision.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during consent", "exception": "", "quote": "Site study staff performing consent must provide participants adequate information to allow for an informed decision about participation, facilitate the potential participant''s understanding of the information, and provide ample time and opportunity to inquire about details of the trial.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0903"}','','[]',6903,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0904','check','','judgment','','{"kind": "judgment", "text": "Facilitate the potential participant''s understanding of consent information.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during consent", "exception": "", "quote": "Site study staff performing consent must provide participants adequate information to allow for an informed decision about participation, facilitate the potential participant''s understanding of the information, and provide ample time and opportunity to inquire about details of the trial.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0904"}','','[]',6904,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0905','check','','judgment','','{"kind": "judgment", "text": "Allow ample time and opportunity for questions about trial details.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during consent", "exception": "", "quote": "Site study staff performing consent must provide participants adequate information to allow for an informed decision about participation, facilitate the potential participant''s understanding of the information, and provide ample time and opportunity to inquire about details of the trial.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0905"}','','[]',6905,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0906','check','','judgment','','{"kind": "judgment", "text": "Do not coerce or unduly influence participation or continued participation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The SI, nor the site study staff, should coerce or unduly influence a potential participant to participate or to continue to participate in the study.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0906"}','','[]',6906,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0907','check','','follow_up','','{"kind": "follow_up", "text": "Continuously provide information as the investigation progresses or participant circumstances require.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study progression or participant information need", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Site study staff must continuously provide information as the clinical investigation progresses or as the participant or situation requires.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "progression_or_info_need", "value_name_id": "", "code": false, "id": "chk:0907"}','','[]',6907,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0908','check','','order','','{"kind": "order", "text": "Conduct Master Protocol consent before consent for the assigned RSA.", "from_event": "", "to_event": "", "first_event": "Master Protocol consent", "then_event": "assigned RSA consent", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants assigned to a regimen", "exception": "", "quote": "Informed consent will be conducted for the Master Protocol and subsequently for the applicable RSA to which that participant was assigned.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "master_consent", "then_event_id": "assigned_rsa_consent", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0908", "implied": true}','','[]',6908,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0909','check','','judgment','','{"kind": "judgment", "text": "Do not consent Master Protocol-ineligible participants for any regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants found ineligible for the Master Protocol", "exception": "", "quote": "Those participants who are not found eligible for the Master Protocol will not be consented for any regimen.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0909"}','','[]',6909,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0910','check','','judgment','','{"kind": "judgment", "text": "When using translated consent for non-English speakers, use an sIRB-approved form translated into the participant''s spoken language.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when obtaining consent using a translated form for a non-English speaker", "exception": "", "quote": "Consent for non-English speakers may be obtained using an sIRB approved consent form that has been translated into the participant''s spoken language.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0910"}','','[]',6910,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0911','check','','judgment','','{"kind": "judgment", "text": "Follow study MOPs and local policy for translator use.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when using translators", "exception": "", "quote": "Sites should follow study MOPs and local policy on the use of translators.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0911"}','','[]',6911,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0912','check','','follow_up','','{"kind": "follow_up", "text": "Obtain Master Protocol or regimen reconsent when required by newly added procedures or information.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "new procedures or information requiring reconsent", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when reconsent is required", "exception": "", "quote": "Participants may be required to reconsent to the Master Protocol or a regimen if new procedures or information is added in the future.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "reconsent_trigger", "value_name_id": "", "code": false, "id": "chk:0912"}','','[]',6912,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0913','check','','follow_up','','{"kind": "follow_up", "text": "Complete required reconsent at the participant''s next visit.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "requirement for participant reconsent", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when reconsent is required", "exception": "remote reconsent is permitted when the next visit is remote, using the specified process", "quote": "Should a participant need to reconsent, this should occur during the participant''s next visit.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "reconsent_required", "value_name_id": "", "code": false, "id": "chk:0913"}','','[]',6913,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0914','check','','follow_up','','{"kind": "follow_up", "text": "Provide a copy of the informed consent form for remote reconsent.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "remote reconsent", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when the next visit and reconsent are remote", "exception": "", "quote": "1. The site staff provides a copy of the informed consent form to the participant.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "remote_reconsent", "value_name_id": "", "code": false, "id": "chk:0914"}','','[]',6914,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0915','check','','order','','{"kind": "order", "text": "Have the participant read the remote reconsent form without signing before the staff review.", "from_event": "", "to_event": "", "first_event": "participant reads unsigned reconsent form", "then_event": "remote consent review", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during remote reconsent", "exception": "", "quote": "2. The participant reads through the consent form but does not sign.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "unsigned_reconsent_reading", "then_event_id": "remote_consent_review", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0915", "implied": true}','','[]',6915,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0916','check','','follow_up','','{"kind": "follow_up", "text": "The Site Investigator or approved, delegated consent staff must contact the participant and review the form by phone or telemedicine.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "remote reconsent", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during remote reconsent", "exception": "", "quote": "3. The Site Investigator, or other study staff member approved and delegated to obtain informed consent, contacts the participant and reviews the informed consent form with the participant over the phone or via telemedicine.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "remote_reconsent", "value_name_id": "", "code": false, "id": "chk:0916"}','','[]',6916,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0917','check','','order','','{"kind": "order", "text": "Complete the remote consent review before the participant signs.", "from_event": "", "to_event": "", "first_event": "remote consent review", "then_event": "participant signs reconsent form", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during remote reconsent", "exception": "", "quote": "4. The participant signs the informed consent form and provides the original signed consent form back to the site.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "remote_consent_review", "then_event_id": "reconsent_signature", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0917", "implied": true}','','[]',6917,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0918','check','','follow_up','','{"kind": "follow_up", "text": "Obtain the participant''s original signed consent form back at the site.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "participant signs reconsent form", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during remote reconsent", "exception": "", "quote": "4. The participant signs the informed consent form and provides the original signed consent form back to the site.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "reconsent_signature", "value_name_id": "", "code": false, "id": "chk:0918"}','','[]',6918,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0919','check','','order','','{"kind": "order", "text": "Receive the original signed form before the person who conducted remote consent signs it.", "from_event": "", "to_event": "", "first_event": "site receives original signed reconsent form", "then_event": "remote consenter signs reconsent form", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during remote reconsent", "exception": "", "quote": "Once received at the site, the individual who consented the participant via phone or telemedicine signs the informed consent form.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "original_reconsent_received", "then_event_id": "remote_consenter_signature", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0919", "implied": true}','','[]',6919,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0920','check','','follow_up','','{"kind": "follow_up", "text": "Ensure the individual who conducted consent by phone or telemedicine signs the received form.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "site receives original signed reconsent form", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during remote reconsent", "exception": "", "quote": "Once received at the site, the individual who consented the participant via phone or telemedicine signs the informed consent form.", "section_id": "master:6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "original_reconsent_received", "value_name_id": "", "code": false, "id": "chk:0920"}','','[]',6920,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0921','check','','follow_up','','{"kind": "follow_up", "text": "Collect age, gender, race, ethnicity, and Master Protocol ineligibility reasons for consented participants found ineligible.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "Master Protocol ineligibility determination", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants who signed Master Protocol consent", "exception": "", "quote": "All sites will be required to collect demographic information including age, gender, race, and ethnicity, and reasons for incligibility for the Master Protocol for participants that have signed the Master Protocol consent form and are deemed ineligible for the Master Protocol.", "section_id": "master:6.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "master_screen_failure", "value_name_id": "", "code": false, "id": "chk:0921"}','','[]',6921,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0922','check','','follow_up','','{"kind": "follow_up", "text": "After regimen assignment, confirm regimen-specific eligibility at the Regimen-Specific Screening Visit.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "regimen assignment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "using regimen-specific inclusion and exclusion criteria, if any", "exception": "", "quote": "Once assigned to a regimen, participant eligibility will be confirmed using regimen-specific inclusion and exclusion criteria, if any, during the Regimen-Specific Screening Visit.", "section_id": "master:6.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "regimen_assignment", "value_name_id": "", "code": false, "id": "chk:0922"}','','[]',6922,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0923','check','','follow_up','','{"kind": "follow_up", "text": "Document reasons for regimen ineligibility.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "regimen ineligibility determination", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Reasons for ineligibility for the regimen must be documented", "section_id": "master:6.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "regimen_ineligible", "value_name_id": "", "code": false, "id": "chk:0923"}','','[]',6923,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0924','check','','judgment','','{"kind": "judgment", "text": "Use IRT for regimen assignment.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning a regimen", "exception": "", "quote": "Regimen assignment and treatment randomization will be conducted using an interactive response technology (IRT) system.", "section_id": "master:6.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0924"}','','[]',6924,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0925','check','','judgment','','{"kind": "judgment", "text": "Use IRT for treatment randomization.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when randomizing treatment", "exception": "", "quote": "Regimen assignment and treatment randomization will be conducted using an interactive response technology (IRT) system.", "section_id": "master:6.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0925"}','','[]',6925,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0926','check','','not_checkable','','{"kind": "not_checkable", "text": "Tiered randomization structure, equal regimen allocation, 3:1 active-to-placebo allocation, and RSA-defined multi-arm allocation are statistical design specifications rather than requirements for observed site allocation counts.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The Master Protocol consists of a tiered randomization as described below and depicted in the Study Workflow.", "section_id": "master:6.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0926"}','','[]',6926,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0927','check','','judgment','','{"kind": "judgment", "text": "Assign participants randomly only to recruiting, available regimens to which they have not previously been assigned.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at regimen assignment", "exception": "", "quote": "1. Random equal assignment to a recruiting regimen among all available regimens to which the participant has not previously been assigned.", "section_id": "master:6.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0927"}','','[]',6927,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0928','check','','judgment','','{"kind": "judgment", "text": "Randomize treatment within the assigned regimen rather than another regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at treatment randomization", "exception": "", "quote": "2. Randomization to placebo or an active intervention within the assigned regimen, and randomization to the set of active sub-arms, if applicable.", "section_id": "master:6.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0928"}','','[]',6928,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0929','check','','follow_up','','{"kind": "follow_up", "text": "Perform active sub-arm randomization when applicable.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "treatment randomization in a regimen with active sub-arms", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when active sub-arms are applicable", "exception": "", "quote": "2. Randomization to placebo or an active intervention within the assigned regimen, and randomization to the set of active sub-arms, if applicable.", "section_id": "master:6.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "active_subarm_random", "value_name_id": "", "code": false, "id": "chk:0929"}','','[]',6929,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0930','check','','order','','{"kind": "order", "text": "Confirm Master Protocol eligibility before random regimen assignment.", "from_event": "", "to_event": "", "first_event": "Master Protocol eligibility confirmation", "then_event": "regimen assignment", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "In the first stage, after a participant is determined eligible according to the Master Protocol inclusion and exclusion criteria, a research participant will be randomly assigned equally among all available regimens to which the participant has not previously been assigned.", "section_id": "master:6.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "master_eligibility", "then_event_id": "regimen_assignment", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0930"}','','[]',6930,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0931','check','','order','','{"kind": "order", "text": "Confirm all assigned-regimen inclusion criteria and absence of all exclusion criteria before treatment randomization.", "from_event": "", "to_event": "", "first_event": "regimen eligibility confirmation", "then_event": "treatment randomization", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "In the second stage, if a participant has been determined eligible by meeting all inclusion and no exclusion criteria specific to their assigned regimen, the research participant will be randomized 3:1 to the active intervention or the placebo for the regimen.", "section_id": "master:6.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "regimen_eligibility_confirmed", "then_event_id": "treatment_randomization", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0931"}','','[]',6931,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0932','check','','judgment','','{"kind": "judgment", "text": "Use the regimen-specific allocation scheme when randomizing participants in a multi-arm regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for regimens with multiple arms", "exception": "", "quote": "If the regimen has multiple arms, a participant will also be randomized according to the allocation scheme for that regimen.", "section_id": "master:6.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0932"}','','[]',6932,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0933','check','','follow_up','','{"kind": "follow_up", "text": "Use IRT for treatment randomization within a regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "treatment randomization", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Randomization into treatment group within a regimen will be facilitated via the IRT system after a participant has been determined eligible for any inclusion and exclusion criteria specific to their assigned regimen.", "section_id": "master:6.4.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "treatment_randomization", "value_name_id": "", "code": false, "id": "chk:0933"}','','[]',6933,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0934','check','','order','','{"kind": "order", "text": "Confirm regimen-specific eligibility before treatment randomization.", "from_event": "", "to_event": "", "first_event": "confirmation of regimen-specific eligibility", "then_event": "treatment randomization", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Randomization into treatment group within a regimen will be facilitated via the IRT system after a participant has been determined eligible for any inclusion and exclusion criteria specific to their assigned regimen.", "section_id": "master:6.4.2", "from_event_id": "", "to_event_id": "", "first_event_id": "regimen_eligibility", "then_event_id": "treatment_randomization", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0934"}','','[]',6934,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0935','check','','not_checkable','','{"kind": "not_checkable", "text": "Interventions may differ in administration mode, frequency, and introduction time; concurrent randomized placebo arms are trial-design requirements. Regimen assignments are unblinded.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Each intervention arm will have its own concurrent, randomized placebo control arm.", "section_id": "master:6.4.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0935"}','','[]',6935,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0936','check','','judgment','','{"kind": "judgment", "text": "Maintain treatment-assignment blinding for participants, SIs, and everyone conducting the regimen through the ATE period, following the Blinding and Unblinding Plan.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Emergency unblinding of a single participant when necessary for safe care.", "quote": "Research participants, SIs, and everyone involved in the conduct of a given trial regimen will not be blinded to regimen assignments but will be blinded to the randomized treatment assignments within a regimen, and this blind will be maintained through the ATE period of the study, as outlined in the HEALEY ALS Platform Trial Blinding and Unblinding Plan.", "section_id": "master:6.4.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0936"}','','[]',6936,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0937','check','','judgment','','{"kind": "judgment", "text": "Emergency unblinding must be necessary for safe participant care.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "emergency unblinding", "exception": "", "quote": "In the event of a medical emergency that necessitates the unblinding of the Medical Monitor (MM) or a SI to safely provide care for a participant, emergency unblinding of that single participant may be undertaken as outlined below.", "section_id": "master:6.4.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0937"}','','[]',6937,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0938','check','','judgment','','{"kind": "judgment", "text": "Unblind only when essential to treat the participant safely.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "emergency unblinding", "exception": "", "quote": "Emergency unblinding for a research participant will only be undertaken when it is essential to treat the participant safely.", "section_id": "master:6.4.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0938"}','','[]',6938,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0939','check','','judgment','','{"kind": "judgment", "text": "Unblinding requires an emergency in which the SI needs treatment identity to provide appropriate treatment or protect participants or others exposed to investigational products.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "emergency unblinding", "exception": "", "quote": "It must only be used in an emergency when the identity of the treatment arm must be known to the SI to provide appropriate medical treatment or otherwise ensure the safety of research participants or others exposed to investigational products.", "section_id": "master:6.4.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0939"}','','[]',6939,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0940','check','','not_checkable','','{"kind": "not_checkable", "text": "Product discontinuation and knowledge of possible assignments usually suffice in emergencies; detailed unblinding information is in the separate plan.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "In most cases, investigational product discontinuation and knowledge of the possible treatment assignments will be sufficient to treat a study participant who presents with an emergency condition.", "section_id": "master:6.4.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0940"}','','[]',6940,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0941','check','','judgment','','{"kind": "judgment", "text": "Limit any necessary unblinding to the affected participant.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "emergency unblinding", "exception": "", "quote": "However, if unblinding is necessary, the blind may be broken only for that participant.", "section_id": "master:6.4.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0941"}','','[]',6941,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0942','check','','judgment','','{"kind": "judgment", "text": "Consider product discontinuation for prohibited-medication concerns or other safety concerns, including missing safety data.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "SI or designee has safety concerns", "exception": "", "quote": "If the SI or designee is concerned about the use of a prohibited medication or other safety issues (including lack of safety data collected), then the investigational product may need to be discontinued.", "section_id": "master:6.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0942"}','','[]',6942,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0943','check','','not_checkable','','{"kind": "not_checkable", "text": "Alternative administration options after loss of swallowing ability are specified in the RSA; participants may stop product at any time for any reason. Discontinuation data are included in the database and reported.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "A research participant may choose to discontinue the investigational product at any time for any reason.", "section_id": "master:6.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0943"}','','[]',6943,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0944','check','','follow_up','','{"kind": "follow_up", "text": "Encourage continued protocol participation under ITT after product discontinuation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug discontinuation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "However, the SI or designee will encourage the research participant to follow the study protocol under the intent-to-treat principle (ITT).", "section_id": "master:6.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_discontinuation", "value_name_id": "", "code": false, "id": "chk:0944"}','','[]',6944,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0945','check','','follow_up','','{"kind": "follow_up", "text": "Encourage off-treatment visits through week 36 and the ATE according to the Schedule of Activities.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug discontinuation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "These research participants will be encouraged to follow the study visits, off treatment, up to the week 36 visit and through the ATE period of the study, following the Schedule of Activities.", "section_id": "master:6.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_discontinuation", "value_name_id": "", "code": false, "id": "chk:0945"}','','[]',6945,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0946','check','','follow_up','','{"kind": "follow_up", "text": "Encourage collection of ALSFRS-R, AEs, concomitant medications, C-SSRS, and other outcome measures.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug discontinuation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "At a minimum, collection of the ALSFRS-R, AEs, Concomitant Medications, C-SSRS, and other outcome measures should be encouraged Loss to follow-up should be prevented whenever possible.", "section_id": "master:6.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_discontinuation", "value_name_id": "", "code": false, "id": "chk:0946"}','','[]',6946,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0947','check','','judgment','','{"kind": "judgment", "text": "Prevent loss to follow-up whenever possible.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "At a minimum, collection of the ALSFRS-R, AEs, Concomitant Medications, C-SSRS, and other outcome measures should be encouraged Loss to follow-up should be prevented whenever possible.", "section_id": "master:6.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0947"}','','[]',6947,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0948','check','','follow_up','','{"kind": "follow_up", "text": "Complete an in-person early termination visit after ITT follow-up ends.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ITT follow-up discontinuation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "participants followed under ITT", "exception": "", "quote": "For participants followed under the ITT principle, an in-person Early Termination Visit will be completed after they discontinue follow-up under the ITT principle.", "section_id": "master:6.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "itt_followup_stop", "value_name_id": "", "code": false, "id": "chk:0948"}','','[]',6948,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0949','check','','order','','{"kind": "order", "text": "Perform the early termination visit after ITT follow-up discontinuation.", "from_event": "", "to_event": "", "first_event": "ITT follow-up discontinuation", "then_event": "early termination visit", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "participants followed under ITT", "exception": "", "quote": "For participants followed under the ITT principle, an in-person Early Termination Visit will be completed after they discontinue follow-up under the ITT principle.", "section_id": "master:6.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "itt_followup_stop", "then_event_id": "et_visit", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0949", "implied": true}','','[]',6949,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0950','check','','follow_up','','{"kind": "follow_up", "text": "Do not omit the follow-up safety call on the basis of ITT follow-up unless that follow-up lasts at least 28 days.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug discontinuation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Participant followed under ITT for at least 28 days.", "quote": "A Follow-Up Safety Call at the time study drug is discontinued is not be required, as long as the participant is followed under the ITT principle for a minimum of 28 days.", "section_id": "master:6.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_discontinuation", "value_name_id": "", "code": false, "id": "chk:0950"}','','[]',6950,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0951','check','','follow_up','','{"kind": "follow_up", "text": "Instruct the participant to return unused product and applicable empty packaging.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug discontinuation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Upon discontinuation of investigational product, the research participant is instructed to return any unused investigational product, including empty packaging, if applicable.", "section_id": "master:6.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_discontinuation", "value_name_id": "", "code": false, "id": "chk:0951"}','','[]',6951,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0952','check','','follow_up','','{"kind": "follow_up", "text": "Record the reason for permanent product discontinuation in the CRF.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "permanent study drug discontinuation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "For all research participants, the reason for permanent discontinuation of investigational product must be recorded in the Case Report Form (CRF).", "section_id": "master:6.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "permanent_drug_stop", "value_name_id": "", "code": false, "id": "chk:0952"}','','[]',6952,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0953','check','','judgment','','{"kind": "judgment", "text": "SI-initiated termination must reflect a condition or situation making continued participation contrary to the participant''s best interest.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "SI or designee terminates participation", "exception": "", "quote": "A SI or designee may terminate a research participant if a medical condition or other situation occurs such that continued participation would not be in the best interest of the participant.", "section_id": "master:6.5.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0953"}','','[]',6953,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0954','check','','not_checkable','','{"kind": "not_checkable", "text": "Participants may withdraw consent without justification.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "A research participant may withdraw consent for study participation.", "section_id": "master:6.5.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0954"}','','[]',6954,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0955','check','','follow_up','','{"kind": "follow_up", "text": "Instruct terminated participants to return unused product and applicable empty packaging.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "participation termination", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Upon termination, the research participant is instructed to return any unused investigational product, including empty packaging material, if applicable.", "section_id": "master:6.5.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "participation_termination", "value_name_id": "", "code": false, "id": "chk:0955"}','','[]',6955,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0956','check','','not_checkable','','{"kind": "not_checkable", "text": "Sponsor may terminate the protocol or a regimen at any time; regimen-specific stopping criteria are in the RSA or statistical analysis plan.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The IND-holder/Sponsor reserves the right to terminate the overall Master Protocol or any individual regimen at any time.", "section_id": "master:6.5.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0956"}','','[]',6956,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0957','check','','not_checkable','','{"kind": "not_checkable", "text": "Platform product selection, RSA product descriptions, possible multiple arms, matching placebos, and shared-placebo rationale are trial-design information.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Each active agent will have a matching placebo.", "section_id": "master:7.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0957"}','','[]',6957,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0958','check','','judgment','','{"kind": "judgment", "text": "Conduct regimens in compliance with the Master Protocol assessments.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All regimens will be compliant with the Master Protocol, which outlines the majority of all clinical, biomarker, and safety assessments, making a shared placebo group both desirable and feasible.", "section_id": "master:7.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0958"}','','[]',6958,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0959','check','','not_checkable','','{"kind": "not_checkable", "text": "Manufacturer identification will be supplied in the RSA.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Details identifying the investigational product manufacturer will be included in the corresponding RSA.", "section_id": "master:7.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0959"}','','[]',6959,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0960','check','','not_checkable','','{"kind": "not_checkable", "text": "Industry partners supply product; GMP packaging and labeling, TMF label samples, and RSA packaging, labeling, and resupply descriptions are manufacturing or central administrative requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Samples of labels will be filed in the Trial Master File (TMF).", "section_id": "master:7.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0960"}','','[]',6960,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0961','check','','judgment','','{"kind": "judgment", "text": "Handle and store product safely and properly at the pharmacy or another designated location.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Investigational product for all regimens will be received at the study site, handled and stored safely and properly at the site pharmacy or other designated location, and kept in a secure location to which only the trial pharmacist and designated pharmacy staff, SI, and clinical staff have access.", "section_id": "master:7.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0961"}','','[]',6961,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0962','check','','judgment','','{"kind": "judgment", "text": "Keep product secure with access limited to the trial pharmacist, designated pharmacy staff, SI, and clinical staff.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Investigational product for all regimens will be received at the study site, handled and stored safely and properly at the site pharmacy or other designated location, and kept in a secure location to which only the trial pharmacist and designated pharmacy staff, SI, and clinical staff have access.", "section_id": "master:7.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0962"}','','[]',6962,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0963','check','','follow_up','','{"kind": "follow_up", "text": "Store received product according to label instructions.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug receipt", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Upon receipt, the investigational product will be stored according to the instructions specified on the labels.", "section_id": "master:7.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_receipt", "value_name_id": "", "code": false, "id": "chk:0963"}','','[]',6963,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0964','check','','judgment','','{"kind": "judgment", "text": "Adequately monitor storage conditions and control storage-area temperature.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "product storage", "exception": "", "quote": "Storage conditions will be adequately monitored and temperature in the area in which the investigational product is stored will be controlled, monitored and recorded, at a minimum daily.", "section_id": "master:7.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0964"}','','[]',6964,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0965','check','','follow_up','','{"kind": "follow_up", "text": "Monitor and record storage-area temperature at least daily.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "daily study drug storage", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "product storage", "exception": "", "quote": "Storage conditions will be adequately monitored and temperature in the area in which the investigational product is stored will be controlled, monitored and recorded, at a minimum daily.", "section_id": "master:7.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "daily_drug_storage", "value_name_id": "", "code": false, "id": "chk:0965"}','','[]',6965,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0966','check','','follow_up','','{"kind": "follow_up", "text": "Document amounts dispensed or administered in accordance with local requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug dispensing or administration", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "In accordance with local regulatory requirements, the SI or delegated study staff documents the amount of investigational product dispensed and/or administered to study participants, the amount received from the Central Pharmacy, and the amount destroyed upon completion of the study.", "section_id": "master:7.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_dispense_or_admin", "value_name_id": "", "code": false, "id": "chk:0966"}','','[]',6966,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0967','check','','follow_up','','{"kind": "follow_up", "text": "Document amounts received from the Central Pharmacy.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug receipt", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "In accordance with local regulatory requirements, the SI or delegated study staff documents the amount of investigational product dispensed and/or administered to study participants, the amount received from the Central Pharmacy, and the amount destroyed upon completion of the study.", "section_id": "master:7.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_receipt", "value_name_id": "", "code": false, "id": "chk:0967"}','','[]',6967,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0968','check','','follow_up','','{"kind": "follow_up", "text": "Document amounts destroyed upon study completion.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug destruction", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "study completion", "exception": "", "quote": "In accordance with local regulatory requirements, the SI or delegated study staff documents the amount of investigational product dispensed and/or administered to study participants, the amount received from the Central Pharmacy, and the amount destroyed upon completion of the study.", "section_id": "master:7.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_destruction", "value_name_id": "", "code": false, "id": "chk:0968"}','','[]',6968,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0969','check','','judgment','','{"kind": "judgment", "text": "SI must ensure accountability records are maintained throughout the study.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The SI is responsible for ensuring product accountability records are maintained throughout the course of the study.", "section_id": "master:7.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0969"}','','[]',6969,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0970','check','','follow_up','','{"kind": "follow_up", "text": "Research pharmacist or designated staff must maintain an accurate shipment and dispensing drug-accountability log.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug shipment or dispensing", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The research pharmacist or designated study staff will be responsible for maintaining an accurate record of the shipment and dispensing of investigational product in a drug accountability log.", "section_id": "master:7.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_ship_or_dispense", "value_name_id": "", "code": false, "id": "chk:0970"}','','[]',6970,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0971','check','','not_checkable','','{"kind": "not_checkable", "text": "Additional product-specific information is supplied in the RA and drug MOP.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Additional investigational product-specific details will be provided in the RA and Regimen study drug MOP.", "section_id": "master:7.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0971"}','','[]',6971,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0972','check','','not_checkable','','{"kind": "not_checkable", "text": "Destruction methods, responsible parties, and site retention durations are deferred to the MOP or site policies; no specific duration is supplied here.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Details on how the investigational product will be destroyed, who is responsible for the destruction, and how long documentation will be retained at sites, will be provided in the MOP or defer to site specific policies.", "section_id": "master:7.1.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0972"}','','[]',6972,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0973','check','','not_checkable','','{"kind": "not_checkable", "text": "Each regimen has a separately provided Investigator''s Brochure.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "An Investigator''s Brochure will be provided for each regimen as a separate document to this protocol.", "section_id": "master:7.1.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0973"}','','[]',6973,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0974','check','','not_checkable','','{"kind": "not_checkable", "text": "Dosage-change details and circumstances are supplied in the RSA.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Any changes in dosage, along with the circumstances surrounding those for such, will be described in the RSA.", "section_id": "master:7.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0974"}','','[]',6974,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0975','check','','not_checkable','','{"kind": "not_checkable", "text": "Regimen compliance definitions are supplied in the RSA.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Compliance for each regimen will be defined in the RSA.", "section_id": "master:7.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0975"}','','[]',6975,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0976','check','','follow_up','','{"kind": "follow_up", "text": "Remind noncompliant participants of the importance of taking product per protocol.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study drug noncompliance", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "In cases of non-compliance, the participant will be reminded of the importance of taking the investigational product per protocol.", "section_id": "master:7.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_noncompliance", "value_name_id": "", "code": false, "id": "chk:0976"}','','[]',6976,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0977','check','','not_checkable','','{"kind": "not_checkable", "text": "Overdose actions are supplied in the RSA.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Details on the actions to take in the event of an overdose will be included in the RSA.", "section_id": "master:7.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0977"}','','[]',6977,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0978','check','','not_checkable','','{"kind": "not_checkable", "text": "Necessary concomitant medications are permitted; experimental-dose marketed ALS agents are included in the definition of other investigational products.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Throughout the study, participants may be prescribed concomitant medications deemed necessary to provide adequate care.", "section_id": "master:7.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0978"}','','[]',6978,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0979','check','','judgment','','{"kind": "judgment", "text": "Do not give other investigational products during the study, including marketed agents at experimental dosages being tested for ALS.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the study", "exception": "", "quote": "Participants should not receive other investigational products during the study.", "section_id": "master:7.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0979"}','','[]',6979,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0980','check','','follow_up','','{"kind": "follow_up", "text": "Record all concomitant medications in source documents and eCRF.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "concomitant medication use", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All concomitant medications and significant non-drug therapies, including supplements, received by a participant should be recorded on the appropriate source document and electronic Case Report Form (eCRF).", "section_id": "master:7.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "concomitant_medication_use", "value_name_id": "", "code": false, "id": "chk:0980"}','','[]',6980,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0981','check','','follow_up','','{"kind": "follow_up", "text": "Record significant non-drug therapies, including supplements, in source documents and eCRF.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "significant non-drug therapy use", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All concomitant medications and significant non-drug therapies, including supplements, received by a participant should be recorded on the appropriate source document and electronic Case Report Form (eCRF).", "section_id": "master:7.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "significant_nondrug_therapy", "value_name_id": "", "code": false, "id": "chk:0981"}','','[]',6981,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0982','check','','not_checkable','','{"kind": "not_checkable", "text": "Prohibited-medication details are supplied in the RSA.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Details on medications that may not be taken during the trial will be included in the RSA.", "section_id": "master:7.5.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0982"}','','[]',6982,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0983','check','','not_checkable','','{"kind": "not_checkable", "text": "This section introduces common procedures; regimens may add RSA procedures.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "This section describes trial procedures that are common to all regimens tested in the HEALEY ALS Platform Trial as detailed in the Master Protocol.", "section_id": "master:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0983"}','','[]',6983,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0984','check','','judgment','','{"kind": "judgment", "text": "Follow the common Master Protocol procedures for every regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Each regimen will follow these procedures and may add additional procedures as described in the corresponding RSA.", "section_id": "master:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0984"}','','[]',6984,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0985','check','','order','','{"kind": "order", "text": "Obtain signed Master Protocol consent before any study test or procedure.", "from_event": "", "to_event": "", "first_event": "Master Protocol informed consent signing", "then_event": "study test or procedure", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All participants will sign the Master Protocol ICF prior to undergoing any study tests or procedures.", "section_id": "master:8", "from_event_id": "", "to_event_id": "", "first_event_id": "master_consent_signing", "then_event_id": "study_procedure", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0985"}','','[]',6985,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0986','check','','judgment','','{"kind": "judgment", "text": "Calculate visit windows in consecutive calendar days from baseline day 0, the first administration day.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "1. Visit windows are consecutive calendar days and the target visit dates are calculated from the Baseline Visit - Day 0 (first day of investigational product administration).", "section_id": "master:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0986"}','','[]',6986,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0987','check','','order','','{"kind": "order", "text": "Perform vital capacity at the start of the visit before other testing.", "from_event": "", "to_event": "", "first_event": "vital capacity assessment", "then_event": "other visit testing", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "visit includes vital capacity", "exception": "", "quote": "2. Assessment of vital capacity should be performed at the start of a visit so as not to fatigue the participant with other testing.", "section_id": "master:8", "from_event_id": "", "to_event_id": "", "first_event_id": "vc_assessment", "then_event_id": "other_visit_testing", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0987", "implied": true}','','[]',6987,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0988','check','','judgment','','{"kind": "judgment", "text": "Perform remaining assessments in the listed sequence.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "3. The remaining clinical assessments should be administered in the same sequence as listed in the sections below and at approximately the same time of the day.", "section_id": "master:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0988"}','','[]',6988,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0989','check','','judgment','','{"kind": "judgment", "text": "Perform clinical assessments at approximately the same time of day.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "3. The remaining clinical assessments should be administered in the same sequence as listed in the sections below and at approximately the same time of the day.", "section_id": "master:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0989"}','','[]',6989,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0990','check','','order','','{"kind": "order", "text": "Complete Master Protocol visit activities before additional RSA assessments.", "from_event": "", "to_event": "", "first_event": "Master Protocol visit activities completion", "then_event": "additional RSA assessments", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "visit has additional RSA assessments", "exception": "RSA specifies otherwise.", "quote": "a. Any additional assessments that are included in an RSA for a given visit should be completed once the Master Protocol SOA for that visit is complete, unless otherwise specified in the RSA.", "section_id": "master:8", "from_event_id": "", "to_event_id": "", "first_event_id": "master_visit_complete", "then_event_id": "additional_rsa_assessments", "event_id": "", "value_name_id": "", "code": true, "id": "chk:0990", "implied": true}','','[]',6990,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:0991','check','','judgment','','{"kind": "judgment", "text": "Use the same outcome evaluator throughout a participant''s regimen participation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "4. Outcomes for individual participants should be measured by the same evaluator throughout their participation in a regimen.", "section_id": "master:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:0991"}','','[]',6991,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
