INSERT INTO guide VALUES('NCT05842941','checks','chk:1010','check','','follow_up','','{"kind": "follow_up", "text": "Collect screening blood including coagulation parameters, urine for urinalysis, and blood biomarker sample.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "master protocol screening visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Collect blood samples for clinical screening assessments (including coagulation parameters) and, for women of child bearing potential (WOCBP), for pregnancy test Collect urine for urinalysis Collect blood biomarker sample Review and document concomitant medications Assess and document AEs Schedule the Regimen Specific Screening Visit if the participant passes screening for the Master Protocol 8.1.I Regimen Assignment Once a participant''s Master Protocol eligibility is confirmed the participant will be randomly assigned to a regimen and will undergo informed consent for that regimen at their scheduled Regimen-Specific Screening Visit.", "section_id": "master:8.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "master_screening_visit", "value_name_id": "", "code": false, "id": "chk:1010"}','','[]',7010,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
