INSERT INTO guide VALUES('NCT05842941','checks','chk:1014','check','','order','','{"kind": "order", "text": "Confirm Master Protocol eligibility before random regimen assignment.", "from_event": "", "to_event": "", "first_event": "Master Protocol eligibility confirmation", "then_event": "random regimen assignment", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Collect blood samples for clinical screening assessments (including coagulation parameters) and, for women of child bearing potential (WOCBP), for pregnancy test Collect urine for urinalysis Collect blood biomarker sample Review and document concomitant medications Assess and document AEs Schedule the Regimen Specific Screening Visit if the participant passes screening for the Master Protocol 8.1.I Regimen Assignment Once a participant''s Master Protocol eligibility is confirmed the participant will be randomly assigned to a regimen and will undergo informed consent for that regimen at their scheduled Regimen-Specific Screening Visit.", "section_id": "master:8.1", "from_event_id": "", "to_event_id": "", "first_event_id": "master_eligibility", "then_event_id": "regimen_randomization", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1014"}','','[]',7014,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1015','check','','not_checkable','','{"kind": "not_checkable", "text": "The screening list specifies a preferred order, not an absolute sequence.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The following procedures will be performed in-person, after Master Protocol informed consent is obtained, to determine the participant''s eligibility for the Master Protocol and are listed in preferred order to be completed:", "section_id": "master:8.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1015"}','','[]',7015,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1016','check','','not_checkable','','{"kind": "not_checkable", "text": "Signing Master Protocol consent defines enrollment. Time-dependent disqualification may resolve within screening without rescreening. Immediate reassignment after regimen-specific ineligibility and administrative regimen screen failure before consent are permitted.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Any participant who signs the Master Protocol consent form will be considered enrolled in the Platform Trial.", "section_id": "master:8.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1016"}','','[]',7016,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
