INSERT INTO guide VALUES('NCT05842941','checks','chk:1019','check','','follow_up','','{"kind": "follow_up", "text": "Capture and enter eligibility criteria assessed before screen failure in EDC.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "Master Protocol screen failure", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Any eligibility criteria that were assessed prior to when the research participant failed to meet an inclusion criterion or met an exclusion criterion.", "section_id": "master:8.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "master_screen_failure", "value_name_id": "", "code": false, "id": "chk:1019"}','','[]',7019,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1020','check','','judgment','','{"kind": "judgment", "text": "Use resolution of time-dependent disqualification without rescreening only if it resolves within the screening period.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "eligibility accepted after resolution of time-dependent disqualification without rescreening", "exception": "", "quote": "If a research participant fails to meet a time-dependent Master Protocol eligibility criterion (e.g., duration of stable medication prior to enrollment, interval following last use of an investigational treatment, or other criteria as applicable), then that participant may become eligible immediately after resolution of the disqualifying condition if resolution occurs within the screening period and re-screening is not required.", "section_id": "master:8.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1020"}','','[]',7020,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1021','check','','judgment','','{"kind": "judgment", "text": "Repeat failed screening vital capacity on a different day within the initial screening period.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "reassessing failed screening vital capacity", "exception": "", "quote": "If a participant fails to meet the vital capacity screening criterion on the day of the Master Protocol Screening visit, vital capacity may be reassessed on a different day during the initial screening period.", "section_id": "master:8.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1021"}','','[]',7021,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1022','check','','judgment','','{"kind": "judgment", "text": "Repeat eligibility safety labs during Master Protocol screening when necessary.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "repeat eligibility safety labs", "exception": "", "quote": "Safety labs required for the site investigator to determine eligibility, can be repeated during the Master Protocol screening period, if necessary.", "section_id": "master:8.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1022"}','','[]',7022,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1023','check','','follow_up','','{"kind": "follow_up", "text": "Complete a full Master Protocol screening visit, including consent, when rescreening after the initial window.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "Master Protocol rescreening", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "initial screening window has ended", "exception": "", "quote": "If a participant is re-screened for Master Protocol eligibility after the initial screening window ends, they must complete a full Master Protocol Screening Visit, including informed consent, as outlined in section 8.1.", "section_id": "master:8.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "master_rescreening", "value_name_id": "", "code": false, "id": "chk:1023"}','','[]',7023,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1024','check','','order','','{"kind": "order", "text": "Obtain written Master Protocol re-consent before reassignment after discontinuing a randomized regimen.", "from_event": "", "to_event": "", "first_event": "written Master Protocol re-consent", "then_event": "regimen reassignment", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "previously randomized participant discontinued a regimen", "exception": "", "quote": "The research participant must provide written informed re-consent to the Master Protocol and must still meet the Master Protocol inclusion and exclusion eligibility criteria in order to be re-assigned into a different regimen.", "section_id": "master:8.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "master_reconsent", "then_event_id": "regimen_reassignment", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1024", "implied": false}','','[]',7024,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1025','check','','judgment','','{"kind": "judgment", "text": "Confirm continued Master Protocol eligibility before reassignment after discontinuing a randomized regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "previously randomized participant being reassigned", "exception": "", "quote": "The research participant must provide written informed re-consent to the Master Protocol and must still meet the Master Protocol inclusion and exclusion eligibility criteria in order to be re-assigned into a different regimen.", "section_id": "master:8.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1025"}','','[]',7025,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1026','check','','interval','','{"kind": "interval", "text": "Wait at least 30 days before rescreening after a regimen stops for futility or success; use a longer known five-half-life period instead.", "from_event": "regimen discontinuation", "to_event": "Master Protocol rescreening", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 30, "max": null, "applies_when": "regimen stopped for futility or success", "exception": "", "quote": "The research participant may be re-screened after 30 days or 5 half-lives (if known), whichever is longer", "section_id": "master:8.1.2", "from_event_id": "regimen_discontinuation", "to_event_id": "master_rescreening", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1026", "implied": false, "stated": [30, null]}','','[]',7026,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
