INSERT INTO guide VALUES('NCT05842941','checks','chk:1170','check','','not_checkable','','{"kind": "not_checkable", "text": "Regimen-specific outcome measures, timing, and activities are deferred to the RSA.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The outcome measures that are required to be collected for each regimen, and the timing of and activities for the Early Termination Visit and Follow-Up Safety Call, will be detailed in the RSA.", "section_id": "master:8.12", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1170"}','','[]',7170,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1171','check','','not_checkable','','{"kind": "not_checkable", "text": "Defines deviations, responsible parties, and minor/major classifications; major classification is determined by the Sponsor.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "A protocol deviation is any noncompliance with the sIRB approved clinical trial protocol.", "section_id": "master:8.13", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1171"}','','[]',7171,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1172','check','','judgment','','{"kind": "judgment", "text": "Do not report patient reported outcomes omitted because of a language barrier or attempted but failed procedures as protocol deviations.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "missed or failed assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "patient reported outcomes not performed due to a participant language barrier, or procedures attempted but failed", "exception": "", "quote": "Patient reported outcomes (c.g. ALSAQ-40) not performed due to a participant language barrier, and procedures that were attempted but failed will not be reported as protocol deviations.", "section_id": "master:8.13", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "missed_failed_assessment", "value_name_id": "", "code": false, "id": "chk:1172"}','','[]',7172,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1173','check','','follow_up','','{"kind": "follow_up", "text": "Develop corrective and preventative actions for deviations.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "protocol deviation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "As a result of deviations, corrective and preventative actions are to be developed by the site with review by the Coordination Center (CC) and Study Monitors and implemented promptly.", "section_id": "master:8.13", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "protocol_deviation", "value_name_id": "", "code": false, "id": "chk:1173"}','','[]',7173,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
