INSERT INTO guide VALUES('NCT05842941','checks','chk:1175','check','','judgment','','{"kind": "judgment", "text": "Implement corrective and preventative actions promptly.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "protocol deviation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "As a result of deviations, corrective and preventative actions are to be developed by the site with review by the Coordination Center (CC) and Study Monitors and implemented promptly.", "section_id": "master:8.13", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "protocol_deviation", "value_name_id": "", "code": false, "id": "chk:1175"}','','[]',7175,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1176','check','','follow_up','','{"kind": "follow_up", "text": "Record deviations in participant source documentation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "protocol deviation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Excluded events expressly not considered reportable deviations.", "quote": "All deviations from the protocol will be recorded in the participant''s source documentation.", "section_id": "master:8.13", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "protocol_deviation", "value_name_id": "", "code": false, "id": "chk:1176"}','','[]',7176,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1177','check','','follow_up','','{"kind": "follow_up", "text": "Enter deviations in the EDC Protocol Deviations Log.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "protocol deviation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Excluded events expressly not considered reportable deviations.", "quote": "Protocol deviations must be entered in the Protocol Deviations Log in the EDC system.", "section_id": "master:8.13", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "protocol_deviation", "value_name_id": "", "code": false, "id": "chk:1177"}','','[]',7177,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1178','check','','follow_up','','{"kind": "follow_up", "text": "Report deviations to the sIRB according to its guidelines.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "protocol deviation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Excluded events expressly not considered reportable deviations.", "quote": "Deviations will be reported to the sIRB per their guidelines.", "section_id": "master:8.13", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "protocol_deviation", "value_name_id": "", "code": false, "id": "chk:1178"}','','[]',7178,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1179','check','','follow_up','','{"kind": "follow_up", "text": "Report missed visits and unattempted procedures as protocol deviations when not attributable to illness, injury, or progressive disability.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "missed visit or procedure", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "procedure not attempted or visit missed", "exception": "Illness, injury, or progressive disability; other express protocol or MOP exceptions.", "quote": "Missed visits and any procedures not performed (not attempted) for reasons other than illness, injury or progressive disability (i.e., participant is physically unable to perform test) will be reported as protocol deviations.", "section_id": "master:8.14", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "missed_visit_procedure", "value_name_id": "", "code": false, "id": "chk:1179"}','','[]',7179,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1180','check','','judgment','','{"kind": "judgment", "text": "Do not report illness-, injury-, or disability-related omissions or attempted but failed procedures as deviations.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "missed visit or procedure", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "omission due to illness, injury or disability, or attempted but failed procedure", "exception": "", "quote": "Procedures or visits not performed due to illness, injury or disability, including procedures that were attempted but failed (e.g., blood samples unable to be drawn after multiple attempts, or weight unable to be obtained due to participant immobility will not be reported as protocol deviations.", "section_id": "master:8.14", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "missed_visit_procedure", "value_name_id": "", "code": false, "id": "chk:1180"}','','[]',7180,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1181','check','','follow_up','','{"kind": "follow_up", "text": "Report investigational product compliance outside RSA limits as a protocol deviation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "investigational product compliance outside RSA limits", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Investigational product compliance that is outside the limits set in the RSA will be reported as a protocol deviation (see RSA for further details).", "section_id": "master:8.14", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ip_compliance_outside_limits", "value_name_id": "", "code": false, "id": "chk:1181"}','','[]',7181,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1182','check','','not_checkable','','{"kind": "not_checkable", "text": "Additional deviation instructions and exceptions are in the MOP; RSA compliance limits are not supplied here.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Details and specific instructions regarding protocol deviations, including any exceptions to this standard procedure, are found in the study Manual of Procedures.", "section_id": "master:8.14", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1182"}','','[]',7182,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1183','check','','follow_up','','{"kind": "follow_up", "text": "Document pandemic-related missed assessments as such in source documentation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "missed assessment due to pandemic-related restrictions", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Missed assessments due to pandemic-related restrictions must be documented as such in the source documentation and in the EDC.", "section_id": "master:8.14", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "pandemic_missed_assessment", "value_name_id": "", "code": false, "id": "chk:1183"}','','[]',7183,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1184','check','','follow_up','','{"kind": "follow_up", "text": "Document pandemic-related missed assessments as such in EDC.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "missed assessment due to pandemic-related restrictions", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Missed assessments due to pandemic-related restrictions must be documented as such in the source documentation and in the EDC.", "section_id": "master:8.14", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "pandemic_missed_assessment", "value_name_id": "", "code": false, "id": "chk:1184"}','','[]',7184,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1185','check','','not_checkable','','{"kind": "not_checkable", "text": "Describes permissible death-information sources, possible later vital-status ascertainment, outside-vendor ascertainment, and the next chapter heading.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Information on whether a participant has died may be obtained from the participant''s family, from clinic notes, or from a publicly available data source like the Centers for Disease Control and Prevention (CDC) National Death Index or the Social Security Death Index.", "section_id": "master:8.15", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1185"}','','[]',7185,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1186','check','','follow_up','','{"kind": "follow_up", "text": "Site staff must determine vital status for every randomized participant throughout placebo-controlled follow-up, including death date or PAV status, or last-known-alive and last-known-PAV-free dates.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "placebo-controlled follow-up", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for each randomized participant", "exception": "", "quote": "Vital status, defined as a determination of date of death or PAV status or date last known alive and date last known to be PAV-free, will be determined by site study staff for each randomized participant throughout the placebo-controlled portion of their follow-up (generally the Week 36 visit, as indicated in the SOA.", "section_id": "master:8.15", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "placebo_followup", "value_name_id": "", "code": false, "id": "chk:1186"}','','[]',7186,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1187','check','','judgment','','{"kind": "judgment", "text": "Complete a second vital-status check for every randomized participant approximately at regimen placebo-controlled LPLV.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "regimen placebo-controlled last patient last visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for each randomized participant", "exception": "", "quote": "At approximately the time of the last patient last visit (LPLV) of the placebo-controlled period of a given regimen, a second vital status check will be completed by site study staff for each randomized participant.", "section_id": "master:8.15", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "regimen_pc_lplv", "value_name_id": "", "code": false, "id": "chk:1187"}','','[]',7187,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
