INSERT INTO guide VALUES('NCT05842941','checks','chk:1196','check','','follow_up','','{"kind": "follow_up", "text": "Perform the specified clinical safety tests at master protocol screening, RSA screening/baseline, weeks 4, 8, 16, 24, and week 36 or early termination.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "scheduled clinical safety laboratory visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The following laboratory tests will be performed for safety at the Master Protocol Screening to determine eligibility and at the following visits: Screening/Baseline as described in the RSA, Week 4, Week 8, Week 16, Week 24 and Week 36/ET", "section_id": "master:9.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "scheduled_safety_labs", "value_name_id": "", "code": false, "id": "chk:1196"}','','[]',7196,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1197','check','','follow_up','','{"kind": "follow_up", "text": "Obtain the complete hematology differential panel: hematocrit, hemoglobin, platelets, RBC indices, total RBC, total WBC, and WBC differential.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "scheduled clinical safety laboratory visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Hematology with differential panel: complete blood count with differential (hematocrit, hemoglobin, platelet count, RBC indices, Total RBC, Total WBC, and WBC & differential)", "section_id": "master:9.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "scheduled_safety_labs", "value_name_id": "", "code": false, "id": "chk:1197"}','','[]',7197,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1198','check','','follow_up','','{"kind": "follow_up", "text": "Obtain the full chemistry/LFT panel: ALT, AST, albumin, alkaline phosphatase, bicarbonate, blood urea nitrogen, calcium, chloride, creatinine, cystatin C, glucose, magnesium, phosphate, potassium, sodium, total bilirubin, and total protein.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "scheduled clinical safety laboratory visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Blood chemistry panel/Liver function tests (LFTs): alanine aminotransferase (ALT (SGPT), aspartate aminotransferase (AST (SGOT)), albumin, alkaline phosphatase, bicarbonate, blood urea nitrogen, calcium, chloride, creatinine (estimated Glomerular Filtration Rate [eGFR] will be calculated using the using the CKD-EPI 2021 equation), cystatin C, glucose, magnesium, phosphate, potassium, sodium, total bilirubin and total protein", "section_id": "master:9.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "scheduled_safety_labs", "value_name_id": "", "code": false, "id": "chk:1198"}','','[]',7198,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
