INSERT INTO guide VALUES('NCT05842941','checks','chk:1204','check','','follow_up','','{"kind": "follow_up", "text": "Ensure every participant receives clinical safety laboratory testing at SOA-designated visits.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "scheduled clinical safety laboratory visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All participants will have clinical safety laboratory tests at the designated visits outlined in the schedule of activities.", "section_id": "master:9.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "scheduled_safety_labs", "value_name_id": "", "code": false, "id": "chk:1204"}','','[]',7204,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1205','check','','not_checkable','','{"kind": "not_checkable", "text": "The SI may order additional local or central retesting for AEs, suspected pregnancy, or missing results; participants may be asked to return for missing-result blood collection. These are permissions, not unconditional requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "If additional testing is required to obtain results, the participant may be asked to return to repeat blood collection for such missing results.", "section_id": "master:9.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1205"}','','[]',7205,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1206','check','','follow_up','','{"kind": "follow_up", "text": "Perform a standard 12-lead ECG at screening and SOA-designated safety assessments.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "scheduled ECG assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "A standard 12-lead ECG will be performed for safety at the screening visit to determine eligibility and for safety as outlined in the schedule of activities.", "section_id": "master:9.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "scheduled_ecg", "value_name_id": "", "code": false, "id": "chk:1206"}','','[]',7206,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1207','check','','judgment','','{"kind": "judgment", "text": "Use the study-provided ECG device.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ECG collection", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The ECG should be collected using the study provided ECG device.", "section_id": "master:9.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ecg_collection", "value_name_id": "", "code": false, "id": "chk:1207"}','','[]',7207,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1208','check','','follow_up','','{"kind": "follow_up", "text": "Keep a copy of ECG tracings on site as source documentation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ECG collection", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Tracings will be reviewed by a central ECG reader and a copy of the tracings will be kept on site as part of the source documents.", "section_id": "master:9.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ecg_collection", "value_name_id": "", "code": false, "id": "chk:1208"}','','[]',7208,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1209','check','','not_checkable','','{"kind": "not_checkable", "text": "Central ECG reader review is not a site action; additional guidance is in the MOP.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Additional guidance is included in the MOP.", "section_id": "master:9.1.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1209"}','','[]',7209,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1210','check','','follow_up','','{"kind": "follow_up", "text": "Perform and record a physical examination.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "physical examination assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "A physical examination will be performed and recorded.", "section_id": "master:9.1.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "physical_exam", "value_name_id": "", "code": false, "id": "chk:1210"}','','[]',7210,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1211','check','','follow_up','','{"kind": "follow_up", "text": "Perform and record a neurological examination.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "neurological examination assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "A neurological examination will be performed and recorded.", "section_id": "master:9.1.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "neurological_exam", "value_name_id": "", "code": false, "id": "chk:1211"}','','[]',7211,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1212','check','','not_checkable','','{"kind": "not_checkable", "text": "Provides FDA/C-CASA rationale, C-SSRS background, lifetime versus since-last-visit interpretation, and a triage-guideline reference.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The C-SSRS involves a series of probing questions to inquire about possible suicidal thinking and behavior.", "section_id": "master:9.1.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1212"}','','[]',7212,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1213','check','','follow_up','','{"kind": "follow_up", "text": "Administer the C-SSRS Baseline version at baseline.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "baseline visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "At the Baseline Visit, the C-SSRS Baseline version will be administered.", "section_id": "master:9.1.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "baseline_visit", "value_name_id": "", "code": false, "id": "chk:1213"}','','[]',7213,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1214','check','','follow_up','','{"kind": "follow_up", "text": "Administer the C-SSRS Since Last Visit version at all other visits.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "non-baseline visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "At all other visits, the Since Last Visit version of the C-SSRS will be administered.", "section_id": "master:9.1.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "nonbaseline_visit", "value_name_id": "", "code": false, "id": "chk:1214"}','','[]',7214,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1215','check','','follow_up','','{"kind": "follow_up", "text": "Notify an appropriately qualified clinician during the visit to determine safety actions following the specified positive suicidality response.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "positive C-SSRS safety trigger", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during treatment: positive ideation severity question 4 or 5, positive suicidal behavior suicide-attempt response, or participant suicidal ideation during C-SSRS administration", "exception": "", "quote": "If there is a positive response to question 4 or 5 on the severity of ideation subscale or any positive response on the suicidal behavior subscale of suicide attempt or suicidal ideation by the participant during the administration of the C-SSRS during the treatment period, the appropriately qualified clinician will be notified during the study visit to determine the appropriate actions required to ensure the participant''s safety.", "section_id": "master:9.1.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "cssrs_safety_trigger", "value_name_id": "", "code": false, "id": "chk:1215"}','','[]',7215,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1216','check','','follow_up','','{"kind": "follow_up", "text": "Ensure the participant is seen by a licensed physician or other locally qualified individual following the positive C-SSRS safety trigger.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "positive C-SSRS safety trigger", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "after the specified positive C-SSRS response during treatment", "exception": "", "quote": "The site must ensure that the participant is seen by a licensed physician (or other qualified individual as required by local institutional policy) before leaving the study site.", "section_id": "master:9.1.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "cssrs_safety_trigger", "value_name_id": "", "code": false, "id": "chk:1216"}','','[]',7216,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1217','check','','order','','{"kind": "order", "text": "The qualified clinician assessment must precede departure from the site.", "from_event": "", "to_event": "", "first_event": "qualified clinician safety assessment", "then_event": "participant leaves study site", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "after the specified positive C-SSRS response during treatment", "exception": "", "quote": "The site must ensure that the participant is seen by a licensed physician (or other qualified individual as required by local institutional policy) before leaving the study site.", "section_id": "master:9.1.6", "from_event_id": "", "to_event_id": "", "first_event_id": "clinician_safety_check", "then_event_id": "site_departure", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1217", "implied": false}','','[]',7217,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1218','check','','follow_up','','{"kind": "follow_up", "text": "The SI must determine whether the participant should remain on study drug.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "positive C-SSRS safety trigger", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "after the specified positive C-SSRS response during treatment", "exception": "", "quote": "The SI will determine whether the participant should remain on study drug.", "section_id": "master:9.1.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "cssrs_safety_trigger", "value_name_id": "", "code": false, "id": "chk:1218"}','','[]',7218,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1219','check','','judgment','','{"kind": "judgment", "text": "Prefer a medically licensed physician, nurse, nurse practitioner, or physician assistant to assess the C-SSRS; this is a recommendation rather than an absolute restriction.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "C-SSRS assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "It is recommended that a medically licensed physician, nurse, nurse practitioner, or physician assistant to assess the C-SSRS.", "section_id": "master:9.1.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "cssrs", "value_name_id": "", "code": false, "id": "chk:1219"}','','[]',7219,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1220','check','','judgment','','{"kind": "judgment", "text": "All C-SSRS evaluators must be certified.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "C-SSRS assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All evaluators must be certified to perform the C-SSKS.", "section_id": "master:9.1.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "cssrs", "value_name_id": "", "code": false, "id": "chk:1220"}','','[]',7220,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1221','check','','order','','{"kind": "order", "text": "Obtain certification before performing the C-SSRS.", "from_event": "", "to_event": "", "first_event": "C-SSRS evaluator certification", "then_event": "C-SSRS assessment", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Certification is required prior to performing the C-SSRS.", "section_id": "master:9.1.6", "from_event_id": "", "to_event_id": "", "first_event_id": "cssrs_certification", "then_event_id": "cssrs", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1221"}','','[]',7221,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1222','check','','not_checkable','','{"kind": "not_checkable", "text": "Additional regimen endpoints are described in the RSA.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Details of any additional specific endpoints required for a regimen will be described in the corresponding RSA.", "section_id": "master:9.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1222"}','','[]',7222,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1223','check','','not_checkable','','{"kind": "not_checkable", "text": "Describes ALSFRS-R scoring, meaning, validity, reliability, administration duration, and equivalence of phone, in-person, caregiver, and web responses.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Each functional activity is rated 0-4 for a total score that ranges from 0 to 48.", "section_id": "master:9.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1223"}','','[]',7223,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
