INSERT INTO guide VALUES('NCT05842941','checks','chk:1230','check','','value','','{"kind": "value", "text": "Perform at least three VC trials per testing session.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "VC trials per testing session", "operator": "lt", "limit": 3, "limit2": null, "value_unit": "trials", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Three VC trials are required for each testing session, however up to 5 trials may be performed if the variability between the highest and second highest VC is 10% or greater for the first 3 trials.", "section_id": "master:9.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "vc_trials_per_session", "code": true, "id": "chk:1230"}','','[]',7230,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1231','check','','value','','{"kind": "value", "text": "Do not exceed three VC trials unless first-three-trial variability between the highest and second highest VC is at least 10%.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "VC trials per testing session", "operator": "gt", "limit": 3, "limit2": null, "value_unit": "trials", "unit": "", "min": null, "max": null, "applies_when": "variability between highest and second highest VC in the first three trials is below 10%", "exception": "", "quote": "Three VC trials are required for each testing session, however up to 5 trials may be performed if the variability between the highest and second highest VC is 10% or greater for the first 3 trials.", "section_id": "master:9.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "vc_trials_per_session", "code": true, "id": "chk:1231", "implied": false}','','[]',7231,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1232','check','','value','','{"kind": "value", "text": "Do not exceed five VC trials even when additional trials are permitted.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "VC trials per testing session", "operator": "gt", "limit": 5, "limit2": null, "value_unit": "trials", "unit": "", "min": null, "max": null, "applies_when": "variability between highest and second highest VC in the first three trials is at least 10%", "exception": "", "quote": "Three VC trials are required for each testing session, however up to 5 trials may be performed if the variability between the highest and second highest VC is 10% or greater for the first 3 trials.", "section_id": "master:9.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "vc_trials_per_session", "code": true, "id": "chk:1232", "implied": false}','','[]',7232,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1233','check','','follow_up','','{"kind": "follow_up", "text": "Record only the three best VC trials on the CRF.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "SVC assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Only the 3 best trials are recorded on the CRF.", "section_id": "master:9.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "svc_assessment", "value_name_id": "", "code": false, "id": "chk:1233"}','','[]',7233,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
