INSERT INTO guide VALUES('NCT05842941','checks','chk:1235','check','','value','','{"kind": "value", "text": "Do not score post-screening VC with fewer than three measurable trials.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "measurable VC trials per testing session", "operator": "lt", "limit": 3, "limit2": null, "value_unit": "trials", "unit": "", "min": null, "max": null, "applies_when": "when scoring VC at any visit after screening", "exception": "", "quote": "At least 3 measurable VC trials must be completed to score VC for all visits after screening.", "section_id": "master:9.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "measurable_vc_trials", "code": true, "id": "chk:1235", "implied": false}','','[]',7235,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
