INSERT INTO guide VALUES('NCT05842941','checks','chk:1243','check','','judgment','','{"kind": "judgment", "text": "Prefer a single evaluator for all measures throughout the study as much as possible; this is not an absolute requirement.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "evaluator assignment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "When a single evaluator is not possible.", "quote": "It is strongly preferred that a single evaluator performs all measures throughout the study, as much as possible.", "section_id": "master:9.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "evaluator_assignment", "value_name_id": "", "code": false, "id": "chk:1243"}','','[]',7243,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
