INSERT INTO guide VALUES('NCT05842941','checks','chk:1246','check','','not_checkable','','{"kind": "not_checkable", "text": "Defines the composite survival endpoint, PAV (>22 hours/day for >7 consecutive days), first-day initiation dating, fifteenth-of-month imputation, and baseline-PAV censoring. These are endpoint/statistical definitions, not ventilation limits imposed on sites.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Death equivalent will be defined as use of permanent assisted ventilation (PAV), where PAV is defined as more than 22 hours per day of noninvasive or invasive mechanical ventilation for more than seven consecutive days.", "section_id": "master:9.2.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1246"}','','[]',7246,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
