INSERT INTO guide VALUES('NCT05842941','checks','chk:1250','check','','not_checkable','','{"kind": "not_checkable", "text": "Describes indefinite research storage, participant ability to withdraw sample-use consent, inability to destroy already-used samples, and Laboratory Manual/RSA references.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants have the option of declining participation in this portion of the study at any time by withdrawing their consent to have their sample used.", "section_id": "master:9.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1250"}','','[]',7250,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1251','check','','follow_up','','{"kind": "follow_up", "text": "Collect blood for DNA extraction/genome sequencing at baseline from consenting participants.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "baseline visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants consenting to DNA collection", "exception": "Collection may occur any time after baseline if the baseline sample is not obtained for any reason or is unusable.", "quote": "All participants consenting to DNA collection will provide a blood sample for deoxyribonucleic acid (DNA) extraction for genome sequencing during the Baseline Visit.", "section_id": "master:9.3.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "baseline_visit", "value_name_id": "", "code": false, "id": "chk:1251"}','','[]',7251,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
