INSERT INTO guide VALUES('NCT05842941','checks','chk:1258','check','','order','','{"kind": "order", "text": "Collect the second coagulation parameters before the second lumbar puncture.", "from_event": "", "to_event": "", "first_event": "second coagulation sample collection", "then_event": "second lumbar puncture", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for participants undergoing a second lumbar puncture", "exception": "", "quote": "Coagulation parameters will be collected a second time, prior to the second lumbar puncture, as defined in the RSA.", "section_id": "master:9.3.4", "from_event_id": "", "to_event_id": "", "first_event_id": "coag_sample_2", "then_event_id": "lp_2", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1258", "implied": true}','','[]',7258,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1259','check','','follow_up','','{"kind": "follow_up", "text": "The SI must discuss all potential LP risks, including injection-site pain, anesthetic reactions, entrance-site bleeding and infection, and post-LP low-pressure headache.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "planned lumbar puncture", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The SI will discuss all potential LP risks to the subjects including:", "section_id": "master:9.3.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "planned_lp", "value_name_id": "", "code": false, "id": "chk:1259"}','','[]',7259,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1260','check','','not_checkable','','{"kind": "not_checkable", "text": "Provides research-LP complication evidence and statistics from Alzheimer''s disease cohorts.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "No other local or generalized complications occurred.", "section_id": "master:9.3.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1260"}','','[]',7260,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1261','check','','judgment','','{"kind": "judgment", "text": "LP must be performed by the SI or staff with appropriate qualifications, experience, and training under institutional policy.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "lumbar puncture", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The procedure must be performed by the SI or another staff member with the appropriate qualifications, experience, and training in performing LPs per institutional policy.", "section_id": "master:9.3.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "lumbar_puncture", "value_name_id": "", "code": false, "id": "chk:1261"}','','[]',7261,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1262','check','','judgment','','{"kind": "judgment", "text": "Use an atraumatic Sprotte needle when possible.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "lumbar puncture", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "When use of an atraumatic Sprotte needle is not possible.", "quote": "When possible, LPs should be performed with an atraumatic Sprotte needle to reduce the risk of post-LP headache.", "section_id": "master:9.3.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "lumbar_puncture", "value_name_id": "", "code": false, "id": "chk:1262"}','','[]',7262,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1263','check','','not_checkable','','{"kind": "not_checkable", "text": "States that protocol AE definitions and reporting procedures comply with FDA regulations and ICH guidelines.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The AE definitions and reporting procedures provided in this protocol comply with all applicable United States Food and Drug Administration (FDA) regulations and ICH guidelines.", "section_id": "master:10", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1263"}','','[]',7263,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1264','check','','judgment','','{"kind": "judgment", "text": "The SI must carefully monitor every participant for possible AEs throughout the study.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "participant study participation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The SI will carefully monitor each participant throughout the study for possible adverse events.", "section_id": "master:10", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "study_participation", "value_name_id": "", "code": false, "id": "chk:1264"}','','[]',7264,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1265','check','','follow_up','','{"kind": "follow_up", "text": "Document every AE on the specifically designed AE CRFs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "adverse event", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All AEs will be documented on CRFs designed specifically for this purpose.", "section_id": "master:10", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "adverse_event", "value_name_id": "", "code": false, "id": "chk:1265"}','','[]',7265,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1266','check','','follow_up','','{"kind": "follow_up", "text": "Report all AEs, serious or non-serious, including those causing permanent investigational product discontinuation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "adverse event", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "It is also important to report all AEs, especially those that result in permanent discontinuation of the investigational product being studied, whether serious or non-serious.", "section_id": "master:10", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "adverse_event", "value_name_id": "", "code": false, "id": "chk:1266"}','','[]',7266,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1267','check','','judgment','','{"kind": "judgment", "text": "Classify unfavorable and unintended signs, symptoms, diseases, and clinically significant laboratory findings temporally associated with the study as AEs regardless of relatedness.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Outcome measure results, stable pre-existing chronic conditions, and symptoms of ALS progression are excluded as specified below.", "quote": "An AE is any unfavorable and unintended sign (including a clinically significant abnormal laboratory finding, for example, symptom, or disease temporally associated with a study, use of a drug product or device whether or not considered related to the drug product or device.", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_classification", "value_name_id": "", "code": false, "id": "chk:1267"}','','[]',7267,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1268','check','','judgment','','{"kind": "judgment", "text": "Classify an AE as a suspected ADR only when a causal relationship to the medicinal product is a reasonable possibility.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "suspected ADR classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Therefore, a subset of AEs can be classified as suspected ADRs, if there is a causal relationship to the medicinal product.", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "suspected_adr", "value_name_id": "", "code": false, "id": "chk:1268"}','','[]',7268,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1269','check','','judgment','','{"kind": "judgment", "text": "Include new conditions, worsening pre-existing conditions, and clinically significant examination or test abnormalities as AEs; do not record outcome measure results as AEs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Examples of adverse events include: new conditions, worsening of pre-existing conditions, clinically significant abnormal physical examination signs (e.g., skin rash, peripheral edema, etc.), or clinically significant abnormal test results (e.g., lab values or vital signs), with the exception of outcome measure results, which are not being recorded as adverse events in this trial (they are being collected, but analyzed separately).", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_classification", "value_name_id": "", "code": false, "id": "chk:1269"}','','[]',7269,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1270','check','','judgment','','{"kind": "judgment", "text": "Do not classify stable chronic conditions present before study start as AEs if they do not worsen during the trial.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for pre-existing stable chronic conditions", "exception": "", "quote": "Stable chronic conditions (e.g., diabetes, arthritis) that are present prior to the start of the study and do not worsen during the trial are NOT considered adverse events.", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_classification", "value_name_id": "", "code": false, "id": "chk:1270"}','','[]',7270,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1271','check','','follow_up','','{"kind": "follow_up", "text": "Record chronic conditions as AEs when they become more frequent or more severe.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "increased frequency or severity of chronic condition", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Chronic conditions that occur more frequently (for intermittent conditions) or with greater severity, would be considered as worsened and therefore would be recorded as adverse events.", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "chronic_condition_worsening", "value_name_id": "", "code": false, "id": "chk:1271"}','','[]',7271,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1272','check','','judgment','','{"kind": "judgment", "text": "Do not record symptoms of ALS progression or worsening, including normal progression, as AEs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for symptoms of ALS progression or worsening", "exception": "", "quote": "Symptoms of progression/worsening of ALS, including ''normal'' progression, will not be recorded as adverse events.", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_classification", "value_name_id": "", "code": false, "id": "chk:1272"}','','[]',7272,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1273','check','','follow_up','','{"kind": "follow_up", "text": "Have the SI identify and record a specific disease or syndrome on the AE log rather than its individual signs and symptoms when discernible.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE log completion", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when a specific disease or syndrome is discernible at AE log completion", "exception": "", "quote": "If discernible at the time of completing the AE log, a specific disease or syndrome rather than individual associated signs and symptoms should be identified by the SI and recorded on the AE log.", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_log_completion", "value_name_id": "", "code": false, "id": "chk:1273"}','','[]',7273,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1274','check','','follow_up','','{"kind": "follow_up", "text": "Record a sign, symptom, or clinically significant laboratory anomaly as a separate AE when the SI does not consider it part of a specific disease or syndrome.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "sign, symptom, or clinically significant laboratory anomaly", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when the SI does not consider the finding a component of a specific disease or syndrome", "exception": "", "quote": "However, if an observed or reported sign, symptom, or clinically significant laboratory anomaly is not considered by the SI to be a component of a specific disease or syndrome, then it should be recorded as a separate AE on the AE log.", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "clinical_anomaly", "value_name_id": "", "code": false, "id": "chk:1274"}','','[]',7274,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1275','check','','follow_up','','{"kind": "follow_up", "text": "Monitor participants for AEs from Master Protocol consent signing through completion of participation as defined in the RSA.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "Master Protocol consent signing", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "from Master Protocol consent signing until completion of participation as defined in the RSA", "exception": "", "quote": "Clinically significant laboratory abnormalities, such as those that require intervention, are those that are identified as such by the Participants will be monitored for adverse events from the time they sign consent for the Master Protocol until completion of their participation as defined in the RSA.", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "master_consent_signing", "value_name_id": "", "code": false, "id": "chk:1275"}','','[]',7275,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1276','check','','judgment','','{"kind": "judgment", "text": "Classify an AE as unexpected when its specificity or severity is inconsistent with the current regimen-applicable Investigator''s Brochure.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "unexpected AE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "An unexpected adverse event is any adverse event, the specificity or severity of which is not consistent with the current regimen applicable Investigator''s Brochure.", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "unexpected_ae", "value_name_id": "", "code": false, "id": "chk:1276"}','','[]',7276,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1277','check','','judgment','','{"kind": "judgment", "text": "Classify an unexpected AE as an unexpected suspected ADR when the SI or Sponsor considers investigational-product causation a reasonable possibility.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "unexpected suspected ADR classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "An unexpected, suspected adverse drug reaction is any unexpected adverse event that for which, in the opinion of the SI or Sponsor, there is a reasonable possibility that the investigational product caused the event.", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "unexpected_suspected_adr", "value_name_id": "", "code": false, "id": "chk:1277"}','','[]',7277,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1278','check','','not_checkable','','{"kind": "not_checkable", "text": "Background includes ADR terminology and the clinical and ancillary-test routes of AE detection. The laboratory-significance sentence is incomplete in the supplied text and does not identify who determines significance.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Adverse events are generally detected in two ways:", "section_id": "master:10.1.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1278"}','','[]',7278,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1279','check','','judgment','','{"kind": "judgment", "text": "Classify an AE resulting in death as serious.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "SAE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when an AE results in death", "exception": "", "quote": "1. Results in death.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sae_classification", "value_name_id": "", "code": false, "id": "chk:1279"}','','[]',7279,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1280','check','','judgment','','{"kind": "judgment", "text": "Classify an AE posing an immediate risk of death as it occurs as serious, based on SI or Sponsor assessment; hypothetical death if the event were worse does not qualify.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "SAE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when evaluating the life-threatening criterion", "exception": "An event that might hypothetically cause death if more severe does not qualify under this criterion.", "quote": "a. This serious criterion applies if the study participant, in the view of the SI or Sponsor, is at immediate risk of death from the AE as it occurs.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sae_classification", "value_name_id": "", "code": false, "id": "chk:1280"}','','[]',7280,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1281','check','','judgment','','{"kind": "judgment", "text": "Classify an AE requiring inpatient hospitalization or prolonging existing hospitalization as serious.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "SAE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when an AE requires inpatient hospitalization or prolongs existing hospitalization", "exception": "Elective procedures and routinely scheduled treatments do not qualify by this criterion.", "quote": "3. Requires inpatient hospitalization or prolongation of existing hospitalization.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sae_classification", "value_name_id": "", "code": false, "id": "chk:1281"}','','[]',7281,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1282','check','','judgment','','{"kind": "judgment", "text": "Do not classify hospitalization for an elective procedure, including elective feeding tube placement, or routinely scheduled treatment as an SAE solely on the hospitalization criterion.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "SAE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for elective procedure or routinely scheduled treatment hospitalization", "exception": "", "quote": "a. Hospitalization for an elective procedure (including elective PEG tube/g-tube/feeding tube placement) or a routinely scheduled treatment is not an SAE by this criterion because an elective or scheduled \"procedure\" or a \"treatment\" is not an untoward medical occurrence.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sae_classification", "value_name_id": "", "code": false, "id": "chk:1282"}','','[]',7282,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1283','check','','judgment','','{"kind": "judgment", "text": "Classify an AE causing persistent or significant disability or incapacity as serious; disability means substantial disruption of normal life functions.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "SAE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when an AE causes persistent or significant disability or incapacity", "exception": "", "quote": "a. This criterion applies if the \"disability\" caused by the reported AE results in a substantial disruption of the participant''s ability to carry out normal life functions.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sae_classification", "value_name_id": "", "code": false, "id": "chk:1283"}','','[]',7283,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1284','check','','judgment','','{"kind": "judgment", "text": "Classify an AE resulting in a congenital anomaly or birth defect in a participant''s offspring as serious, regardless of the participant''s sex.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "SAE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when an AE results in congenital anomaly or birth defect in participant offspring", "exception": "", "quote": "5. Results in congenital anomaly or birth defect in the offspring of the participant (whether the participant is male or female.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sae_classification", "value_name_id": "", "code": false, "id": "chk:1284"}','','[]',7284,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1285','check','','judgment','','{"kind": "judgment", "text": "Classify an AE necessitating medical or surgical intervention to prevent permanent impairment of body function or permanent damage to body structure as serious.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "SAE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when an AE necessitates intervention to prevent permanent impairment or damage", "exception": "", "quote": "6. Necessitates medical or surgical intervention to preclude permanent impairment of a body function or permanent damage to a body structure.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sae_classification", "value_name_id": "", "code": false, "id": "chk:1285"}','','[]',7285,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1286','check','','judgment','','{"kind": "judgment", "text": "Consider medically important events as SAEs when medical judgment indicates participant jeopardy and possible intervention to prevent a listed serious outcome, even without death, life threat, or hospitalization.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "SAE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for important medical events", "exception": "", "quote": "7. Important medical events that may not result in death, are not life-threatening, or do not require hospitalization may also be considered SAEs when, based upon appropriate medical judgment, they may jeopardize the participant and may require medical or surgical intervention to prevent one of the outcomes listed in this definition.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sae_classification", "value_name_id": "", "code": false, "id": "chk:1286"}','','[]',7286,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1287','check','','judgment','','{"kind": "judgment", "text": "Do not classify an inpatient admission as an SAE in the absence of a precipitating treatment-emergent clinical AE.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "SAE classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for inpatient admissions without a precipitating treatment-emergent clinical AE", "exception": "", "quote": "An inpatient hospital admission in the absence of a precipitating, treatment-emergent, clinical adverse event may meet criteria for \"seriousness\" but is not an adverse experience, and will therefore, not be considered an SAE.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sae_classification", "value_name_id": "", "code": false, "id": "chk:1287"}','','[]',7287,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1288','check','','judgment','','{"kind": "judgment", "text": "Classify an SAE as a serious suspected ADR when the SI or Sponsor considers investigational-product causation a reasonable possibility.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "serious suspected ADR classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "A serious, suspected adverse drug reaction is an SAE that, in the opinion of the SI or Sponsor, there is a reasonable possibility that the investigational product caused the event.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "serious_suspected_adr", "value_name_id": "", "code": false, "id": "chk:1288"}','','[]',7288,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1289','check','','follow_up','','{"kind": "follow_up", "text": "Ensure the SI classifies AEs as serious or non-serious.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The SI is responsible for classifying adverse events as serious or non-serious.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_assessment", "value_name_id": "", "code": false, "id": "chk:1289"}','','[]',7289,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1290','check','','not_checkable','','{"kind": "not_checkable", "text": "Illustrative background examples include social admissions, blood dyscrasias, convulsions, and drug dependency or abuse.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Examples of such medical events include blood dyscrasias or convulsions that do not result in inpatient hospitalization, or the development of drug dependency or drug abuse.", "section_id": "master:10.1.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1290"}','','[]',7290,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1291','check','','follow_up','','{"kind": "follow_up", "text": "The SI must carefully monitor every participant throughout the study for possible AEs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study participation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "throughout the study", "exception": "", "quote": "The SI will carefully monitor each participant throughout the study for possible AEs.", "section_id": "master:10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "study_participation", "value_name_id": "", "code": false, "id": "chk:1291"}','','[]',7291,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1292','check','','follow_up','','{"kind": "follow_up", "text": "Document every AE in source records.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE identification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All AEs will be documented on source and CRFs designed specifically for this purpose.", "section_id": "master:10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_identification", "value_name_id": "", "code": false, "id": "chk:1292"}','','[]',7292,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1293','check','','follow_up','','{"kind": "follow_up", "text": "Document every AE on the specifically designed CRFs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE identification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All AEs will be documented on source and CRFs designed specifically for this purpose.", "section_id": "master:10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_identification", "value_name_id": "", "code": false, "id": "chk:1293"}','','[]',7293,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1294','check','','follow_up','','{"kind": "follow_up", "text": "Collect and report every AE in EDC.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE identification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All AEs will be collected and reported in the EDC system and compiled into reports for monthly reviewing by the MM for the Master Protocol.", "section_id": "master:10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_identification", "value_name_id": "", "code": false, "id": "chk:1294"}','','[]',7294,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1295','check','','judgment','','{"kind": "judgment", "text": "Pay special attention to AEs leading to permanent investigational-product discontinuation, whether serious or non-serious.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for AEs resulting in permanent investigational-product discontinuation", "exception": "", "quote": "Special attention will be paid to those that result in permanent discontinuation of the investigational products) being studied, whether serious or non-serious.", "section_id": "master:10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_assessment", "value_name_id": "", "code": false, "id": "chk:1295"}','','[]',7295,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1296','check','','not_checkable','','{"kind": "not_checkable", "text": "Central administration compiles monthly AE reports for MM review; the Master Protocol MM promptly reviews relevant product safety information, including all SAEs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The Master Protocol MM shall promptly review all information relevant to the safety of the investigational product, including all SAEs.", "section_id": "master:10.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1296"}','','[]',7296,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1297','check','','follow_up','','{"kind": "follow_up", "text": "At every visit, including telephone interviews, ask about problems or symptoms since the last visit to identify AEs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "participant visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "at each visit, including telephone interviews", "exception": "", "quote": "At each visit (including telephone interviews), the participant will be asked if they have had any problems or symptoms since their last visit in order to determine the occurrence of adverse events.", "section_id": "master:10.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "participant_visit", "value_name_id": "", "code": false, "id": "chk:1297"}','','[]',7297,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
