INSERT INTO guide VALUES('NCT05842941','checks','chk:1304','check','','follow_up','','{"kind": "follow_up", "text": "Probe to determine the reported AE''s outcome.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "participant reports AE", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "If the participant reports an adverse event, site staff will probe further to determine:", "section_id": "master:10.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "participant_ae_report", "value_name_id": "", "code": false, "id": "chk:1304"}','','[]',7304,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1305','check','','judgment','','{"kind": "judgment", "text": "Use the mild severity classification for events requiring minimal or no treatment and not interfering with daily activities.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE severity assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Mild - Events require minimal or no treatment and do not interfere with the participant''s daily activities.", "section_id": "master:10.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_severity", "value_name_id": "", "code": false, "id": "chk:1305"}','','[]',7305,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1306','check','','judgment','','{"kind": "judgment", "text": "Use the moderate severity guidelines: low inconvenience or concern with therapeutic measures, with possible interference with functioning.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE severity assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Moderate - Events result in a low level of inconvenience or concern with the therapeutic measures.", "section_id": "master:10.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_severity", "value_name_id": "", "code": false, "id": "chk:1306"}','','[]',7306,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1307','check','','judgment','','{"kind": "judgment", "text": "Use the severe severity guidelines for events interrupting usual daily activity and potentially requiring systemic drug therapy or other treatment.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE severity assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Severe - Events interrupt a participant''s usual daily activity and may require systemic drug therapy or other treatment.", "section_id": "master:10.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_severity", "value_name_id": "", "code": false, "id": "chk:1307"}','','[]',7307,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1308','check','','judgment','','{"kind": "judgment", "text": "Do not equate severe AE severity with SAE seriousness automatically.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE seriousness assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Of note, the term \"severe\" does not necessarily equate to \"serious\".", "section_id": "master:10.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_seriousness", "value_name_id": "", "code": false, "id": "chk:1308"}','','[]',7308,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1309','check','','not_checkable','','{"kind": "not_checkable", "text": "Descriptive severity background notes that severe events are usually potentially life-threatening or incapacitating.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Severe events are usually potentially life-threatening or incapacitating.", "section_id": "master:10.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1309"}','','[]',7309,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1310','check','','follow_up','','{"kind": "follow_up", "text": "Have the SI specify AE relatedness based on temporal relationship and clinical judgment using the protocol definitions.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE relatedness assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The relationship of the AE to the investigational product is specified by the SI based on temporal relationship and his/her clinical judgment, using the following definitions:", "section_id": "master:10.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_relatedness", "value_name_id": "", "code": false, "id": "chk:1310"}','','[]',7310,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1311','check','','judgment','','{"kind": "judgment", "text": "Apply the Related definition when the AE is known to occur with intervention, intervention causation is reasonably possible, or there is a temporal relationship.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE relatedness assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Related - The AE is known to occur with the study intervention, there is a reasonable possibility that the study intervention caused the AE, or there is a temporal relationship between the study intervention and event.", "section_id": "master:10.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_relatedness", "value_name_id": "", "code": false, "id": "chk:1311"}','','[]',7311,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1312','check','','judgment','','{"kind": "judgment", "text": "Apply the Not Related definition when intervention causation is not reasonably possible, there is no temporal relationship to onset, or an alternate etiology is established.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "AE relatedness assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Not Related - There is not a reasonable possibility that the administration of the study intervention caused the event, there is no temporal relationship between the study intervention and event onset, or an alternate etiology has been established.", "section_id": "master:10.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_relatedness", "value_name_id": "", "code": false, "id": "chk:1312"}','','[]',7312,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1313','check','','not_checkable','','{"kind": "not_checkable", "text": "Reasonable possibility is defined as evidence suggesting a causal relationship between intervention and AE.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Reasonable possibility means that there is evidence to suggest a causal relationship between the study intervention and the AE.", "section_id": "master:10.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1313"}','','[]',7313,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1314','check','','follow_up','','{"kind": "follow_up", "text": "Record all clinical AEs in participant records.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "clinical AE identification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All clinical Adverse Events and Key Study Events (e.g., Mortality, Pregnancy, PAV, and Tracheostomy) are recorded in the participant''s records.", "section_id": "master:10.2.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ae_identification", "value_name_id": "", "code": false, "id": "chk:1314"}','','[]',7314,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
