INSERT INTO guide VALUES('NCT05842941','checks','chk:1326','check','','not_checkable','','{"kind": "not_checkable", "text": "The parenthetical mortality, pregnancy, PAV, and tracheostomy list illustrates Key Study Events rather than adding separate administrative requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All clinical Adverse Events and Key Study Events (e.g., Mortality, Pregnancy, PAV, and Tracheostomy) are recorded in the participant''s records.", "section_id": "master:10.2.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1326"}','','[]',7326,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1327','check','','interval','','{"kind": "interval", "text": "Report every SAE to the CC within 24 hours of site notification.", "from_event": "site notified of SAE", "to_event": "SAE reported to CC", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "hours", "min": 0, "max": 24, "applies_when": "for all events meeting SAE criteria", "exception": "", "quote": "The following are considered reportable events and must be reported to the CC within 24 hours of the site being notified of the event: all events that meet the above criteria for SAEs, or any unexpected AE that is deemed related to the study drug, which would have implications for the conduct of the study (e.g., requiring a significant and usually safety-related change to the protocol such as revising inclusion/exclusion criteria or including a new monitoring requirement, informed consent or investigator''s brochure).", "section_id": "master:10.3", "from_event_id": "site_sae_awareness", "to_event_id": "sae_cc_report", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1327", "implied": true, "stated": [0, 24]}','','[]',7327,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1328','check','','interval','','{"kind": "interval", "text": "Report an unexpected study-drug-related AE with implications for study conduct to the CC within 24 hours of site notification.", "from_event": "site notified of unexpected study-drug-related AE", "to_event": "unexpected study-drug-related AE reported to CC", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "hours", "min": 0, "max": 24, "applies_when": "when an unexpected AE is deemed related to study drug and has implications for study conduct", "exception": "", "quote": "The following are considered reportable events and must be reported to the CC within 24 hours of the site being notified of the event: all events that meet the above criteria for SAEs, or any unexpected AE that is deemed related to the study drug, which would have implications for the conduct of the study (e.g., requiring a significant and usually safety-related change to the protocol such as revising inclusion/exclusion criteria or including a new monitoring requirement, informed consent or investigator''s brochure).", "section_id": "master:10.3", "from_event_id": "site_unexpected_drug_ae", "to_event_id": "unexpected_drug_ae_cc", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1328", "implied": false, "stated": [0, 24]}','','[]',7328,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1329','check','','follow_up','','{"kind": "follow_up", "text": "Report dosage changes according to the applicable RSA timelines; this section supplies no numeric deadline.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "dosage change", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "as applicable under the RSA", "exception": "", "quote": "The timelines for reporting dosage changes are described in each RSA as applicable.", "section_id": "master:10.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "dosage_change", "value_name_id": "", "code": false, "id": "chk:1329"}','','[]',7329,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1330','check','','not_checkable','','{"kind": "not_checkable", "text": "Central responsibilities include Data Management AE report compilation; MM review of AE reports and blinded enrollment, laboratory, and deviation data; Medical Monitor Report terminology; MM communication with Sponsor, DSMB, and CC; expedited FDA SUSAR submission; and aggregate DSMB/Sponsor safety reporting. Death, respiratory failure, and routine-procedure hospitalization are excluded from individual expedited FDA reporting, not from the site''s CC reporting requirement.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Death, respiratory failure and hospitalization for routine procedures (i.e., g-tube placement) will not be reported individually in an expedited manner because they are anticipated to occur in the study population at some frequency independent of drug expose.", "section_id": "master:10.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1330"}','','[]',7330,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1331','check','','not_checkable','','{"kind": "not_checkable", "text": "Statistical framework, recommended design, Appendix I and regimen-specific SAP details and precedence, and separation of unblinded interim statisticians from other analyses are statistical and central administrative requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Interim analyses will be performed by a distinct team of unblinded statisticians.", "section_id": "master:11", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1331"}','','[]',7331,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1332','check','','order','','{"kind": "order", "text": "Determine eligibility under Master Protocol inclusion and exclusion criteria before randomizing to an actively enrolling regimen.", "from_event": "", "to_event": "", "first_event": "Master Protocol eligibility determination", "then_event": "regimen randomization", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants in the master protocol will be randomized in two stages; first to one of the actively enrolling regimens after the participant is determined to be eligible based on Master Protocol inclusion and exclusion criteria; and then 3:1 to active treatment or placebo within the regimen after the participant is determined to be eligible based on any regimen-specific eligibility criteria.", "section_id": "master:11.1", "from_event_id": "", "to_event_id": "", "first_event_id": "master_eligibility", "then_event_id": "regimen_randomization", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1332"}','','[]',7332,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1333','check','','judgment','','{"kind": "judgment", "text": "Randomize participants only to an actively enrolling regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "regimen randomization", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants in the master protocol will be randomized in two stages; first to one of the actively enrolling regimens after the participant is determined to be eligible based on Master Protocol inclusion and exclusion criteria; and then 3:1 to active treatment or placebo within the regimen after the participant is determined to be eligible based on any regimen-specific eligibility criteria.", "section_id": "master:11.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "regimen_randomization", "value_name_id": "", "code": false, "id": "chk:1333"}','','[]',7333,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1334','check','','order','','{"kind": "order", "text": "Randomize to a regimen before randomizing to active treatment or placebo within it.", "from_event": "", "to_event": "", "first_event": "regimen randomization", "then_event": "within-regimen treatment randomization", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants in the master protocol will be randomized in two stages; first to one of the actively enrolling regimens after the participant is determined to be eligible based on Master Protocol inclusion and exclusion criteria; and then 3:1 to active treatment or placebo within the regimen after the participant is determined to be eligible based on any regimen-specific eligibility criteria.", "section_id": "master:11.1", "from_event_id": "", "to_event_id": "", "first_event_id": "regimen_randomization", "then_event_id": "treatment_randomization", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1334"}','','[]',7334,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1335','check','','order','','{"kind": "order", "text": "Determine regimen-specific eligibility before randomizing to active treatment or placebo within the regimen.", "from_event": "", "to_event": "", "first_event": "regimen-specific eligibility determination", "then_event": "within-regimen treatment randomization", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Participants in the master protocol will be randomized in two stages; first to one of the actively enrolling regimens after the participant is determined to be eligible based on Master Protocol inclusion and exclusion criteria; and then 3:1 to active treatment or placebo within the regimen after the participant is determined to be eligible based on any regimen-specific eligibility criteria.", "section_id": "master:11.1", "from_event_id": "", "to_event_id": "", "first_event_id": "regimen_eligibility_review", "then_event_id": "treatment_randomization", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1335"}','','[]',7335,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1336','check','','not_checkable','','{"kind": "not_checkable", "text": "Statistical overview covers trial aim; active/placebo regimen and focal/non-focal terminology; recommended Week 36 joint function/survival endpoint and Bayesian shared-placebo analysis; survival composite and PAV definition (ventilation more than 22 hours/day for more than seven consecutive days, dated to the first day); 3:1 within-regimen allocation design; parallel regimen launch/exit; and non-binding early stopping evaluation under the SAPs. These are statistical definitions and platform-level responsibilities, not additional site timing or measured-value limits.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The primary survival endpoint is the composite event of death or a death equivalent of progression to PAV.", "section_id": "master:11.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1336"}','','[]',7336,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1337','check','','not_checkable','','{"kind": "not_checkable", "text": "Statistical requirements cover longitudinal and survival data through Week 36, inclusion of substitute and early termination assessments, focal/non-focal terminology, ITT population, shared and concurrent controls, the recommended 180-day control inclusion bounds, and SAP details. Protocol/RSA design permits limited additional eligibility criteria only for safety or mechanism of action; major criteria may subset shared controls if assessable for all entrants, with any such subset pre-specified in the RSA. These are analysis-population and protocol-design provisions, not site visit windows or washouts.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The recommended analysis population for the primary analysis of the focal regimen is based on the intent to treat (ITT) principle and includes all participants randomized within the focal regimen and control participants from all contributing non-focal regimens.", "section_id": "master:11.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1337"}','','[]',7337,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1338','check','','not_checkable','','{"kind": "not_checkable", "text": "Primary efficacy statistical specifications include the default Bayesian shared function/survival model unless RSA or R-SAP specifies otherwise; all available longitudinal data; exponential and piece-wise exponential survival descriptions; common treatment effect and participant frailty; joint interpretation; linear placebo progression and proportional active slowing; DRR; intercept, slope, baseline-covariate, and regimen random effects; and full Appendix I specification.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Unless otherwise specified in the RSA or R-SAP, the primary analysis for each focal regimen is a Bayesian shared parameter model of function and survival.", "section_id": "master:11.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1338"}','','[]',7338,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1339','check','','not_checkable','','{"kind": "not_checkable", "text": "Missing-data statistical provisions cover variable follow-up, use of all available longitudinal data, mortality and missing-at-random handling, no primary efficacy imputation, and planned sensitivity analyses of missing-data effects.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "No imputation is planned for the primary efficacy analysis.", "section_id": "master:11.2.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1339"}','','[]',7339,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1340','check','','interval','','{"kind": "interval", "text": "Wait at least 30 days after regimen completion before re-screening and assignment to another regimen.", "from_event": "regimen completion", "to_event": "master protocol re-screening", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "days", "min": 30, "max": null, "applies_when": "for participants entering another regimen after completing a regimen", "exception": "", "quote": "Upon completion of a regimen, a research participant may be re-screened into the Master Protocol and assigned to another regimen after 30 days or 5 half-lives (if known), whichever is longer.", "section_id": "master:11.2.4", "from_event_id": "regimen_completion", "to_event_id": "master_rescreening", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1340", "implied": false, "stated": [30, null]}','','[]',7340,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1341','check','','judgment','','{"kind": "judgment", "text": "If five known half-lives exceed 30 days, wait that longer washout period before re-screening and assignment to another regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "master protocol re-screening", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when the previous regimen treatment half-life is known", "exception": "", "quote": "Upon completion of a regimen, a research participant may be re-screened into the Master Protocol and assigned to another regimen after 30 days or 5 half-lives (if known), whichever is longer.", "section_id": "master:11.2.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "master_rescreening", "value_name_id": "", "code": false, "id": "chk:1341"}','','[]',7341,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1342','check','','judgment','','{"kind": "judgment", "text": "Re-screened participants must meet eligibility criteria before subsequent randomization in a different regimen.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "subsequent regimen randomization", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for re-screened participants", "exception": "", "quote": "Those participants who have been re-screened and meet eligibility criteria for a subsequent randomization in a different regimen will be analyzed as new participants with new baseline visits and sets of observations for each regimen to which they were assigned.", "section_id": "master:11.2.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "subsequent_regimen_random", "value_name_id": "", "code": false, "id": "chk:1342"}','','[]',7342,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1343','check','','follow_up','','{"kind": "follow_up", "text": "Obtain a new baseline visit and set of observations for each regimen assigned to a repeat participant.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "repeat participant assigned to another regimen", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for repeat participants assigned to another regimen", "exception": "", "quote": "Those participants who have been re-screened and meet eligibility criteria for a subsequent randomization in a different regimen will be analyzed as new participants with new baseline visits and sets of observations for each regimen to which they were assigned.", "section_id": "master:11.2.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "regimen_reassignment", "value_name_id": "", "code": false, "id": "chk:1343"}','','[]',7343,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1344','check','','not_checkable','','{"kind": "not_checkable", "text": "Statistical provisions treat repeat participants as new participants, treat observations across regimens as conditionally independent, locate analysis alterations in the RSA and R-SAP, and explain the expected lack of prior-treatment effects after washout and progression adjustment.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Within the primary analysis, sets of observations from a repeat participant across multiple regimens will be treated as independent conditional on baseline covariates within each regimen.", "section_id": "master:11.2.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1344"}','','[]',7344,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1345','check','','not_checkable','','{"kind": "not_checkable", "text": "Statistical plans recommend pooling active doses for the primary analysis and specifying separate dose analyses in the R-SAP.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if an RSA includes multiple doses", "exception": "", "quote": "If an RSA includes multiple doses under investigation, the recommended primary analysis will be a pooled analysis of all active doses compared to the shared control.", "section_id": "master:11.2.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1345"}','','[]',7345,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1346','check','','not_checkable','','{"kind": "not_checkable", "text": "Interim analyses permit early stopping and occur simultaneously for actively enrolling regimens with sufficient data; they began May 28, 2021 and continue throughout the trial.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Multiple interim analyses will allow for early stopping within each regimen, with interim analyses occurring simultaneously for all actively enrolling regimens with sufficient data.", "section_id": "master:11.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1346"}','','[]',7346,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1347','check','','not_checkable','','{"kind": "not_checkable", "text": "Regimen design generally excludes early success stopping; where included, posterior-probability criteria in Appendix I of the M-SAP are simulation-calibrated to a one-sided 2.5% Type I error, and stopping is non-binding.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The posterior probability for declaring success is specified in Appendix I of the M-SAP and determined based on clinical trial simulations to achieve an overall one-sided Type I error of 2.5%.", "section_id": "master:11.3.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1347"}','','[]',7347,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1348','check','','not_checkable','','{"kind": "not_checkable", "text": "Futility is determined using posterior-probability rules in the M-SAP; early futility stopping is non-binding.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Futility will be declared for a regimen at an interim analysis based on the posterior probability that the treatment slows progression (detailed rules defined within the M-SAP).", "section_id": "master:11.3.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1348"}','','[]',7348,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1349','check','','not_checkable','','{"kind": "not_checkable", "text": "Secondary efficacy analysis uses CAFS joint ranks based on survival and ALSFRS-R change through 36 weeks, with linear-regression adjustment for covariates identified in the M-SAP and applicable R-SAP.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "As a secondary analysis, a joint-rank test of function and survival will be performed, using the Combined Analysis of Function and Survival model (CAFS).", "section_id": "master:11.4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1349"}','','[]',7349,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1350','check','','not_checkable','','{"kind": "not_checkable", "text": "Secondary endpoints and analyses are specified in each RSA and R-SAP.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Secondary endpoints and analyses will be detailed within each RSA and R-SAP.", "section_id": "master:11.4.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1350"}','','[]',7350,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1351','check','','not_checkable','','{"kind": "not_checkable", "text": "Exploratory endpoints and analyses are specified in each RSA and R-SAP.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Exploratory endpoints and analyses will be detailed within each RSA and R-SAP.", "section_id": "master:11.4.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1351"}','','[]',7351,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1352','check','','not_checkable','','{"kind": "not_checkable", "text": "Sensitivity analyses assess alternative analysis populations, modeling assumptions, and missing data; details are in Appendix I of the M-SAP.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Additional sensit\u0131vity analyses of the primary efficacy analys\u0131s will be conducted for various definitions of the analysis population (e.g., depending on the definition of shared controls), and to evaluate the potential effect of modeling assumptions and missing data.", "section_id": "master:11.4.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1352"}','','[]',7352,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1353','check','','not_checkable','','{"kind": "not_checkable", "text": "Safety analyses summarize treated participants by treatment group, suicidal ideation and behavior, continuous measures and baseline changes, Kaplan-Meier death estimates, MedDRA adverse-event categories and severity/relatedness/outcome, and laboratory CTCAE grades and normal ranges; the R-SAP may specify additional assessments.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Safety data, including deaths and death-equivalents, treatment-emergent adverse events (TEAE), and changes in vital signs, ECGs, and clinical laboratory test results, will be summarized for each treatment group among all participants who initiate treatment.", "section_id": "master:11.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1353"}','','[]',7353,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1354','check','','follow_up','','{"kind": "follow_up", "text": "Record clinically significant out-of-range laboratory tests as adverse events.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "clinically significant out-of-range laboratory test", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Clinically significant out-of-range laboratory tests are recorded as adverse events and will be documented in the TEA summaries.", "section_id": "master:11.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "significant_abnormal_lab", "value_name_id": "", "code": false, "id": "chk:1354"}','','[]',7354,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1355','check','','not_checkable','','{"kind": "not_checkable", "text": "Sample-size justification describes simulation assumptions, virtual trial execution, operating characteristics, Appendix I results, 2.5% one-sided Type I error and at least 80% power for 30% slowing under a common function/survival effect. The embedded Section 12 introduction describes development of the EDC system.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Clinical trial simulation is used to quantify operating characteristics for each regimen.", "section_id": "master:11.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1355"}','','[]',7355,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1356','check','','order','','{"kind": "order", "text": "Review protocol procedures with the SI and associated personnel before the study begins.", "from_event": "", "to_event": "", "first_event": "protocol procedure review with SI and associated personnel", "then_event": "study start", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Protocol procedures are reviewed with the SI and associated personnel prior to the study to ensure the accuracy and reliability of data.", "section_id": "master:12.1", "from_event_id": "", "to_event_id": "", "first_event_id": "procedure_review", "then_event_id": "study_start", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1356"}','','[]',7356,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1357','check','','judgment','','{"kind": "judgment", "text": "Each SI must adhere to the protocol.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Each SI must adhere to the protocol detailed in this document and agree that any changes to the protocol must be approved by the sIRB prior to implementing the change unless it is to address immediate participant safety.", "section_id": "master:12.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1357"}','','[]',7357,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1358','check','','order','','{"kind": "order", "text": "Obtain sIRB approval before implementing a protocol change.", "from_event": "", "to_event": "", "first_event": "sIRB approval of protocol change", "then_event": "protocol change implementation", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when changing the protocol", "exception": "change addresses immediate participant safety", "quote": "Each SI must adhere to the protocol detailed in this document and agree that any changes to the protocol must be approved by the sIRB prior to implementing the change unless it is to address immediate participant safety.", "section_id": "master:12.1", "from_event_id": "", "to_event_id": "", "first_event_id": "sirb_change_approval", "then_event_id": "protocol_change_start", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1358", "implied": true}','','[]',7358,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1359','check','','not_checkable','','{"kind": "not_checkable", "text": "Defines data management, designates NCRI as the DCC, assigns clinical data-system responsibilities, and requires centralized management under NCRI policies and regulatory requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The Neurological Clinical Research Institute (NCRI) will serve as the Data Coordination Center (DCC) for the Master Protocol and is responsible for developing, testing, and managing the clinical data systems and management activities.", "section_id": "master:12.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1359"}','','[]',7359,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1360','check','','judgment','','{"kind": "judgment", "text": "Collect data into appropriate source documents and electronic source documents.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study data collection", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Site personnel will collect data onto source documents as appropriate and into electronic source documents (e.g., voice sample data, EMR data, etc).", "section_id": "master:12.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "study_data_collection", "value_name_id": "", "code": false, "id": "chk:1360"}','','[]',7360,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1361','check','','follow_up','','{"kind": "follow_up", "text": "Transcribe source-document values into corresponding eCRFs in EDC.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "source-document data collection", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Values from source documents will be transcribed into the corresponding eCRFs in the EDC system by site personnel; electronically captured data will be transmitted to their respective vendors for consolidation and reconciliation with the study EDC system.", "section_id": "master:12.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "source_data_collection", "value_name_id": "", "code": false, "id": "chk:1361"}','','[]',7361,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1362','check','','follow_up','','{"kind": "follow_up", "text": "Transmit electronically captured data to the respective vendors for consolidation and reconciliation with EDC.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "electronic data capture", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Values from source documents will be transcribed into the corresponding eCRFs in the EDC system by site personnel; electronically captured data will be transmitted to their respective vendors for consolidation and reconciliation with the study EDC system.", "section_id": "master:12.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "edc", "value_name_id": "", "code": false, "id": "chk:1362"}','','[]',7362,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1363','check','','not_checkable','','{"kind": "not_checkable", "text": "Clinical-site monitoring will assess compliance with protocol, data-management requirements, and GCP.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Clinical sites will be monitored to ensure compliance with the study protocol, data management requirements, and GCP.", "section_id": "master:12.2.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1363"}','','[]',7363,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1364','check','','judgment','','{"kind": "judgment", "text": "Enter collected data into EDC shortly after a visit; no numeric deadline is specified.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "visit data entry", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Site personnel are instructed to enter collected data into the EDC system shortly after a visit.", "section_id": "master:12.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "visit_data_entry", "value_name_id": "", "code": false, "id": "chk:1364"}','','[]',7364,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1365','check','','interval','','{"kind": "interval", "text": "Enter an SAE in EDC within 24 hours of site awareness.", "from_event": "site aware of SAE", "to_event": "SAE entered in EDC", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "hours", "min": 0, "max": 24, "applies_when": "", "exception": "", "quote": "Please note: SAEs must be entered into the EDC system and reported to the CC within 24 hours of site awareness of the SAE.", "section_id": "master:12.2.2", "from_event_id": "site_sae_awareness", "to_event_id": "sae_edc_entry", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1365", "stated": [0, 24]}','','[]',7365,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1366','check','','interval','','{"kind": "interval", "text": "Report an SAE to the CC within 24 hours of site awareness.", "from_event": "site aware of SAE", "to_event": "SAE reported to CC", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "hours", "min": 0, "max": 24, "applies_when": "", "exception": "", "quote": "Please note: SAEs must be entered into the EDC system and reported to the CC within 24 hours of site awareness of the SAE.", "section_id": "master:12.2.2", "from_event_id": "site_sae_awareness", "to_event_id": "sae_cc_report", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1366", "stated": [0, 24]}','','[]',7366,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1367','check','','judgment','','{"kind": "judgment", "text": "Site staff must collect data under SI supervision according to the site''s delegation log.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study data collection", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Data collection is the responsibility of the staff at the site under the supervision of the SI as specified in the delegation log for that site.", "section_id": "master:12.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "study_data_collection", "value_name_id": "", "code": false, "id": "chk:1367"}','','[]',7367,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1368','check','','judgment','','{"kind": "judgment", "text": "The SI must maintain complete and accurate study documentation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "during the study", "exception": "", "quote": "During the study, the SI must maintain complete and accurate documentation for the study.", "section_id": "master:12.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1368"}','','[]',7368,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1369','check','','not_checkable','','{"kind": "not_checkable", "text": "EDC will include logic/range checks, in-form rules, and electronic queries; sites have access only to queries for their own participants.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "To ensure accuracy and completeness of the data set, logic and range checks as well as in-form rules will be built into the EDC system, and electronic queries will be created to track potential data issues.", "section_id": "master:12.2.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1369"}','','[]',7369,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1370','check','','not_checkable','','{"kind": "not_checkable", "text": "EDC supports independent regimen locks and read-only access after locking until access revocation; database-lock procedures are in DM SOPs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The EDC system will have the ability to lock each trial regimen independently to prevent any modification of data once a trial regimen is closed.", "section_id": "master:12.2.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1370"}','','[]',7370,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1371','check','','not_checkable','','{"kind": "not_checkable", "text": "Sponsor-designated qualified monitors oversee all trial aspects under GCP, applicable regulations, and a predefined Clinical Monitoring Plan.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All aspects of the trial, including the individual regimens, will be monitored by qualified individuals designated by the Sponsor.", "section_id": "master:12.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1371"}','','[]',7371,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1372','check','','judgment','','{"kind": "judgment", "text": "Allow monitors access to clinical supplies, dispensing and storage areas, and participant clinical files.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "monitor access", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The SIs will agree to allow monitors access to the clinical supplies, dispensing and storage areas, and to the clinical files of the study participants, and, if requested, agree to assist the monitors.", "section_id": "master:12.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "monitor_access", "value_name_id": "", "code": false, "id": "chk:1372"}','','[]',7372,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1373','check','','follow_up','','{"kind": "follow_up", "text": "Assist monitors when requested.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "monitor request for assistance", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The SIs will agree to allow monitors access to the clinical supplies, dispensing and storage areas, and to the clinical files of the study participants, and, if requested, agree to assist the monitors.", "section_id": "master:12.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "monitor_assistance_request", "value_name_id": "", "code": false, "id": "chk:1373"}','','[]',7373,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1374','check','','not_checkable','','{"kind": "not_checkable", "text": "Monitors review source documentation, ICFs, and facilities for protocol and regulatory compliance, visit at plan-defined intervals, identify noncompliance, assist with corrective/preventative plans when appropriate, communicate significant noncompliance to the Sponsor, and follow regimen-specific plan appendices.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Study Monitors will visit each study site during the course of the study to review source documentation, ICF, and the clinical facilities to ensure the study is conducted in accordance with the study protocol and compliance with ICH/GP and regulatory guidelines.", "section_id": "master:12.3.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1374"}','','[]',7374,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1375','check','','judgment','','{"kind": "judgment", "text": "Investigators must allow and ensure access to all source documents and medical records related to study participation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "monitor access", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Investigators are responsible for allowing and ensuring access to all source documents and medical records related to the participant''s participation in the study.", "section_id": "master:12.3.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "monitor_access", "value_name_id": "", "code": false, "id": "chk:1375"}','','[]',7375,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1376','check','','not_checkable','','{"kind": "not_checkable", "text": "Study monitors provide monitoring and applicable protocol-compliance reports to the Sponsor and other parties under the Clinical Monitoring Plan.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The Study Monitors will provide monitoring reports to the Sponsor and, if requested, and when required, will provide reports of protocol compliance to the Sponsor and other applicable parties as detailed in the Clinical Monitoring Plan.", "section_id": "master:12.3.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1376"}','','[]',7376,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1377','check','','not_checkable','','{"kind": "not_checkable", "text": "An independent DSMB operates under its Charter, receives periodic blinded/unblinded regimen reports and pooled placebo data, and meets in person or by teleconference. Biostatisticians provide SAE/enrollment summaries. Events of special interest within 24 hours of dosing and severe unexpected SAEs are reported to the DSMB within one business day of CC awareness. The DSMB may request more frequent reports, review abnormalities, recommend modifications/termination, stop unsafe enrollment, and examine increased AE frequency. The CC provides premeeting enrollment, missing-data, and adherence updates and handles DSMB communication.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "AE(s) of Special Interest events occurring within 24 hours of dosing for any given treatment arm, and any severe unexpected serious adverse events for a treatment arm are considered events of interest and will be reported in real-time (within 1 business day of CC awareness) to the DSMB.", "section_id": "master:12.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1377"}','','[]',7377,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1378','check','','judgment','','{"kind": "judgment", "text": "Use the participant''s NeuroGUID or a derivative as the identifier for study samples.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study sample identification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "A participant Neurological Global Unique Identifier (NeuroGUID), or its derivitives'', will be used as the identifier for participant''s samples participating in this study.", "section_id": "master:12.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sample_identification", "value_name_id": "", "code": false, "id": "chk:1378"}','','[]',7378,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1379','check','','not_checkable','','{"kind": "not_checkable", "text": "Describes the 11-character NeuroGUID, licensed encryption, secure website and server generation using identifying elements, lack of identifying-information storage, and deterministic return of the same NeuroGUID for the same inputs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The NeuroGUID is an 11-character string that is generated using encryption technology and algorithms licensed by the NCRI from the NIH in 2013.", "section_id": "master:12.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1379"}','','[]',7379,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1380','check','','judgment','','{"kind": "judgment", "text": "The SI must ensure reported data are accurate, complete, legible, original, and timely.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study data reporting", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The SI is responsible for ensuring the accuracy, completeness, legibility, originality and timeliness of the data reported.", "section_id": "master:12.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "study_data_reporting", "value_name_id": "", "code": false, "id": "chk:1380"}','','[]',7380,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1381','check','','judgment','','{"kind": "judgment", "text": "Complete all source documents neatly and legibly.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "source document completion", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All source documents should be completed in a neat, legible manner to ensure accurate interpretation of data.", "section_id": "master:12.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "source_completion", "value_name_id": "", "code": false, "id": "chk:1381"}','','[]',7381,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1382','check','','judgment','','{"kind": "judgment", "text": "Use dark ink on paper records.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "paper record completion", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Dark ink is required to ensure clarity of reproduced copies.", "section_id": "master:12.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "paper_record_complete", "value_name_id": "", "code": false, "id": "chk:1382"}','','[]',7382,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1383','check','','follow_up','','{"kind": "follow_up", "text": "Cross out the original entry with a single line when correcting a record.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "record correction", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "When making changes or corrections, cross out the original entry with a single line, and initial and date the change.", "section_id": "master:12.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "record_correction", "value_name_id": "", "code": false, "id": "chk:1383"}','','[]',7383,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
