INSERT INTO guide VALUES('NCT05842941','checks','chk:1391','check','','judgment','','{"kind": "judgment", "text": "Ensure source-derived eCRF data are consistent with source documents.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "eCRF data transcription", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "discrepancies are explained", "quote": "Data reported in the eCRF derived from source documents should be consistent with the source documents and discrepancies should be explained", "section_id": "master:12.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ecrf_transcription", "value_name_id": "", "code": false, "id": "chk:1391"}','','[]',7391,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1392','check','','follow_up','','{"kind": "follow_up", "text": "Explain discrepancies between eCRF data and source documents.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "eCRF and source-document discrepancy", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Data reported in the eCRF derived from source documents should be consistent with the source documents and discrepancies should be explained", "section_id": "master:12.6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "ecrf_source_discrepancy", "value_name_id": "", "code": false, "id": "chk:1392"}','','[]',7392,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1393','check','','judgment','','{"kind": "judgment", "text": "Keep participant medical information confidential and do not disclose it to unauthorized third parties.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "participant medical information disclosure", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "authorized disclosures to the parties identified in this section", "quote": "Study participant medical information obtained by this study is confidential, and disclosure to third parties other than those noted below is prohibited.", "section_id": "master:12.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "medical_information_disclosure", "value_name_id": "", "code": false, "id": "chk:1393"}','','[]',7393,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1394','check','','order','','{"kind": "order", "text": "Obtain participant permission before giving medical information to the participant''s personal physician or other appropriate medical personnel responsible for their welfare.", "from_event": "", "to_event": "", "first_event": "participant permission for medical information disclosure", "then_event": "medical information disclosure to participant care personnel", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when disclosing information to participant care personnel", "exception": "", "quote": "Upon the participant''s permission, medical information may be given to his or her personal physician or other appropriate medical personnel responsible for his or her welfare.", "section_id": "master:12.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "disclosure_permission", "then_event_id": "care_team_disclosure", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1394", "implied": true}','','[]',7394,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1395','check','','judgment','','{"kind": "judgment", "text": "Adhere to all local and federal guidelines and regulations for participant data confidentiality.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All local and federal guidelines and regulations regarding maintaining study participant confidentiality of data will be adhered to.", "section_id": "master:12.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1395"}','','[]',7395,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1396','check','','judgment','','{"kind": "judgment", "text": "Make study data available for inspection by FDA, OHRP, Sponsor, pertinent national/local authorities, CC or representatives, study monitors, and siRB.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "study data inspection", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Data generated by this study must be available for inspection by representatives of the US FDA, the Office for Human Research Protections (OHRP), the sponsor, all pertinent national and local health and regulatory authorities, the CC or their representative, Study Monitoring personnel, and the siRB.", "section_id": "master:12.6.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "study_data_inspection", "value_name_id": "", "code": false, "id": "chk:1396"}','','[]',7396,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1397','check','','interval','','{"kind": "interval", "text": "Retain all study-conduct and investigational-drug distribution records, including applicable CRFs, consent forms, laboratory results, and medical inventory records, for at least two years after marketing application approval.", "from_event": "marketing application approval", "to_event": "study record disposal", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "years", "min": 2, "max": null, "applies_when": "when a marketing application is approved", "exception": "", "quote": "US FDA regulations (21 CFR 312.62[c]) require that records and documents pertaining to the conduct of this study and the distribution of investigational drugs, including CRFs (if applicable), consent forms, laboratory test results, and medical inventory records, must be retained by the SI for two years after marketing application approval.", "section_id": "master:12.6.2", "from_event_id": "marketing_approval", "to_event_id": "record_disposal", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1397", "stated": [2, null]}','','[]',7397,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1398','check','','interval','','{"kind": "interval", "text": "If no application is filed, retain records for at least seven years after investigation discontinuation and notification of FDA and applicable national and local health authorities.", "from_event": "investigation discontinued and FDA and applicable health authorities notified", "to_event": "study record disposal", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "years", "min": 7, "max": null, "applies_when": "if no application is filed", "exception": "", "quote": "If no application is filed, these records must be kept for seven years after the investigation is discontinued and the US FDA and the applicable national and local health authorities are notified.", "section_id": "master:12.6.2", "from_event_id": "investigation_stop_notification", "to_event_id": "record_disposal", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1398", "stated": [7, null]}','','[]',7398,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1399','check','','not_checkable','','{"kind": "not_checkable", "text": "The CC or its representative notifies SIs of the events that determine record-retention periods.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The CC or their representative will notify the Sis of these events.", "section_id": "master:12.6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1399"}','','[]',7399,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1400','check','','order','','{"kind": "order", "text": "Retain all study documents and records until written notification from the Sponsor or its representative.", "from_event": "", "to_event": "", "first_event": "written Sponsor or representative notification permitting end of record retention", "then_event": "end of study record retention", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The SIs should retain all study documents and records until they are notified in writing by the Sponsor or their representative.", "section_id": "master:12.6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "retention_end_permission", "then_event_id": "record_retention_end", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1400"}','','[]',7400,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1401','check','','order','','{"kind": "order", "text": "Obtain written Sponsor approval before disposing of any records.", "from_event": "", "to_event": "", "first_event": "written Sponsor approval of record disposal", "then_event": "study record disposal", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "No records may be disposed of without the written approval of the Sponsor.", "section_id": "master:12.6.2", "from_event_id": "", "to_event_id": "", "first_event_id": "sponsor_disposal_approval", "then_event_id": "record_disposal", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1401"}','','[]',7401,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
