INSERT INTO guide VALUES('NCT05842941','checks','chk:1404','check','','not_checkable','','{"kind": "not_checkable", "text": "The Executive Committee governs the Publication Policy for trial and RSA results; its responsibilities are described in the Governance Plan.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The HEALEY ALS Platform Trial Executive Committee will govern the HEALEY ALS Platform Trial Publication Policy, which details the process of publishing of results from the HEALEY ALS Platform Trial and all RSAs.", "section_id": "master:12.7.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1404"}','','[]',7404,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1405','check','','order','','{"kind": "order", "text": "Obtain written agreement from the HEALEY ALS Platform Trial Executive Committee before publishing any trial or RSA data or results.", "from_event": "", "to_event": "", "first_event": "written Executive Committee agreement to publication", "then_event": "publication of trial or RSA data or results", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "No data or results generated from the HEALEY ALS Platform Trial or its RSAs may be published without written agreement from the HEALEY ALS Platform Trial Executive Committee.", "section_id": "master:12.7.1", "from_event_id": "", "to_event_id": "", "first_event_id": "ec_publication_agreement", "then_event_id": "results_publication", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1405"}','','[]',7405,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1406','check','','not_checkable','','{"kind": "not_checkable", "text": "Data and sample sharing policies are specified in trial legal agreements; this section gives no concrete sharing rule.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Data and sample sharing policies will be specified in the legal agreements governing the trial.", "section_id": "master:12.7.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1406"}','','[]',7406,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1407','check','','not_checkable','','{"kind": "not_checkable", "text": "The Master Protocol and every RSA are registered on ClinicalTrials.gov, and results are posted under applicable regulations; these are trial-level administrative responsibilities.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The Master Protocol and each RSA will be registered on www.ClinicalTrials.gov.", "section_id": "master:12.7.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1407"}','','[]',7407,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1408','check','','not_checkable','','{"kind": "not_checkable", "text": "The appendix title, source attribution, Table 1 reference descriptions of regional motor-neuron signs, and appended ALSFRS-R title/version are background or reference material, not independent site requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Information obtained from the web site: www.wfnals.org.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1408"}','','[]',7408,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1409','check','','judgment','','{"kind": "judgment", "text": "An ALS diagnosis requires evidence of LMN degeneration by clinical, electrophysiological, or neuropathologic examination.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnosis", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when diagnosing ALS", "exception": "", "quote": "The diagnosis of Amyotrophic Lateral Sclerosis [ALS] requires:\nA - The presence of:\n(A:1) evidence of lower motor neuron (LMN) degeneration by clinical, electrophysiology cal or neuropathologic examination, (A:2) evidence of upper motor neuron (UMN) degeneration by clinical examination, and (A:3) progressive spread of symptoms or signs within a region or to other regions, as determined by history or examination, together with B - The absence of:\n(B:I) electrophysiological and pathological evidence of other disease processes that might explain the signs of LMN and/or UMN degeneration, and (B:2) neuroimaging evidence of other disease processes that might explain the observed clinical and electrophysiological signs.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_diagnosis", "value_name_id": "", "code": false, "id": "chk:1409"}','','[]',7409,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1410','check','','judgment','','{"kind": "judgment", "text": "An ALS diagnosis requires evidence of UMN degeneration by clinical examination.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnosis", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when diagnosing ALS", "exception": "", "quote": "The diagnosis of Amyotrophic Lateral Sclerosis [ALS] requires:\nA - The presence of:\n(A:1) evidence of lower motor neuron (LMN) degeneration by clinical, electrophysiology cal or neuropathologic examination, (A:2) evidence of upper motor neuron (UMN) degeneration by clinical examination, and (A:3) progressive spread of symptoms or signs within a region or to other regions, as determined by history or examination, together with B - The absence of:\n(B:I) electrophysiological and pathological evidence of other disease processes that might explain the signs of LMN and/or UMN degeneration, and (B:2) neuroimaging evidence of other disease processes that might explain the observed clinical and electrophysiological signs.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_diagnosis", "value_name_id": "", "code": false, "id": "chk:1410"}','','[]',7410,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1411','check','','judgment','','{"kind": "judgment", "text": "An ALS diagnosis requires progressive spread of symptoms or signs within a region or to other regions, established by history or examination.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnosis", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when diagnosing ALS", "exception": "", "quote": "The diagnosis of Amyotrophic Lateral Sclerosis [ALS] requires:\nA - The presence of:\n(A:1) evidence of lower motor neuron (LMN) degeneration by clinical, electrophysiology cal or neuropathologic examination, (A:2) evidence of upper motor neuron (UMN) degeneration by clinical examination, and (A:3) progressive spread of symptoms or signs within a region or to other regions, as determined by history or examination, together with B - The absence of:\n(B:I) electrophysiological and pathological evidence of other disease processes that might explain the signs of LMN and/or UMN degeneration, and (B:2) neuroimaging evidence of other disease processes that might explain the observed clinical and electrophysiological signs.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_diagnosis", "value_name_id": "", "code": false, "id": "chk:1411"}','','[]',7411,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1412','check','','judgment','','{"kind": "judgment", "text": "An ALS diagnosis requires absence of electrophysiological and pathological evidence of other diseases that could explain LMN or UMN degeneration signs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnosis", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when diagnosing ALS", "exception": "", "quote": "The diagnosis of Amyotrophic Lateral Sclerosis [ALS] requires:\nA - The presence of:\n(A:1) evidence of lower motor neuron (LMN) degeneration by clinical, electrophysiology cal or neuropathologic examination, (A:2) evidence of upper motor neuron (UMN) degeneration by clinical examination, and (A:3) progressive spread of symptoms or signs within a region or to other regions, as determined by history or examination, together with B - The absence of:\n(B:I) electrophysiological and pathological evidence of other disease processes that might explain the signs of LMN and/or UMN degeneration, and (B:2) neuroimaging evidence of other disease processes that might explain the observed clinical and electrophysiological signs.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_diagnosis", "value_name_id": "", "code": false, "id": "chk:1412"}','','[]',7412,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1413','check','','judgment','','{"kind": "judgment", "text": "An ALS diagnosis requires absence of neuroimaging evidence of other diseases that could explain the observed clinical and electrophysiological signs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnosis", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when diagnosing ALS", "exception": "", "quote": "The diagnosis of Amyotrophic Lateral Sclerosis [ALS] requires:\nA - The presence of:\n(A:1) evidence of lower motor neuron (LMN) degeneration by clinical, electrophysiology cal or neuropathologic examination, (A:2) evidence of upper motor neuron (UMN) degeneration by clinical examination, and (A:3) progressive spread of symptoms or signs within a region or to other regions, as determined by history or examination, together with B - The absence of:\n(B:I) electrophysiological and pathological evidence of other disease processes that might explain the signs of LMN and/or UMN degeneration, and (B:2) neuroimaging evidence of other disease processes that might explain the observed clinical and electrophysiological signs.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_diagnosis", "value_name_id": "", "code": false, "id": "chk:1413"}','','[]',7413,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1414','check','','judgment','','{"kind": "judgment", "text": "Take a careful history and perform physical and neurological examinations searching for UMN and LMN signs in all four regions: brainstem, cervical, thoracic, and lumbosacral spinal cord.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnostic assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assessing an ALS diagnosis", "exception": "", "quote": "A careful history, physical and neurological examination must search for clinical evidence of UMN and LMN signs in four regions [brainstem, cervical, thoracic, or lumbosacral spinal cord] (see Table 1) of the central nervous system [CNS].", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_diagnostic_assessment", "value_name_id": "", "code": false, "id": "chk:1414"}','','[]',7414,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1415','check','','judgment','','{"kind": "judgment", "text": "Apply ancillary tests reasonably, as clinically indicated, to exclude other disease processes.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnostic assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when ancillary testing is clinically indicated", "exception": "", "quote": "Ancillary tests should be reasonably applied, as clinically indicated, to exclude other disease processes.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_diagnostic_assessment", "value_name_id": "", "code": false, "id": "chk:1415"}','','[]',7415,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1416','check','','judgment','','{"kind": "judgment", "text": "Ancillary testing should include electrodiagnostic, neurophysiological, neuroimaging, and clinical laboratory studies as clinically indicated.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnostic assessment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when ancillary testing is clinically indicated", "exception": "", "quote": "These should include electrodiagnostic, neurophysiological, neuroimaging and clinical laboratory studies.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_diagnostic_assessment", "value_name_id": "", "code": false, "id": "chk:1416"}','','[]',7416,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1417','check','','judgment','','{"kind": "judgment", "text": "Require clinical evidence of both LMN and UMN degeneration for an ALS diagnosis.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnosis", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when diagnosing ALS", "exception": "", "quote": "Clinical evidence of LMN and UMN degeneration is required for the diagnosis of ALS.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_diagnosis", "value_name_id": "", "code": false, "id": "chk:1417"}','','[]',7417,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1418','check','','judgment','','{"kind": "judgment", "text": "If categorizing clinical diagnostic certainty without pathological confirmation, base the category on the regional distribution of UMN and LMN signs in the brainstem, cervical, thoracic, or lumbosacral spinal cord.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnostic classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when categorizing ALS diagnostic certainty without pathological confirmation", "exception": "", "quote": "The clinical diagnosis of ALS, without pathological confirmation, may be categorized into various levels of certainty by clinical assessment alone depending on the presence of UMN and LMN signs together in the same topographical anatomic region in either the brainstem [bulbar cranial motor neurons], cervical, thoracic, or lumbosacral spinal cord [anterior horn motor neurons].", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_classification", "value_name_id": "", "code": false, "id": "chk:1418"}','','[]',7418,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1419','check','','judgment','','{"kind": "judgment", "text": "Classify ALS as Clinically Definite only with clinical evidence of both UMN and LMN signs in three regions.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnostic classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning Clinically Definite ALS", "exception": "", "quote": "A. Clinically Definite ALS is defined on clinical evidence alone by the presence of UMN, as well as LMN signs, in three regions.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_classification", "value_name_id": "", "code": false, "id": "chk:1419"}','','[]',7419,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1420','check','','judgment','','{"kind": "judgment", "text": "Classify ALS as Clinically Probable only with clinical UMN and LMN signs in at least two regions.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnostic classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning Clinically Probable ALS", "exception": "", "quote": "B. Clinically Probable ALS is defined on clinical evidence alone by UMN and LMN signs in at least two regions with some UMN signs necessarily rostral to (above) the LMN signs.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_classification", "value_name_id": "", "code": false, "id": "chk:1420"}','','[]',7420,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1421','check','','judgment','','{"kind": "judgment", "text": "Clinically Probable ALS requires some UMN signs rostral to the LMN signs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnostic classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning Clinically Probable ALS", "exception": "", "quote": "B. Clinically Probable ALS is defined on clinical evidence alone by UMN and LMN signs in at least two regions with some UMN signs necessarily rostral to (above) the LMN signs.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_classification", "value_name_id": "", "code": false, "id": "chk:1421"}','','[]',7421,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1422','check','','judgment','','{"kind": "judgment", "text": "Clinically Probable ALS - Laboratory-supported requires clinical UMN and LMN dysfunction signs in only one region, or UMN signs alone in one region.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnostic classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning Clinically Probable ALS - Laboratory-supported", "exception": "", "quote": "C. Clinically Probable ALS - Laboratory-supported is defined when clinical signs of UMN and LMN dysfunction are in only one region, or when UMN signs alone are present in one region, and LMN signs defined by EMG criteria are present in at least two limbs, with proper application of neuroimaging and clinical laboratory protocols to exclude other causes.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_classification", "value_name_id": "", "code": false, "id": "chk:1422"}','','[]',7422,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1423','check','','judgment','','{"kind": "judgment", "text": "Clinically Probable ALS - Laboratory-supported requires EMG-defined LMN signs in at least two limbs.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnostic classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning Clinically Probable ALS - Laboratory-supported", "exception": "", "quote": "C. Clinically Probable ALS - Laboratory-supported is defined when clinical signs of UMN and LMN dysfunction are in only one region, or when UMN signs alone are present in one region, and LMN signs defined by EMG criteria are present in at least two limbs, with proper application of neuroimaging and clinical laboratory protocols to exclude other causes.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_classification", "value_name_id": "", "code": false, "id": "chk:1423"}','','[]',7423,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1424','check','','judgment','','{"kind": "judgment", "text": "Properly apply neuroimaging and clinical laboratory protocols to exclude other causes before assigning Clinically Probable ALS - Laboratory-supported.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnostic classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning Clinically Probable ALS - Laboratory-supported", "exception": "", "quote": "C. Clinically Probable ALS - Laboratory-supported is defined when clinical signs of UMN and LMN dysfunction are in only one region, or when UMN signs alone are present in one region, and LMN signs defined by EMG criteria are present in at least two limbs, with proper application of neuroimaging and clinical laboratory protocols to exclude other causes.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_classification", "value_name_id": "", "code": false, "id": "chk:1424"}','','[]',7424,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1425','check','','judgment','','{"kind": "judgment", "text": "Assign Clinically Possible ALS only when the stated alternative patterns are satisfied: UMN and LMN dysfunction together in only one region; UMN signs alone in two or more regions; or LMN signs rostral to UMN signs with Clinically Probable -Laboratory-supported ALS not provable using the specified clinical and ancillary evidence.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "ALS diagnostic classification", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning Clinically Possible ALS", "exception": "", "quote": "D. Clinically Possible ALS is defined when clinical signs of UMN and LMN dysfunction are found together in only one region or UMN signs are found alone in two or more regions; or LMN signs are found rostral to UMN signs and the diagnosis of Clinically Probable -Laboratory-supported ALS cannot be proven by evidence on clinical grounds in conjunction with electrodiagnostic, neurophysiologic, neuroimaging or clinical laboratory studies.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "als_classification", "value_name_id": "", "code": false, "id": "chk:1425"}','','[]',7425,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1426','check','','order','','{"kind": "order", "text": "Exclude other diagnoses before accepting a diagnosis of Clinically Possible ALS.", "from_event": "", "to_event": "", "first_event": "exclusion of other diagnoses", "then_event": "acceptance of Clinically Possible ALS diagnosis", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when assigning Clinically Possible ALS", "exception": "", "quote": "Other diagnoses must have been excluded to accept a diagnosis of Clinically Possible ALS.", "section_id": "master:appendix-i-el-escorial-world-federation-", "from_event_id": "", "to_event_id": "", "first_event_id": "other_diagnoses_excluded", "then_event_id": "possible_als_acceptance", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1426", "implied": true}','','[]',7426,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1427','check','','not_checkable','','{"kind": "not_checkable", "text": "The supplied C-SSRS section contains only baseline and since-last-visit appendix titles and source attributions; it supplies no site administration, timing, scoring, or follow-up requirements.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Information obtained from: http://www.cssrs.columbia.edu/", "section_id": "master:appendix-iii-columbia-suicide-severity-r", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1427"}','','[]',7427,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1428','check','','not_checkable','','{"kind": "not_checkable", "text": "References 1\u201323 are bibliographic background citations, not requirements a site can violate.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Natural history of ALS: symptoms, strength, pulmonary function, and disability.", "section_id": "master:references", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1428"}','','[]',7428,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1429','check','','not_checkable','','{"kind": "not_checkable", "text": "Background, manual scope, and ownership statements are not site-deviation rules.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The information contained herein is the property of the Sponsor and Labcorp CLS and may not be reproduced, published, or disclosed to others without written authorization.", "section_id": "site_lab_manual:front", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1429"}','','[]',7429,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1430','check','','not_checkable','','{"kind": "not_checkable", "text": "Contact information and escalation listings are administrative reference only.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Contact: Sponsor / Clinical Contacts | Details: Denali Therapeutics Inc., Clinical Operations Manager, ALS_Platform@denalitherapeutics.com, Phone: +1-650-555-0100", "section_id": "site_lab_manual:1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1430"}','','[]',7430,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1431','check','','follow_up','','{"kind": "follow_up", "text": "Site must contact World Courier to arrange sample pick-up.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "sample pick-up arrangement", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "To arrange sample pick-up, contact World Courier.", "section_id": "site_lab_manual:2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sample_pickup_arrangement", "value_name_id": "", "code": false, "id": "chk:1431"}','','[]',7431,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1432','check','','follow_up','','{"kind": "follow_up", "text": "Site must provide the courier with the site account number, destination, and temperature-handling requirement.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "sample pick-up arrangement", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Please provide the World Courier representative with your specific Site Account Number, the destination (Labcorp Central Laboratory), and specify that the shipment requires Dry Ice (for frozen samples) or Ambient handling.", "section_id": "site_lab_manual:2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sample_pickup_arrangement", "value_name_id": "", "code": false, "id": "chk:1432"}','','[]',7432,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1433','check','','judgment','','{"kind": "judgment", "text": "Frozen specimens should not be shipped on Friday unless the stated exception is met.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "frozen specimen shipment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "Saturday delivery surcharge is pre-approved and dry-ice top-up is guaranteed by the courier.", "quote": "samples should NOT be shipped on Friday unless a Saturday delivery surcharge is pre-approved and dry-ice top-up is guaranteed by the courier.", "section_id": "site_lab_manual:2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "frozen_specimen_shipment", "value_name_id": "", "code": false, "id": "chk:1433"}','','[]',7433,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1434','check','','not_checkable','','{"kind": "not_checkable", "text": "The note that telephone visits require no lab collections is informational only.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Note: Only in-clinic visits are shown; telephone visits (e.g., Wk 2, Wk 12) require no lab collections.", "section_id": "site_lab_manual:3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1434"}','','[]',7434,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
