INSERT INTO guide VALUES('NCT05842941','checks','chk:1452','check','','order','','{"kind": "order", "text": "Blood draws must follow the specified order of draw.", "from_event": "light blue tube draw", "to_event": "gold sst tube draw", "first_event": "light blue tube draw", "then_event": "gold sst tube draw", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Blood must be collected in the sequence: Light Blue \u2192 Gold SST \u2192 Lavender EDTA.", "section_id": "site_lab_manual:5", "from_event_id": "light_blue_tube_draw", "to_event_id": "gold_sst_tube_draw", "first_event_id": "light_blue_tube_draw", "then_event_id": "gold_sst_tube_draw", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1452"}','','[]',7452,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1453','check','','order','','{"kind": "order", "text": "Blood draws must continue in the specified order of draw.", "from_event": "gold sst tube draw", "to_event": "lavender edta tube draw", "first_event": "gold sst tube draw", "then_event": "lavender edta tube draw", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Blood must be collected in the sequence: Light Blue \u2192 Gold SST \u2192 Lavender EDTA.", "section_id": "site_lab_manual:5", "from_event_id": "gold_sst_tube_draw", "to_event_id": "lavender_edta_tube_draw", "first_event_id": "gold_sst_tube_draw", "then_event_id": "lavender_edta_tube_draw", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1453"}','','[]',7453,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1454','check','','judgment','','{"kind": "judgment", "text": "Centrifuges must be programmed using RCF or g and not RPM.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "centrifuge programming", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Always program centrifuges using Relative Centrifugal Force (RCF or g), not RPM.", "section_id": "site_lab_manual:5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "centrifuge_programming", "value_name_id": "", "code": false, "id": "chk:1454"}','','[]',7454,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1455','check','','follow_up','','{"kind": "follow_up", "text": "Light blue tube specimens must be inverted, centrifuged, transferred, and frozen immediately.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "light blue specimen processing", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Invert 3-4x. Centrifuge at 1,500 x g for 15 min at Room Temp (20-25\u00b0C). Transfer plasma to cryovial. Freeze immediately.", "section_id": "site_lab_manual:5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "light_blue_specimen_processing", "value_name_id": "", "code": false, "id": "chk:1455"}','','[]',7455,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1456','check','','follow_up','','{"kind": "follow_up", "text": "Gold SST specimens must be inverted, allowed to clot, centrifuged, and shipped ambient.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "gold sst specimen processing", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Invert 5x. Allow to clot upright for 30 min. Centrifuge at 1,500 - 2,000 x g for 10-15 min at Room Temp. Ship ambient.", "section_id": "site_lab_manual:5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "gold_sst_specimen_processing", "value_name_id": "", "code": false, "id": "chk:1456"}','','[]',7456,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1457','check','','follow_up','','{"kind": "follow_up", "text": "3.0 mL lavender EDTA specimens must be inverted and shipped ambient whole blood on the day of collection without centrifugation.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "lavender edta whole blood specimen processing", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Invert 8-10x. Do Not Centrifuge. Ship as ambient whole blood on day of collection.", "section_id": "site_lab_manual:5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "lavender_edta_whole_blood_specimen_processing", "value_name_id": "", "code": false, "id": "chk:1457"}','','[]',7457,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1458','check','','interval','','{"kind": "interval", "text": "PK plasma and biomarker EDTA specimens must be frozen within 60 minutes after collection processing.", "from_event": "pk plasma sample collection", "to_event": "freeze pk plasma sample", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "minutes", "unit": "minutes", "min": 0, "max": 60, "applies_when": "", "exception": "", "quote": "Freeze at -70\u00b0C within 60 mins.", "section_id": "site_lab_manual:5", "from_event_id": "pk_plasma_sample_collection", "to_event_id": "freeze_pk_plasma_sample", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1458", "stated": [0, 60]}','','[]',7458,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1459','check','','follow_up','','{"kind": "follow_up", "text": "Specialty tubes for genomics/DNA must be inverted, not centrifuged, and frozen immediately at -70\u00b0C.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "specialty tube processing", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Invert 8-10x. Do Not Centrifuge. Freeze immediately at -70\u00b0C.", "section_id": "site_lab_manual:5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "specialty_tube_processing", "value_name_id": "", "code": false, "id": "chk:1459"}','','[]',7459,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1460','check','','not_checkable','','{"kind": "not_checkable", "text": "The blood volume table is a reference summary of estimated collection volumes.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The table below outlines the estimated blood volume drawn for Central Laboratory assessments at each visit, ensuring safety limits are not exceeded.", "section_id": "site_lab_manual:maximum-research-blood-volume-table", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1460"}','','[]',7460,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1461','check','','value','','{"kind": "value", "text": "Clinical chemistry/endocrinology blood volume must not exceed the listed maximum at each visit.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "Clinical Chemistry/Endo (SST) blood volume", "operator": "gt", "limit": 40.5, "limit2": null, "value_unit": "mL", "unit": "", "min": null, "max": null, "applies_when": "at baseline", "exception": "", "quote": "Clinical Chemistry/Endo (SST): Screening 8.5 mL | Baseline 17.0 mL | Wk 4 8.5 mL | Wk 8 8.5 mL | Wk 16 8.5 mL | Wk 24 17.0 mL | ATE Wks (Typical) 8.5 mL", "section_id": "site_lab_manual:maximum-research-blood-volume-table", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "clinical_chemistry_endo_sst_blood_volume", "code": true, "id": "chk:1461", "implied": true}','','[]',7461,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1462','check','','not_checkable','','{"kind": "not_checkable", "text": "Temperature-control packaging choices are operational instructions rather than reportable site rules.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "For Frozen Shipments: Place the sealed bag into the EPS foam insulated thermal box (M9.5).", "section_id": "site_lab_manual:step-3-temperature-control-thermal-box-d", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1462"}','','[]',7462,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1463','check','','not_checkable','','{"kind": "not_checkable", "text": "Mandatory documentation list is reference information; only the specific documentary requirements below are checkable.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Each shipment tendered to the courier must be accompanied by the following documentation:", "section_id": "site_lab_manual:mandatory-documentation", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1463"}','','[]',7463,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1464','check','','follow_up','','{"kind": "follow_up", "text": "A completed sample requisition form must be placed inside the shipping container but outside the sealed biohazard bag, and a photocopy retained in the subject''s chart.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "sample requisition form handling", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Place the completed Requisition Form inside the shipping container, but outside the sealed biohazard bag. Retain a photocopy for the subject''s chart.", "section_id": "site_lab_manual:mandatory-documentation", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "sample_requisition_form_handling", "value_name_id": "", "code": false, "id": "chk:1464"}','','[]',7464,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1465','check','','follow_up','','{"kind": "follow_up", "text": "International shipments must include the customs invoice printed on hospital/institution letterhead and signed.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "customs invoice preparation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for international shipments", "exception": "", "quote": "Print the Customs Invoice (Appendix 3) on your hospital/institution letterhead and sign it.", "section_id": "site_lab_manual:mandatory-documentation", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "customs_invoice_preparation", "value_name_id": "", "code": false, "id": "chk:1465"}','','[]',7465,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1466','check','','follow_up','','{"kind": "follow_up", "text": "Shipments crossing international borders into the United States must include the customs invoice/USDA statement in triplicate.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "customs invoice and USDA statement inclusion", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for shipments crossing international borders into the United States", "exception": "", "quote": "This document must be printed on your hospital''s letterhead paper, signed, and included in triplicate for any shipments crossing international borders into the United States.", "section_id": "site_lab_manual:appendix-3-customs-invoice-usda-statemen", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "customs_invoice_usda_statement_inclusion", "value_name_id": "", "code": false, "id": "chk:1466"}','','[]',7466,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1467','check','','not_checkable','','{"kind": "not_checkable", "text": "Investigational Product & Pharmacy Handling Manual", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "This manual provides detailed instructions for the Investigational Drug Service (IDS) and clinical site staff regarding the receipt, storage, preparation, dispensing, and accountability of the Investigational Medicinal Product (IMP) for Regimen G of the HEALEY ALS Platform Trial.", "section_id": "site_pharmacy_manual:front", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1467"}','','[]',7467,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1468','check','','not_checkable','','{"kind": "not_checkable", "text": "Study directory and general information are descriptive only.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Table columns: Item | Details", "section_id": "site_pharmacy_manual:1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1468"}','','[]',7468,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1469','check','','not_checkable','','{"kind": "not_checkable", "text": "The double-blind, placebo-controlled design and open-label extension description are background information.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Regimen G utilizes a double-blind, placebo-controlled design for the initial 24-week period, followed by an open-label Active Treatment Extension (ATE) period where all subjects receive active DNL343.", "section_id": "site_pharmacy_manual:2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1469"}','','[]',7469,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1470','check','','not_checkable','','{"kind": "not_checkable", "text": "Shipping descriptions are background information.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "IMP is shipped via validated temperature-controlled couriers from the CDMO regional depots.", "section_id": "site_pharmacy_manual:3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1470"}','','[]',7470,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1471','check','','follow_up','','{"kind": "follow_up", "text": "Upon arrival, inspect the outer shipping container for physical damage.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "shipment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Upon arrival, immediately inspect the outer shipping container for physical damage.", "section_id": "site_pharmacy_manual:3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "shipment", "value_name_id": "", "code": false, "id": "chk:1471"}','','[]',7471,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1472','check','','follow_up','','{"kind": "follow_up", "text": "Stop the TempTale device after shipment arrival.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "TempTale device", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Press and hold the \"STOP\" button on the TempTale device for 3-5 seconds until the stop icon appears.", "section_id": "site_pharmacy_manual:3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "temptale_device", "value_name_id": "", "code": false, "id": "chk:1472"}','','[]',7472,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
