INSERT INTO guide VALUES('NCT05842941','checks','chk:1475','check','','follow_up','','{"kind": "follow_up", "text": "If a temperature alarm is triggered, isolate the affected kits in the pharmacy under appropriate storage conditions.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "affected kits", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if TempTale triggered a temperature alarm", "exception": "", "quote": "Immediately isolate the affected kits in the pharmacy under appropriate storage conditions.", "section_id": "site_pharmacy_manual:3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "affected_kits", "value_name_id": "", "code": false, "id": "chk:1475"}','','[]',7475,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1476','check','','follow_up','','{"kind": "follow_up", "text": "If a temperature alarm is triggered, mark the affected kits as quarantined in the IRT.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "affected kits", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if TempTale triggered a temperature alarm", "exception": "", "quote": "Mark them as \"Quarantined\" in the IRT and email the PDF report to the CDMO Supply Chain Manager for disposition.", "section_id": "site_pharmacy_manual:3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "affected_kits", "value_name_id": "", "code": false, "id": "chk:1476"}','','[]',7476,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
