INSERT INTO guide VALUES('NCT05842941','checks','chk:1478','check','','follow_up','','{"kind": "follow_up", "text": "If a temperature alarm is triggered, do not dispense the affected kits.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "affected kits", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if TempTale triggered a temperature alarm", "exception": "", "quote": "Do NOT dispense.", "section_id": "site_pharmacy_manual:3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "affected_kits", "value_name_id": "", "code": false, "id": "chk:1478"}','','[]',7478,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1479','check','','follow_up','','{"kind": "follow_up", "text": "Register shipment receipt in the IRT and confirm receipt of all physical kit numbers.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "shipment", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Enter the shipment number and confirm receipt of all physical kit numbers.", "section_id": "site_pharmacy_manual:3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "shipment", "value_name_id": "", "code": false, "id": "chk:1479"}','','[]',7479,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1480','check','','not_checkable','','{"kind": "not_checkable", "text": "Blinding maintenance instructions are background and administrative.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "During the 24-week placebo-controlled phase, the active and placebo stick packs are visually indistinguishable.", "section_id": "site_pharmacy_manual:critical-blinding-maintenance", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1480"}','','[]',7480,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1481','check','','not_checkable','','{"kind": "not_checkable", "text": "Storage conditions are stated as requirements, but the exact operational alarm handling details beyond the temperature threshold are not further broken out here.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Storage Conditions: Both DNL343 and Placebo must be stored at Controlled Room Temperature (below 30\u00b0C / 86\u00b0F).", "section_id": "site_pharmacy_manual:4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1481"}','','[]',7481,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1482','check','','value','','{"kind": "value", "text": "Stored IMP temperature must be below 30\u00b0C / 86\u00b0F.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "storage temperature", "operator": "ge", "limit": 30, "limit2": null, "value_unit": "degrees C", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Both DNL343 and Placebo must be stored at Controlled Room Temperature (below 30\u00b0C / 86\u00b0F).", "section_id": "site_pharmacy_manual:4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "storage_temperature", "code": true, "id": "chk:1482"}','','[]',7482,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1483','check','','follow_up','','{"kind": "follow_up", "text": "Protect IMP from extreme heat and moisture.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "IMP", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Protect from extreme heat and moisture.", "section_id": "site_pharmacy_manual:4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "imp", "value_name_id": "", "code": false, "id": "chk:1483"}','','[]',7483,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1484','check','','value','','{"kind": "value", "text": "Kits must be stored in a secure, limited-access area.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "kits", "value_name": "storage access", "operator": "outside", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Kits must be stored in a secure, limited-access area (e.g., locked pharmacy) in accordance with ICH-GCP.", "section_id": "site_pharmacy_manual:4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "kits", "value_name_id": "storage_access", "code": false, "id": "chk:1484"}','','[]',7484,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1485','check','','follow_up','','{"kind": "follow_up", "text": "If pharmacy temperature exceeds 30\u00b0C, move the IMP to an alternate compliant storage location if the primary area cannot be rapidly corrected.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "IMP", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if the pharmacy environmental monitoring system detects a temperature > 30\u00b0C", "exception": "", "quote": "Move the IMP to an alternate compliant storage location if the primary area cannot be rapidly corrected.", "section_id": "site_pharmacy_manual:4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "imp", "value_name_id": "", "code": false, "id": "chk:1485"}','','[]',7485,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
