INSERT INTO guide VALUES('NCT05842941','checks','chk:1490','check','','interval','','{"kind": "interval", "text": "Once the stick pack is opened and mixed, administer the dose within 15 minutes.", "from_event": "stick pack opened and granules mixed", "to_event": "study drug dose", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "minutes", "min": 0, "max": 15, "applies_when": "", "exception": "", "quote": "Once the stick pack is opened and the granules are mixed with water or soft food, the dose MUST be administered within 15 minutes.", "section_id": "site_pharmacy_manual:5", "from_event_id": "stick_pack_opening_and_granules_mixing", "to_event_id": "study_drug_dose", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1490", "stated": [0, 15]}','','[]',7490,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1491','check','','interval','','{"kind": "interval", "text": "A prepared soft-food dose must be consumed within 15 minutes.", "from_event": "prepared dose", "to_event": "study drug dose", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "minutes", "min": 0, "max": 15, "applies_when": "for soft food administration", "exception": "", "quote": "The subject must consume the entire portion of the mixture immediately (within 15 minutes).", "section_id": "site_pharmacy_manual:method-b-preparation-in-soft-food-oral-a", "from_event_id": "prepared_dose", "to_event_id": "study_drug_dose", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1491", "implied": true, "stated": [0, 15]}','','[]',7491,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
