INSERT INTO guide VALUES('NCT05842941','checks','chk:1502','check','','follow_up','','{"kind": "follow_up", "text": "The dispensing label must include the instruction to take 2 stick packs once daily and store below 30\u00b0C.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "dispensing label", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The label must not obscure the original clinical label and must include: Subject ID Number; Protocol Number (NCT05842941); Date Dispensed & Dispenser Initials; Instructions: \"Take 2 stick packs once daily. Store below 30\u00b0C.\"", "section_id": "site_pharmacy_manual:dispensing-to-subjects-for-home-use", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "dispensing_label", "value_name_id": "", "code": false, "id": "chk:1502"}','','[]',7502,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1503','check','','follow_up','','{"kind": "follow_up", "text": "Provide the subject or caregiver with training on the preparation methods and the 15-minute post-mixing administration window.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "subject or caregiver", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Provide the subject/caregiver with thorough training on the preparation methods (Water or Soft Food) and emphasize the 15-minute post-mixing administration window.", "section_id": "site_pharmacy_manual:dispensing-to-subjects-for-home-use", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "subject_or_caregiver", "value_name_id": "", "code": false, "id": "chk:1503"}','','[]',7503,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1504','check','','not_checkable','','{"kind": "not_checkable", "text": "In-clinic administration instructions are operational guidance.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "For visits requiring in-clinic dosing (e.g., Baseline, Week 4, Week 24 PK sampling):", "section_id": "site_pharmacy_manual:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1504"}','','[]',7504,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1505','check','','follow_up','','{"kind": "follow_up", "text": "Before opening the stick packs, ensure the subject is ready to receive the dose.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "subject", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for in-clinic dosing", "exception": "", "quote": "Ensure the subject is ready to receive the dose before opening the stick packs, due to the strict 15-minute stability window.", "section_id": "site_pharmacy_manual:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "subject", "value_name_id": "", "code": false, "id": "chk:1505"}','','[]',7505,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1506','check','','follow_up','','{"kind": "follow_up", "text": "If administering via an enteral feeding tube, flush the administration cup or syringe with additional water and flush the tube to ensure the full dose is delivered and the tube remains patent.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "tube administration", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if administering via an enteral feeding tube", "exception": "", "quote": "If administering via an enteral feeding tube, flush the administration cup/syringe with an additional 15\u201330 mL of water, draw it up, and flush the tube to ensure 100% of the dose is delivered and the tube remains patent.", "section_id": "site_pharmacy_manual:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "tube_administration", "value_name_id": "", "code": false, "id": "chk:1506"}','','[]',7506,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1507','check','','follow_up','','{"kind": "follow_up", "text": "If administered orally via cup, rinse the cup with a small amount of water and have the subject drink it to avoid residual granules.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "oral cup administration", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if administered orally via cup", "exception": "", "quote": "If administered orally via cup, add a small amount of water to the empty cup, swirl, and have the subject drink it to ensure no residual granules are left behind.", "section_id": "site_pharmacy_manual:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "oral_cup_administration", "value_name_id": "", "code": false, "id": "chk:1507"}','','[]',7507,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1508','check','','not_checkable','','{"kind": "not_checkable", "text": "Accountability and reconciliation background states responsibility under ICH-GCP.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Under ICH-GCP, the Investigator is responsible for ensuring that all IMP is adequately accounted for throughout the trial.", "section_id": "site_pharmacy_manual:7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1508"}','','[]',7508,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1509','check','','follow_up','','{"kind": "follow_up", "text": "The pharmacy must maintain a master drug accountability log tracking receipt, overall inventory, and final disposition of all cartons.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "cartons", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The Pharmacy must maintain a master log tracking the receipt, overall inventory, and final disposition of all cartons.", "section_id": "site_pharmacy_manual:7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "cartons", "value_name_id": "", "code": false, "id": "chk:1509"}','','[]',7509,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1510','check','','follow_up','','{"kind": "follow_up", "text": "Maintain a subject-specific dispensing log tracking the exact dates and kit numbers dispensed to and returned by each subject.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "subject", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Maintain a subject-specific log tracking the exact dates and kit numbers dispensed to, and returned by, each subject.", "section_id": "site_pharmacy_manual:7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "subject", "value_name_id": "", "code": false, "id": "chk:1510"}','','[]',7510,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1511','check','','follow_up','','{"kind": "follow_up", "text": "Subjects must return all unused stick packs, empty cartons, and empty stick pack wrappers to every clinic visit.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "clinic visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Instruct subjects to return all unused stick packs, as well as all empty cartons and empty stick pack wrappers, to every clinic visit.", "section_id": "site_pharmacy_manual:7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "clinic_visit", "value_name_id": "", "code": false, "id": "chk:1511"}','','[]',7511,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1512','check','','follow_up','','{"kind": "follow_up", "text": "Count returned intact packets and wrappers to calculate dosing compliance and record the result in the subject''s eCRF and DAL.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "returned intact packets and wrappers", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Site staff must count the returned intact packets and wrappers to calculate dosing compliance and record this in the subject''s eCRF and DAL.", "section_id": "site_pharmacy_manual:7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "returned_intact_packets_and_wrappers", "value_name_id": "", "code": false, "id": "chk:1512"}','','[]',7512,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1513','check','','follow_up','','{"kind": "follow_up", "text": "Unused, expired, or quarantined kits must be returned to the CDMO depot using the pre-supplied return shipping materials after IRT return authorization.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "unused, expired, or quarantined kits", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Unused, expired, or quarantined kits must be returned to the CDMO depot (Fisher Clinical Services) using the pre-supplied return shipping materials, following IRT return authorization.", "section_id": "site_pharmacy_manual:7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "unused_expired_or_quarantined_kits", "value_name_id": "", "code": false, "id": "chk:1513"}','','[]',7513,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
