INSERT INTO guide VALUES('NCT05842941','checks','chk:1516','check','','order','','{"kind": "order", "text": "Before the Regimen G study link becomes active on your dashboard, you must complete the assigned Medidata eLearning modules (e.g., Rave EDC Data Entry, Rave EDC PI Signature).", "from_event": "", "to_event": "", "first_event": "assigned Medidata eLearning modules", "then_event": "Regimen G study link becomes active", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Before the Regimen G study link becomes active on your dashboard, you must complete the assigned Medidata eLearning modules (e.g., Rave EDC Data Entry, Rave EDC PI Signature).", "section_id": "site_edc_guide:2", "from_event_id": "", "to_event_id": "", "first_event_id": "assigned_medidata_elearning_modules", "then_event_id": "regimen_g_study_link_activation", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1516"}','','[]',7516,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
