INSERT INTO guide VALUES('NCT05842941','checks','chk:1526','check','','not_checkable','','{"kind": "not_checkable", "text": "Once a subject is screened and randomized via the study''s IRT/IWRS system, the integration automatically pushes the Subject ID into Rave and generates the initial Subject Matrix.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Once a subject is screened and randomized via the study''s IRT/IWRS system, the integration automatically pushes the Subject ID into Rave and generates the initial Subject Matrix.", "section_id": "site_edc_guide:4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1526"}','','[]',7526,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1527','check','','follow_up','','{"kind": "follow_up", "text": "If a subject is re-consented (e.g., transition to the ATE period or protocol amendment), record this on the Informed Consent log form by clicking Add a new Log line.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "re-consent on the Informed Consent log form", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a subject is re-consented", "exception": "", "quote": "If a subject is re-consented (e.g., transition to the ATE period or protocol amendment), record this on the Informed Consent log form by clicking Add a new Log line.", "section_id": "site_edc_guide:informed-consent-eligibility", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "reconsent_informed_consent_log", "value_name_id": "", "code": false, "id": "chk:1527"}','','[]',7527,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1528','check','','follow_up','','{"kind": "follow_up", "text": "If \"Not Met\" is selected for any criterion, the system will fire a hard edit check requiring the selection of a specific failure reason.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "selection of a specific failure reason", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if \"Not Met\" is selected for any criterion", "exception": "", "quote": "If \"Not Met\" is selected for any criterion, the system will fire a hard edit check requiring the selection of a specific failure reason.", "section_id": "site_edc_guide:informed-consent-eligibility", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "failure_reason_selection", "value_name_id": "", "code": false, "id": "chk:1528"}','','[]',7528,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1529','check','','value','','{"kind": "value", "text": "The protocol permits a dose reduction to 100 mg due to intolerability.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "Planned Dose Level", "operator": "lt", "limit": 200, "limit2": null, "value_unit": "mg", "unit": "", "min": null, "max": null, "applies_when": "if the dose is adjusted", "exception": "", "quote": "The protocol permits a dose reduction to 100 mg due to intolerability.", "section_id": "site_edc_guide:drug-administration-pk-reconciliation", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "planned_dose_level", "code": true, "id": "chk:1529", "implied": false}','','[]',7529,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
