INSERT INTO guide VALUES('NCT05842941','checks','chk:1561','check','','follow_up','','{"kind": "follow_up", "text": "Check the authorization acknowledgment box at the bottom of the page, enter your Medidata login password, and click Sign.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "check the authorization acknowledgment box; enter password; click Sign", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "for PI signing", "exception": "", "quote": "Check the authorization acknowledgment box at the bottom of the page, enter your Medidata login password, and click Sign.", "section_id": "site_edc_guide:7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "authorization_acknowledgment_signature", "value_name_id": "", "code": false, "id": "chk:1561"}','','[]',7561,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1562','check','','order','','{"kind": "order", "text": "If a CRC or CRA modifies a single data point or responds to a query on a form that has already been signed, the signature is immediately broken.", "from_event": "CRC or CRA modifies a single data point or responds to a query on a signed form", "to_event": "signature is broken", "first_event": "CRC or CRA modifies a single data point or responds to a query on a signed form", "then_event": "signature is broken", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a signed form is modified or a query is answered", "exception": "", "quote": "If a CRC or CRA modifies a single data point or responds to a query on a form that has already been signed, the signature is immediately broken.", "section_id": "site_edc_guide:7", "from_event_id": "signed_form_query_response", "to_event_id": "signature_broken", "first_event_id": "signed_form_query_response", "then_event_id": "signature_broken", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1562", "implied": true}','','[]',7562,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1563','check','','follow_up','','{"kind": "follow_up", "text": "The frozen/padlock icon will lift, and the form will revert to \"Requires Signature\" status, requiring the PI to re-sign the updated form.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "PI to re-sign the updated form", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a signed form is modified or a query is answered", "exception": "", "quote": "The frozen/padlock icon will lift, and the form will revert to \"Requires Signature\" status, requiring the PI to re-sign the updated form.", "section_id": "site_edc_guide:7", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "pir_to_resign_updated_form", "value_name_id": "", "code": false, "id": "chk:1563"}','','[]',7563,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
