INSERT INTO guide VALUES('NCT05842941','checks','chk:1571','check','','follow_up','','{"kind": "follow_up", "text": "Look for the checkbox next to the field typically labeled \"ND\" (Not Done) or \"UNK\" (Unknown).", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "use the checkbox labeled \"ND\" (Not Done) or \"UNK\" (Unknown)", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a lab parameter was not done and the field only accepts numeric values", "exception": "", "quote": "Look for the checkbox next to the field typically labeled \"ND\" (Not Done) or \"UNK\" (Unknown).", "section_id": "site_edc_guide:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "nd_or_unk_checkbox_selection", "value_name_id": "", "code": false, "id": "chk:1571"}','','[]',7571,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1572','check','','follow_up','','{"kind": "follow_up", "text": "Checking this box overrides the numeric requirement and resolves the system query.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "resolve the system query", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if the ND/UNK checkbox is checked", "exception": "", "quote": "Checking this box overrides the numeric requirement and resolves the system query.", "section_id": "site_edc_guide:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "system_query_resolution", "value_name_id": "", "code": false, "id": "chk:1572"}','','[]',7572,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1573','check','','follow_up','','{"kind": "follow_up", "text": "If you discover a critical source data error on a locked form, you must contact the Lead Data Manager to request the form be temporarily unlocked.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "contact the Lead Data Manager to request the form be temporarily unlocked", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a critical source data error is discovered on a locked form", "exception": "", "quote": "If you discover a critical source data error on a locked form, you must contact the Lead Data Manager to request the form be temporarily unlocked.", "section_id": "site_edc_guide:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "data_manager_unlock_request", "value_name_id": "", "code": false, "id": "chk:1573"}','','[]',7573,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1574','check','','follow_up','','{"kind": "follow_up", "text": "You must complete the End of Treatment form, the End of Study / Early Termination form (selecting \"Withdrawal of Consent\" as the primary reason), and ensure all Adverse Events have End Dates or are explicitly marked as \"Ongoing at Study Exit.\"", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "complete the End of Treatment form; complete the End of Study / Early Termination form; ensure all Adverse Events have End Dates or are marked \"Ongoing at Study Exit\"", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if the patient withdrew consent during the Active Treatment Extension (ATE)", "exception": "", "quote": "You must complete the End of Treatment form, the End of Study / Early Termination form (selecting \"Withdrawal of Consent\" as the primary reason), and ensure all Adverse Events have End Dates or are explicitly marked as \"Ongoing at Study Exit.\"", "section_id": "site_edc_guide:8", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "study_closeout_form_completion", "value_name_id": "", "code": false, "id": "chk:1574"}','','[]',7574,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1575','check','','not_checkable','','{"kind": "not_checkable", "text": "Study directory, blinding architecture, study drug description, and contact information are administrative/background information and are not monitor-checkable site behavior rules.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Protocol Number: NCT05842941 (Master & Regimen G Appendix)", "section_id": "site_irt_guide:1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1575"}','','[]',7575,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1576','check','','not_checkable','','{"kind": "not_checkable", "text": "System access roles, Part 11 signature mechanics, dashboard descriptions, and general navigation guidance are operational background rather than site compliance rules.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "All critical transactions in Suvoda require 21 CFR Part 11 Electronic Signatures, meaning you must re-enter your username and password to finalize Randomization, Dispensing, or Unblinding actions.", "section_id": "site_irt_guide:2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1576"}','','[]',7576,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1577','check','','order','','{"kind": "order", "text": "The subject must sign the Master and Regimen-Specific Informed Consent Forms before being registered in Suvoda.", "from_event": "", "to_event": "", "first_event": "informed consent", "then_event": "screening visit", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "To register a subject who has signed the Master and Regimen-Specific Informed Consent Forms:", "section_id": "site_irt_guide:3.1", "from_event_id": "", "to_event_id": "", "first_event_id": "informed_consent", "then_event_id": "screening", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1577"}','','[]',7577,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1578','check','','follow_up','','{"kind": "follow_up", "text": "The site must print or save the automated Screening Confirmation PDF for source records after subject registration.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "screening visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Print or save the automated Screening Confirmation PDF for your source records.", "section_id": "site_irt_guide:3.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "screening", "value_name_id": "", "code": false, "id": "chk:1578"}','','[]',7578,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1579','check','','follow_up','','{"kind": "follow_up", "text": "The site must verify stratification data in the EDC before executing IRT randomization.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "randomization", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Ensure this data is verified in the EDC prior to executing IRT randomization.", "section_id": "site_irt_guide:3.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "randomization", "value_name_id": "", "code": false, "id": "chk:1579"}','','[]',7579,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1580','check','','follow_up','','{"kind": "follow_up", "text": "The site must obtain and enter the required stratification variables and subject weight during randomization.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "randomization", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Enter the required Stratification variables and the Subject Weight (kg).", "section_id": "site_irt_guide:3.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "randomization", "value_name_id": "", "code": false, "id": "chk:1580"}','','[]',7580,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1581','check','','follow_up','','{"kind": "follow_up", "text": "The site must authenticate the randomization transaction with the Suvoda username and password.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "randomization", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Enter your Suvoda username and password to authenticate the randomization transaction.", "section_id": "site_irt_guide:3.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "randomization", "value_name_id": "", "code": false, "id": "chk:1581"}','','[]',7581,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1582','check','','follow_up','','{"kind": "follow_up", "text": "The site must retrieve the exact assigned cartons from the pharmacy and file the Dispensation Confirmation PDF in the subject binder.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "randomization", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Retrieve the exact assigned cartons from the pharmacy. Print the Dispensation Confirmation PDF and file it in the subject binder.", "section_id": "site_irt_guide:3.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "randomization", "value_name_id": "", "code": false, "id": "chk:1582"}','','[]',7582,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1583','check','','follow_up','','{"kind": "follow_up", "text": "At scheduled dispensation visits, the subject must return unused drug and receive new supply.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "scheduled dispensation visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "At subsequent in-clinic visits, the subject will return unused drug and receive new supply.", "section_id": "site_irt_guide:3.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "scheduled_dispensation_visit", "value_name_id": "", "code": false, "id": "chk:1583"}','','[]',7583,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1584','check','','not_checkable','','{"kind": "not_checkable", "text": "Telephone visits at Weeks 2, 12, and 20 do not require IRT dispensation; this is visit-design guidance rather than an actionable site compliance rule.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Telephone visits at Weeks 2, 12, and 20 do not require IRT dispensation).", "section_id": "site_irt_guide:3.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1584"}','','[]',7584,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1585','check','','judgment','','{"kind": "judgment", "text": "The dose-reduction question must be answered based on whether the subject is experiencing a dose-limiting toxicity requiring dose reduction.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "scheduled dispensation visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Is the subject experiencing a dose-limiting toxicity requiring a dose reduction?", "section_id": "site_irt_guide:3.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "scheduled_dispensation_visit", "value_name_id": "", "code": false, "id": "chk:1585"}','','[]',7585,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1586','check','','follow_up','','{"kind": "follow_up", "text": "If dose reduction is needed, the site must ensure the system logs the dose reduction to 100 mg QD and adjusts resupply algorithms accordingly.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "scheduled dispensation visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if the subject is experiencing a dose-limiting toxicity requiring a dose reduction", "exception": "", "quote": "If Yes, the system logs the dose reduction to 100 mg QD and adjusts resupply algorithms accordingly.", "section_id": "site_irt_guide:3.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "scheduled_dispensation_visit", "value_name_id": "", "code": false, "id": "chk:1586"}','','[]',7586,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1587','check','','follow_up','','{"kind": "follow_up", "text": "The site must authenticate with the password and dispense the newly assigned kit numbers at scheduled dispensation visits.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "scheduled dispensation visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Authenticate with your password and dispense the newly assigned Kit Numbers.", "section_id": "site_irt_guide:3.3", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "scheduled_dispensation_visit", "value_name_id": "", "code": false, "id": "chk:1587"}','','[]',7587,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1588','check','','order','','{"kind": "order", "text": "The Week 24 visit must be completed before the subject transitions to the open-label ATE period.", "from_event": "", "to_event": "", "first_event": "week 24 visit", "then_event": "ate period", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "At the Week 24 Visit, the subject completes the double-blind period and transitions to the Open-Label ATE period", "section_id": "site_irt_guide:3.4", "from_event_id": "", "to_event_id": "", "first_event_id": "w24_visit", "then_event_id": "ate_period", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1588"}','','[]',7588,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1589','check','','follow_up','','{"kind": "follow_up", "text": "The site must execute the Week 24 end-of-double-blind/start-of-ATE visit in Suvoda.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "week 24 visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Select the Subject ID and execute the Week 24 (End of Double-Blind / Start of ATE) visit.", "section_id": "site_irt_guide:3.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "w24_visit", "value_name_id": "", "code": false, "id": "chk:1589"}','','[]',7589,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1590','check','','follow_up','','{"kind": "follow_up", "text": "The site must authenticate and confirm the Week 24 transition so Suvoda assigns open-label ATE kits.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "week 24 visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Authenticate and Confirm. Suvoda will assign Open-Label ATE Kits.", "section_id": "site_irt_guide:3.4", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "w24_visit", "value_name_id": "", "code": false, "id": "chk:1590"}','','[]',7590,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1591','check','','order','','{"kind": "order", "text": "The site must not dispense leftover double-blind kits after the subject enters the ATE period.", "from_event": "double-blind kit dispensing", "to_event": "ate period", "first_event": "double-blind kit dispensing", "then_event": "ate period", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "when the subject is entering the ATE period", "exception": "", "quote": "Do not dispense any leftover double-blind kits to a subject entering the ATE period.", "section_id": "site_irt_guide:3.4", "from_event_id": "double_blind_kit_dispensing", "to_event_id": "ate_period", "first_event_id": "double_blind_kit_dispensing", "then_event_id": "ate_period", "event_id": "", "value_name_id": "", "code": true, "id": "chk:1591", "implied": false}','','[]',7591,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1592','check','','follow_up','','{"kind": "follow_up", "text": "If a subject permanently discontinues study drug or completes the trial, the site must discontinue the subject in Suvoda and enter the discontinuation date and primary reason.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "subject discontinuation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a subject permanently discontinues study drug or completes the trial", "exception": "", "quote": "Enter the Date of Discontinuation and select the primary reason (e.g., Adverse Event, Withdrawal by Subject).", "section_id": "site_irt_guide:3.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "subject_discontinuation", "value_name_id": "", "code": false, "id": "chk:1592"}','','[]',7592,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1593','check','','follow_up','','{"kind": "follow_up", "text": "Discontinuing the subject must stop all future automated resupply shipments for that subject.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "subject discontinuation", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a subject permanently discontinues study drug or completes the trial", "exception": "", "quote": "This stops all future automated resupply shipments for this subject.", "section_id": "site_irt_guide:3.5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "subject_discontinuation", "value_name_id": "", "code": false, "id": "chk:1593"}','','[]',7593,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1594','check','','follow_up','','{"kind": "follow_up", "text": "When a shipment arrives, the site must stop the TempTale monitor and download the PDF data.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "shipment receipt", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Stop the TempTale monitor included in the physical shipment and download the PDF data.", "section_id": "site_irt_guide:4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "shipment_receipt", "value_name_id": "", "code": false, "id": "chk:1594"}','','[]',7594,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
