INSERT INTO guide VALUES('NCT05842941','checks','chk:1596','check','','judgment','','{"kind": "judgment", "text": "The site must determine whether there were any temperature excursions upon shipment receipt.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "shipment receipt", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Were there any temperature excursions?", "section_id": "site_irt_guide:4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "shipment_receipt", "value_name_id": "", "code": false, "id": "chk:1596"}','','[]',7596,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1597','check','','follow_up','','{"kind": "follow_up", "text": "If there are no temperature excursions, all kits must be moved to Available status.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "shipment receipt", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if there are no temperature excursions", "exception": "", "quote": "If No, all kits are moved to Available status.", "section_id": "site_irt_guide:4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "shipment_receipt", "value_name_id": "", "code": false, "id": "chk:1597"}','','[]',7597,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1598','check','','follow_up','','{"kind": "follow_up", "text": "If there are temperature excursions, the entire shipment must be placed in Quarantined status and the site must physically quarantine the drug and email the TempTale PDF to the CDMO for disposition.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "shipment receipt", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if there are temperature excursions", "exception": "", "quote": "If Yes, the entire shipment is placed in Quarantined status. You must physically quarantine the drug and email the TempTale PDF to the CDMO for disposition.", "section_id": "site_irt_guide:4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "shipment_receipt", "value_name_id": "", "code": false, "id": "chk:1598"}','','[]',7598,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1599','check','','follow_up','','{"kind": "follow_up", "text": "If a physically damaged kit is found, the site must receive the shipment without an excursion and immediately mark the damaged kit as Damaged in Inventory.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "damaged kit found", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a physically damaged kit is found", "exception": "", "quote": "receive the shipment without an excursion, but immediately navigate to the Inventory tab, select the damaged Kit Number, and change its status from Available to Damaged.", "section_id": "site_irt_guide:4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "damaged_kit_found", "value_name_id": "", "code": false, "id": "chk:1599"}','','[]',7599,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1600','check','','follow_up','','{"kind": "follow_up", "text": "If a shipment is damaged, the site must notify that Suvoda will automatically trigger a replacement shipment if the site''s buffer falls below the required threshold.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "damaged kit found", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a physically damaged kit is found", "exception": "", "quote": "Suvoda will automatically trigger a replacement shipment if your site''s buffer falls below the required threshold.", "section_id": "site_irt_guide:4.1", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "damaged_kit_found", "value_name_id": "", "code": false, "id": "chk:1600"}','','[]',7600,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
