INSERT INTO guide VALUES('NCT05842941','checks','chk:1604','check','','follow_up','','{"kind": "follow_up", "text": "The site must ensure the kit status is updated to Returned for complete lifecycle tracking.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "drug return", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "The system updates the kit status to Returned, ensuring complete lifecycle tracking for the Sponsor.", "section_id": "site_irt_guide:4.2", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "drug_return", "value_name_id": "", "code": false, "id": "chk:1604"}','','[]',7604,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1605','check','','judgment','','{"kind": "judgment", "text": "Emergency unblinding may be performed only when knowledge of treatment assignment is absolutely necessary for immediate medical management.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "emergency unblinding", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Emergency unblinding should only be performed if knowledge of the subject''s treatment assignment is absolutely necessary for their immediate medical management.", "section_id": "site_irt_guide:5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "emergency_unblinding", "value_name_id": "", "code": false, "id": "chk:1605"}','','[]',7605,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1606','check','','judgment','','{"kind": "judgment", "text": "Only the Principal Investigator or an authorized Sub-Investigator may perform emergency unblinding.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "emergency unblinding", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Only the Principal Investigator (PI) or authorized Sub-Investigator has the system permissions to execute a code break.", "section_id": "site_irt_guide:5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "emergency_unblinding", "value_name_id": "", "code": false, "id": "chk:1606"}','','[]',7606,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
