INSERT INTO guide VALUES('NCT05842941','checks','chk:1611','check','','follow_up','','{"kind": "follow_up", "text": "Emergency unblinding must trigger an automated unblinded alert email to the Sponsor Medical Monitor and the Suvoda Helpdesk.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "emergency unblinding", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "An automated, unblinded alert email is instantly dispatched to the Sponsor Medical Monitor and the Suvoda Helpdesk.", "section_id": "site_irt_guide:5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "emergency_unblinding", "value_name_id": "", "code": false, "id": "chk:1611"}','','[]',7611,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1612','check','','follow_up','','{"kind": "follow_up", "text": "Unblinding a subject automatically discontinues them from further double-blind protocol treatment.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "emergency unblinding", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Unblinding a subject automatically discontinues them from further double-blind protocol treatment.", "section_id": "site_irt_guide:5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "emergency_unblinding", "value_name_id": "", "code": false, "id": "chk:1612"}','','[]',7612,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1613','check','','follow_up','','{"kind": "follow_up", "text": "Unblinding must prevent any future double-blind kits from being dispensed to the subject.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "emergency unblinding", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "Suvoda will prevent any future double-blind kits from being dispensed to this subject.", "section_id": "site_irt_guide:5", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "emergency_unblinding", "value_name_id": "", "code": false, "id": "chk:1613"}','','[]',7613,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1614','check','','follow_up','','{"kind": "follow_up", "text": "If a kit is damaged at the pharmacy, the site must not give the damaged kit to the subject and must replace it in Suvoda using the damaged-kit reason.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "damaged kit found", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a kit is damaged at the pharmacy", "exception": "", "quote": "Do not give the damaged kit to the subject.", "section_id": "site_irt_guide:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "damaged_kit_found", "value_name_id": "", "code": false, "id": "chk:1614"}','','[]',7614,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1615','check','','follow_up','','{"kind": "follow_up", "text": "If a kit is damaged at the pharmacy, the site must select the Replace Kit action, choose the damaged kit, enter the reason, and enter the password.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "damaged kit found", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a kit is damaged at the pharmacy", "exception": "", "quote": "Log into Suvoda, navigate to the Subject ID, and select the Replace Kit action.", "section_id": "site_irt_guide:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "damaged_kit_found", "value_name_id": "", "code": false, "id": "chk:1615"}','','[]',7615,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1616','check','','follow_up','','{"kind": "follow_up", "text": "If a kit is damaged at the pharmacy, Suvoda must assign a new replacement kit number and change the damaged kit status to Damaged.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "damaged kit found", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a kit is damaged at the pharmacy", "exception": "", "quote": "Suvoda will assign a new, replacement Kit Number to the subject and change the damaged kit''s status to Damaged.", "section_id": "site_irt_guide:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "damaged_kit_found", "value_name_id": "", "code": false, "id": "chk:1616"}','','[]',7616,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1617','check','','follow_up','','{"kind": "follow_up", "text": "If a subject misses Week 4 entirely, the site must record a missed visit and choose Week 4 from the dropdown.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "week 4 visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a subject misses Week 4 entirely", "exception": "", "quote": "Navigate to the Subject ID, click on the Action menu, and select Missed Visit.", "section_id": "site_irt_guide:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "w4_visit", "value_name_id": "", "code": false, "id": "chk:1617"}','','[]',7617,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1618','check','','follow_up','','{"kind": "follow_up", "text": "Recording a missed Week 4 visit must cause the system to skip the Week 4 dispensation logic and prepare the timeline for Week 8.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "week 4 visit", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if a subject misses Week 4 entirely", "exception": "", "quote": "This ensures the system skips the Week 4 dispensation logic and prepares the subject''s timeline for the Week 8 visit.", "section_id": "site_irt_guide:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "w4_visit", "value_name_id": "", "code": false, "id": "chk:1618"}','','[]',7618,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1619','check','','not_checkable','','{"kind": "not_checkable", "text": "Manual extra-drug ordering is prohibited in principle, but the helpdesk/CRA authorization pathway is support guidance rather than a site action rule in this excerpt.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "", "exception": "", "quote": "No. Suvoda uses a predictive algorithm to manage your site''s inventory based on your current screening and active subject data.", "section_id": "site_irt_guide:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "", "value_name_id": "", "code": false, "id": "chk:1619"}','','[]',7619,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1620','check','','follow_up','','{"kind": "follow_up", "text": "If the TempTale monitor alarms upon receipt, the site must mark the shipment as containing an excursion during receipt.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "shipment receipt", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if the TempTale monitor alarms upon receipt", "exception": "", "quote": "You must mark the shipment as containing an excursion during receipt", "section_id": "site_irt_guide:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "shipment_receipt", "value_name_id": "", "code": false, "id": "chk:1620"}','','[]',7620,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
INSERT INTO guide VALUES('NCT05842941','checks','chk:1621','check','','follow_up','','{"kind": "follow_up", "text": "If the TempTale monitor alarms upon receipt, Suvoda must quarantine the kits and block dispensing until the Sponsor/CDMO explicitly changes status to Available.", "from_event": "", "to_event": "", "first_event": "", "then_event": "", "event": "shipment receipt", "value_name": "", "operator": "", "limit": null, "limit2": null, "value_unit": "", "unit": "", "min": null, "max": null, "applies_when": "if the TempTale monitor alarms upon receipt", "exception": "", "quote": "The system will physically block you from dispensing these kits until the Sponsor/CDMO reviews the TempTale data and explicitly changes their status to Available in the system.", "section_id": "site_irt_guide:6", "from_event_id": "", "to_event_id": "", "first_event_id": "", "then_event_id": "", "event_id": "shipment_receipt", "value_name_id": "", "code": false, "id": "chk:1621"}','','[]',7621,'master=6.0 (14 Oct 2024) sha256:28e3263947cc; regimen_g=2.0 (18 Dec 2023) sha256:2308a883adb7; site_edc_guide=1.0 sha256:c631de9ef9f3; site_irt_guide=sha256:7c030baf67bb; site_lab_manual=2.0 (Dec 2023) sha256:9239cb6e1799; site_pharmacy_manual=2.0 sha256:9586af7f3f43');
