/* WARNING: Script requires that SQLITE_DBCONFIG_DEFENSIVE be disabled */
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE documents (
    study_id TEXT NOT NULL,
    doc_id TEXT NOT NULL,
    path TEXT NOT NULL,
    sha256 TEXT NOT NULL,
    pages INTEGER NOT NULL,
    ingested_at TEXT NOT NULL,
    PRIMARY KEY (study_id, doc_id)
);
CREATE TABLE doc_pages (
    study_id TEXT NOT NULL,
    doc_id TEXT NOT NULL,
    page INTEGER NOT NULL,
    text TEXT NOT NULL,
    PRIMARY KEY (study_id, doc_id, page)
);
CREATE TABLE rules (
    id TEXT PRIMARY KEY,
    study_id TEXT NOT NULL,
    doc_id TEXT NOT NULL,
    doc_sha256 TEXT NOT NULL,
    pattern_class TEXT NOT NULL,
    kind TEXT NOT NULL,
    text TEXT NOT NULL,
    check_type TEXT NOT NULL,
    parameter TEXT,
    operator TEXT,
    value REAL,
    value2 REAL,
    unit TEXT,
    condition TEXT,
    applies_to TEXT,
    source_quote TEXT NOT NULL,
    source_page INTEGER,
    section TEXT,
    verified INTEGER NOT NULL,
    order_idx INTEGER NOT NULL,
    active INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL
, review TEXT, unless TEXT);
CREATE TABLE rule_decisions (
    study_id TEXT NOT NULL,
    rule_key TEXT NOT NULL,
    source_quote TEXT NOT NULL,
    text TEXT NOT NULL,
    suggest TEXT CHECK (suggest IN ('keep','remove')),
    reason_type TEXT,
    why TEXT,
    decision TEXT CHECK (decision IN ('keep','remove')),
    decided_by TEXT,
    decided_at TEXT,
    note TEXT,
    PRIMARY KEY (study_id, rule_key)
);
CREATE TABLE allowances (
    id TEXT PRIMARY KEY,
    study_id TEXT NOT NULL,
    doc_id TEXT NOT NULL,
    text TEXT NOT NULL,
    classes TEXT NOT NULL,
    source_quote TEXT NOT NULL,
    source_page INTEGER,
    created_at TEXT NOT NULL
);
CREATE TABLE guide (
    study_id TEXT NOT NULL,
    doc_id TEXT NOT NULL,
    id TEXT NOT NULL,
    kind TEXT NOT NULL,
    number TEXT,
    title TEXT NOT NULL,
    path TEXT,
    text TEXT NOT NULL,
    about TEXT,
    topics TEXT,
    ord INTEGER, version TEXT,
    PRIMARY KEY (study_id, id)
);
COMMIT;
